--
-- Name: _dispatch_alert_notifications(bigint, integer, character varying, bigint, integer, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api._dispatch_alert_notifications(p_alert_id bigint, p_alert_type_id integer, p_entity_type character varying, p_entity_id bigint, p_vehicle_id integer, p_driver_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
v_channels          TEXT[];
    v_channel           TEXT;
    v_queued            INT := 0;
    v_recipient_type    VARCHAR(20);
    v_recipient_id      BIGINT;
BEGIN
    -- Leer canales del alert_type
SELECT notification_channels INTO v_channels
FROM core_operations.alert_type
WHERE alert_type_id = p_alert_type_id;

-- Sin canales configurados: nada que encolar
IF v_channels IS NULL OR array_length(v_channels, 1) IS NULL THEN
        RETURN 0;
END IF;

    -- Determinar receptor principal según entity_type
CASE p_entity_type
        WHEN 'DRIVER' THEN
            v_recipient_type := 'DRIVER';
            v_recipient_id   := p_driver_id;
WHEN 'VEHICLE' THEN
            -- El receptor de alertas de vehículo es el conductor activo (si lo hay)
            v_recipient_type := 'DRIVER';
            v_recipient_id   := p_driver_id;
WHEN 'TRIP' THEN
            v_recipient_type := 'DRIVER';
            v_recipient_id   := p_driver_id;
ELSE
            -- ROUTE / SYSTEM: receptor es 'SYSTEM' (operador de turno, sin ID específico)
            v_recipient_type := 'SYSTEM';
            v_recipient_id   := NULL;
END CASE;

    -- Insertar un registro por canal
    FOREACH v_channel IN ARRAY v_channels
    LOOP
        -- Validar que el canal esté en el dominio del CHECK de la tabla
        IF v_channel NOT IN ('EMAIL', 'SMS', 'PUSH', 'WEBHOOK', 'WHATSAPP') THEN
            CONTINUE;   -- ignorar canales desconocidos silenciosamente
END IF;

INSERT INTO core_operations.alert_communication_log (
    alert_id,
    channel,
    recipient_type,
    recipient_id,
    status,
    created_at
)
VALUES (
           p_alert_id,
           v_channel,
           v_recipient_type,
           v_recipient_id,
           'PENDING',
           NOW()
       );
v_queued := v_queued + 1;
END LOOP;

PERFORM pg_notify(
    'alert_new',    -- todo : NOTIFICATION NAME (CHANNEL)
    jsonb_build_object(
        'alert_id',       p_alert_id,
        'entity_type_id',    p_alert_type_id,
        'entity_id',    p_entity_id,
        'vehicle_id',     p_vehicle_id,
        'driver_id',     p_driver_id
    )::TEXT
);
RETURN v_queued;
END;
$$;


--
-- Name: _generate_driver_code(); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api._generate_driver_code() RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_prefix        VARCHAR(10);
    v_next_seq      INT;
    v_code          VARCHAR(20);
    v_cfg_value     TEXT;
BEGIN
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'hr.driver_code_prefix';

v_prefix := COALESCE(NULLIF(TRIM(v_cfg_value), ''), 'DRV');

    -- ── Filtro estricto: solo códigos con sufijo numérico puro ────────────
SELECT COALESCE(
               MAX(
                       REGEXP_REPLACE(driver_code, '^' || v_prefix || '-0*', '')::INT
               ), 0
       ) + 1
INTO v_next_seq
FROM hr.driver
WHERE driver_code ~ ('^' || v_prefix || '-[0-9]+$');

v_code := v_prefix || '-' || LPAD(v_next_seq::TEXT, 4, '0');

    WHILE EXISTS (SELECT 1 FROM hr.driver WHERE driver_code = v_code) LOOP
        v_next_seq := v_next_seq + 1;
        v_code     := v_prefix || '-' || LPAD(v_next_seq::TEXT, 4, '0');
END LOOP;

RETURN v_code;
END;
$_$;


--
-- Name: _generate_employee_code(); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api._generate_employee_code() RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_prefix        VARCHAR(10);
    v_next_seq      INT;
    v_code          VARCHAR(20);
    v_cfg_value     TEXT;
    v_suffix        TEXT;
BEGIN
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'hr.employee_code_prefix';

v_prefix := COALESCE(NULLIF(TRIM(v_cfg_value), ''), 'EMP');

    -- ── Buscar solo códigos que siguen el patrón prefijo-NNNN ─────────────
    -- Filtra con regex estricto ANTES de intentar el cast a INT
    -- Así los códigos manuales como 'EMP-CAJERO-001' son ignorados
SELECT COALESCE(
               MAX(
                       REGEXP_REPLACE(employee_code, '^' || v_prefix || '-0*', '')::INT
               ), 0
       ) + 1
INTO v_next_seq
FROM hr.personnel
WHERE employee_code ~ ('^' || v_prefix || '-[0-9]+$');
--                     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^
--                     Solo coincide con prefijo-DÍGITOS (ej: EMP-0001)
--                     Excluye EMP-CAJERO-001, EMP-HIRED-001, etc.

v_code := v_prefix || '-' || LPAD(v_next_seq::TEXT, 4, '0');

    -- Protección ante colisión concurrente
    WHILE EXISTS (SELECT 1 FROM hr.personnel WHERE employee_code = v_code) LOOP
        v_next_seq := v_next_seq + 1;
        v_code     := v_prefix || '-' || LPAD(v_next_seq::TEXT, 4, '0');
END LOOP;

RETURN v_code;
END;
$_$;


--
-- Name: _generate_vehicle_code(); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api._generate_vehicle_code() RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_prefix        VARCHAR(10);
    v_next_seq      INT;
    v_code          VARCHAR(20);
    v_cfg_value     TEXT;
BEGIN
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'fleet.vehicle_code_prefix';

v_prefix := COALESCE(NULLIF(TRIM(v_cfg_value), ''), 'BUS');

    -- Solo considera códigos con sufijo numérico puro (evita códigos manuales)
SELECT COALESCE(
               MAX(
                       REGEXP_REPLACE(internal_code, '^' || v_prefix || '-0*', '')::INT
               ), 0
       ) + 1
INTO v_next_seq
FROM fleet.vehicle
WHERE internal_code ~ ('^' || v_prefix || '-[0-9]+$');

v_code := v_prefix || '-' || LPAD(v_next_seq::TEXT, 3, '0');

    -- Protección ante colisión concurrente
    WHILE EXISTS (SELECT 1 FROM fleet.vehicle WHERE internal_code = v_code) LOOP
        v_next_seq := v_next_seq + 1;
        v_code     := v_prefix || '-' || LPAD(v_next_seq::TEXT, 3, '0');
END LOOP;

RETURN v_code;
END;
$_$;


--
-- Name: acknowledge_alert(api.acknowledge_alert_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.acknowledge_alert(p_input api.acknowledge_alert_input) RETURNS api.acknowledge_alert_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.acknowledge_alert_result;
    v_alert         core_operations.alert%ROWTYPE;
    v_alert_type    core_operations.alert_type%ROWTYPE;
    v_now           TIMESTAMPTZ := NOW();
    v_log_id        BIGINT;
    v_changes       JSONB;
BEGIN

    -- ── Val: campos obligatorios ──────────────────────────────────────────
    IF p_input.alert_id IS NULL OR p_input.alert_timestamp IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ALERT_KEY';
        v_result.error_message := 'alert_id y alert_timestamp son obligatorios '
                                  || '(clave compuesta por particionado mensual)';
RETURN v_result;
END IF;

    IF p_input.acknowledged_by IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_USER';
        v_result.error_message := 'acknowledged_by (user_id) es obligatorio';
RETURN v_result;
END IF;

    -- ── Val: usuario existe y está activo ─────────────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM identity."user"
        WHERE user_id = p_input.acknowledged_by AND is_active = TRUE
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'USER_NOT_FOUND';
        v_result.error_message := 'user_id=' || p_input.acknowledged_by
                                  || ' no existe o está inactivo';
RETURN v_result;
END IF;

    -- ── Buscar alerta por clave compuesta (acota a 2 particiones) ─────────
SELECT * INTO v_alert
FROM core_operations.alert
WHERE alert_id        = p_input.alert_id
  AND alert_timestamp = p_input.alert_timestamp;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ALERT_NOT_FOUND';
        v_result.error_message := 'Alerta alert_id=' || p_input.alert_id
                                  || ' con alert_timestamp='
                                  || p_input.alert_timestamp::TEXT || ' no existe';
RETURN v_result;
END IF;

    -- ── Cargar alert_type ─────────────────────────────────────────────────
SELECT * INTO v_alert_type
FROM core_operations.alert_type
WHERE alert_type_id = v_alert.alert_type_id;

-- ── Caso especial: ya fue reconocida → warning, no error duro ─────────
IF v_alert.acknowledged_by IS NOT NULL THEN
        v_result.success          := TRUE;
        v_result.warning          := 'ALREADY_ACKNOWLEDGED: La alerta ya fue reconocida por '
                                     || 'user_id=' || v_alert.acknowledged_by::TEXT
                                     || ' el ' || v_alert.acknowledged_at::TEXT;
        v_result.alert_id         := v_alert.alert_id;
        v_result.alert_type_code  := v_alert_type.code;
        v_result.entity_type      := v_alert.entity_type;
        v_result.vehicle_id       := v_alert.vehicle_id;
        v_result.driver_id        := v_alert.driver_id;
        v_result.severity         := v_alert.severity;
        v_result.previous_status  := v_alert.status;
        v_result.current_status   := v_alert.status;
        v_result.acknowledged_by  := v_alert.acknowledged_by;
        v_result.acknowledged_at  := v_alert.acknowledged_at;
        v_result.activity_log_id  := NULL;
RETURN v_result;
END IF;

    -- ── Val: solo alertas ACTIVE pueden reconocerse ───────────────────────
    IF v_alert.status <> 'ACTIVE' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ALERT_NOT_ACTIVE';
        v_result.error_message := 'Solo se pueden reconocer alertas en estado ACTIVE. '
                                  || 'Estado actual: ' || v_alert.status;
RETURN v_result;
END IF;

    -- ── Actualizar alerta ─────────────────────────────────────────────────
UPDATE core_operations.alert
SET status          = 'ACKNOWLEDGED',
    acknowledged_by = p_input.acknowledged_by,
    acknowledged_at = v_now
WHERE alert_id        = p_input.alert_id
  AND alert_timestamp = p_input.alert_timestamp;

-- acknowledge_alert
-- PERFORM pg_notify(
--     'alert_updated',
--     jsonb_build_object(
--         'alert_id',        p_input.alert_id,
--         'new_status',      'ACKNOWLEDGED',
--         'acknowledged_by', p_input.acknowledged_by,
--         'acknowledged_at', v_now,
--         'severity',        v_alert.severity,
--         'entity_type',     v_alert.entity_type,
--         'vehicle_id',      v_alert.vehicle_id
--     )::TEXT
-- );
-- ── Registrar en activity_log ─────────────────────────────────────────
v_changes := jsonb_build_object(
        'before', jsonb_build_object('status', 'ACTIVE', 'acknowledged_by', NULL),
        'after',  jsonb_build_object('status', 'ACKNOWLEDGED',
                                     'acknowledged_by', p_input.acknowledged_by,
                                     'acknowledged_at', v_now),
        'fields_changed', jsonb_build_array('status', 'acknowledged_by', 'acknowledged_at'),
        'alert_type_code', v_alert_type.code
    );

INSERT INTO identity.activity_log (
    user_id, action, resource_type, resource_id,
    changes, status, created_at
)
VALUES (
           p_input.acknowledged_by,
           'ALERT_ACKNOWLEDGE',
           'core_operations.alert',
           p_input.alert_id,
           v_changes, 'SUCCESS', v_now
       )
    RETURNING log_id INTO v_log_id;

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success          := TRUE;
    v_result.alert_id         := v_alert.alert_id;
    v_result.alert_type_code  := v_alert_type.code;
    v_result.entity_type      := v_alert.entity_type;
    v_result.vehicle_id       := v_alert.vehicle_id;
    v_result.driver_id        := v_alert.driver_id;
    v_result.severity         := v_alert.severity;
    v_result.previous_status  := 'ACTIVE';
    v_result.current_status   := 'ACKNOWLEDGED';
    v_result.acknowledged_by  := p_input.acknowledged_by;
    v_result.acknowledged_at  := v_now;
    v_result.activity_log_id  := v_log_id;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: assign_role_to_user(api.assign_role_to_user_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.assign_role_to_user(p_input api.assign_role_to_user_input) RETURNS api.assign_role_to_user_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.assign_role_to_user_result;
    v_role              identity.role%ROWTYPE;
    v_user_role_id      BIGINT;
BEGIN

    -- ── Validación 1: usuario existe ──────────────────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM identity.user
        WHERE user_id = p_input.user_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'USER_NOT_FOUND';
        v_result.error_message := 'El user_id=' || p_input.user_id || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 2: rol existe y está activo ────────────────────────────
SELECT * INTO v_role
FROM identity.role
WHERE role_id = p_input.role_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_NOT_FOUND';
        v_result.error_message := 'El role_id=' || p_input.role_id || ' no existe';
RETURN v_result;
END IF;

    IF v_role.is_active = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_NOT_FOUND';
        v_result.error_message := 'El rol "' || v_role.name || '" existe pero está inactivo';
RETURN v_result;
END IF;

    -- ── Validación 3: el usuario tiene acceso al tenant del rol ───────────
    IF NOT EXISTS (
        SELECT 1 FROM identity.user_tenant_access
        WHERE user_id   = p_input.user_id
          AND tenant_id = v_role.tenant_id
          AND is_active = TRUE
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_TENANT_MISMATCH';
        v_result.error_message := 'El usuario user_id=' || p_input.user_id
                                  || ' no tiene acceso al tenant_id=' || v_role.tenant_id
                                  || ' al que pertenece el rol "' || v_role.name || '"';
RETURN v_result;
END IF;

    -- ── Validación 4: asignación activa ya existe ─────────────────────────
    IF EXISTS (
        SELECT 1 FROM identity.user_role
        WHERE user_id   = p_input.user_id
          AND role_id   = p_input.role_id
          AND tenant_id = v_role.tenant_id
          AND is_active = TRUE
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_ALREADY_ASSIGNED';
        v_result.error_message := 'El usuario ya tiene asignado el rol "'
                                  || v_role.name || '" en este tenant';
RETURN v_result;
END IF;

    -- ── Validación 5: expires_at no puede ser en el pasado ────────────────
    IF p_input.expires_at IS NOT NULL
       AND p_input.expires_at <= NOW()
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_EXPIRY_DATE';
        v_result.error_message := 'expires_at debe ser una fecha futura. '
                                  || 'Valor recibido: ' || p_input.expires_at::TEXT;
RETURN v_result;
END IF;

    -- ── Insertar asignación ───────────────────────────────────────────────
INSERT INTO identity.user_role (
    user_id,
    role_id,
    tenant_id,
    is_active,
    assigned_by,
    assigned_at,
    expires_at
)
VALUES (
           p_input.user_id,
           p_input.role_id,
           v_role.tenant_id,
           TRUE,
           p_input.assigned_by,
           NOW(),
           p_input.expires_at
       )
    RETURNING user_role_id INTO v_user_role_id;

-- ── Poblar resultado campo a campo ────────────────────────────────────
SELECT
    ur.user_role_id,
    ur.user_id,
    ur.role_id,
    ur.tenant_id,
    ur.is_active,
    ur.assigned_by,
    ur.assigned_at,
    ur.expires_at
INTO
    v_result.user_role_id,
    v_result.user_id,
    v_result.role_id,
    v_result.tenant_id,
    v_result.is_active,
    v_result.assigned_by,
    v_result.assigned_at,
    v_result.expires_at
FROM identity.user_role ur
WHERE ur.user_role_id = v_user_role_id;

v_result.success     := TRUE;
    v_result.role_name   := v_role.name;
    v_result.is_temporary := (p_input.expires_at IS NOT NULL);

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        -- Race condition: asignación creada concurrentemente
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_ALREADY_ASSIGNED';
        v_result.error_message := 'Conflicto de unicidad: el rol "'
                                  || v_role.name
                                  || '" fue asignado concurrentemente a este usuario';
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: assign_roles_to_user(api.assign_roles_to_user_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.assign_roles_to_user(p_input api.assign_roles_to_user_input) RETURNS api.assign_roles_to_user_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.assign_roles_to_user_result;
    v_item              api.user_role_item;
    v_item_result       api.user_role_item_result;
    v_item_results      api.user_role_item_result[]
                            := ARRAY[]::api.user_role_item_result[];
    v_total_inserted    INT := 0;
    v_total_revoked     INT := 0;
    v_total_skipped     INT := 0;
    v_total_errors      INT := 0;
    v_role              identity.role%ROWTYPE;
    v_user_role_id      BIGINT;
    v_processed_roles   BIGINT[] := ARRAY[]::BIGINT[];
    -- Para la fase de revocación
    v_submitted_ids     BIGINT[] := ARRAY[]::BIGINT[];
    v_del_role_id       BIGINT;
    v_del_role_name     VARCHAR(100);
    v_del_tenant_id     BIGINT;
    v_del_user_role_id  BIGINT;
    v_del_expires_at    TIMESTAMPTZ;
    v_del_assigned_at   TIMESTAMPTZ;
BEGIN

    -- ── Validación 1: user_id obligatorio ─────────────────────────────────
    IF p_input.user_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_USER_ID';
        v_result.error_message := 'user_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: usuario existe y está activo ────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM identity."user"
        WHERE user_id  = p_input.user_id
          AND is_active = TRUE
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'USER_NOT_FOUND';
        v_result.error_message := 'user_id=' || p_input.user_id
                                  || ' no existe o está inactivo';
RETURN v_result;
END IF;

    -- ── Validación 3: assigned_by existe si se proveyó ────────────────────
    IF p_input.assigned_by IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM identity."user"
            WHERE user_id  = p_input.assigned_by
              AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ASSIGNED_BY_NOT_FOUND';
            v_result.error_message := 'assigned_by=' || p_input.assigned_by
                                      || ' no existe o está inactivo';
RETURN v_result;
END IF;
END IF;

    -- ── Validación 4: array no puede ser NULL ─────────────────────────────
    IF p_input.roles IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_ROLES_ARRAY';
        v_result.error_message := 'El array de roles es NULL. '
                                  || 'Para revocar todos los roles envíe un array vacío []';
RETURN v_result;
END IF;


    -- ════════════════════════════════════════════════════════
    -- FASE 1: Upsert de cada rol enviado
    -- ════════════════════════════════════════════════════════
    IF array_length(p_input.roles, 1) IS NOT NULL THEN

        FOREACH v_item IN ARRAY p_input.roles
        LOOP
            v_item_result.role_id       := v_item.role_id;
            v_item_result.role_name     := NULL;
            v_item_result.tenant_id     := NULL;
            v_item_result.user_role_id  := NULL;
            v_item_result.status        := NULL;
            v_item_result.is_temporary  := NULL;
            v_item_result.expires_at    := v_item.expires_at;
            v_item_result.assigned_at   := NULL;
            v_item_result.error_code    := NULL;
            v_item_result.error_message := NULL;

            -- ── Val: role_id obligatorio ──────────────────────────────────
            IF v_item.role_id IS NULL THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_ROLE_ID';
                v_item_result.error_message := 'role_id es obligatorio en cada ítem';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: role_id no duplicado en el batch ─────────────────────
            IF v_item.role_id = ANY(v_processed_roles) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_ROLE_IN_BATCH';
                v_item_result.error_message := 'role_id=' || v_item.role_id
                                               || ' aparece más de una vez en el mismo lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: rol existe y está activo ─────────────────────────────
SELECT * INTO v_role
FROM identity.role
WHERE role_id = v_item.role_id;

IF NOT FOUND THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'ROLE_NOT_FOUND';
                v_item_result.error_message := 'role_id=' || v_item.role_id || ' no existe';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_item_result.role_name := v_role.name;
            v_item_result.tenant_id := v_role.tenant_id;

            IF v_role.is_active = FALSE THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'ROLE_INACTIVE';
                v_item_result.error_message := 'El rol "' || v_role.name || '" está inactivo';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: usuario tiene acceso al tenant del rol ───────────────
            IF NOT EXISTS (
                SELECT 1 FROM identity.user_tenant_access
                WHERE user_id   = p_input.user_id
                  AND tenant_id = v_role.tenant_id
                  AND is_active  = TRUE
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'ROLE_TENANT_MISMATCH';
                v_item_result.error_message := 'El usuario no tiene acceso al tenant_id='
                                               || v_role.tenant_id
                                               || ' del rol "' || v_role.name || '"';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: expires_at no puede ser en el pasado ─────────────────
            IF v_item.expires_at IS NOT NULL
               AND v_item.expires_at <= NOW()
            THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'INVALID_EXPIRY_DATE';
                v_item_result.error_message := 'expires_at debe ser una fecha futura. '
                                               || 'Recibido: ' || v_item.expires_at::TEXT
                                               || ' en rol "' || v_role.name || '"';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Ya existe activo → SKIPPED ────────────────────────────────
            IF EXISTS (
                SELECT 1 FROM identity.user_role
                WHERE user_id   = p_input.user_id
                  AND role_id   = v_item.role_id
                  AND tenant_id = v_role.tenant_id
                  AND is_active  = TRUE
            ) THEN
SELECT user_role_id, assigned_at, expires_at
INTO v_user_role_id,
    v_item_result.assigned_at,
    v_item_result.expires_at
FROM identity.user_role
WHERE user_id   = p_input.user_id
  AND role_id   = v_item.role_id
  AND tenant_id = v_role.tenant_id
  AND is_active  = TRUE;

v_item_result.status       := 'SKIPPED';
                v_item_result.user_role_id := v_user_role_id;
                v_item_result.is_temporary := (v_item_result.expires_at IS NOT NULL);
                v_item_results    := v_item_results || v_item_result;
                v_total_skipped   := v_total_skipped + 1;
                v_submitted_ids   := v_submitted_ids || v_user_role_id;
                v_processed_roles := v_processed_roles || v_item.role_id;
CONTINUE;
END IF;

            -- ── INSERT ────────────────────────────────────────────────────
INSERT INTO identity.user_role (
    user_id, role_id, tenant_id,
    is_active, assigned_by, assigned_at, expires_at
)
VALUES (
           p_input.user_id, v_item.role_id, v_role.tenant_id,
           TRUE, p_input.assigned_by, NOW(), v_item.expires_at
       )
    RETURNING user_role_id, assigned_at
INTO v_user_role_id, v_item_result.assigned_at;

v_item_result.status       := 'INSERTED';
            v_item_result.user_role_id := v_user_role_id;
            v_item_result.is_temporary := (v_item.expires_at IS NOT NULL);
            v_item_results    := v_item_results || v_item_result;
            v_total_inserted  := v_total_inserted + 1;
            v_submitted_ids   := v_submitted_ids || v_user_role_id;
            v_processed_roles := v_processed_roles || v_item.role_id;

END LOOP;

END IF; -- fin FASE 1


    -- ════════════════════════════════════════════════════════
    -- FASE 2: Revocar roles activos no presentes en el payload
    -- Solo se revocan los que NO tuvieron ERROR en validación.
    -- Los roles con ERROR se preservan (no entran en submitted_ids).
    -- ════════════════════════════════════════════════════════
FOR v_del_user_role_id,
        v_del_role_id,
        v_del_role_name,
        v_del_tenant_id,
        v_del_expires_at,
        v_del_assigned_at
    IN
SELECT ur.user_role_id,
       ur.role_id,
       r.name,
       ur.tenant_id,
       ur.expires_at,
       ur.assigned_at
FROM identity.user_role ur
         JOIN identity.role r ON r.role_id = ur.role_id
WHERE ur.user_id   = p_input.user_id
  AND ur.is_active  = TRUE
  AND ur.user_role_id <> ALL(v_submitted_ids)
ORDER BY r.name
    LOOP
UPDATE identity.user_role
SET is_active = FALSE
WHERE user_role_id = v_del_user_role_id;

v_total_revoked := v_total_revoked + 1;

        v_item_result.role_id       := v_del_role_id;
        v_item_result.role_name     := v_del_role_name;
        v_item_result.tenant_id     := v_del_tenant_id;
        v_item_result.user_role_id  := v_del_user_role_id;
        v_item_result.status        := 'REVOKED';
        v_item_result.is_temporary  := (v_del_expires_at IS NOT NULL);
        v_item_result.expires_at    := v_del_expires_at;
        v_item_result.assigned_at   := v_del_assigned_at;
        v_item_result.error_code    := NULL;
        v_item_result.error_message := NULL;
        v_item_results := v_item_results || v_item_result;

END LOOP;


    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success         := TRUE;
    v_result.user_id         := p_input.user_id;
    v_result.total_submitted := COALESCE(array_length(p_input.roles, 1), 0);
    v_result.total_inserted  := v_total_inserted;
    v_result.total_revoked   := v_total_revoked;
    v_result.total_skipped   := v_total_skipped;
    v_result.total_errors    := v_total_errors;
    v_result.detail          := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: assign_vehicle_to_driver(api.assign_vehicle_to_driver_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.assign_vehicle_to_driver(p_input api.assign_vehicle_to_driver_input) RETURNS api.assign_vehicle_to_driver_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                    api.assign_vehicle_to_driver_result;
    v_vehicle                   fleet.vehicle%ROWTYPE;
    v_driver                    hr.driver%ROWTYPE;
    v_driver_full_name          VARCHAR(255);
    v_assignment_id             BIGINT;
    v_prev_assignment_id        BIGINT;
    v_assignment_type           VARCHAR(20);
BEGIN

    -- ── Validación 1: assignment_type dentro del dominio ──────────────────
    v_assignment_type := COALESCE(
        NULLIF(TRIM(COALESCE(p_input.assignment_type, '')), ''),
        'OWNER_OPERATOR'
    );

    IF v_assignment_type NOT IN (
        'OWNER_OPERATOR', 'HIRED_DRIVER', 'TEMPORARY', 'REPLACEMENT'
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_ASSIGNMENT_TYPE';
        v_result.error_message := 'assignment_type inválido: "' || v_assignment_type
                                  || '". Válidos: OWNER_OPERATOR, HIRED_DRIVER, '
                                  || 'TEMPORARY, REPLACEMENT';
RETURN v_result;
END IF;

    -- ── Validación 2: assigned_by existe ──────────────────────────────────
    IF p_input.assigned_by IS NULL
       OR NOT EXISTS (
           SELECT 1 FROM identity.user
           WHERE user_id = p_input.assigned_by AND is_active = TRUE
       )
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'GRANTING_USER_NOT_FOUND';
        v_result.error_message := 'El usuario assigned_by='
                                  || COALESCE(p_input.assigned_by::TEXT, 'NULL')
                                  || ' no existe o está inactivo';
RETURN v_result;
END IF;

    -- ── Validación 3: vehículo existe ─────────────────────────────────────
SELECT * INTO v_vehicle
FROM fleet.vehicle
WHERE vehicle_id = p_input.vehicle_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_FOUND';
        v_result.error_message := 'El vehículo vehicle_id=' || p_input.vehicle_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 4: vehículo en estado ACTIVE ───────────────────────────
    IF v_vehicle.status <> 'ACTIVE' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_ACTIVE';
        v_result.error_message := 'El vehículo "' || v_vehicle.plate_number
                                  || '" tiene status=' || v_vehicle.status
                                  || '. Solo vehículos ACTIVE pueden asignarse';
RETURN v_result;
END IF;

    -- ── Validación 5: vehículo operacional ───────────────────────────────
    IF v_vehicle.is_operational = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_OPERATIONAL';
        v_result.error_message := 'El vehículo "' || v_vehicle.plate_number
                                  || '" no está operacional (is_operational=false). '
                                  || 'Verifique documentos vencidos o estado de GPS';
RETURN v_result;
END IF;

    -- ── Validación 6: conductor existe ────────────────────────────────────
SELECT * INTO v_driver
FROM hr.driver
WHERE driver_id = p_input.driver_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DRIVER_NOT_FOUND';
        v_result.error_message := 'El conductor driver_id=' || p_input.driver_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- Nombre del conductor para el result
SELECT full_name INTO v_driver_full_name
FROM hr.person
WHERE person_id = v_driver.person_id;

-- ── Validación 7: conductor activo ────────────────────────────────────
IF v_driver.employment_status <> 'ACTIVE' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DRIVER_NOT_ACTIVE';
        v_result.error_message := 'El conductor "' || v_driver.driver_code
                                  || '" tiene employment_status='
                                  || v_driver.employment_status
                                  || '. Solo conductores ACTIVE pueden asignarse';
RETURN v_result;
END IF;

    -- ── Validación 8: conductor disponible ───────────────────────────────
    IF v_driver.is_available = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DRIVER_NOT_AVAILABLE';
        v_result.error_message := 'El conductor "' || v_driver.driver_code
                                  || '" no está disponible (is_available=false). '
                                  || 'Puede tener puntos de licencia bajos o estar suspendido';
RETURN v_result;
END IF;

    -- ── Cerrar asignación previa del vehículo si existe ───────────────────
UPDATE fleet.vehicle_assignment
SET
    unassigned_at  = NOW(),
    unassigned_by  = p_input.assigned_by,
    is_active      = FALSE
WHERE vehicle_id  = p_input.vehicle_id
  AND is_active   = TRUE
    RETURNING assignment_id INTO v_prev_assignment_id;

-- ── Insertar nueva asignación ─────────────────────────────────────────
INSERT INTO fleet.vehicle_assignment (
    vehicle_id,
    driver_id,
    assignment_type,
    assigned_by,
    assigned_at,
    is_active,
    notes
)
VALUES (
           p_input.vehicle_id,
           p_input.driver_id,
           v_assignment_type,
           p_input.assigned_by,
           NOW(),
           TRUE,
           p_input.notes
       )
    RETURNING assignment_id INTO v_assignment_id;

-- ── Actualizar current_vehicle_id del conductor ───────────────────────
UPDATE hr.driver
SET
    current_vehicle_id = p_input.vehicle_id,
    updated_at         = NOW()
WHERE driver_id = p_input.driver_id;

-- ── Poblar resultado campo a campo ────────────────────────────────────
SELECT
    va.assignment_id,
    va.vehicle_id,
    va.driver_id,
    va.assignment_type,
    va.assigned_at,
    va.assigned_by,
    va.created_at
INTO
    v_result.assignment_id,
    v_result.vehicle_id,
    v_result.driver_id,
    v_result.assignment_type,
    v_result.assigned_at,
    v_result.assigned_by,
    v_result.created_at
FROM fleet.vehicle_assignment va
WHERE va.assignment_id = v_assignment_id;

v_result.success                    := TRUE;
    v_result.plate_number               := v_vehicle.plate_number;
    v_result.internal_code              := v_vehicle.internal_code;
    v_result.driver_code                := v_driver.driver_code;
    v_result.driver_full_name           := v_driver_full_name;
    v_result.previous_assignment_closed := (v_prev_assignment_id IS NOT NULL);
    v_result.previous_assignment_id     := v_prev_assignment_id;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: auto_close_stale_alerts(); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.auto_close_stale_alerts() RETURNS api.auto_close_stale_alerts_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.auto_close_stale_alerts_result;
    v_batch_size    INT;
    v_cfg_value     TEXT;
    v_alerts_closed INT := 0;
    v_log_id        BIGINT;
    v_start_ts      TIMESTAMPTZ := NOW();
    v_now           TIMESTAMPTZ := NOW();
    -- Ventana de búsqueda: alertas de los últimos 6 meses (6 particiones)
    -- Es un balance entre cobertura y performance
    v_window_start  TIMESTAMPTZ := v_now - INTERVAL '6 months';
BEGIN

    -- ── Leer batch_size desde configuración ───────────────────────────────
SELECT value INTO v_cfg_value
FROM shared.configuration WHERE key = 'alerts.auto_close_batch_size';

BEGIN
        v_batch_size := COALESCE(NULLIF(TRIM(v_cfg_value), ''), '500')::INT;
        IF v_batch_size <= 0 THEN v_batch_size := 500; END IF;
EXCEPTION WHEN OTHERS THEN
        v_batch_size := 500;  -- BATCH_SIZE_NOT_CONFIGURED: usar default
END;

    -- ── Cerrar alertas cuyo auto_closed_at ya pasó ────────────────────────
    -- Condiciones:
    --   1. status IN ('ACTIVE', 'ACKNOWLEDGED') — no las ya cerradas
    --   2. auto_closed_at IS NOT NULL — solo las que tienen cierre automático
    --   3. auto_closed_at <= NOW() — el tiempo de cierre ya expiró
    --   4. Ventana de 6 meses para limitar el scan de particiones
    -- Usamos CTE con LIMIT para procesar en lote y evitar bloquear la tabla
WITH stale AS (
    SELECT alert_id, alert_timestamp
    FROM core_operations.alert
    WHERE status         IN ('ACTIVE', 'ACKNOWLEDGED')
      AND auto_closed_at IS NOT NULL
      AND auto_closed_at <= v_now
      AND alert_timestamp >= v_window_start   -- acota particiones
    ORDER BY alert_timestamp ASC              -- las más antiguas primero
    LIMIT v_batch_size
    )
UPDATE core_operations.alert a
SET status        = 'AUTO_CLOSED',
    auto_closed_at = v_now      -- sobreescribir con el timestamp real de cierre
    FROM stale
WHERE a.alert_id        = stale.alert_id
  AND a.alert_timestamp = stale.alert_timestamp;

GET DIAGNOSTICS v_alerts_closed = ROW_COUNT;

-- ── Registrar en activity_log (aunque no cierre nada, para trazabilidad) ──
INSERT INTO identity.activity_log (
    user_id,
    action,
    resource_type,
    resource_id,
    changes,
    status,
    created_at
)
VALUES (
           NULL,   -- acción del sistema, sin user_id
           'ALERT_AUTO_CLOSE_JOB',
           'core_operations.alert',
           NULL,
           jsonb_build_object(
                   'alerts_closed',   v_alerts_closed,
                   'batch_size',      v_batch_size,
                   'window_start',    v_window_start,
                   'executed_at',     v_now,
                   'execution_time_ms',
                   ROUND(EXTRACT(EPOCH FROM (NOW() - v_start_ts)) * 1000, 2)
           ),
           'SUCCESS',
           v_now
       )
    RETURNING log_id INTO v_log_id;

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success            := TRUE;
    v_result.batch_size_used    := v_batch_size;
    v_result.alerts_closed      := v_alerts_closed;
    v_result.execution_time_ms  := ROUND(
                                       EXTRACT(EPOCH FROM (NOW() - v_start_ts)) * 1000, 2
                                   );
    v_result.activity_log_id    := v_log_id;
    v_result.executed_at        := v_now;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        -- No lanza hacia afuera — registra el error en el log y retorna
BEGIN
INSERT INTO identity.activity_log (
    user_id, action, resource_type, resource_id,
    changes, status, error_message, created_at
)
VALUES (
           NULL, 'ALERT_AUTO_CLOSE_JOB', 'core_operations.alert', NULL,
           jsonb_build_object('error', SQLERRM),
           'FAILED', SQLERRM, v_now
       );
EXCEPTION WHEN OTHERS THEN
            NULL; -- si el log también falla, silenciar
END;

        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.executed_at   := v_now;
RETURN v_result;
END;
$$;


--
-- Name: create_alert(api.create_alert_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.create_alert(p_input api.create_alert_input) RETURNS api.create_alert_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.create_alert_result;
    v_alert_type        core_operations.alert_type%ROWTYPE;
    v_alert_id          BIGINT;
    v_alert_ts          TIMESTAMPTZ;
    v_auto_closed_at    TIMESTAMPTZ;
    v_notifications     INT := 0;
BEGIN

    -- ── Validación 1: alert_type_id obligatorio ───────────────────────────
    IF p_input.alert_type_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ALERT_TYPE_ID';
        v_result.error_message := 'alert_type_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: alert_type existe y está activo ─────────────────────
SELECT * INTO v_alert_type
FROM core_operations.alert_type
WHERE alert_type_id = p_input.alert_type_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ALERT_TYPE_NOT_FOUND';
        v_result.error_message := 'alert_type_id=' || p_input.alert_type_id || ' no existe';
RETURN v_result;
END IF;

    IF v_alert_type.is_active = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ALERT_TYPE_INACTIVE';
        v_result.error_message := 'El tipo de alerta "' || v_alert_type.name
                                  || '" está inactivo y no puede usarse para crear alertas';
RETURN v_result;
END IF;

    -- ── Validación 3: entity_type dentro del dominio ──────────────────────
    IF p_input.entity_type IS NULL
       OR p_input.entity_type NOT IN ('VEHICLE', 'DRIVER', 'TRIP', 'ROUTE', 'SYSTEM')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_ENTITY_TYPE';
        v_result.error_message := 'entity_type inválido: "'
                                  || COALESCE(p_input.entity_type, 'NULL')
                                  || '". Válidos: VEHICLE, DRIVER, TRIP, ROUTE, SYSTEM';
RETURN v_result;
END IF;

    -- ── Validación 4: entity_id obligatorio ──────────────────────────────
    IF p_input.entity_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ENTITY_ID';
        v_result.error_message := 'entity_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 5: coherencia entity_type ↔ campo específico ──────────
    IF p_input.entity_type = 'VEHICLE' THEN
        IF p_input.vehicle_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ENTITY_TYPE_VEHICLE_REQUIRES_VEHICLE_ID';
            v_result.error_message := 'entity_type=VEHICLE requiere vehicle_id';
RETURN v_result;
END IF;
        IF NOT EXISTS (
            SELECT 1 FROM fleet.vehicle WHERE vehicle_id = p_input.vehicle_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'VEHICLE_NOT_FOUND';
            v_result.error_message := 'vehicle_id=' || p_input.vehicle_id || ' no existe';
RETURN v_result;
END IF;
END IF;

    IF p_input.entity_type = 'DRIVER' THEN
        IF p_input.driver_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ENTITY_TYPE_DRIVER_REQUIRES_DRIVER_ID';
            v_result.error_message := 'entity_type=DRIVER requiere driver_id';
RETURN v_result;
END IF;
        IF NOT EXISTS (
            SELECT 1 FROM hr.driver WHERE driver_id = p_input.driver_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DRIVER_NOT_FOUND';
            v_result.error_message := 'driver_id=' || p_input.driver_id || ' no existe';
RETURN v_result;
END IF;
END IF;

    IF p_input.entity_type = 'TRIP' THEN
        IF p_input.trip_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ENTITY_TYPE_TRIP_REQUIRES_TRIP_ID';
            v_result.error_message := 'entity_type=TRIP requiere trip_id';
RETURN v_result;
END IF;
        -- NOTA: cuando exista la tabla trip se agrega aquí la validación de existencia
END IF;

    -- ── Validación 6: coordenadas coherentes si se proveen ────────────────
    IF (p_input.latitude IS NULL) <> (p_input.longitude IS NULL) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INCOMPLETE_COORDINATES';
        v_result.error_message := 'Debe proveer latitude y longitude juntas, o ninguna';
RETURN v_result;
END IF;

    IF p_input.latitude IS NOT NULL THEN
        IF p_input.latitude < -90 OR p_input.latitude > 90 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_LATITUDE';
            v_result.error_message := 'latitude fuera de rango [-90, 90]: '
                                      || p_input.latitude::TEXT;
RETURN v_result;
END IF;
        IF p_input.longitude < -180 OR p_input.longitude > 180 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_LONGITUDE';
            v_result.error_message := 'longitude fuera de rango [-180, 180]: '
                                      || p_input.longitude::TEXT;
RETURN v_result;
END IF;
END IF;

    -- ── Resolver timestamp ────────────────────────────────────────────────
    v_alert_ts := COALESCE(p_input.alert_timestamp, NOW());

    -- ── Calcular auto_closed_at si el tipo tiene auto_close_after_min ─────
    IF v_alert_type.auto_close_after_min IS NOT NULL THEN
        v_auto_closed_at := v_alert_ts
                            + (v_alert_type.auto_close_after_min || ' minutes')::INTERVAL;
ELSE
        v_auto_closed_at := NULL;
END IF;

    -- ── Insertar la alerta ────────────────────────────────────────────────
    -- La partición mensual se selecciona automáticamente por PostgreSQL
    -- según alert_timestamp.
INSERT INTO core_operations.alert (
    alert_type_id,
    entity_type,
    entity_id,
    trip_id,
    vehicle_id,
    driver_id,
    severity,
    alert_timestamp,
    latitude,
    longitude,
    description,
    metadata,
    auto_closed_at,
    status
)
VALUES (
           p_input.alert_type_id,
           p_input.entity_type,
           p_input.entity_id,
           p_input.trip_id,
           p_input.vehicle_id,
           p_input.driver_id,
           v_alert_type.severity,          -- siempre desde el catálogo, no editable externamente
           v_alert_ts,
           p_input.latitude,
           p_input.longitude,
           p_input.description,
           p_input.metadata,
           v_auto_closed_at,
           'ACTIVE'
       )
    RETURNING alert_id INTO v_alert_id;

-- ── Encolar notificaciones por canal ──────────────────────────────────
v_notifications := api._dispatch_alert_notifications(
        v_alert_id,
        p_input.alert_type_id,
        p_input.entity_type,
        p_input.entity_id,
        p_input.vehicle_id, -- vehicle_id tendrá valor solo cuando el ENTITY_TYPE sea vehicle
        p_input.driver_id
    );

    -- ── Poblar resultado ──────────────────────────────────────────────────
    v_result.success                 := TRUE;
    v_result.alert_id                := v_alert_id;
    v_result.alert_type_id           := v_alert_type.alert_type_id;
    v_result.alert_type_code         := v_alert_type.code;
    v_result.alert_type_name         := v_alert_type.name;
    v_result.entity_type             := p_input.entity_type;
    v_result.entity_id               := p_input.entity_id;
    v_result.vehicle_id              := p_input.vehicle_id;
    v_result.driver_id               := p_input.driver_id;
    v_result.trip_id                 := p_input.trip_id;
    v_result.severity                := v_alert_type.severity;
    v_result.status                  := 'ACTIVE';
    v_result.alert_timestamp         := v_alert_ts;
    v_result.auto_closed_at          := v_auto_closed_at;
    v_result.requires_acknowledgment := v_alert_type.requires_acknowledgment;
    v_result.notifications_queued    := v_notifications;
    v_result.notification_channels   := v_alert_type.notification_channels;
    v_result.created_at              := NOW();

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: create_configuration(api.create_configuration_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.create_configuration(p_input api.create_configuration_input) RETURNS api.create_configuration_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.create_configuration_result;
    v_existing      shared.configuration%ROWTYPE;
    v_dummy_int     BIGINT;
    v_dummy_bool    BOOLEAN;
    v_dummy_dec     DECIMAL;
    v_exists        BOOLEAN := FALSE;
BEGIN

    -- ── Validación 1: data_type conocido ──────────────────────────────────
    IF p_input.data_type NOT IN ('STRING', 'INTEGER', 'BOOLEAN', 'JSON', 'DECIMAL') THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'UNKNOWN_DATA_TYPE';
        v_result.error_message := 'data_type inválido: "' || p_input.data_type
                                  || '". Válidos: STRING, INTEGER, BOOLEAN, JSON, DECIMAL';
RETURN v_result;
END IF;

    -- ── Validación 2: valor casteable al data_type declarado ──────────────
BEGIN
CASE p_input.data_type
            WHEN 'INTEGER' THEN
                v_dummy_int := p_input.value::BIGINT;

WHEN 'BOOLEAN' THEN
                IF p_input.value NOT IN ('true', 'false', 'TRUE', 'FALSE', '1', '0') THEN
                    RAISE EXCEPTION 'not boolean';
END IF;

WHEN 'DECIMAL' THEN
                v_dummy_dec := p_input.value::DECIMAL;

WHEN 'JSON' THEN
                PERFORM p_input.value::JSONB;

ELSE
                -- STRING: cualquier valor es válido, no requiere cast
                NULL;
END CASE;
EXCEPTION
        WHEN OTHERS THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DATA_TYPE_VALUE';
            v_result.error_message := 'El valor "' || p_input.value
                                      || '" no es compatible con data_type=' || p_input.data_type;
RETURN v_result;
END;

    -- ── Verificar si la clave ya existe ───────────────────────────────────
SELECT * INTO v_existing
FROM shared.configuration
WHERE key = p_input.key;

IF FOUND THEN
        v_exists := TRUE;

        -- Modo insert puro: rechazar duplicado
        IF COALESCE(p_input.allow_update, FALSE) = FALSE THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DUPLICATE_CONFIG_KEY';
            v_result.error_message := 'La clave "' || p_input.key || '" ya existe. '
                                      || 'Use allow_update=true para actualizar';
RETURN v_result;
END IF;

        -- Modo upsert: verificar que sea editable
        IF v_existing.is_editable = FALSE THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'CONFIG_NOT_EDITABLE';
            v_result.error_message := 'La configuración "' || p_input.key
                                      || '" tiene is_editable=false y no puede ser modificada';
RETURN v_result;
END IF;

        -- Actualizar
UPDATE shared.configuration
SET
    value       = p_input.value,
    data_type   = p_input.data_type,
    description = COALESCE(p_input.description, v_existing.description),
    updated_at  = NOW()
WHERE key = p_input.key
    RETURNING
    config_id, key, value, data_type, is_editable, created_at, updated_at
INTO
    v_result.config_id, v_result.key, v_result.value,
    v_result.data_type, v_result.is_editable,
    v_result.created_at, v_result.updated_at;

v_result.operation := 'UPDATED';

ELSE
        -- Insertar nueva configuración
        INSERT INTO shared.configuration (
            key,
            value,
            data_type,
            description,
            is_editable
        )
        VALUES (
            p_input.key,
            p_input.value,
            p_input.data_type,
            p_input.description,
            COALESCE(p_input.is_editable, TRUE)
        )
        RETURNING
            config_id, key, value, data_type, is_editable, created_at, updated_at
        INTO
            v_result.config_id, v_result.key, v_result.value,
            v_result.data_type, v_result.is_editable,
            v_result.created_at, v_result.updated_at;

        v_result.operation := 'INSERTED';
END IF;

    v_result.success := TRUE;
RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: create_monthly_partitions(integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.create_monthly_partitions(p_months_ahead integer DEFAULT 2) RETURNS api.create_monthly_partitions_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.create_monthly_partitions_result;
    v_detail            api.partition_result[];
    v_item              api.partition_result;

    v_month_start       DATE;
    v_month_end         DATE;
    v_suffix            TEXT;       -- 'YYYY_MM'
    v_partition_name    TEXT;
    v_ddl               TEXT;

    v_total_created     INT := 0;
    v_total_exists      INT := 0;
    v_total_errors      INT := 0;

    -- Tablas particionadas por MES en el sistema
    -- schema | tabla_padre
    v_monthly_tables    TEXT[][] := ARRAY[
        ARRAY['identity',        'login_attempt'],
        ARRAY['identity',        'activity_log'],
        ARRAY['core_operations', 'alert']
    ];

    v_table_entry       TEXT[];
    v_schema            TEXT;
    v_table             TEXT;
    v_month_offset      INT;
BEGIN

    IF p_months_ahead < 0 OR p_months_ahead > 12 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_MONTHS_AHEAD';
        v_result.error_message := 'p_months_ahead debe estar entre 0 y 12';
RETURN v_result;
END IF;

    v_detail := ARRAY[]::api.partition_result[];

    -- Iterar: mes actual + p_months_ahead meses futuros
FOR v_month_offset IN 0..p_months_ahead
    LOOP
        v_month_start := DATE_TRUNC('month', CURRENT_DATE + (v_month_offset || ' months')::INTERVAL)::DATE;
        v_month_end   := (v_month_start + INTERVAL '1 month')::DATE;
        v_suffix      := TO_CHAR(v_month_start, 'YYYY_MM');

        FOREACH v_table_entry SLICE 1 IN ARRAY v_monthly_tables
        LOOP
            v_schema         := v_table_entry[1];
            v_table          := v_table_entry[2];
            v_partition_name := v_table || '_' || v_suffix;

            v_item.table_name      := v_schema || '.' || v_table;
            v_item.partition_name  := v_schema || '.' || v_partition_name;
            v_item.period          := v_suffix;
            v_item.status          := NULL;
            v_item.error_message   := NULL;

            -- Verificar si la partición ya existe
            IF EXISTS (
                SELECT 1
                FROM pg_class     c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE n.nspname = v_schema
                  AND c.relname = v_partition_name
            ) THEN
                v_item.status   := 'ALREADY_EXISTS';
                v_total_exists  := v_total_exists + 1;
                v_detail        := v_detail || v_item;
CONTINUE;
END IF;

            -- Construir y ejecutar el DDL de creación
BEGIN
                v_ddl := FORMAT(
                    'CREATE TABLE %I.%I PARTITION OF %I.%I
                     FOR VALUES FROM (%L) TO (%L)',
                    v_schema, v_partition_name,
                    v_schema, v_table,
                    v_month_start::TEXT,
                    v_month_end::TEXT
                );

EXECUTE v_ddl;

v_item.status   := 'CREATED';
                v_total_created := v_total_created + 1;

EXCEPTION
                WHEN OTHERS THEN
                    v_item.status        := 'ERROR';
                    v_item.error_message := SQLERRM;
                    v_total_errors       := v_total_errors + 1;
END;

            v_detail := v_detail || v_item;
END LOOP;
END LOOP;

    v_result.success             := TRUE;
    v_result.months_ahead        := p_months_ahead;
    v_result.total_created       := v_total_created;
    v_result.total_already_exist := v_total_exists;
    v_result.total_errors        := v_total_errors;
    v_result.detail              := v_detail;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_detail;
RETURN v_result;
END;
$$;


--
-- Name: create_user_session(api.create_user_session_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.create_user_session(p_input api.create_user_session_input) RETURNS api.create_user_session_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.create_user_session_result;
    v_user                  identity.user%ROWTYPE;
    v_session_id            BIGINT;
    v_max_sessions          INT;
    v_active_session_count  INT;
    v_other_sessions        api.concurrent_session_info[];
    v_session_info          api.concurrent_session_info;
    v_cfg_value             TEXT;
BEGIN

    -- ── Validación 1: usuario existe y está activo ────────────────────────
SELECT * INTO v_user
FROM identity.user
WHERE user_id = p_input.user_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'USER_NOT_FOUND';
        v_result.error_message := 'El user_id=' || p_input.user_id || ' no existe';
RETURN v_result;
END IF;

    IF v_user.is_active = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'USER_INACTIVE';
        v_result.error_message := 'El usuario "' || v_user.username
                                  || '" está inactivo y no puede iniciar sesión';
RETURN v_result;
END IF;

    -- ── Validación 2: token duplicado ─────────────────────────────────────
    IF EXISTS (
        SELECT 1 FROM identity.user_session
        WHERE token = p_input.token
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_TOKEN';
        v_result.error_message := 'El token ya existe en el sistema. '
                                  || 'Regenere el token e intente nuevamente';
RETURN v_result;
END IF;

    -- ── Validación 3: expires_at debe ser futuro ──────────────────────────
    IF p_input.expires_at IS NULL OR p_input.expires_at <= NOW() THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_EXPIRY';
        v_result.error_message := 'expires_at debe ser una fecha futura. '
                                  || 'Valor recibido: '
                                  || COALESCE(p_input.expires_at::TEXT, 'NULL');
RETURN v_result;
END IF;

    -- ── Leer límite de sesiones concurrentes desde configuración ──────────
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'security.max_concurrent_sessions';

-- Si no existe la clave o no es parseable, se permite sin límite (NULL)
BEGIN
        v_max_sessions := v_cfg_value::INT;
EXCEPTION
        WHEN OTHERS THEN
            v_max_sessions := NULL;
END;

    -- ── Contar sesiones activas vigentes del usuario ───────────────────────
SELECT COUNT(*) INTO v_active_session_count
FROM identity.user_session
WHERE user_id   = p_input.user_id
  AND is_active = TRUE
  AND expires_at > NOW();

-- ── Recopilar detalle de sesiones concurrentes (para el result) ────────
SELECT ARRAY_AGG(
               ROW(
                       s.session_id,
                       s.ip_address,
                       s.started_at,
                       s.last_activity_at
               )::api.concurrent_session_info
        ORDER BY s.last_activity_at DESC
       )
INTO v_other_sessions
FROM identity.user_session s
WHERE s.user_id   = p_input.user_id
  AND s.is_active = TRUE
  AND s.expires_at > NOW();

-- ── Validación 4: límite de sesiones concurrentes ─────────────────────
IF v_max_sessions IS NOT NULL
       AND v_active_session_count >= v_max_sessions
    THEN
        v_result.success                := FALSE;
        v_result.error_code             := 'MAX_SESSIONS_EXCEEDED';
        v_result.error_message          := 'El usuario ya tiene ' || v_active_session_count
                                           || ' sesión(es) activa(s). '
                                           || 'El límite configurado es '
                                           || v_max_sessions || '. '
                                           || 'Cierre una sesión existente e intente nuevamente';
        v_result.concurrent_sessions    := v_active_session_count;
        v_result.max_allowed_sessions   := v_max_sessions;
        v_result.other_active_sessions  := v_other_sessions;
RETURN v_result;
END IF;

    -- ── Insertar sesión ───────────────────────────────────────────────────
INSERT INTO identity.user_session (
    user_id,
    token,
    ip_address,
    user_agent,
    started_at,
    last_activity_at,
    expires_at,
    is_active
)
VALUES (
           p_input.user_id,
           p_input.token,
           p_input.ip_address,
           p_input.user_agent,
           NOW(),
           NOW(),
           p_input.expires_at,
           TRUE
       )
    RETURNING session_id INTO v_session_id;

-- ── Poblar resultado campo a campo ────────────────────────────────────
SELECT
    s.session_id,
    s.user_id,
    s.token,
    s.ip_address,
    s.started_at,
    s.expires_at,
    s.is_active,
    s.created_at
INTO
    v_result.session_id,
    v_result.user_id,
    v_result.token,
    v_result.ip_address,
    v_result.started_at,
    v_result.expires_at,
    v_result.is_active,
    v_result.created_at
FROM identity.user_session s
WHERE s.session_id = v_session_id;

v_result.success                := TRUE;
    v_result.concurrent_sessions    := v_active_session_count;  -- sesiones previas (sin contar la nueva)
    v_result.max_allowed_sessions   := v_max_sessions;
    v_result.other_active_sessions  := v_other_sessions;

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_TOKEN';
        v_result.error_message := 'Colisión de token detectada por concurrencia. '
                                  || 'Regenere el token e intente nuevamente';
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: create_weekly_partitions(integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.create_weekly_partitions(p_weeks_ahead integer DEFAULT 3) RETURNS api.create_monthly_partitions_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.create_monthly_partitions_result;
    v_detail            api.partition_result[];
    v_item              api.partition_result;

    v_week_start        DATE;
    v_week_end          DATE;
    v_suffix            TEXT;       -- 'YYYY_wWW'
    v_partition_name    TEXT;
    v_ddl               TEXT;

    v_total_created     INT := 0;
    v_total_exists      INT := 0;
    v_total_errors      INT := 0;

    v_weekly_tables     TEXT[][] := ARRAY[
        ARRAY['fleet',           'gps_raw_event'],
        ARRAY['core_operations', 'trip_location']
    ];

    v_table_entry       TEXT[];
    v_schema            TEXT;
    v_table             TEXT;
    v_week_offset       INT;
BEGIN

    IF p_weeks_ahead < 0 OR p_weeks_ahead > 52 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_WEEKS_AHEAD';
        v_result.error_message := 'p_weeks_ahead debe estar entre 0 y 52';
RETURN v_result;
END IF;

    v_detail := ARRAY[]::api.partition_result[];

FOR v_week_offset IN 0..p_weeks_ahead
    LOOP
        -- Inicio de la semana (lunes) para cada offset
        v_week_start := DATE_TRUNC('week', CURRENT_DATE + (v_week_offset * 7 || ' days')::INTERVAL)::DATE;
        v_week_end   := v_week_start + 7;
        v_suffix     := TO_CHAR(v_week_start, 'YYYY') || '_w' || LPAD(TO_CHAR(v_week_start, 'IW'), 2, '0');

        FOREACH v_table_entry SLICE 1 IN ARRAY v_weekly_tables
        LOOP
            v_schema         := v_table_entry[1];
            v_table          := v_table_entry[2];
            v_partition_name := v_table || '_' || v_suffix;

            v_item.table_name      := v_schema || '.' || v_table;
            v_item.partition_name  := v_schema || '.' || v_partition_name;
            v_item.period          := v_suffix;
            v_item.status          := NULL;
            v_item.error_message   := NULL;

            IF EXISTS (
                SELECT 1
                FROM pg_class     c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE n.nspname = v_schema
                  AND c.relname = v_partition_name
            ) THEN
                v_item.status   := 'ALREADY_EXISTS';
                v_total_exists  := v_total_exists + 1;
                v_detail        := v_detail || v_item;
CONTINUE;
END IF;

BEGIN
                v_ddl := FORMAT(
                    'CREATE TABLE %I.%I PARTITION OF %I.%I
                     FOR VALUES FROM (%L) TO (%L)',
                    v_schema, v_partition_name,
                    v_schema, v_table,
                    v_week_start::TEXT,
                    v_week_end::TEXT
                );

EXECUTE v_ddl;

v_item.status   := 'CREATED';
                v_total_created := v_total_created + 1;

EXCEPTION
                WHEN OTHERS THEN
                    v_item.status        := 'ERROR';
                    v_item.error_message := SQLERRM;
                    v_total_errors       := v_total_errors + 1;
END;

            v_detail := v_detail || v_item;
END LOOP;
END LOOP;

    v_result.success             := TRUE;
    v_result.months_ahead        := p_weeks_ahead;   -- reusamos el campo como "periods_ahead"
    v_result.total_created       := v_total_created;
    v_result.total_already_exist := v_total_exists;
    v_result.total_errors        := v_total_errors;
    v_result.detail              := v_detail;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_detail;
RETURN v_result;
END;
$$;


--
-- Name: deactivate_route(api.deactivate_route_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.deactivate_route(p_input api.deactivate_route_input) RETURNS api.deactivate_route_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.deactivate_route_result;
    v_route             core_operations.route%ROWTYPE;
    v_stops_deactivated INT := 0;
    v_log_id            BIGINT;
    v_changes           JSONB;
    v_deactivated_at    TIMESTAMPTZ := NOW();
BEGIN

    -- ── Validación 1: route_id obligatorio ────────────────────────────────
    IF p_input.route_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ROUTE_ID';
        v_result.error_message := 'route_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: la ruta existe ──────────────────────────────────────
SELECT * INTO v_route
FROM core_operations.route
WHERE route_id = p_input.route_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROUTE_NOT_FOUND';
        v_result.error_message := 'La ruta route_id=' || p_input.route_id || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 3: deactivated_by existe si se proveyó ─────────────────
    IF p_input.deactivated_by IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM identity."user"
            WHERE user_id = p_input.deactivated_by AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'USER_NOT_FOUND';
            v_result.error_message := 'El user_id=' || p_input.deactivated_by
                                      || ' indicado en deactivated_by no existe o está inactivo';
RETURN v_result;
END IF;
END IF;

    -- ── Caso especial: ruta ya inactiva — warning, no error duro ──────────
    IF v_route.is_active = FALSE THEN
        v_result.success             := TRUE;
        v_result.error_code          := NULL;
        v_result.error_message       := NULL;
        v_result.warning             := 'ROUTE_ALREADY_INACTIVE: La ruta "'
                                        || v_route.code
                                        || '" ya estaba inactiva. No se realizó ningún cambio';
        v_result.route_id            := v_route.route_id;
        v_result.route_code          := v_route.code;
        v_result.route_name          := v_route.name;
        v_result.company_id          := v_route.company_id;
        v_result.was_active          := FALSE;
        v_result.stops_deactivated   := 0;
        v_result.activity_log_id     := NULL;  -- no se loguea acción sin efecto
        v_result.deactivated_by      := p_input.deactivated_by;
        v_result.deactivated_at      := v_deactivated_at;
        v_result.updated_at          := v_route.updated_at;
RETURN v_result;
END IF;

    -- ── NOTA sobre ROUTE_HAS_ACTIVE_TRIPS ────────────────────────────────
    -- La tabla 'trip' vinculada a rutas no está presente en el schema actual.
    -- Cuando exista, agregar aquí:
    --   IF EXISTS (SELECT 1 FROM core_operations.trip
    --              WHERE route_id = p_input.route_id AND status IN ('IN_PROGRESS','SCHEDULED'))
    --   THEN ... RETURN error ROUTE_HAS_ACTIVE_TRIPS ... END IF;

    -- ── Desactivar la ruta ────────────────────────────────────────────────
UPDATE core_operations.route
SET is_active  = FALSE,
    updated_at = v_deactivated_at
WHERE route_id = p_input.route_id;

-- ── Desactivar paradas en cascada ─────────────────────────────────────
UPDATE core_operations.route_stop
SET is_active = FALSE
WHERE route_id = p_input.route_id
  AND is_active = TRUE;  -- solo las que estaban activas (para contar correctamente)

GET DIAGNOSTICS v_stops_deactivated = ROW_COUNT;

-- ── Construir snapshot JSONB para activity_log ────────────────────────
v_changes := jsonb_build_object(
        'before', jsonb_build_object(
            'is_active', TRUE,
            'code',      v_route.code,
            'name',      v_route.name
        ),
        'after', jsonb_build_object(
            'is_active', FALSE,
            'code',      v_route.code,
            'name',      v_route.name
        ),
        'fields_changed', jsonb_build_array('is_active'),
        'stops_deactivated', v_stops_deactivated,
        'reason', p_input.reason
    );

    -- ── Registrar en identity.activity_log ───────────────────────────────
INSERT INTO identity.activity_log (
    user_id,
    action,
    resource_type,
    resource_id,
    changes,
    status,
    created_at
)
VALUES (
           p_input.deactivated_by,
           'ROUTE_DEACTIVATE',
           'core_operations.route',
           p_input.route_id,
           v_changes,
           'SUCCESS',
           v_deactivated_at
       )
    RETURNING log_id INTO v_log_id;

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success             := TRUE;
    v_result.error_code          := NULL;
    v_result.error_message       := NULL;
    v_result.warning             := NULL;
    v_result.route_id            := v_route.route_id;
    v_result.route_code          := v_route.code;
    v_result.route_name          := v_route.name;
    v_result.company_id          := v_route.company_id;
    v_result.was_active          := TRUE;
    v_result.stops_deactivated   := v_stops_deactivated;
    v_result.activity_log_id     := v_log_id;
    v_result.deactivated_by      := p_input.deactivated_by;
    v_result.deactivated_at      := v_deactivated_at;
    v_result.updated_at          := v_deactivated_at;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: deduct_license_points(api.deduct_license_points_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.deduct_license_points(p_input api.deduct_license_points_input) RETURNS api.deduct_license_points_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.deduct_license_points_result;
    v_driver            hr.driver%ROWTYPE;
    v_person            hr.person%ROWTYPE;
    v_points_after      INT;
    v_min_threshold     INT;
    v_cfg_value         TEXT;
    v_dispatch_blocked  BOOLEAN := FALSE;
    v_new_is_available  BOOLEAN;
    v_log_id            BIGINT;
    v_changes           JSONB;
BEGIN

    -- ── Validación 1: cantidad a deducir debe ser > 0 ─────────────────────
    IF p_input.points IS NULL OR p_input.points <= 0 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_POINTS_AMOUNT';
        v_result.error_message := 'La cantidad de puntos a deducir debe ser mayor a 0. '
                                  || 'Recibido: ' || COALESCE(p_input.points::TEXT, 'NULL');
RETURN v_result;
END IF;

    -- ── Validación 2: conductor existe ────────────────────────────────────
SELECT * INTO v_driver
FROM hr.driver
WHERE driver_id = p_input.driver_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DRIVER_NOT_FOUND';
        v_result.error_message := 'El conductor driver_id=' || p_input.driver_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- Datos de la persona para el result
SELECT * INTO v_person
FROM hr.person
WHERE person_id = v_driver.person_id;

-- ── Validación 3: ya está en 0, no se puede deducir más ───────────────
IF v_driver.license_points = 0 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'POINTS_ALREADY_ZERO';
        v_result.error_message := 'El conductor "' || v_person.full_name
                                  || '" ya tiene 0 puntos de licencia. '
                                  || 'No se puede deducir más';
RETURN v_result;
END IF;

    -- ── Calcular puntos resultantes (mínimo 0) ────────────────────────────
    v_points_after := GREATEST(v_driver.license_points - p_input.points, 0);

    -- ── Leer umbral mínimo desde configuración ────────────────────────────
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'dispatch.min_license_points';

BEGIN
        v_min_threshold := COALESCE(NULLIF(TRIM(v_cfg_value), ''), '75')::INT;
EXCEPTION
        WHEN OTHERS THEN
            v_min_threshold := 75;  -- fallback seguro
END;

    -- ── Determinar si se bloquea el despacho ──────────────────────────────
    -- Bloquear si: resultado < umbral Y el conductor aún está ACTIVE
    IF v_points_after < v_min_threshold
       AND v_driver.employment_status = 'ACTIVE'
    THEN
        v_dispatch_blocked  := TRUE;
        v_new_is_available  := FALSE;
ELSE
        v_dispatch_blocked  := FALSE;
        v_new_is_available  := v_driver.is_available;  -- conservar estado actual
END IF;

    -- ── Construir JSON before/after para activity_log ─────────────────────
    v_changes := JSONB_BUILD_OBJECT(
        'before', JSONB_BUILD_OBJECT(
            'license_points',   v_driver.license_points,
            'is_available',     v_driver.is_available
        ),
        'after', JSONB_BUILD_OBJECT(
            'license_points',   v_points_after,
            'is_available',     v_new_is_available
        ),
        'points_deducted',  p_input.points,
        'reason',           p_input.reason,
        'dispatch_blocked', v_dispatch_blocked,
        'min_threshold',    v_min_threshold
    );

    -- ── Actualizar hr.driver ──────────────────────────────────────────────
UPDATE hr.driver
SET
    license_points  = v_points_after,
    is_available    = v_new_is_available,
    notes           = COALESCE(notes || E'\n', '')
        || TO_CHAR(NOW(), 'YYYY-MM-DD HH24:MI')
        || ' [PUNTOS -' || p_input.points::TEXT || '] '
                          || COALESCE(p_input.reason, 'Sin motivo especificado'),
        updated_at      = NOW()
WHERE driver_id = p_input.driver_id;

-- ── Registrar en identity.activity_log ───────────────────────────────
INSERT INTO identity.activity_log (
    user_id,
    action,
    resource_type,
    resource_id,
    changes,
    status,
    created_at
)
VALUES (
           p_input.changed_by,
           'DRIVER_LICENSE_POINTS_DEDUCT',
           'hr.driver',
           p_input.driver_id,
           v_changes,
           'SUCCESS',
           NOW()
       )
    RETURNING log_id INTO v_log_id;

-- ── Poblar resultado campo a campo ────────────────────────────────────
v_result.success            := TRUE;
    v_result.driver_id          := p_input.driver_id;
    v_result.driver_code        := v_driver.driver_code;
    v_result.full_name          := v_person.full_name;
    v_result.points_deducted    := p_input.points;
    v_result.points_before      := v_driver.license_points;
    v_result.points_after       := v_points_after;
    v_result.min_threshold      := v_min_threshold;
    v_result.dispatch_blocked   := v_dispatch_blocked;
    v_result.is_available       := v_new_is_available;
    v_result.activity_log_id    := v_log_id;
    v_result.changed_by         := p_input.changed_by;
    v_result.updated_at         := NOW();

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: delete_gps_device(api.delete_gps_device_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.delete_gps_device(p_input api.delete_gps_device_input) RETURNS api.delete_gps_device_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result api.delete_gps_device_result;
    v_device fleet.gps_device%ROWTYPE;
BEGIN
    -- Buscar el dispositivo
SELECT *
INTO v_device
FROM fleet.gps_device
WHERE
    (p_input.gps_device_id IS NOT NULL AND gps_device_id = p_input.gps_device_id)
   OR
    (p_input.device_id IS NOT NULL AND device_id = p_input.device_id)
    LIMIT 1;

-- No existe
IF NOT FOUND THEN
        v_result.success := FALSE;
        v_result.error_code := 'NOT_FOUND';
        v_result.error_message := 'GPS device no encontrado';
RETURN v_result;
END IF;

-- TODO : (Opcional) Validación de negocio
-- Ejemplo: evitar borrar si está asociado a vehículo
-- IF v_device.vehicle_id IS NOT NULL THEN
--     v_result.success := FALSE;
--     v_result.error_code := 'DEVICE_IN_USE';
--     v_result.error_message := 'El dispositivo está asignado a un vehículo';
--     RETURN v_result;
-- END IF;

    -- Delete físico
DELETE FROM fleet.gps_device
WHERE gps_device_id = v_device.gps_device_id;

--  Resultado
v_result.success := TRUE;
    v_result.gps_device_id := v_device.gps_device_id;
    v_result.device_id := v_device.device_id;
    v_result.deleted_at := NOW();

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success := FALSE;
        v_result.error_code := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: delete_vehicle(character varying); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.delete_vehicle(p_plate_number character varying) RETURNS api.delete_vehicle_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result api.delete_vehicle_result;
    v_deleted_plate VARCHAR;
BEGIN
    -- Inicialización
    v_result.success := true;
    v_result.error_code := NULL;
    v_result.error_message := NULL;

    -- Intentar eliminar
DELETE FROM fleet.vehicle
WHERE plate_number = p_plate_number
    RETURNING plate_number INTO v_deleted_plate;

-- Validar si existía
IF v_deleted_plate IS NULL THEN
        RAISE EXCEPTION 'Vehículo con placa % no existe', p_plate_number
            USING ERRCODE = 'P0002'; -- no_data_found custom
END IF;

    v_result.plate_number := v_deleted_plate;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success := false;
        v_result.error_code := SQLSTATE;
        v_result.error_message := SQLERRM;
        v_result.plate_number := NULL;
RETURN v_result;
END;
$$;


--
-- Name: evaluate_gps_alerts(api.evaluate_gps_alerts_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.evaluate_gps_alerts(p_input api.evaluate_gps_alerts_input) RETURNS api.evaluate_gps_alerts_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.evaluate_gps_alerts_result;
    v_event             fleet.gps_raw_event%ROWTYPE;
    v_vehicle           fleet.vehicle%ROWTYPE;
    v_driver_id         INT;
    v_item              api.alert_evaluated_item;
    v_items             api.alert_evaluated_item[]
                            := ARRAY[]::api.alert_evaluated_item[];
    v_alerts_inserted   INT := 0;
    v_alerts_updated    INT := 0;
    v_rules_evaluated   INT := 0;
    -- Umbrales desde configuración
    v_max_speed_kmh     NUMERIC;
    v_max_stopped_min   NUMERIC;
    v_max_signal_min    NUMERIC;
    v_cfg_value         TEXT;
    -- Para evaluación de STOPPED
    v_prev_speed        NUMERIC;
    v_stopped_since     TIMESTAMPTZ;
    v_stopped_minutes   NUMERIC;
    -- Para evaluación de SIGNAL_LOST
    v_last_comm_at      TIMESTAMPTZ;
    v_signal_lost_min   NUMERIC;
    -- Para upsert de alertas
    v_alert_type        core_operations.alert_type%ROWTYPE;
    v_existing_alert_id BIGINT;
    v_existing_alert_ts TIMESTAMPTZ;
    v_new_alert_id      BIGINT;
    v_alert_ts          TIMESTAMPTZ;
BEGIN

    -- ── Validación 1: raw_event_id obligatorio ────────────────────────────
    IF p_input.raw_event_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_RAW_EVENT_ID';
        v_result.error_message := 'raw_event_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Resolver el evento GPS ────────────────────────────────────────────
    -- Búsqueda en la tabla particionada: primero en el mes actual, luego
    -- en el anterior para cubrir eventos de cambio de mes.
SELECT * INTO v_event
FROM fleet.gps_raw_event
WHERE raw_event_id = p_input.raw_event_id
  AND gps_timestamp >= date_trunc('month', NOW()) - INTERVAL '1 month'
ORDER BY gps_timestamp DESC
    LIMIT 1;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'RAW_EVENT_NOT_FOUND';
        v_result.error_message := 'El evento raw_event_id=' || p_input.raw_event_id
                                  || ' no existe o es demasiado antiguo';
RETURN v_result;
END IF;

    -- ── Resolver vehicle_id ───────────────────────────────────────────────
    -- Prioridad: input > evento GPS
    v_event.vehicle_id := COALESCE(p_input.vehicle_id, v_event.vehicle_id);

    IF v_event.vehicle_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_FOUND';
        v_result.error_message := 'El evento raw_event_id=' || p_input.raw_event_id
                                  || ' no tiene vehicle_id asociado. '
                                  || 'Provéalo en el input o asigne el dispositivo GPS al vehículo';
RETURN v_result;
END IF;

    -- ── Resolver datos del vehículo ───────────────────────────────────────
SELECT * INTO v_vehicle
FROM fleet.vehicle
WHERE vehicle_id = v_event.vehicle_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_FOUND';
        v_result.error_message := 'vehicle_id=' || v_event.vehicle_id || ' no existe';
RETURN v_result;
END IF;

    -- ── Resolver driver activo del vehículo (si tiene asignación) ─────────
SELECT d.driver_id INTO v_driver_id
FROM fleet.vehicle_assignment va
         JOIN hr.driver d ON d.driver_id = va.driver_id
WHERE va.vehicle_id = v_event.vehicle_id
  AND va.is_active  = TRUE
    LIMIT 1;

-- ── Leer umbrales desde configuración ─────────────────────────────────
-- gps.max_speed_kmh: velocidad máxima permitida (default 80)
SELECT value INTO v_cfg_value FROM shared.configuration
WHERE key = 'gps.max_speed_kmh';
BEGIN v_max_speed_kmh := COALESCE(NULLIF(TRIM(v_cfg_value),''),'80')::NUMERIC;
EXCEPTION WHEN OTHERS THEN v_max_speed_kmh := 80; END;

    -- gps.max_stopped_minutes: minutos detenido fuera de terminal que genera alerta (default 10)
SELECT value INTO v_cfg_value FROM shared.configuration
WHERE key = 'gps.max_stopped_minutes';
BEGIN v_max_stopped_min := COALESCE(NULLIF(TRIM(v_cfg_value),''),'10')::NUMERIC;
EXCEPTION WHEN OTHERS THEN v_max_stopped_min := 10; END;

    -- gps.max_signal_lost_minutes: minutos sin señal antes de alerta (default 15)
SELECT value INTO v_cfg_value FROM shared.configuration
WHERE key = 'gps.max_signal_lost_minutes';
BEGIN v_max_signal_min := COALESCE(NULLIF(TRIM(v_cfg_value),''),'15')::NUMERIC;
EXCEPTION WHEN OTHERS THEN v_max_signal_min := 15; END;

    -- Fijar timestamp del evento para el alert
    v_alert_ts := v_event.gps_timestamp;

    -- ══════════════════════════════════════════════════════════════════════
    -- REGLA 1: SPEEDING — velocidad excesiva
    -- ══════════════════════════════════════════════════════════════════════
    v_rules_evaluated := v_rules_evaluated + 1;
    v_item := ROW(NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)::api.alert_evaluated_item;
    v_item.alert_type_code := 'SPEEDING';
    v_item.threshold_value := v_max_speed_kmh;
    v_item.observed_value  := v_event.speed_kmh;

    -- Buscar el alert_type en catálogo
SELECT * INTO v_alert_type
FROM core_operations.alert_type
WHERE code = 'SPEEDING' AND is_active = TRUE;

IF NOT FOUND THEN
        v_item.alert_action := 'SKIPPED_CONFIG_MISSING';
        v_item.rule_triggered := FALSE;
        v_item.description := 'alert_type SPEEDING no encontrado o inactivo';
    ELSIF v_event.speed_kmh IS NULL OR v_event.speed_kmh <= v_max_speed_kmh THEN
        v_item.rule_triggered := FALSE;
        v_item.alert_action   := 'SKIPPED_NO_VIOLATION';
        v_item.alert_type_id  := v_alert_type.alert_type_id;
        v_item.description    := 'Velocidad dentro del límite';
ELSE
        -- Violación detectada: upsert de alerta
        v_item.rule_triggered := TRUE;
        v_item.alert_type_id  := v_alert_type.alert_type_id;
        v_item.description    := 'Velocidad ' || v_event.speed_kmh::TEXT
                                  || ' km/h supera el límite de '
                                  || v_max_speed_kmh::TEXT || ' km/h';

        -- ¿Ya existe alerta ACTIVE del mismo tipo para este vehículo?
SELECT alert_id, alert_timestamp INTO v_existing_alert_id, v_existing_alert_ts
FROM core_operations.alert
WHERE vehicle_id     = v_event.vehicle_id
  AND alert_type_id  = v_alert_type.alert_type_id
  AND status         = 'ACTIVE'
  AND alert_timestamp >= date_trunc('month', NOW()) - INTERVAL '1 month'
ORDER BY alert_timestamp DESC
    LIMIT 1;

IF FOUND THEN
            -- UPDATE: refrescar timestamp, coordenadas y metadata de la alerta existente
UPDATE core_operations.alert
SET alert_timestamp = v_alert_ts,
    latitude        = v_event.latitude,
    longitude       = v_event.longitude,
    description     = v_item.description,
    metadata        = jsonb_build_object(
            'raw_event_id', v_event.raw_event_id,
            'speed_kmh',    v_event.speed_kmh,
            'threshold',    v_max_speed_kmh
                      )
WHERE alert_id        = v_existing_alert_id
  AND alert_timestamp  = v_existing_alert_ts;

v_item.alert_id     := v_existing_alert_id;
            v_item.alert_action := 'UPDATED';
            v_alerts_updated    := v_alerts_updated + 1;
ELSE
            -- INSERT: nueva alerta de exceso de velocidad
            INSERT INTO core_operations.alert (
                alert_type_id, entity_type, entity_id,
                vehicle_id, driver_id,
                severity, alert_timestamp,
                latitude, longitude,
                description, metadata, status
            )
            VALUES (
                v_alert_type.alert_type_id, 'VEHICLE', v_event.vehicle_id,
                v_event.vehicle_id, v_driver_id,
                v_alert_type.severity, v_alert_ts,
                v_event.latitude, v_event.longitude,
                v_item.description,
                jsonb_build_object(
                    'raw_event_id', v_event.raw_event_id,
                    'speed_kmh',    v_event.speed_kmh,
                    'threshold',    v_max_speed_kmh
                ),
                'ACTIVE'
            )
            RETURNING alert_id INTO v_new_alert_id;

            v_item.alert_id     := v_new_alert_id;
            v_item.alert_action := 'INSERTED';
            v_alerts_inserted   := v_alerts_inserted + 1;
END IF;
END IF;

    v_items := v_items || v_item;

    -- ══════════════════════════════════════════════════════════════════════
    -- REGLA 2: VEHICLE_STOPPED — detenido fuera de terminal por mucho tiempo
    -- Aproximación: si speed=0 y el evento anterior también tenía speed=0,
    -- calculamos cuánto tiempo lleva detenido consultando el evento más
    -- reciente con speed > 0 en las últimas 2 horas.
    -- ══════════════════════════════════════════════════════════════════════
    v_rules_evaluated := v_rules_evaluated + 1;
    v_item := ROW(NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)::api.alert_evaluated_item;
    v_item.alert_type_code := 'VEHICLE_STOPPED';
    v_item.threshold_value := v_max_stopped_min;

SELECT * INTO v_alert_type
FROM core_operations.alert_type
WHERE code = 'VEHICLE_STOPPED' AND is_active = TRUE;

IF NOT FOUND THEN
        v_item.alert_action   := 'SKIPPED_CONFIG_MISSING';
        v_item.rule_triggered := FALSE;
        v_item.description    := 'alert_type VEHICLE_STOPPED no encontrado o inactivo';
    ELSIF v_event.speed_kmh IS NULL OR v_event.speed_kmh > 0 THEN
        -- El vehículo se está moviendo: no aplica
        v_item.rule_triggered := FALSE;
        v_item.alert_action   := 'SKIPPED_NO_VIOLATION';
        v_item.alert_type_id  := v_alert_type.alert_type_id;
        v_item.observed_value := 0;
        v_item.description    := 'Vehículo en movimiento (speed=' || COALESCE(v_event.speed_kmh::TEXT,'NULL') || ' km/h)';
ELSE
        -- Velocidad = 0: buscar cuándo fue la última vez que se movió
SELECT gps_timestamp INTO v_stopped_since
FROM fleet.gps_raw_event
WHERE vehicle_id   = v_event.vehicle_id
  AND speed_kmh    > 0
  AND gps_timestamp BETWEEN v_alert_ts - INTERVAL '2 hours' AND v_alert_ts
ORDER BY gps_timestamp DESC
    LIMIT 1;

IF v_stopped_since IS NULL THEN
            -- Sin movimiento en las últimas 2 horas: asumir detenido desde hace 2h
            v_stopped_minutes := 120;
ELSE
            v_stopped_minutes := ROUND(
                EXTRACT(EPOCH FROM (v_alert_ts - v_stopped_since)) / 60.0, 2
            );
END IF;

        v_item.alert_type_id  := v_alert_type.alert_type_id;
        v_item.observed_value := v_stopped_minutes;

        IF v_stopped_minutes <= v_max_stopped_min THEN
            v_item.rule_triggered := FALSE;
            v_item.alert_action   := 'SKIPPED_NO_VIOLATION';
            v_item.description    := 'Detenido ' || v_stopped_minutes::TEXT
                                     || ' min (bajo el límite de ' || v_max_stopped_min::TEXT || ' min)';
ELSE
            v_item.rule_triggered := TRUE;
            v_item.description    := 'Vehículo detenido ' || v_stopped_minutes::TEXT
                                     || ' min, supera límite de ' || v_max_stopped_min::TEXT || ' min';

SELECT alert_id, alert_timestamp INTO v_existing_alert_id, v_existing_alert_ts
FROM core_operations.alert
WHERE vehicle_id    = v_event.vehicle_id
  AND alert_type_id = v_alert_type.alert_type_id
  AND status        = 'ACTIVE'
  AND alert_timestamp >= date_trunc('month', NOW()) - INTERVAL '1 month'
ORDER BY alert_timestamp DESC
    LIMIT 1;

IF FOUND THEN
UPDATE core_operations.alert
SET alert_timestamp = v_alert_ts,
    latitude        = v_event.latitude,
    longitude       = v_event.longitude,
    description     = v_item.description,
    metadata        = jsonb_build_object(
            'raw_event_id',    v_event.raw_event_id,
            'stopped_minutes', v_stopped_minutes,
            'threshold_min',   v_max_stopped_min
                      )
WHERE alert_id       = v_existing_alert_id
  AND alert_timestamp = v_existing_alert_ts;

v_item.alert_id     := v_existing_alert_id;
                v_item.alert_action := 'UPDATED';
                v_alerts_updated    := v_alerts_updated + 1;
ELSE
                INSERT INTO core_operations.alert (
                    alert_type_id, entity_type, entity_id,
                    vehicle_id, driver_id,
                    severity, alert_timestamp,
                    latitude, longitude,
                    description, metadata, status
                )
                VALUES (
                    v_alert_type.alert_type_id, 'VEHICLE', v_event.vehicle_id,
                    v_event.vehicle_id, v_driver_id,
                    v_alert_type.severity, v_alert_ts,
                    v_event.latitude, v_event.longitude,
                    v_item.description,
                    jsonb_build_object(
                        'raw_event_id',    v_event.raw_event_id,
                        'stopped_minutes', v_stopped_minutes,
                        'threshold_min',   v_max_stopped_min
                    ),
                    'ACTIVE'
                )
                RETURNING alert_id INTO v_new_alert_id;

                v_item.alert_id     := v_new_alert_id;
                v_item.alert_action := 'INSERTED';
                v_alerts_inserted   := v_alerts_inserted + 1;
END IF;
END IF;
END IF;

    v_items := v_items || v_item;

    -- ══════════════════════════════════════════════════════════════════════
    -- REGLA 3: SIGNAL_LOST — tiempo sin señal GPS
    -- Se evalúa comparando last_communication_at del dispositivo con NOW()
    -- ══════════════════════════════════════════════════════════════════════
    v_rules_evaluated := v_rules_evaluated + 1;
    v_item := ROW(NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)::api.alert_evaluated_item;
    v_item.alert_type_code := 'SIGNAL_LOST';
    v_item.threshold_value := v_max_signal_min;

SELECT * INTO v_alert_type
FROM core_operations.alert_type
WHERE code = 'SIGNAL_LOST' AND is_active = TRUE;

IF NOT FOUND THEN
        v_item.alert_action   := 'SKIPPED_CONFIG_MISSING';
        v_item.rule_triggered := FALSE;
        v_item.description    := 'alert_type SIGNAL_LOST no encontrado o inactivo';
ELSE
        -- Obtener last_communication_at del dispositivo GPS vinculado al vehículo
SELECT gd.last_communication_at INTO v_last_comm_at
FROM fleet.gps_device gd
WHERE gd.vehicle_id    = v_event.vehicle_id
  AND gd.is_operational = TRUE
ORDER BY gd.last_communication_at DESC
    LIMIT 1;

IF v_last_comm_at IS NULL THEN
            v_item.rule_triggered := FALSE;
            v_item.alert_action   := 'SKIPPED_NO_VIOLATION';
            v_item.alert_type_id  := v_alert_type.alert_type_id;
            v_item.description    := 'Sin dispositivo GPS operativo vinculado al vehículo';
ELSE
            v_signal_lost_min := ROUND(
                EXTRACT(EPOCH FROM (NOW() - v_last_comm_at)) / 60.0, 2
            );
            v_item.alert_type_id  := v_alert_type.alert_type_id;
            v_item.observed_value := v_signal_lost_min;

            IF v_signal_lost_min <= v_max_signal_min THEN
                v_item.rule_triggered := FALSE;
                v_item.alert_action   := 'SKIPPED_NO_VIOLATION';
                v_item.description    := 'Señal recibida hace ' || v_signal_lost_min::TEXT
                                         || ' min (bajo el límite de ' || v_max_signal_min::TEXT || ' min)';
ELSE
                v_item.rule_triggered := TRUE;
                v_item.description    := 'Sin señal GPS por ' || v_signal_lost_min::TEXT
                                         || ' min, supera límite de ' || v_max_signal_min::TEXT || ' min';

SELECT alert_id, alert_timestamp INTO v_existing_alert_id, v_existing_alert_ts
FROM core_operations.alert
WHERE vehicle_id    = v_event.vehicle_id
  AND alert_type_id = v_alert_type.alert_type_id
  AND status        = 'ACTIVE'
  AND alert_timestamp >= date_trunc('month', NOW()) - INTERVAL '1 month'
ORDER BY alert_timestamp DESC
    LIMIT 1;

IF FOUND THEN
UPDATE core_operations.alert
SET alert_timestamp = NOW(),
    description     = v_item.description,
    metadata        = jsonb_build_object(
            'raw_event_id',       v_event.raw_event_id,
            'signal_lost_minutes', v_signal_lost_min,
            'threshold_min',       v_max_signal_min,
            'last_comm_at',        v_last_comm_at
                      )
WHERE alert_id       = v_existing_alert_id
  AND alert_timestamp = v_existing_alert_ts;

v_item.alert_id     := v_existing_alert_id;
                    v_item.alert_action := 'UPDATED';
                    v_alerts_updated    := v_alerts_updated + 1;
ELSE
                    INSERT INTO core_operations.alert (
                        alert_type_id, entity_type, entity_id,
                        vehicle_id, driver_id,
                        severity, alert_timestamp,
                        latitude, longitude,
                        description, metadata, status
                    )
                    VALUES (
                        v_alert_type.alert_type_id, 'VEHICLE', v_event.vehicle_id,
                        v_event.vehicle_id, v_driver_id,
                        v_alert_type.severity, NOW(),
                        v_event.latitude, v_event.longitude,
                        v_item.description,
                        jsonb_build_object(
                            'raw_event_id',       v_event.raw_event_id,
                            'signal_lost_minutes', v_signal_lost_min,
                            'threshold_min',       v_max_signal_min,
                            'last_comm_at',        v_last_comm_at
                        ),
                        'ACTIVE'
                    )
                    RETURNING alert_id INTO v_new_alert_id;

                    v_item.alert_id     := v_new_alert_id;
                    v_item.alert_action := 'INSERTED';
                    v_alerts_inserted   := v_alerts_inserted + 1;
END IF;
END IF;
END IF;
END IF;

    v_items := v_items || v_item;

    -- ── Poblar resultado global ───────────────────────────────────────────
    v_result.success          := TRUE;
    v_result.raw_event_id     := v_event.raw_event_id;
    v_result.vehicle_id       := v_event.vehicle_id;
    v_result.plate_number     := v_vehicle.plate_number;
    v_result.gps_timestamp    := v_event.gps_timestamp;
    v_result.rules_evaluated  := v_rules_evaluated;
    v_result.alerts_inserted  := v_alerts_inserted;
    v_result.alerts_updated   := v_alerts_updated;
    v_result.detail           := v_items;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_items;
RETURN v_result;
END;
$$;


--
-- Name: export_all_user_permissions(); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.export_all_user_permissions() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result jsonb := '{}';
    v_user RECORD;
    v_user_data jsonb;
BEGIN
FOR v_user IN
SELECT DISTINCT u.user_id, u.username, uta.tenant_id
FROM identity."user" u
         JOIN identity.user_tenant_access uta ON u.user_id = uta.user_id
WHERE u.is_active = true AND uta.is_active = true
    LOOP
SELECT jsonb_object_agg(
               perm_code,
               scopes_by_company
       ) INTO v_user_data
FROM (
         SELECT
             sub.code as perm_code,
             COALESCE(
                     jsonb_object_agg(
                             company_id::text,
                             scope_array
                     ),
                     '{}'::jsonb
             ) as scopes_by_company
         FROM (
                  SELECT
                      p.code,
                      rps_agg.company_id,
                      -- Si hay NULL en los scopes, solo devolver [null]
                      CASE
                          WHEN bool_or(rps_agg.scope_id IS NULL) THEN jsonb_build_array(null)
                          ELSE jsonb_agg(rps_agg.scope_id)
                          END as scope_array
                  FROM identity.user_role ur
                           JOIN identity.role_permission rp ON ur.role_id = rp.role_id
                           JOIN identity.permission p ON rp.permission_id = p.permission_id
                           LEFT JOIN identity.role_permission_scope rps_agg
                                     ON rps_agg.role_permission_id = rp.role_permission_id
                                         AND rps_agg.is_active = true
                                         AND p.is_active = true -- SOLO PERMISOS ACTIVOS
                  WHERE ur.user_id = v_user.user_id
                    AND ur.is_active = true
                    AND rp.is_active = true
                  GROUP BY p.code, rps_agg.company_id
              ) sub
         WHERE company_id IS NOT NULL
         GROUP BY perm_code
     ) final;

v_result := v_result || jsonb_build_object(
                    v_user.username::text,
                    jsonb_build_object(
                            'userId', v_user.user_id,
                            'username', v_user.username,
                            'tenantId', v_user.tenant_id,
                            'permissions', COALESCE(v_user_data, '{}'::jsonb)
                    )
                                    );
END LOOP;

RETURN v_result;
END;
$$;


--
-- Name: get_alert_types(boolean, character varying); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_alert_types(p_only_active boolean DEFAULT true, p_category character varying DEFAULT NULL::character varying) RETURNS api.get_alert_types_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_alert_types_result;
    v_valid_categories  TEXT[] := ARRAY['TRACKER','PANIC','VEHICLE','DISPATCH','DRIVER','SYSTEM'];
BEGIN
    -- ── Validación: category conocida si se filtra por ella ───────────────
    IF p_category IS NOT NULL
       AND NOT (p_category = ANY(v_valid_categories)) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_CATEGORY';
        v_result.error_message := 'category inválida: "' || p_category
                                  || '". Válidas: '
                                  || array_to_string(v_valid_categories, ', ');
        v_result.total         := 0;
        v_result.items         := ARRAY[]::api.alert_type_row[];
RETURN v_result;
END IF;

    -- ── Consulta principal ────────────────────────────────────────────────
SELECT
    COUNT(*)::INTEGER,
        ARRAY_AGG(
            ROW(
                    at.alert_type_id,
                    at.code,
                    at.name,
                    at.description,
                    at.category,
                    at.severity,
                    at.requires_acknowledgment,
                    at.auto_close_after_min,
                    at.notification_channels,
                    at.display_order,
                    at.is_active,
                    at.created_at
            )::api.alert_type_row
            ORDER BY at.display_order ASC, at.alert_type_id ASC
            )
INTO
    v_result.total,
    v_result.items
FROM core_operations.alert_type at
WHERE (p_only_active = false  OR at.is_active = true)
  AND (p_category    IS NULL  OR at.category  = p_category);

-- ARRAY_AGG retorna NULL cuando no hay filas; normalizamos a array vacío
v_result.items         := COALESCE(v_result.items, ARRAY[]::api.alert_type_row[]);
    v_result.total         := COALESCE(v_result.total, 0);
    v_result.success       := TRUE;
    v_result.error_code    := NULL;
    v_result.error_message := NULL;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.total         := 0;
        v_result.items         := ARRAY[]::api.alert_type_row[];
RETURN v_result;
END;
$$;


--
-- Name: FUNCTION get_alert_types(p_only_active boolean, p_category character varying); Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON FUNCTION api.get_alert_types(p_only_active boolean, p_category character varying) IS 'Grupo G — Alertas. Lectura del catálogo de tipos de alerta.
p_only_active=true (default): solo vigentes — uso normal del frontend y de create_alert().
p_only_active=false: todos, incluyendo reservados para módulos futuros — panel admin.
p_category: filtro opcional por categoría (TRACKER, PANIC, VEHICLE, DISPATCH, DRIVER, SYSTEM).';


--
-- Name: get_alerts(api.get_alerts_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_alerts(p_input api.get_alerts_input) RETURNS api.get_alerts_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_alerts_result;

    v_valid_statuses    TEXT[] := ARRAY['ACTIVE','ACKNOWLEDGED','RESOLVED','AUTO_CLOSED'];
    v_valid_severities  TEXT[] := ARRAY['CRITICAL','HIGH','MEDIUM','LOW','INFO'];

    v_page_size         INTEGER;
    v_date_from         TIMESTAMPTZ;
    v_date_to           TIMESTAMPTZ;
    v_default_window_hours INTEGER := 24;
BEGIN
    -- ── Validación 1: status ──────────────────────────────────────────────
    IF p_input.status IS NOT NULL
       AND NOT (p_input.status = ANY(v_valid_statuses)) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_STATUS';
        v_result.error_message := 'status inválido: "' || p_input.status
                                  || '". Válidos: '
                                  || array_to_string(v_valid_statuses, ', ')
                                  || '. Omite el parámetro para traer todos.';
        v_result.items         := ARRAY[]::api.alert_row[];
RETURN v_result;
END IF;

    -- ── Validación 2: severity ────────────────────────────────────────────
    IF p_input.severity IS NOT NULL
       AND NOT (p_input.severity = ANY(v_valid_severities)) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_SEVERITY';
        v_result.error_message := 'severity inválida: "' || p_input.severity
                                  || '". Válidas: '
                                  || array_to_string(v_valid_severities, ', ');
        v_result.items         := ARRAY[]::api.alert_row[];
RETURN v_result;
END IF;

    -- ── Validación 3: page_size ───────────────────────────────────────────
    v_page_size := COALESCE(p_input.page_size, 50);
    IF v_page_size < 1 OR v_page_size > 200 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_PAGE_SIZE';
        v_result.error_message := 'page_size debe estar entre 1 y 200. Recibido: '
                                  || v_page_size::TEXT;
        v_result.items         := ARRAY[]::api.alert_row[];
RETURN v_result;
END IF;

    -- ── Validación 4: rango de fechas ─────────────────────────────────────
    v_date_to   := COALESCE(p_input.date_to, NOW());
    v_date_from := COALESCE(p_input.date_from,
                            v_date_to - (v_default_window_hours || ' hours')::INTERVAL);

    IF v_date_from >= v_date_to THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DATE_RANGE';
        v_result.error_message := 'date_from debe ser anterior a date_to.';
        v_result.items         := ARRAY[]::api.alert_row[];
RETURN v_result;
END IF;

    -- ── Consulta principal ────────────────────────────────────────────────
    -- PATRÓN: ARRAY_AGG(ROW(...)::tipo) sobre CTE con LIMIT page_size+1.
    -- La CTE permite aplicar LIMIT antes del ARRAY_AGG manteniendo
    -- partition pruning y el uso de índices existentes.
    -- ORDER BY dentro de ARRAY_AGG alinea con el orden de la CTE.

WITH paged AS (
    SELECT
        a.alert_id,
        a.alert_type_id,
        at.code             AS alert_type_code,
        at.name             AS alert_type_name,
        a.entity_type,
        a.entity_id,
        a.vehicle_id,
        a.driver_id,
        a.severity,
        a.status,
        a.alert_timestamp,
        a.latitude,
        a.longitude,
        a.description,
        a.metadata,
        a.acknowledged_by,
        a.acknowledged_at,
        a.resolved_at,
        a.auto_closed_at,
        a.created_at
    FROM core_operations.alert a
             JOIN core_operations.alert_type at
ON at.alert_type_id = a.alert_type_id
WHERE
-- Partition pruning: siempre presente
    a.alert_timestamp >= v_date_from
  AND a.alert_timestamp <  v_date_to
-- Filtros opcionales
  AND (p_input.status        IS NULL OR a.status        = p_input.status)
  AND (p_input.vehicle_id    IS NULL OR a.vehicle_id    = p_input.vehicle_id)
  AND (p_input.driver_id     IS NULL OR a.driver_id     = p_input.driver_id)
  AND (p_input.alert_type_id IS NULL OR a.alert_type_id = p_input.alert_type_id)
  AND (p_input.severity      IS NULL OR a.severity      = p_input.severity)
-- Cursor keyset
  AND (
    p_input.cursor IS NULL
   OR a.alert_timestamp < (p_input.cursor).last_alert_timestamp
   OR (
    a.alert_timestamp = (p_input.cursor).last_alert_timestamp
  AND a.alert_id    < (p_input.cursor).last_alert_id
    )
    )
ORDER BY a.alert_timestamp DESC, a.alert_id DESC
    LIMIT v_page_size + 1   -- +1 para detectar has_next_page sin COUNT(*)
    )
SELECT
    ARRAY_AGG(
            ROW(
                    p.alert_id,
                    p.alert_type_id,
                    p.alert_type_code,
                    p.alert_type_name,
                    p.entity_type,
                    p.entity_id,
                    p.vehicle_id,
                    p.driver_id,
                    p.severity,
                    p.status,
                    p.alert_timestamp,
                    p.latitude,
                    p.longitude,
                    p.description,
                    p.metadata,
                    p.acknowledged_by,
                    p.acknowledged_at,
                    p.resolved_at,
                    p.auto_closed_at,
                    p.created_at
            )::api.alert_row
            ORDER BY p.alert_timestamp DESC, p.alert_id DESC
    )
INTO v_result.items
FROM paged p;

-- ── Normalizar NULL cuando no hay filas ───────────────────────────────
v_result.items := COALESCE(v_result.items, ARRAY[]::api.alert_row[]);

    -- ── Detectar has_next_page y recortar al page_size real ───────────────
    IF array_length(v_result.items, 1) > v_page_size THEN
        v_result.has_next_page := TRUE;
        v_result.items := v_result.items[1:v_page_size];
ELSE
        v_result.has_next_page := FALSE;
END IF;

    v_result.total_in_page := COALESCE(array_length(v_result.items, 1), 0);

    -- ── Cursor para la siguiente página ───────────────────────────────────
    IF v_result.has_next_page AND v_result.total_in_page > 0 THEN
        v_result.next_cursor := ROW(
            (v_result.items[v_result.total_in_page]).alert_timestamp,
            (v_result.items[v_result.total_in_page]).alert_id
        )::api.alert_cursor;
ELSE
        v_result.next_cursor := NULL;
END IF;

    v_result.success           := TRUE;
    v_result.error_code        := NULL;
    v_result.error_message     := NULL;
    v_result.applied_date_from := v_date_from;
    v_result.applied_date_to   := v_date_to;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.items         := ARRAY[]::api.alert_row[];
RETURN v_result;
END;
$$;


--
-- Name: FUNCTION get_alerts(p_input api.get_alerts_input); Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON FUNCTION api.get_alerts(p_input api.get_alerts_input) IS 'Grupo G — Alertas. Consulta paginada de alertas con filtros opcionales.
Paginado por keyset (cursor) sobre (alert_timestamp DESC, alert_id DESC):
O(log n) en cualquier página, compatible con tabla particionada.
Siempre aplica rango de fechas para activar partition pruning — default últimas 24h.
page_size: 1-200, default 50. Pasar next_cursor del resultado anterior para avanzar.';


--
-- Name: get_catalog(character varying[], boolean); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_catalog(p_categories character varying[] DEFAULT NULL::character varying[], p_only_active boolean DEFAULT true) RETURNS api.get_catalog_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_catalog_result;
    v_valid_categories  TEXT[] := ARRAY[
        'vehicle_status', 'fuel_type', 'trip_status', 'incident_type',
        'employment_type', 'employment_status', 'payment_method',
        'document_restriction_type', 'schedule_type', 'exception_type',
        'job_title'
    ];
    v_bad_cat           VARCHAR(50);
BEGIN
    -- ── Validación: cada categoría recibida debe ser conocida ─────────────
    -- Solo si se pasó un array no vacío; NULL significa "todas" → sin validar
    IF p_categories IS NOT NULL AND array_length(p_categories, 1) > 0 THEN
SELECT cat INTO v_bad_cat
FROM unnest(p_categories) AS cat
WHERE cat != ALL(v_valid_categories)
        LIMIT 1;

IF FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_CATEGORY';
            v_result.error_message := 'Categoría desconocida: "' || v_bad_cat
                                      || '". Válidas: '
                                      || array_to_string(v_valid_categories, ', ');
            v_result.total_categories := 0;
            v_result.total_items      := 0;
            v_result.categories       := ARRAY[]::api.catalog_category_group[];
RETURN v_result;
END IF;
END IF;

    -- ── Consulta principal ────────────────────────────────────────────────
    -- Estrategia de índices:
    --   p_only_active = TRUE  → idx_catalog_category_order (parcial, el más pequeño)
    --   p_only_active = FALSE → idx_catalog_category
    --   Ambos cubren el filtro de category = ANY(p_categories).
    --
    -- El agrupamiento por categoría ocurre en BD con una única pasada;
    -- el backend recibe el resultado ya estructurado por grupo.

WITH base AS (
    SELECT
        catalog_id,
        category,
        code,
        name,
        description,
        display_order,
        is_active,
        created_at
    FROM shared.catalog
    WHERE (p_only_active = FALSE OR is_active = TRUE)
      AND (p_categories  IS NULL
        OR array_length(p_categories, 1) IS NULL
        OR category = ANY(p_categories))
    ORDER BY category ASC, display_order ASC, code ASC
),
     grouped AS (
         SELECT
             category,
             COUNT(*)::INTEGER AS total,
                 ARRAY_AGG(
                         ROW(
                                 catalog_id,
                                 category,
                                 code,
                                 name,
                                 description,
                                 display_order,
                                 is_active,
                                 created_at
                         )::api.catalog_row
                ORDER BY display_order ASC, code ASC
                 ) AS items
         FROM base
         GROUP BY category
     )
SELECT
    COUNT(*)::INTEGER,
        SUM(total)::INTEGER,
        ARRAY_AGG(
            ROW(category, total, items)::api.catalog_category_group
            ORDER BY category ASC
            )
INTO
    v_result.total_categories,
    v_result.total_items,
    v_result.categories
FROM grouped;

-- Normalizar NULLs cuando no hay filas
v_result.categories       := COALESCE(v_result.categories, ARRAY[]::api.catalog_category_group[]);
    v_result.total_categories := COALESCE(v_result.total_categories, 0);
    v_result.total_items      := COALESCE(v_result.total_items, 0);
    v_result.success          := TRUE;
    v_result.error_code       := NULL;
    v_result.error_message    := NULL;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success          := FALSE;
        v_result.error_code       := 'INTERNAL_ERROR';
        v_result.error_message    := SQLERRM;
        v_result.total_categories := 0;
        v_result.total_items      := 0;
        v_result.categories       := ARRAY[]::api.catalog_category_group[];
RETURN v_result;
END;
$$;


--
-- Name: FUNCTION get_catalog(p_categories character varying[], p_only_active boolean); Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON FUNCTION api.get_catalog(p_categories character varying[], p_only_active boolean) IS 'Lectura del catálogo genérico agrupada por categoría.
p_categories = NULL → todas las categorías.
p_categories = ARRAY[''fuel_type'',''vehicle_status''] → solo esas dos.
p_only_active = TRUE (default) → activa idx_catalog_category_order (parcial).
p_only_active = FALSE → activa idx_catalog_category.
Retorna api.catalog_category_group[] listo para poblar dropdowns múltiples.';


--
-- Name: get_checkpoints(api.get_checkpoints_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_checkpoints(p_input api.get_checkpoints_input) RETURNS api.get_checkpoints_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.get_checkpoints_result;
    v_route_code        VARCHAR(20);
    v_route_type        VARCHAR(20);
    v_direction         VARCHAR(10);
    v_types             VARCHAR(20)[];
    v_normalized_types  core_operations.checkpoint_type_enum[];
    v_type_str          VARCHAR(20);
    v_checkpoints       api.checkpoint_item_result[];
BEGIN

    -- ── Validación 1: route_id obligatorio ────────────────────────────────
    IF p_input.route_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ROUTE_ID';
        v_result.error_message := 'route_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: ruta existe y está activa ───────────────────────────
SELECT code, route_type
INTO v_route_code, v_route_type
FROM core_operations.route
WHERE route_id = p_input.route_id
  AND is_active = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROUTE_NOT_FOUND';
        v_result.error_message := 'La ruta route_id=' || p_input.route_id
                                  || ' no existe o está inactiva';
RETURN v_result;
END IF;

    -- ── Normalizar direction ──────────────────────────────────────────────
    --    NULL → sin filtro; valor presente → validar y normalizar
    IF p_input.direction IS NOT NULL AND TRIM(p_input.direction) <> '' THEN

        v_direction := UPPER(TRIM(p_input.direction));

        IF v_direction NOT IN ('IDA', 'VUELTA', 'CIRCULAR') THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DIRECTION';
            v_result.error_message := 'direction="' || p_input.direction
                                      || '" inválido. Válidos: IDA, VUELTA, CIRCULAR';
RETURN v_result;
END IF;

        -- Coherencia con route_type
        IF v_route_type = 'CIRCULAR' AND v_direction <> 'CIRCULAR' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DIRECTION_ROUTE_TYPE_MISMATCH';
            v_result.error_message := 'La ruta es CIRCULAR. '
                                      || 'Solo se puede filtrar por direction=CIRCULAR';
RETURN v_result;
END IF;

        IF v_route_type = 'LINEAR' AND v_direction = 'CIRCULAR' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DIRECTION_ROUTE_TYPE_MISMATCH';
            v_result.error_message := 'La ruta es LINEAR. '
                                      || 'direction=CIRCULAR no aplica. Use IDA o VUELTA';
RETURN v_result;
END IF;

END IF;

    -- ── Normalizar checkpoint_types ───────────────────────────────────────
    --    NULL o array vacío → sin filtro
    --    Array con valores → validar cada uno y convertir al ENUM
    IF p_input.checkpoint_types IS NOT NULL
       AND array_length(p_input.checkpoint_types, 1) IS NOT NULL
    THEN
        v_normalized_types := ARRAY[]::core_operations.checkpoint_type_enum[];

        FOREACH v_type_str IN ARRAY p_input.checkpoint_types
        LOOP
            IF LOWER(TRIM(v_type_str)) NOT IN ('bus_stop', 'checkpoint', 'terminal') THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_CHECKPOINT_TYPE';
                v_result.error_message := 'checkpoint_type="' || v_type_str
                                          || '" inválido. Válidos: bus_stop, checkpoint, terminal';
RETURN v_result;
END IF;

            v_normalized_types := v_normalized_types
                || LOWER(TRIM(v_type_str))::core_operations.checkpoint_type_enum;
END LOOP;

        -- Deduplicar por si el cliente envió el mismo tipo dos veces
SELECT array_agg(DISTINCT t ORDER BY t)
INTO v_normalized_types
FROM unnest(v_normalized_types) AS t;

-- Guardar versión texto para el resultado (parallel a v_normalized_types)
SELECT array_agg(t::VARCHAR ORDER BY t)
INTO v_types
FROM unnest(v_normalized_types) AS t;

END IF;

    -- ── Consulta principal ────────────────────────────────────────────────
SELECT array_agg(
               ROW(
                       cp.checkpoint_id,
                       cp.checkpoint_code,
                       cp.name,
                       cp.checkpoint_type::VARCHAR,
                       cp.is_route_endpoint,
                       cp.direction,
                       cp.sequence_number,
                       cp.latitude,
                       cp.longitude,
                       cp.distance_from_origin_km,
                       cp.estimated_duration_minutes,
                       cp.geofence_radius_meters,
                       cp.is_active,
                       cp.created_at
               )::api.checkpoint_item_result
        ORDER BY cp.direction, cp.sequence_number
       )
INTO v_checkpoints
FROM core_operations.checkpoint cp
WHERE cp.route_id = p_input.route_id
  AND cp.is_active = TRUE
  -- Filtro direction: aplica solo si se recibió
  AND (v_direction IS NULL OR cp.direction = v_direction)
  -- Filtro tipos: aplica solo si se recibió al menos uno
  AND (v_normalized_types IS NULL OR cp.checkpoint_type = ANY(v_normalized_types));

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success          := TRUE;
    v_result.route_id         := p_input.route_id;
    v_result.route_code       := v_route_code;
    v_result.route_type       := v_route_type;
    v_result.direction_filter := v_direction;
    v_result.types_filter     := v_types;
    v_result.total_count      := COALESCE(array_length(v_checkpoints, 1), 0);
    v_result.checkpoints      := COALESCE(v_checkpoints, ARRAY[]::api.checkpoint_item_result[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_companies(api.get_companies_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_companies(p_input api.get_companies_input) RETURNS api.get_companies_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result        api.get_companies_result;
    v_tenant_id     BIGINT;
    v_page_number   INT;
    v_page_size     INT;
    v_offset        INT;
    v_search        TEXT;
    v_total         BIGINT;
    v_total_pages   INT;
BEGIN

    -- ── Normalizar parámetros ─────────────────────────────────────────
    v_tenant_id   := p_input.tenant_id;
    v_page_number := GREATEST(COALESCE(p_input.page_number, 1), 1);
    v_page_size   := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset      := (v_page_number - 1) * v_page_size;
    v_search      := NULLIF(TRIM(COALESCE(p_input.search, '')), '');

    -- ── Validaciones ──────────────────────────────────────────────────
    IF v_tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    IF NOT EXISTS (
        SELECT 1 FROM identity.tenant WHERE tenant_id = v_tenant_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'TENANT_NOT_FOUND';
        v_result.error_message := 'El tenant_id=' || v_tenant_id || ' no existe';
RETURN v_result;
END IF;

    -- ════════════════════════════════════════════════════════════════
    -- QUERY PRINCIPAL
    --
    -- Flujo: identity.tenant_company → shared.company
    --
    -- Filtros disponibles:
    --   · search        → tax_id, legal_name, trade_name  (ILIKE)
    --   · is_active     → estado de la empresa
    --   · link_is_active → estado del vínculo en tenant_company
    -- ════════════════════════════════════════════════════════════════
WITH base AS (
    SELECT
        c.company_id,
        c.tax_id,
        c.legal_name,
        c.trade_name,
        c.address,
        c.phone,
        c.email,
        c.logo_url,
        c.is_active         AS company_is_active,
        tc.tenant_company_id,
        tc.is_active        AS link_is_active,
        tc.created_at       AS linked_at
    FROM identity.tenant_company tc
             JOIN shared.company c ON c.company_id = tc.company_id
    WHERE tc.tenant_id = v_tenant_id
      -- Filtro estado de la empresa
      AND (p_input.is_active      IS NULL OR c.is_active   = p_input.is_active)
      -- Filtro estado del vínculo tenant↔empresa
      AND (p_input.link_is_active IS NULL OR tc.is_active  = p_input.link_is_active)
      -- Filtro búsqueda de texto
      AND (
        v_search IS NULL
            OR c.tax_id     ILIKE '%' || v_search || '%'
              OR c.legal_name ILIKE '%' || v_search || '%'
              OR c.trade_name ILIKE '%' || v_search || '%'
        )
),
     counted AS (
         SELECT COUNT(*) AS total FROM base
     ),
     paged AS (
         SELECT *
         FROM base
         ORDER BY
             legal_name,
             company_id
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT
    (SELECT total FROM counted),
    ARRAY_AGG(
            ROW(
                    pg.company_id,
                    pg.tax_id,
                    pg.legal_name,
                    pg.trade_name,
                    pg.address,
                    pg.phone,
                    pg.email,
                    pg.logo_url,
                    pg.company_is_active,
                    pg.tenant_company_id,
                    pg.link_is_active,
                    pg.linked_at
            )::api.company_row
            ORDER BY pg.legal_name, pg.company_id
    )
INTO v_total, v_result.companies
FROM paged pg;

-- ── Metadata de paginación ────────────────────────────────────────
v_total_pages := GREATEST(
        CEIL(v_total::NUMERIC / v_page_size)::INT, 1
    );

    v_result.success        := TRUE;
    v_result.page_number    := v_page_number;
    v_result.page_size      := v_page_size;
    v_result.total_records  := COALESCE(v_total, 0);
    v_result.total_pages    := v_total_pages;
    v_result.has_next_page  := v_page_number < v_total_pages;
    v_result.has_prev_page  := v_page_number > 1;
    v_result.companies      := COALESCE(v_result.companies, ARRAY[]::api.company_row[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_document_types(api.get_document_types_input_v2); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_document_types(p_input api.get_document_types_input_v2 DEFAULT ROW(true, NULL::character varying(20), NULL::character varying(20), NULL::character varying(100), NULL::boolean, NULL::boolean)::api.get_document_types_input_v2) RETURNS api.get_document_types_result_v2
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.get_document_types_result_v2;
    v_is_active         BOOLEAN;
    v_entity_type       VARCHAR(20);
    v_restriction_type  VARCHAR(20);
    v_name_search       VARCHAR(100);
    v_requires_expiry   BOOLEAN;
    v_is_mandatory      BOOLEAN;
    v_items             api.document_type_item_v2[];
BEGIN

    -- ── Normalizar filtros ────────────────────────────────────────────────
    -- is_active: si viene NULL se interpreta como TRUE (comportamiento por defecto)
    v_is_active := COALESCE(p_input.is_active, TRUE);

    -- entity_type: NULL o cadena vacía = sin filtro
    v_entity_type := NULLIF(UPPER(TRIM(COALESCE(p_input.entity_type, ''))), '');

    -- restriction_type: NULL o cadena vacía = sin filtro
    v_restriction_type := NULLIF(UPPER(TRIM(COALESCE(p_input.restriction_type, ''))), '');

    -- name_search: NULL o cadena vacía = sin filtro
    v_name_search := NULLIF(TRIM(COALESCE(p_input.name_search, '')), '');

    -- requires_expiry y is_mandatory: NULL = sin filtro
    v_requires_expiry := p_input.requires_expiry;
    v_is_mandatory    := p_input.is_mandatory;

    -- ── Validar entity_type si se proveyó ─────────────────────────────────
    IF v_entity_type IS NOT NULL
       AND v_entity_type NOT IN ('DRIVER', 'VEHICLE', 'COMPANY', 'GENERAL')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_ENTITY_TYPE';
        v_result.error_message := 'entity_type inválido: "' || v_entity_type
                                  || '". Válidos: DRIVER, VEHICLE, COMPANY, GENERAL';
RETURN v_result;
END IF;

    -- ── Validar restriction_type si se proveyó ────────────────────────────
    IF v_restriction_type IS NOT NULL
       AND v_restriction_type NOT IN ('CRITICAL', 'WARNING', 'NONE')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_RESTRICTION_TYPE';
        v_result.error_message := 'restriction_type inválido: "' || v_restriction_type
                                  || '". Válidos: CRITICAL, WARNING, NONE';
RETURN v_result;
END IF;

    -- ── Consulta principal ────────────────────────────────────────────────
SELECT array_agg(
               ROW(
                       dt.document_type_id,
                       dt.code,
                       dt.name,
                       dt.description,
                       dt.entity_type,
                       dt.restriction_type,
                       dt.is_mandatory,
                       dt.requires_expiry,
                       dt.alert_days_before,
                       dt.is_active,
                       dt.created_at
               )::api.document_type_item_v2
        ORDER BY dt.entity_type, dt.name
       )
INTO v_items
FROM shared.document_type dt
WHERE
  -- Filtro is_active: siempre aplica (nunca es NULL tras normalización)
    dt.is_active = v_is_active

  -- Filtro entity_type: solo si se proveyó
  AND (v_entity_type IS NULL OR dt.entity_type = v_entity_type)

  -- Filtro restriction_type: solo si se proveyó
  AND (v_restriction_type IS NULL OR dt.restriction_type = v_restriction_type)

  -- Filtro name_search: búsqueda parcial case-insensitive
  AND (v_name_search IS NULL OR dt.name ILIKE '%' || v_name_search || '%')

  -- Filtro requires_expiry: solo si se proveyó
  AND (v_requires_expiry IS NULL OR dt.requires_expiry = v_requires_expiry)

  -- Filtro is_mandatory: solo si se proveyó
  AND (v_is_mandatory IS NULL OR dt.is_mandatory = v_is_mandatory);

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success                := TRUE;
    v_result.filter_is_active       := v_is_active;
    v_result.filter_entity_type     := v_entity_type;
    v_result.filter_restriction_type := v_restriction_type;
    v_result.filter_name_search     := v_name_search;
    v_result.filter_requires_expiry := v_requires_expiry;
    v_result.filter_is_mandatory    := v_is_mandatory;
    v_result.total_count            := COALESCE(array_length(v_items, 1), 0);
    v_result.document_types         := COALESCE(v_items, ARRAY[]::api.document_type_item_v2[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_drivers(api.get_drivers_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_drivers(p_input api.get_drivers_input DEFAULT ROW(NULL::integer[], NULL::character varying(20)[], NULL::character varying(20)[], NULL::boolean, NULL::boolean, NULL::character varying(255), NULL::character varying(20), 1, 20)::api.get_drivers_input) RETURNS api.get_drivers_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.get_drivers_result;
    v_company_ids           INT[];
    v_emp_status            VARCHAR(20)[];
    v_emp_type              VARCHAR(20)[];
    v_is_available          BOOLEAN;
    v_low_points            BOOLEAN;
    v_name_search           VARCHAR(255);
    v_code_search           VARCHAR(20);
    v_page                  INT;
    v_page_size             INT;
    v_offset                INT;
    v_total_count           INT;
    v_total_pages           INT;
    v_items                 api.driver_list_item[];
    v_s                     VARCHAR(20);
    v_t                     VARCHAR(20);
BEGIN

    -- ── Normalizar paginación ─────────────────────────────────────────────
    v_page      := GREATEST(COALESCE(p_input.page, 1), 1);
    v_page_size := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset    := (v_page - 1) * v_page_size;

    -- ── Normalizar filtros ────────────────────────────────────────────────
    v_company_ids := CASE
        WHEN p_input.company_ids IS NULL
          OR array_length(p_input.company_ids, 1) IS NULL
        THEN NULL
        ELSE p_input.company_ids
END;

    IF p_input.employment_status IS NOT NULL
       AND array_length(p_input.employment_status, 1) IS NOT NULL
    THEN
        v_emp_status := ARRAY[]::VARCHAR[];
        FOREACH v_s IN ARRAY p_input.employment_status
        LOOP
            v_emp_status := v_emp_status || UPPER(TRIM(v_s));
END LOOP;
END IF;

    IF p_input.employment_type IS NOT NULL
       AND array_length(p_input.employment_type, 1) IS NOT NULL
    THEN
        v_emp_type := ARRAY[]::VARCHAR[];
        FOREACH v_t IN ARRAY p_input.employment_type
        LOOP
            v_emp_type := v_emp_type || UPPER(TRIM(v_t));
END LOOP;
END IF;

    v_is_available := p_input.is_available;
    v_low_points   := COALESCE(p_input.low_license_points, FALSE);
    v_name_search  := NULLIF(TRIM(COALESCE(p_input.name_search, '')), '');
    v_code_search  := NULLIF(UPPER(TRIM(COALESCE(p_input.driver_code_search, ''))), '');

    -- ── Validaciones ──────────────────────────────────────────────────────
    IF v_emp_status IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_emp_status) s
        WHERE s NOT IN ('ACTIVE','SUSPENDED','TERMINATED')
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_EMPLOYMENT_STATUS';
        v_result.error_message := 'Válidos: ACTIVE, SUSPENDED, TERMINATED';
RETURN v_result;
END IF;

    IF v_emp_type IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_emp_type) t
        WHERE t NOT IN ('OWNER_OPERATOR','HIRED_DRIVER')
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_EMPLOYMENT_TYPE';
        v_result.error_message := 'Válidos: OWNER_OPERATOR, HIRED_DRIVER';
RETURN v_result;
END IF;

    IF v_company_ids IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_company_ids) cid
        LEFT JOIN shared.company c ON c.company_id = cid
        WHERE c.company_id IS NULL
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'COMPANY_NOT_FOUND';
        v_result.error_message := 'Uno o más company_id del filtro no existen';
RETURN v_result;
END IF;

    -- ── Contar total ──────────────────────────────────────────────────────
SELECT COUNT(*)
INTO v_total_count
FROM hr.driver d
         JOIN hr.person p ON p.person_id = d.person_id
WHERE (v_company_ids IS NULL   OR d.company_id        = ANY(v_company_ids))
  AND (v_emp_status IS NULL    OR d.employment_status = ANY(v_emp_status))
  AND (v_emp_type IS NULL      OR d.employment_type   = ANY(v_emp_type))
  AND (v_is_available IS NULL  OR d.is_available      = v_is_available)
  AND (NOT v_low_points        OR d.license_points    < 75)
  AND (v_name_search IS NULL   OR p.full_name         ILIKE '%' || v_name_search || '%')
  AND (v_code_search IS NULL   OR d.driver_code       ILIKE '%' || v_code_search || '%');

v_total_pages := GREATEST(CEIL(v_total_count::NUMERIC / v_page_size)::INT, 1);

    -- ── Consulta principal con patrón CTE ─────────────────────────────────
WITH paged AS (
    -- Paso 1: paginar primero sobre driver + person
    SELECT
        d.driver_id,
        d.driver_code,
        d.person_id,
        p.full_name,
        p.tax_id,
        p.phone_mobile,
        d.company_id,
        c.trade_name            AS company_name,
        d.employment_type,
        d.employment_status,
        d.is_available,
        d.license_points,
        d.current_vehicle_id,
        d.total_trips,
        d.rating_average,
        d.hire_date,
        d.updated_at
    FROM hr.driver d
             JOIN hr.person   p ON p.person_id  = d.person_id
             JOIN shared.company c ON c.company_id = d.company_id
    WHERE (v_company_ids IS NULL   OR d.company_id        = ANY(v_company_ids))
      AND (v_emp_status IS NULL    OR d.employment_status = ANY(v_emp_status))
      AND (v_emp_type IS NULL      OR d.employment_type   = ANY(v_emp_type))
      AND (v_is_available IS NULL  OR d.is_available      = v_is_available)
      AND (NOT v_low_points        OR d.license_points    < 75)
      AND (v_name_search IS NULL   OR p.full_name         ILIKE '%' || v_name_search || '%')
      AND (v_code_search IS NULL   OR d.driver_code       ILIKE '%' || v_code_search || '%')
    ORDER BY p.full_name
    LIMIT v_page_size OFFSET v_offset
    ),
    current_vehicle AS (
-- Paso 2: vehículo actual solo para los drivers de la página
-- Usa current_vehicle_id que ya está en driver (desnormalizado por performance)
SELECT
    v.vehicle_id,
    v.plate_number,
    v.internal_code
FROM fleet.vehicle v
WHERE v.vehicle_id = ANY(
    SELECT current_vehicle_id FROM paged WHERE current_vehicle_id IS NOT NULL
    )
    ),
    critical_docs AS (
-- Paso 3: documentos críticos vencidos por persona
-- Un solo escaneo acotado a los person_ids de la página
SELECT
    pd.person_id,
    COUNT(*)::INT AS expired_critical_docs
FROM hr.person_document pd
    JOIN shared.document_type dt ON dt.document_type_id = pd.document_type_id
WHERE pd.person_id = ANY(SELECT person_id FROM paged)
  AND pd.status            = 'EXPIRED'
  AND dt.restriction_type  = 'CRITICAL'
GROUP BY pd.person_id
    )
SELECT array_agg(
               (
                pg.driver_id,
                pg.driver_code,
                pg.person_id,
                pg.full_name,
                pg.tax_id,
                pg.phone_mobile,
                pg.company_id,
                pg.company_name,
                pg.employment_type,
                pg.employment_status,
                pg.is_available,
                pg.license_points,
                pg.current_vehicle_id,
                cv.plate_number,
                cv.internal_code,
                pg.total_trips,
                pg.rating_average,
                COALESCE(cd.expired_critical_docs, 0),
                pg.hire_date,
                pg.updated_at
                   )::api.driver_list_item
                ORDER BY pg.full_name
       )
INTO v_items
FROM paged pg
         LEFT JOIN current_vehicle cv ON cv.vehicle_id = pg.current_vehicle_id
         LEFT JOIN critical_docs   cd ON cd.person_id  = pg.person_id;

-- ── Resultado ─────────────────────────────────────────────────────────
v_result.success                      := TRUE;
    v_result.page                         := v_page;
    v_result.page_size                    := v_page_size;
    v_result.total_count                  := v_total_count;
    v_result.total_pages                  := v_total_pages;
    v_result.has_next_page                := v_page < v_total_pages;
    v_result.has_prev_page                := v_page > 1;
    v_result.filter_company_ids           := v_company_ids;
    v_result.filter_employment_status     := v_emp_status;
    v_result.filter_employment_type       := v_emp_type;
    v_result.filter_is_available          := v_is_available;
    v_result.filter_low_license_points    := v_low_points;
    v_result.filter_name_search           := v_name_search;
    v_result.filter_driver_code_search    := v_code_search;
    v_result.drivers                      := COALESCE(v_items, ARRAY[]::api.driver_list_item[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_gps_devices(api.get_gps_devices_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_gps_devices(p_input api.get_gps_devices_input) RETURNS api.get_gps_devices_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_gps_devices_result;
    v_page_size         INTEGER;
    v_valid_statuses    TEXT[] := ARRAY['ACTIVE','INACTIVE','ERROR','MAINTENANCE'];
    v_valid_types       TEXT[] := ARRAY['TRACKER_GPS','ANDROID_TABLET'];
BEGIN
    -- ── Validación 1: status ──────────────────────────────────────────────
    IF p_input.status IS NOT NULL
       AND NOT (p_input.status = ANY(v_valid_statuses)) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_STATUS';
        v_result.error_message := 'status inválido: "' || p_input.status
                                  || '". Válidos: '
                                  || array_to_string(v_valid_statuses, ', ');
        v_result.items         := ARRAY[]::api.gps_device_row[];
RETURN v_result;
END IF;

    -- ── Validación 2: device_type ─────────────────────────────────────────
    IF p_input.device_type IS NOT NULL
       AND NOT (p_input.device_type = ANY(v_valid_types)) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DEVICE_TYPE';
        v_result.error_message := 'device_type inválido: "' || p_input.device_type
                                  || '". Válidos: '
                                  || array_to_string(v_valid_types, ', ');
        v_result.items         := ARRAY[]::api.gps_device_row[];
RETURN v_result;
END IF;

    -- ── Validación 3: page_size ───────────────────────────────────────────
    v_page_size := COALESCE(p_input.page_size, 50);
    IF v_page_size < 1 OR v_page_size > 200 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_PAGE_SIZE';
        v_result.error_message := 'page_size debe estar entre 1 y 200. Recibido: '
                                  || v_page_size::TEXT;
        v_result.items         := ARRAY[]::api.gps_device_row[];
RETURN v_result;
END IF;

    -- ── Consulta principal ────────────────────────────────────────────────
    -- ÍNDICES ACTIVOS SEGÚN FILTROS:
    --   company_id + status   → idx_gps_device_company (company_id, status)
    --   is_operational = TRUE → idx_gps_device_last_comm / idx_gps_device_vehicle
    --   has_vehicle = TRUE    → idx_gps_device_vehicle (parcial WHERE is_operational)
    --   Sin filtros           → seq scan sobre tabla pequeña (aceptable)
    --
    -- El LEFT JOIN a vehicle es O(1) por fila vía PK — costo mínimo.
    -- Cursor sobre gps_device_id ASC: usa el PK btree directamente.
    -- page_size + 1 para detectar has_next_page sin COUNT(*).

WITH paged AS (
    SELECT
        g.gps_device_id,
        g.device_id,
        g.device_type,
        g.company_id,
        g.imei,
        g.serial_number,
        g.model,
        g.manufacturer,
        g.sim_card_number,
        g.sim_provider,
        g.firmware_version,
        g.posting_interval_seconds,
        g.status,
        g.is_operational,
        g.last_communication_at,
        g.installed_at,
        g.created_at,
        g.updated_at,
        -- Vehículo embebido: NULL cuando no hay vinculación
        CASE WHEN v.vehicle_id IS NOT NULL
                 THEN ROW(
                    v.vehicle_id,
                    v.plate_number,
                    v.internal_code,
                    v.brand,
                    v.model,
                    v.year,
                    v.status,
                    v.is_operational
                      )::api.gps_device_vehicle_info
             ELSE NULL
            END AS vehicle
    FROM fleet.gps_device g
             LEFT JOIN fleet.vehicle v ON v.vehicle_id = g.vehicle_id
    WHERE
      -- Filtros opcionales — cada condición cortocircuita con IS NULL
        (p_input.status        IS NULL OR g.status        = p_input.status)
      AND (p_input.device_type   IS NULL OR g.device_type   = p_input.device_type)
      AND (p_input.company_id    IS NULL OR g.company_id    = p_input.company_id)
      AND (p_input.is_operational IS NULL OR g.is_operational = p_input.is_operational)
      AND (
        p_input.has_vehicle IS NULL
            OR (p_input.has_vehicle = TRUE  AND g.vehicle_id IS NOT NULL)
            OR (p_input.has_vehicle = FALSE AND g.vehicle_id IS NULL)
        )
      -- Cursor keyset sobre PK: O(log n) en cualquier página
      AND (
        p_input.cursor IS NULL
            OR g.gps_device_id > (p_input.cursor).last_gps_device_id
        )
    ORDER BY g.gps_device_id ASC
    LIMIT v_page_size + 1
    )
SELECT
    ARRAY_AGG(
            ROW(
                    p.gps_device_id,
                    p.device_id,
                    p.device_type,
                    p.company_id,
                    p.imei,
                    p.serial_number,
                    p.model,
                    p.manufacturer,
                    p.sim_card_number,
                    p.sim_provider,
                    p.firmware_version,
                    p.posting_interval_seconds,
                    p.status,
                    p.is_operational,
                    p.last_communication_at,
                    p.installed_at,
                    p.created_at,
                    p.updated_at,
                    p.vehicle
            )::api.gps_device_row
            ORDER BY p.gps_device_id ASC
    )
INTO v_result.items
FROM paged p;

-- ── Normalizar NULL ───────────────────────────────────────────────────
v_result.items := COALESCE(v_result.items, ARRAY[]::api.gps_device_row[]);

    -- ── Detectar has_next_page y recortar ─────────────────────────────────
    IF array_length(v_result.items, 1) > v_page_size THEN
        v_result.has_next_page := TRUE;
        v_result.items         := v_result.items[1:v_page_size];
ELSE
        v_result.has_next_page := FALSE;
END IF;

    v_result.total_in_page := COALESCE(array_length(v_result.items, 1), 0);

    -- ── Cursor siguiente página ───────────────────────────────────────────
    IF v_result.has_next_page AND v_result.total_in_page > 0 THEN
        v_result.next_cursor := ROW(
            (v_result.items[v_result.total_in_page]).gps_device_id
        )::api.gps_device_cursor;
ELSE
        v_result.next_cursor := NULL;
END IF;

    v_result.success       := TRUE;
    v_result.error_code    := NULL;
    v_result.error_message := NULL;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.items         := ARRAY[]::api.gps_device_row[];
RETURN v_result;
END;
$$;


--
-- Name: FUNCTION get_gps_devices(p_input api.get_gps_devices_input); Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON FUNCTION api.get_gps_devices(p_input api.get_gps_devices_input) IS 'Listado paginado de dispositivos GPS con datos del vehículo vinculado embebidos.
Cursor keyset sobre gps_device_id ASC (PK): O(log n) sin degradación por página.
Filtros: status, device_type, company_id, is_operational, has_vehicle.
has_vehicle=TRUE → solo vinculados | FALSE → solo huérfanos | NULL → todos.
vehicle embebido es NULL cuando el dispositivo no tiene vehicle_id asignado.';


--
-- Name: get_people(api.get_people_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_people(p_input api.get_people_input) RETURNS api.get_people_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result        api.get_people_result;
    v_tenant_id     BIGINT;
    v_page_number   INT;
    v_page_size     INT;
    v_offset        INT;
    v_search        TEXT;
    v_total         BIGINT;
    v_total_pages   INT;
BEGIN

    -- ── Normalizar parámetros ─────────────────────────────────────────────
    v_tenant_id   := p_input.tenant_id;
    v_page_number := GREATEST(COALESCE(p_input.page_number, 1), 1);
    v_page_size   := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset      := (v_page_number - 1) * v_page_size;
    v_search      := NULLIF(TRIM(COALESCE(p_input.search, '')), '');

    -- ── Validación: tenant_id obligatorio ─────────────────────────────────
    IF v_tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    IF NOT EXISTS (
        SELECT 1 FROM identity.tenant WHERE tenant_id = v_tenant_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'TENANT_NOT_FOUND';
        v_result.error_message := 'El tenant_id=' || v_tenant_id || ' no existe';
RETURN v_result;
END IF;

    -- ════════════════════════════════════════════════════════
    -- QUERY PRINCIPAL
    --
    -- Corrección del filtro de tenant:
    --   El CTE base ahora parte de identity.user_tenant_access
    --   para garantizar que solo se devuelven personas cuyo
    --   usuario tiene acceso al tenant solicitado.
    --
    --   Flujo: user_tenant_access → user → (personnel | driver) → person
    --
    --   Las personas sin cuenta (sin user_id) NO aparecen en este
    --   listado porque no tienen acceso a ningún tenant. Si se
    --   necesitaran, habría que hacer el join inverso desde person.
    --
    -- external_id: viene directo de identity.user.
    -- tenant_id: se propaga desde user_tenant_access para mostrarlo
    --   en el resultado (útil cuando el cliente maneja multi-tenant).
    -- ════════════════════════════════════════════════════════
WITH base AS (
    SELECT
        p.person_id,
        p.given_names,
        p.father_last_name,
        p.mother_last_name,
        p.full_name,
        p.tax_id,
        p.is_active,
        p.phone_mobile,
        u.user_id,
        u.external_id,
        u.username,
        uta.tenant_id,
        uta.is_active   AS tenant_access_active
    FROM identity.user_tenant_access uta
             -- ▶ Filtro de tenant aplicado aquí, en el primer JOIN
             JOIN identity."user" u
                  ON  u.user_id  = uta.user_id
                      AND uta.tenant_id = v_tenant_id
        -- Puente user → person a través de personnel o driver
        -- Ambos tienen UNIQUE(user_id) y UNIQUE(person_id) → sin duplicados
             LEFT JOIN hr.personnel pnl ON pnl.user_id = u.user_id
             LEFT JOIN hr.driver    drv ON drv.user_id = u.user_id
             JOIN hr.person p
                  ON  p.person_id = COALESCE(pnl.person_id, drv.person_id)
    WHERE
      -- Filtro is_active sobre la persona
        (p_input.is_active IS NULL OR p.is_active = p_input.is_active)
      -- Filtro search: nombre completo, tax_id o username
      AND (
        v_search IS NULL
            OR p.full_name ILIKE '%' || v_search || '%'
                OR p.tax_id    ILIKE '%' || v_search || '%'
                OR u.username  ILIKE '%' || v_search || '%'
        )
),
     counted AS (
         SELECT COUNT(*) AS total FROM base
     ),
     paged AS (
         SELECT *
         FROM base
         ORDER BY
             father_last_name,
             mother_last_name,
             given_names,
             person_id
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT
    (SELECT total FROM counted),
    ARRAY_AGG(
            ROW(
                    pg.person_id,
                -- display_name: máx 2 nombres de pila + apellidos
                    TRIM(
                            CASE
                                WHEN array_length(
                                             string_to_array(TRIM(pg.given_names), ' '), 1
                                     ) >= 2
                                    THEN (string_to_array(TRIM(pg.given_names), ' '))[1]
                             || ' '
                             || (string_to_array(TRIM(pg.given_names), ' '))[2]
                                ELSE TRIM(pg.given_names)
                                END
                                || ' ' || pg.father_last_name
                                || ' ' || pg.mother_last_name
                    ),
                    pg.given_names,
                    pg.father_last_name,
                    pg.mother_last_name,
                    pg.tax_id,
                    pg.user_id,
                    pg.external_id,         -- ▶ añadido
                    pg.username,
                    pg.tenant_id,           -- ▶ añadido
            -- Roles activos del usuario en el tenant
            -- Subquery escalar evaluado solo sobre filas de la página
                    (
                        SELECT STRING_AGG(r.name, ', ' ORDER BY r.name)
                        FROM identity.user_role  ur
                                 JOIN identity.role       r
                                      ON  r.role_id   = ur.role_id
                                          AND r.is_active = TRUE
                        WHERE ur.user_id   = pg.user_id
                          AND ur.tenant_id = v_tenant_id
                          AND ur.is_active = TRUE
                          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
                    ),
                    pg.is_active,
                    pg.phone_mobile
            )::api.person_row
            ORDER BY
                pg.father_last_name,
            pg.mother_last_name,
            pg.given_names,
            pg.person_id
    )
INTO v_total, v_result.people
FROM paged pg;

-- ── Metadata de paginación ────────────────────────────────────────────
v_total_pages := GREATEST(
        CEIL(v_total::NUMERIC / v_page_size)::INT, 1
    );

    v_result.success        := TRUE;
    v_result.page_number    := v_page_number;
    v_result.page_size      := v_page_size;
    v_result.total_records  := COALESCE(v_total, 0);
    v_result.total_pages    := v_total_pages;
    v_result.has_next_page  := v_page_number < v_total_pages;
    v_result.has_prev_page  := v_page_number > 1;
    v_result.people         := COALESCE(v_result.people, ARRAY[]::api.person_row[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_permission_templates(api.get_permission_templates_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_permission_templates(p_input api.get_permission_templates_input DEFAULT ROW(true, NULL::character varying(50)[], NULL::character varying(100))::api.get_permission_templates_input) RETURNS api.get_permission_templates_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.get_permission_templates_result;
    v_is_active     BOOLEAN;
    v_role_type     VARCHAR(50)[];
    v_name_search   VARCHAR(100);
    v_items         api.permission_template_report_item[];
    v_rt            VARCHAR(50);

    v_valid_role_types TEXT[] := ARRAY[
        'ADMIN','SUPERVISOR','DISPATCHER','CASHIER',
        'FLEET_MANAGER','HR_MANAGER','OPERATOR','AUDITOR'
    ];
BEGIN

    -- ── Normalizar filtros ────────────────────────────────────────────────
    v_is_active   := COALESCE(p_input.is_active, TRUE);
    v_name_search := NULLIF(TRIM(COALESCE(p_input.name_search, '')), '');

    IF p_input.role_type IS NOT NULL
       AND array_length(p_input.role_type, 1) IS NOT NULL
    THEN
        v_role_type := ARRAY[]::VARCHAR[];
        FOREACH v_rt IN ARRAY p_input.role_type
        LOOP
            v_role_type := v_role_type || UPPER(TRIM(v_rt));
END LOOP;
END IF;

    -- ── Validar role_type si se proveyó ───────────────────────────────────
    IF v_role_type IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_role_type) rt
        WHERE rt NOT IN (
            'ADMIN','SUPERVISOR','DISPATCHER','CASHIER',
            'FLEET_MANAGER','HR_MANAGER','OPERATOR','AUDITOR'
        )
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_ROLE_TYPE';
        v_result.error_message := 'role_type contiene valores inválidos. Válidos: '
                                  || ARRAY_TO_STRING(v_valid_role_types, ', ');
RETURN v_result;
END IF;

    -- ── Query principal: CTE de dos pasos ─────────────────────────────────
    -- Paso 1: filtrar plantillas
    -- Paso 2: agregar permisos por plantilla en un solo escaneo
    -- Sin paginación: máximo ~20 plantillas, el resultado es pequeño
WITH filtered_templates AS (
    SELECT
        pt.template_id,
        pt.name,
        pt.description,
        pt.role_type,
        pt.is_active,
        pt.created_at
    FROM identity.permission_template pt
    WHERE pt.is_active    = v_is_active
      AND (v_role_type  IS NULL OR pt.role_type  = ANY(v_role_type))
      AND (v_name_search IS NULL OR pt.name      ILIKE '%' || v_name_search || '%')
),
     perms_agg AS (
         -- Un único escaneo de detail + permission acotado a las plantillas filtradas
         SELECT
             ptd.template_id,
             COUNT(*)::INT AS total_permissions,
                 array_agg(
                         (
                          p.permission_id,
                          p.code,
                          p.module,
                          p.resource,
                          p.action,
                          p.description,
                          p.is_active
                             )::api.template_permission_item
                          ORDER BY p.module, p.resource, p.action
                 ) AS permissions
         FROM identity.permission_template_detail ptd
                  JOIN identity.permission p ON p.permission_id = ptd.permission_id
         WHERE ptd.template_id = ANY(SELECT template_id FROM filtered_templates)
         GROUP BY ptd.template_id
     )
SELECT array_agg(
               (
                ft.template_id,
                ft.name,
                ft.description,
                ft.role_type,
                ft.is_active,
                COALESCE(pa.total_permissions, 0),
                ft.created_at,
                COALESCE(pa.permissions, ARRAY[]::api.template_permission_item[])
                   )::api.permission_template_report_item
                ORDER BY ft.role_type NULLS LAST, ft.name
       )
INTO v_items
FROM filtered_templates ft
         LEFT JOIN perms_agg pa ON pa.template_id = ft.template_id;

-- ── Resultado ─────────────────────────────────────────────────────────
v_result.success            := TRUE;
    v_result.filter_is_active   := v_is_active;
    v_result.filter_role_type   := v_role_type;
    v_result.filter_name_search := v_name_search;
    v_result.total_count        := COALESCE(array_length(v_items, 1), 0);
    v_result.templates          := COALESCE(v_items, ARRAY[]::api.permission_template_report_item[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_permissions(api.get_permissions_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_permissions(p_input api.get_permissions_input DEFAULT ROW(true, NULL::character varying(50)[], NULL::character varying(50)[], NULL::character varying(50)[], NULL::character varying(100))::api.get_permissions_input) RETURNS api.get_permissions_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.get_permissions_result;
    v_is_active     BOOLEAN;
    v_modules       VARCHAR(50)[];
    v_resources     VARCHAR(50)[];
    v_actions       VARCHAR(50)[];
    v_code_search   VARCHAR(100);
    v_items         api.permission_report_item[];
    v_m             VARCHAR(50);
    v_r             VARCHAR(50);
    v_a             VARCHAR(50);

    v_valid_modules TEXT[] := ARRAY[
        'operations','finance','fleet','hr',
        'admin','reports','system','gps','dispatch'
    ];
BEGIN

    -- ── Normalizar filtros ────────────────────────────────────────────────
    v_is_active   := COALESCE(p_input.is_active, TRUE);
    v_code_search := NULLIF(LOWER(TRIM(COALESCE(p_input.code_search, ''))), '');

    IF p_input.modules IS NOT NULL
       AND array_length(p_input.modules, 1) IS NOT NULL
    THEN
        v_modules := ARRAY[]::VARCHAR[];
        FOREACH v_m IN ARRAY p_input.modules
        LOOP
            v_modules := v_modules || LOWER(TRIM(v_m));
END LOOP;
END IF;

    IF p_input.resources IS NOT NULL
       AND array_length(p_input.resources, 1) IS NOT NULL
    THEN
        v_resources := ARRAY[]::VARCHAR[];
        FOREACH v_r IN ARRAY p_input.resources
        LOOP
            v_resources := v_resources || LOWER(TRIM(v_r));
END LOOP;
END IF;

    IF p_input.actions IS NOT NULL
       AND array_length(p_input.actions, 1) IS NOT NULL
    THEN
        v_actions := ARRAY[]::VARCHAR[];
        FOREACH v_a IN ARRAY p_input.actions
        LOOP
            v_actions := v_actions || LOWER(TRIM(v_a));
END LOOP;
END IF;

    -- ── Validar módulos si se proveyeron ──────────────────────────────────
    IF v_modules IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_modules) m
        WHERE m NOT IN (
            'operations','finance','fleet','hr',
            'admin','reports','system','gps','dispatch'
        )
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_MODULE';
        v_result.error_message := 'modules contiene valores inválidos. Válidos: '
                                  || ARRAY_TO_STRING(v_valid_modules, ', ');
RETURN v_result;
END IF;

    -- ── Consulta ──────────────────────────────────────────────────────────
SELECT array_agg(
               (
                p.permission_id,
                p.code,
                p.module,
                p.resource,
                p.action,
                p.description,
                p.is_active,
                p.created_at
                   )::api.permission_report_item
                ORDER BY p.module, p.resource, p.action
       )
INTO v_items
FROM identity.permission p
WHERE p.is_active       = v_is_active
  AND (v_modules   IS NULL OR p.module   = ANY(v_modules))
  AND (v_resources IS NULL OR p.resource = ANY(v_resources))
  AND (v_actions   IS NULL OR p.action   = ANY(v_actions))
  AND (v_code_search IS NULL OR p.code   ILIKE '%' || v_code_search || '%');

-- ── Resultado ─────────────────────────────────────────────────────────
v_result.success            := TRUE;
    v_result.filter_is_active   := v_is_active;
    v_result.filter_modules     := v_modules;
    v_result.filter_resources   := v_resources;
    v_result.filter_actions     := v_actions;
    v_result.filter_code_search := v_code_search;
    v_result.total_count        := COALESCE(array_length(v_items, 1), 0);
    v_result.permissions        := COALESCE(v_items, ARRAY[]::api.permission_report_item[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_person_detail(api.get_person_detail_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_person_detail(p_input api.get_person_detail_input) RETURNS api.get_person_detail_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result    api.get_person_detail_result;
    v_user_id   BIGINT;
BEGIN

    -- ── Validaciones ──────────────────────────────────────────────────────
    IF p_input.person_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_PERSON_ID';
        v_result.error_message := 'person_id es obligatorio';
RETURN v_result;
END IF;

    IF p_input.tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Paso 1: datos de la persona ───────────────────────────────────────
SELECT
    p.person_id,
    p.tax_id,
    p.full_name,
    p.given_names,
    p.father_last_name,
    p.mother_last_name,
    p.gender,
    p.birth_date,
    p.nationality,
    p.marital_status,
    p.blood_type,
    p.email,
    p.phone_mobile,
    p.phone_home,
    p.emergency_contact_name,
    p.emergency_contact_phone,
    p.photo_url,
    p.is_active,
    p.created_at,
    p.updated_at
INTO
    v_result.person_id,
    v_result.tax_id,
    v_result.full_name,
    v_result.given_names,
    v_result.father_last_name,
    v_result.mother_last_name,
    v_result.gender,
    v_result.birth_date,
    v_result.nationality,
    v_result.marital_status,
    v_result.blood_type,
    v_result.email,
    v_result.phone_mobile,
    v_result.phone_home,
    v_result.emergency_contact_name,
    v_result.emergency_contact_phone,
    v_result.photo_url,
    v_result.is_active,
    v_result.person_created_at,
    v_result.person_updated_at
FROM hr.person p
WHERE p.person_id = p_input.person_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'PERSON_NOT_FOUND';
        v_result.error_message := 'person_id=' || p_input.person_id || ' no existe';
RETURN v_result;
END IF;

    -- ── Paso 2: cuenta de sistema vía personnel o driver ──────────────────
    -- Ambos tienen UNIQUE(person_id) y UNIQUE(user_id) → sin duplicados
SELECT
    COALESCE(pnl.user_id, drv.user_id),
    CASE
        WHEN pnl.person_id IS NOT NULL THEN 'PERSONNEL'
        WHEN drv.person_id IS NOT NULL THEN 'DRIVER'
        ELSE NULL
        END,
    COALESCE(pnl.employee_code, drv.driver_code),
    pnl.job_title,
    pnl.department,
    pnl.employment_type,
    COALESCE(pnl.employment_status, drv.employment_status),
    COALESCE(pnl.hire_date, drv.hire_date)
INTO
    v_user_id,
    v_result.role_type,
    v_result.employee_code,
    v_result.job_title,
    v_result.department,
    v_result.employment_type,
    v_result.employment_status,
    v_result.hire_date
FROM hr.person p
         LEFT JOIN hr.personnel pnl ON pnl.person_id = p.person_id
         LEFT JOIN hr.driver    drv ON drv.person_id = p.person_id
WHERE p.person_id = p_input.person_id;

-- ── Paso 3: datos de identity.user si tiene cuenta ────────────────────
IF v_user_id IS NOT NULL THEN
SELECT
    u.user_id,
    u.external_id,
    u.username,
    u.email,
    u.is_active,
    u.last_login_at
INTO
    v_result.user_id,
    v_result.external_id,
    v_result.username,
    v_result.user_email,
    v_result.user_is_active,
    v_result.last_login_at
FROM identity."user" u
WHERE u.user_id = v_user_id;

-- ── Paso 4: acceso al tenant ──────────────────────────────────────
SELECT
    uta.user_tenant_access_id,
    uta.tenant_id,
    uta.is_active,
    uta.granted_at
INTO
    v_result.tenant_access_id,
    v_result.tenant_id,
    v_result.tenant_access_active,
    v_result.granted_at
FROM identity.user_tenant_access uta
WHERE uta.user_id   = v_user_id
  AND uta.tenant_id = p_input.tenant_id;
-- NOT FOUND es válido: persona existe pero sin acceso al tenant aún

-- ── Paso 5: roles activos en el tenant ────────────────────────────
-- Solo se ejecuta si tiene cuenta; acotado a filas activas del usuario
SELECT array_agg(
               (
                ur.user_role_id,
                ur.role_id,
                r.name,
                (ur.expires_at IS NOT NULL),
                ur.expires_at,
                ur.assigned_at
                   )::api.person_role_item
                ORDER BY r.name
       )
INTO v_result.roles
FROM identity.user_role ur
         JOIN identity.role r
              ON  r.role_id   = ur.role_id
                  AND r.is_active = TRUE
WHERE ur.user_id   = v_user_id
  AND ur.tenant_id = p_input.tenant_id
  AND ur.is_active = TRUE
  AND (ur.expires_at IS NULL OR ur.expires_at > NOW());

END IF;

    -- ── Defaults para campos opcionales ───────────────────────────────────
    v_result.roles := COALESCE(v_result.roles, ARRAY[]::api.person_role_item[]);

    v_result.success := TRUE;
RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_personnel(api.get_personnel_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_personnel(p_input api.get_personnel_input) RETURNS api.get_personnel_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_personnel_result;
    v_tenant_id         BIGINT;
    v_page_number       INT;
    v_page_size         INT;
    v_offset            INT;
    v_search            TEXT;
    v_total             BIGINT;
    v_total_pages       INT;
BEGIN

    -- ── Normalizar parámetros ─────────────────────────────────────────
    v_tenant_id   := p_input.tenant_id;
    v_page_number := GREATEST(COALESCE(p_input.page_number, 1), 1);
    v_page_size   := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset      := (v_page_number - 1) * v_page_size;
    v_search      := NULLIF(TRIM(COALESCE(p_input.search, '')), '');

    -- ── Validaciones ──────────────────────────────────────────────────
    IF v_tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    IF NOT EXISTS (
        SELECT 1 FROM identity.tenant WHERE tenant_id = v_tenant_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'TENANT_NOT_FOUND';
        v_result.error_message := 'El tenant_id=' || v_tenant_id || ' no existe';
RETURN v_result;
END IF;

    -- ════════════════════════════════════════════════════════════════
    -- QUERY PRINCIPAL
    --
    -- Punto de entrada: hr.personnel (incluye registros sin user_id)
    --
    -- Filtro de tenant: personnel.company_id → identity.tenant_company
    -- Esto garantiza que solo se listan empleados de empresas que
    -- pertenecen al tenant solicitado.
    --
    -- El JOIN a identity.user es LEFT JOIN → personas sin cuenta
    -- aparecen con user_id/username/roles = NULL.
    -- ════════════════════════════════════════════════════════════════
WITH base AS (
    SELECT
        pnl.personnel_id,
        p.person_id,
        p.given_names,
        p.father_last_name,
        p.mother_last_name,
        p.full_name,
        p.tax_id,
        p.is_active,
        p.phone_mobile,
        pnl.employee_code,
        pnl.job_title,
        pnl.department,
        pnl.employment_type,
        pnl.employment_status,
        pnl.hire_date,
        pnl.termination_date,
        -- Datos de cuenta (opcionales)
        u.user_id,
        u.external_id,
        u.username
    FROM hr.personnel pnl
             -- ▶ Filtro de tenant a través de la empresa
             JOIN identity.tenant_company tc
                  ON  tc.company_id = pnl.company_id
                      AND tc.tenant_id  = v_tenant_id
                      AND tc.is_active  = TRUE
        -- ▶ Datos de persona (siempre existe por FK NOT NULL)
             JOIN hr.person p
                  ON  p.person_id = pnl.person_id
        -- ▶ Cuenta del sistema (opcional)
             LEFT JOIN identity."user" u
                       ON  u.user_id = pnl.user_id
    WHERE
      -- Filtro is_active sobre la persona
        (p_input.is_active IS NULL OR p.is_active = p_input.is_active)
      -- Filtro employment_status sobre el registro de personal
      AND (p_input.employment_status IS NULL
        OR pnl.employment_status = p_input.employment_status)
      -- Filtro search: nombre completo, tax_id, username o employee_code
      AND (
        v_search IS NULL
            OR p.full_name       ILIKE '%' || v_search || '%'
            OR p.tax_id          ILIKE '%' || v_search || '%'
            OR u.username        ILIKE '%' || v_search || '%'
            OR pnl.employee_code ILIKE '%' || v_search || '%'
        )
),
     counted AS (
         SELECT COUNT(*) AS total FROM base
     ),
     paged AS (
         SELECT *
         FROM base
         ORDER BY
             father_last_name,
             mother_last_name,
             given_names,
             personnel_id
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT
    (SELECT total FROM counted),
    ARRAY_AGG(
            ROW(
                    pg.personnel_id,
                    pg.person_id,
                -- display_name: máx 2 nombres de pila + apellidos
                    TRIM(
                            CASE
                                WHEN array_length(
                                             string_to_array(TRIM(pg.given_names), ' '), 1
                                     ) >= 2
                                    THEN (string_to_array(TRIM(pg.given_names), ' '))[1]
                              || ' '
                              || (string_to_array(TRIM(pg.given_names), ' '))[2]
                                ELSE TRIM(pg.given_names)
                                END
                                || ' ' || pg.father_last_name
                                || ' ' || pg.mother_last_name
                    ),
                    pg.given_names,
                    pg.father_last_name,
                    pg.mother_last_name,
                    pg.tax_id,
                    pg.employee_code,
                    pg.job_title,
                    pg.department,
                    pg.employment_type,
                    pg.employment_status,
                    pg.hire_date,
                    pg.termination_date,
                    pg.user_id,
                    pg.external_id,
                    pg.username,
                -- Roles activos (NULL si no tiene cuenta)
                    CASE WHEN pg.user_id IS NOT NULL THEN (
                        SELECT STRING_AGG(r.name, ', ' ORDER BY r.name)
                        FROM identity.user_role  ur
                                 JOIN identity.role       r
                                      ON  r.role_id   = ur.role_id
                                          AND r.is_active = TRUE
                        WHERE ur.user_id   = pg.user_id
                          AND ur.tenant_id = v_tenant_id
                          AND ur.is_active = TRUE
                          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
                    ) END,
                    pg.is_active,
                    pg.phone_mobile
            )::api.personnel_row
            ORDER BY
                pg.father_last_name,
            pg.mother_last_name,
            pg.given_names,
            pg.personnel_id
    )
INTO v_total, v_result.personnel
FROM paged pg;

-- ── Metadata de paginación ────────────────────────────────────────
v_total_pages := GREATEST(
        CEIL(v_total::NUMERIC / v_page_size)::INT, 1
    );

    v_result.success        := TRUE;
    v_result.page_number    := v_page_number;
    v_result.page_size      := v_page_size;
    v_result.total_records  := COALESCE(v_total, 0);
    v_result.total_pages    := v_total_pages;
    v_result.has_next_page  := v_page_number < v_total_pages;
    v_result.has_prev_page  := v_page_number > 1;
    v_result.personnel      := COALESCE(v_result.personnel, ARRAY[]::api.personnel_row[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_persons_by_type(api.get_persons_by_type_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_persons_by_type(p_input api.get_persons_by_type_input) RETURNS api.get_persons_by_type_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result        api.get_persons_by_type_result;
    v_person_type   VARCHAR(20);
    v_is_active     BOOLEAN;
    v_search        TEXT;
    v_company_ids   INT[];
    v_only_base     BOOLEAN;
    v_page_number   INT;
    v_page_size     INT;
    v_offset        INT;
    v_total         BIGINT;
    v_total_pages   INT;
BEGIN

    -- ── Validación ────────────────────────────────────────────────────────
    IF p_input.person_type IS NULL OR TRIM(p_input.person_type) = '' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_PERSON_TYPE';
        v_result.error_message := 'person_type es obligatorio. Válidos: PERSON, DRIVER, OWNER';
RETURN v_result;
END IF;

    v_person_type := UPPER(TRIM(p_input.person_type));

    IF v_person_type NOT IN ('PERSON', 'DRIVER', 'OWNER') THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_PERSON_TYPE';
        v_result.error_message := 'person_type="' || p_input.person_type
            || '" inválido. Válidos: PERSON, DRIVER, OWNER';
RETURN v_result;
END IF;

    -- ── Normalizar ────────────────────────────────────────────────────────
    v_is_active   := COALESCE(p_input.is_active, TRUE);
    v_search      := NULLIF(TRIM(COALESCE(p_input.search, '')), '');
    v_only_base   := COALESCE(p_input.only_base, FALSE);
    v_page_number := GREATEST(COALESCE(p_input.page_number, 1), 1);
    v_page_size   := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset      := (v_page_number - 1) * v_page_size;

    v_company_ids := CASE
                         WHEN p_input.company_ids IS NULL
                             OR array_length(p_input.company_ids, 1) IS NULL
                             THEN NULL
                         ELSE p_input.company_ids
END;

    -- ════════════════════════════════════════════════════════
    -- RAMA PERSON
    -- only_base=TRUE → excluye personas que son DRIVER u OWNER
    -- only_base=FALSE → devuelve todas las personas
    -- ════════════════════════════════════════════════════════
    IF v_person_type = 'PERSON' THEN

SELECT COUNT(*)
INTO v_total
FROM hr.person p
WHERE p.is_active = v_is_active
  AND (v_search IS NULL
    OR p.full_name ILIKE '%' || v_search || '%'
            OR p.tax_id    ILIKE '%' || v_search || '%')
  AND (
    NOT v_only_base
        OR (
        NOT EXISTS (SELECT 1 FROM hr.driver d
                    WHERE d.person_id = p.person_id)
            AND
        NOT EXISTS (SELECT 1 FROM fleet.vehicle_owner vo
                    WHERE vo.person_id = p.person_id)
        )
    );

WITH paged AS (
    SELECT
        p.person_id,
        p.full_name,
        p.tax_id,
        p.phone_mobile,
        p.email,
        p.is_active,
        COALESCE(pnl.user_id, drv.user_id) AS user_id
    FROM hr.person p
             LEFT JOIN hr.personnel pnl ON pnl.person_id = p.person_id
             LEFT JOIN hr.driver    drv ON drv.person_id = p.person_id
    WHERE p.is_active = v_is_active
      AND (v_search IS NULL
        OR p.full_name ILIKE '%' || v_search || '%'
                OR p.tax_id    ILIKE '%' || v_search || '%')
      AND (
        NOT v_only_base
            OR (
            NOT EXISTS (SELECT 1 FROM hr.driver d
                        WHERE d.person_id = p.person_id)
                AND
            NOT EXISTS (SELECT 1 FROM fleet.vehicle_owner vo
                        WHERE vo.person_id = p.person_id)
            )
        )
    ORDER BY p.father_last_name, p.mother_last_name, p.given_names
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT array_agg(
               (
                pg.person_id, pg.person_id, 'PERSON',
                pg.full_name, pg.tax_id, pg.phone_mobile, pg.email, pg.is_active,
                NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                NULL, NULL, NULL, NULL,
                pg.user_id, u.username
                   )::api.person_type_row
                ORDER BY pg.full_name
       )
INTO v_result.people
FROM paged pg
         LEFT JOIN identity."user" u ON u.user_id = pg.user_id;

-- ════════════════════════════════════════════════════════
-- RAMA DRIVER
-- only_base=TRUE → excluye drivers que también son OWNER
-- only_base=FALSE → devuelve todos los drivers
-- ════════════════════════════════════════════════════════
ELSIF v_person_type = 'DRIVER' THEN

SELECT COUNT(*)
INTO v_total
FROM hr.driver d
         JOIN hr.person p ON p.person_id = d.person_id
WHERE p.is_active = v_is_active
  AND (v_company_ids IS NULL OR d.company_id = ANY(v_company_ids))
  AND (v_search IS NULL
    OR p.full_name   ILIKE '%' || v_search || '%'
            OR p.tax_id      ILIKE '%' || v_search || '%'
            OR d.driver_code ILIKE '%' || v_search || '%')
  AND (
    NOT v_only_base
        OR NOT EXISTS (SELECT 1 FROM fleet.vehicle_owner vo
                       WHERE vo.person_id = d.person_id)
    );

WITH paged AS (
    SELECT
        p.person_id,
        d.driver_id,
        p.full_name,
        p.tax_id,
        p.phone_mobile,
        p.email,
        p.is_active,
        d.driver_code,
        d.company_id,
        c.trade_name        AS company_name,
        d.employment_type,
        d.employment_status,
        d.license_points,
        d.is_available,
        d.current_vehicle_id,
        d.user_id
    FROM hr.driver d
             JOIN hr.person      p ON p.person_id  = d.person_id
             JOIN shared.company c ON c.company_id = d.company_id
    WHERE p.is_active = v_is_active
      AND (v_company_ids IS NULL OR d.company_id = ANY(v_company_ids))
      AND (v_search IS NULL
        OR p.full_name   ILIKE '%' || v_search || '%'
                OR p.tax_id      ILIKE '%' || v_search || '%'
                OR d.driver_code ILIKE '%' || v_search || '%')
      AND (
        NOT v_only_base
            OR NOT EXISTS (SELECT 1 FROM fleet.vehicle_owner vo
                           WHERE vo.person_id = d.person_id)
        )
    ORDER BY p.father_last_name, p.mother_last_name, p.given_names
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT array_agg(
               (
                pg.person_id, pg.driver_id, 'DRIVER',
                pg.full_name, pg.tax_id, pg.phone_mobile, pg.email, pg.is_active,
                pg.driver_code, pg.company_id, pg.company_name,
                pg.employment_type, pg.employment_status,
                pg.license_points, pg.is_available,
                v.plate_number,
                NULL, NULL, NULL, NULL,
                pg.user_id, u.username
                   )::api.person_type_row
                ORDER BY pg.full_name
       )
INTO v_result.people
FROM paged pg
         LEFT JOIN fleet.vehicle   v ON v.vehicle_id = pg.current_vehicle_id
         LEFT JOIN identity."user" u ON u.user_id    = pg.user_id;

-- ════════════════════════════════════════════════════════
-- RAMA OWNER
-- only_base=TRUE → excluye owners que también son DRIVER
-- only_base=FALSE → devuelve todos los owners
-- ════════════════════════════════════════════════════════
ELSIF v_person_type = 'OWNER' THEN

SELECT COUNT(*)
INTO v_total
FROM fleet.vehicle_owner vo
         JOIN hr.person p ON p.person_id = vo.person_id
WHERE vo.is_active = v_is_active
  AND (v_search IS NULL
    OR vo.full_name ILIKE '%' || v_search || '%'
            OR vo.tax_id    ILIKE '%' || v_search || '%')
  AND (
    NOT v_only_base
        OR NOT EXISTS (SELECT 1 FROM hr.driver d
                       WHERE d.person_id = vo.person_id)
    );

WITH paged AS (
    SELECT
        p.person_id,
        vo.vehicle_owner_id,
        vo.full_name,
        vo.tax_id,
        p.phone_mobile,
        vo.email,
        vo.is_active,
        vo.phone        AS owner_phone,
        vo.bank_account,
        (
            SELECT COUNT(*)::INT
            FROM fleet.vehicle_owner_share vos
            WHERE vos.vehicle_owner_id = vo.vehicle_owner_id
              AND vos.is_active = TRUE
              AND (vos.valid_until IS NULL OR vos.valid_until >= CURRENT_DATE)
        )               AS vehicles_owned,
        COALESCE(pnl.user_id, drv.user_id) AS user_id
    FROM fleet.vehicle_owner vo
             JOIN hr.person      p   ON p.person_id   = vo.person_id
             LEFT JOIN hr.personnel pnl ON pnl.person_id = p.person_id
             LEFT JOIN hr.driver    drv ON drv.person_id = p.person_id
    WHERE vo.is_active = v_is_active
      AND (v_search IS NULL
        OR vo.full_name ILIKE '%' || v_search || '%'
                OR vo.tax_id    ILIKE '%' || v_search || '%')
      AND (
        NOT v_only_base
            OR NOT EXISTS (SELECT 1 FROM hr.driver d
                           WHERE d.person_id = vo.person_id)
        )
    ORDER BY vo.full_name
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT array_agg(
               (
                pg.person_id, pg.vehicle_owner_id, 'OWNER',
                pg.full_name, pg.tax_id, pg.phone_mobile, pg.email, pg.is_active,
                NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                pg.vehicle_owner_id,
                pg.owner_phone, pg.bank_account, pg.vehicles_owned,
                pg.user_id, u.username
                   )::api.person_type_row
                ORDER BY pg.full_name
       )
INTO v_result.people
FROM paged pg
         LEFT JOIN identity."user" u ON u.user_id = pg.user_id;

END IF;

    -- ── Metadata ──────────────────────────────────────────────────────────
    v_total_pages := GREATEST(
            CEIL(COALESCE(v_total, 0)::NUMERIC / v_page_size)::INT, 1
                     );

    v_result.success        := TRUE;
    v_result.person_type    := v_person_type;
    v_result.page_number    := v_page_number;
    v_result.page_size      := v_page_size;
    v_result.total_records  := COALESCE(v_total, 0);
    v_result.total_pages    := v_total_pages;
    v_result.has_next_page  := v_page_number < v_total_pages;
    v_result.has_prev_page  := v_page_number > 1;
    v_result.people         := COALESCE(v_result.people, ARRAY[]::api.person_type_row[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_roles(api.get_roles_input_v2); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_roles(p_input api.get_roles_input_v2) RETURNS api.get_roles_result_v2
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.get_roles_result_v2;
    v_is_active             BOOLEAN;
    v_name_search           VARCHAR(100);
    v_perm_module           VARCHAR(50);
    v_include_empty         BOOLEAN;
    v_items                 api.role_list_item_v2[];
BEGIN

    -- ── Validación 1: tenant_id obligatorio ───────────────────────────────
    IF p_input.tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: tenant existe ───────────────────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM identity.tenant
        WHERE tenant_id = p_input.tenant_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'TENANT_NOT_FOUND';
        v_result.error_message := 'tenant_id=' || p_input.tenant_id || ' no existe';
RETURN v_result;
END IF;

    -- ── Normalizar filtros ────────────────────────────────────────────────
    v_is_active     := COALESCE(p_input.is_active, TRUE);
    v_name_search   := NULLIF(TRIM(COALESCE(p_input.name_search, '')), '');
    v_perm_module   := NULLIF(LOWER(TRIM(COALESCE(p_input.permission_module, ''))), '');
    v_include_empty := COALESCE(p_input.include_empty_roles, FALSE);

    -- ── Validar permission_module si se proveyó ───────────────────────────
    IF v_perm_module IS NOT NULL
       AND v_perm_module NOT IN (
           'logistics','finance','hr','admin','reports','system','gps','dispatch'
       )
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_PERMISSION_MODULE';
        v_result.error_message := 'permission_module inválido: "' || v_perm_module
                                  || '". Válidos: logistics, finance, hr, admin, '
                                  || 'reports, system, gps, dispatch';
RETURN v_result;
END IF;

    -- ── Query principal: un único barrido con CTEs anidados ───────────────
    --
    -- Estrategia de eficiencia:
    --   1. filtered_roles  → filtra los roles del tenant una vez
    --   2. role_perms      → trae todos los permisos de esos roles en un escaneo
    --   3. perm_scopes     → trae todos los scopes de esos role_permission_ids en un escaneo
    --   4. scopes_agg      → agrega scopes como array por role_permission_id
    --   5. perms_agg       → agrega permisos (con scopes embebidos) por role_id
    --   6. SELECT final    → construye el tipo compuesto sin subqueries adicionales
    --
    -- Sin paginación: con ≤60 roles el resultado completo cabe en memoria
    -- y evita el doble escaneo de COUNT + SELECT.

WITH filtered_roles AS (
    SELECT
        r.role_id,
        r.tenant_id,
        r.name,
        r.description,
        r.is_active,
        r.created_at,
        r.updated_at
    FROM identity.role r
    WHERE r.tenant_id = p_input.tenant_id
      AND r.is_active  = v_is_active
      AND (v_name_search IS NULL OR r.name ILIKE '%' || v_name_search || '%')
),
     role_perms AS (
         -- Todos los permisos de todos los roles filtrados: un solo escaneo
         SELECT
             rp.role_permission_id,
             rp.role_id,
             rp.permission_id,
             rp.is_active        AS rp_is_active,
             p.code,
             p.module,
             p.resource,
             p.action,
             p.description
         FROM identity.role_permission rp
                  JOIN identity.permission p ON p.permission_id = rp.permission_id
         WHERE rp.role_id = ANY(SELECT role_id FROM filtered_roles)
           -- Si se filtra por módulo, solo permisos de ese módulo
           AND (v_perm_module IS NULL OR p.module = v_perm_module)
     ),
     perm_scopes AS (
         -- Todos los scopes de los role_permission anteriores: un solo escaneo
         SELECT
             rps.role_permission_scope_id,
             rps.role_permission_id,
             rps.scope_type_id,
             st.code             AS scope_type_code,
             rps.scope_id,
             rps.company_id,
             rps.is_active
         FROM identity.role_permission_scope rps
                  JOIN identity.scope_type st ON st.scope_type_id = rps.scope_type_id
         WHERE rps.role_permission_id = ANY(SELECT role_permission_id FROM role_perms)
           AND rps.is_active = TRUE
     ),
     scopes_agg AS (
         -- Agrega scopes como array por role_permission_id
         SELECT
             role_permission_id,
             array_agg(
                     (
                      role_permission_scope_id,
                      scope_type_id,
                      scope_type_code,
                      scope_id,
                      company_id,
                      is_active
                         )::api.role_scope_item_v2
                      ORDER BY scope_type_code, scope_id
             ) AS scopes,
             COUNT(*)::INT AS scope_count
         FROM perm_scopes
         GROUP BY role_permission_id
     ),
     perms_agg AS (
         -- Agrega permisos (con scopes embebidos) como array por role_id
         SELECT
             rp.role_id,
             array_agg(
                     (
                      rp.role_permission_id,
                      rp.permission_id,
                      rp.code,
                      rp.module,
                      rp.resource,
                      rp.action,
                      rp.description,
                      rp.rp_is_active,
                      COALESCE(sa.scope_count, 0),
                      COALESCE(sa.scopes, ARRAY[]::api.role_scope_item_v2[])
                         )::api.role_permission_item_v2
                      ORDER BY rp.module, rp.code
             )                           AS permissions,
             COUNT(*) FILTER (
                WHERE rp.rp_is_active = TRUE
            )::INT                      AS active_permission_count
         FROM role_perms rp
                  LEFT JOIN scopes_agg sa ON sa.role_permission_id = rp.role_permission_id
         GROUP BY rp.role_id
     )
SELECT array_agg(
               (
                fr.role_id,
                fr.tenant_id,
                fr.name,
                fr.description,
                fr.is_active,
                COALESCE(pa.active_permission_count, 0),
                fr.created_at,
                fr.updated_at,
                COALESCE(pa.permissions, ARRAY[]::api.role_permission_item_v2[])
                   )::api.role_list_item_v2
                ORDER BY fr.name
       )
INTO v_items
FROM filtered_roles fr
         LEFT JOIN perms_agg pa ON pa.role_id = fr.role_id
-- Si include_empty_roles=FALSE, excluir roles sin permisos en el módulo filtrado
WHERE (
          v_include_empty = TRUE
              OR v_perm_module IS NULL
              OR pa.role_id IS NOT NULL
          );

-- ── Resultado ─────────────────────────────────────────────────────────
v_result.success                    := TRUE;
    v_result.tenant_id                  := p_input.tenant_id;
    v_result.filter_is_active           := v_is_active;
    v_result.filter_name_search         := v_name_search;
    v_result.filter_permission_module   := v_perm_module;
    v_result.filter_include_empty_roles := v_include_empty;
    v_result.total_count                := COALESCE(array_length(v_items, 1), 0);
    v_result.roles                      := COALESCE(v_items, ARRAY[]::api.role_list_item_v2[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_routes(api.get_routes_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_routes(p_input api.get_routes_input DEFAULT ROW(NULL::integer[], NULL::boolean, NULL::character varying(20)[], NULL::character varying(255), false)::api.get_routes_input) RETURNS api.get_routes_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.get_routes_result;
    v_company_ids       INT[];
    v_is_active         BOOLEAN;
    v_route_type        VARCHAR(20)[];
    v_name_search       VARCHAR(255);
    v_incomplete_only   BOOLEAN;
    v_items             api.route_report_item[];
    v_rt                VARCHAR(20);
BEGIN

    -- ── Normalizar filtros ────────────────────────────────────────────────
    v_company_ids := CASE
        WHEN p_input.company_ids IS NULL
          OR array_length(p_input.company_ids, 1) IS NULL
        THEN NULL
        ELSE p_input.company_ids
END;

    v_is_active       := COALESCE(p_input.is_active, TRUE);
    v_name_search     := NULLIF(TRIM(COALESCE(p_input.name_search, '')), '');
    v_incomplete_only := COALESCE(p_input.incomplete_only, FALSE);

    IF p_input.route_type IS NOT NULL
       AND array_length(p_input.route_type, 1) IS NOT NULL
    THEN
        v_route_type := ARRAY[]::VARCHAR[];
        FOREACH v_rt IN ARRAY p_input.route_type
        LOOP
            v_route_type := v_route_type || UPPER(TRIM(v_rt));
END LOOP;
END IF;

    -- ── Validaciones ──────────────────────────────────────────────────────
    IF v_route_type IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_route_type) rt
        WHERE rt NOT IN ('LINEAR', 'CIRCULAR')
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_ROUTE_TYPE';
        v_result.error_message := 'route_type contiene valores inválidos. Válidos: LINEAR, CIRCULAR';
RETURN v_result;
END IF;

    IF v_company_ids IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_company_ids) cid
        LEFT JOIN shared.company c ON c.company_id = cid
        WHERE c.company_id IS NULL
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'COMPANY_NOT_FOUND';
        v_result.error_message := 'Uno o más company_id del filtro no existen';
RETURN v_result;
END IF;

    -- ── Query principal con patrón CTE ────────────────────────────────────
WITH filtered_routes AS (
    -- Paso 1: rutas que cumplen los filtros
    SELECT
        r.route_id,
        r.company_id,
        c.trade_name        AS company_name,
        r.code,
        r.name,
        r.route_type,
        r.total_distance_km,
        r.estimated_duration_minutes,
        r.is_active,
        r.created_at,
        r.updated_at
    FROM core_operations.route r
             JOIN shared.company c ON c.company_id = r.company_id
    WHERE (v_company_ids IS NULL   OR r.company_id  = ANY(v_company_ids))
      AND r.is_active               = v_is_active
      AND (v_route_type IS NULL     OR r.route_type = ANY(v_route_type))
      AND (v_name_search IS NULL    OR r.name       ILIKE '%' || v_name_search || '%')
),
     checkpoint_agg AS (
         -- Paso 2: resumen de checkpoints por ruta + dirección
         -- Un único escaneo sobre checkpoint acotado a los route_ids filtrados
         SELECT
             cp.route_id,
             cp.direction,
             COUNT(*)::INT                                                       AS total_checkpoints,
                 COUNT(*) FILTER (WHERE cp.checkpoint_type = 'bus_stop')::INT       AS total_bus_stops,
                 COUNT(*) FILTER (WHERE cp.checkpoint_type = 'checkpoint')::INT     AS total_controls,
                 COUNT(*) FILTER (WHERE cp.checkpoint_type = 'terminal')::INT       AS total_terminals,
                 BOOL_OR(cp.checkpoint_type = 'terminal' AND cp.is_route_endpoint)  AS has_endpoints,
             MAX(cp.distance_from_origin_km)                                    AS total_distance_km,
             MAX(cp.estimated_duration_minutes)                                  AS estimated_duration_min
         FROM core_operations.checkpoint cp
         WHERE cp.route_id  = ANY(SELECT route_id FROM filtered_routes)
           AND cp.is_active = TRUE
         GROUP BY cp.route_id, cp.direction
     ),
     checkpoint_summary_agg AS (
         -- Paso 3: agrega el resumen por dirección en array por route_id
         SELECT
             route_id,
             array_agg(
                     (
                      direction,
                      total_checkpoints,
                      total_bus_stops,
                      total_controls,
                      total_terminals,
                      has_endpoints,
                      total_distance_km,
                      estimated_duration_min
                         )::api.route_checkpoint_summary
                      ORDER BY direction
             ) AS summary,
             -- Para inferir nombre de terminales: traer el de dirección IDA
             BOOL_OR(has_endpoints) AS route_has_endpoints
         FROM checkpoint_agg
         GROUP BY route_id
     ),
     terminals_ida AS (
         -- Paso 4: nombre de terminales de origen y destino desde IDA
         -- Solo los endpoint terminals, ordenados por sequence_number
         SELECT DISTINCT ON (cp.route_id, cp.is_route_endpoint)
    cp.route_id,
    cp.is_route_endpoint,
    cp.name,
    cp.sequence_number
FROM core_operations.checkpoint cp
WHERE cp.route_id  = ANY(SELECT route_id FROM filtered_routes)
  AND cp.checkpoint_type  = 'terminal'
  AND cp.is_route_endpoint = TRUE
  AND cp.direction         IN ('IDA', 'CIRCULAR')
  AND cp.is_active         = TRUE
ORDER BY cp.route_id, cp.is_route_endpoint, cp.sequence_number
    ),
    route_controls AS (
-- Paso 5: conteo de controles de tiempo por ruta
SELECT
    rc.route_id,
    COUNT(*)::INT                                   AS total_control_points,
    COUNT(*) FILTER (WHERE rc.is_mandatory)::INT   AS mandatory_control_points
FROM core_operations.route_control rc
WHERE rc.route_id = ANY(SELECT route_id FROM filtered_routes)
GROUP BY rc.route_id
    ),
    polyline_flags AS (
-- Paso 6: presencia de polylines por ruta (sin traer las coordenadas)
SELECT
    rp.route_id,
    BOOL_OR(rp.direction = 'IDA')    AS has_polyline_ida,
    BOOL_OR(rp.direction = 'VUELTA') AS has_polyline_vuelta
FROM core_operations.route_polyline rp
WHERE rp.route_id = ANY(SELECT route_id FROM filtered_routes)
GROUP BY rp.route_id
    )
SELECT array_agg(
               (
                fr.route_id,
                fr.company_id,
                fr.company_name,
                fr.code,
                fr.name,
                fr.route_type,
                fr.total_distance_km,
                fr.estimated_duration_minutes,
                fr.is_active,
                   -- Origen: terminal IDA con sequence más bajo
                (SELECT name FROM terminals_ida
                 WHERE route_id = fr.route_id
                 ORDER BY sequence_number ASC  LIMIT 1),
           -- Destino: terminal IDA con sequence más alto
               (SELECT name FROM terminals_ida
                WHERE route_id = fr.route_id
                ORDER BY sequence_number DESC LIMIT 1),
            COALESCE(cs.summary, ARRAY[]::api.route_checkpoint_summary[]),
            COALESCE(rc.total_control_points, 0),
            COALESCE(rc.mandatory_control_points, 0),
            COALESCE(pf.has_polyline_ida, FALSE),
            COALESCE(pf.has_polyline_vuelta, FALSE),
            fr.created_at,
            fr.updated_at
        )::api.route_report_item
        ORDER BY fr.company_name, fr.code
    )
INTO v_items
FROM filtered_routes fr
         LEFT JOIN checkpoint_summary_agg cs ON cs.route_id = fr.route_id
         LEFT JOIN route_controls          rc ON rc.route_id = fr.route_id
         LEFT JOIN polyline_flags          pf ON pf.route_id = fr.route_id
-- Filtro incomplete_only: rutas sin endpoints definidos en checkpoint
WHERE (
          NOT v_incomplete_only
              OR COALESCE(cs.route_has_endpoints, FALSE) = FALSE
          );

-- ── Resultado ─────────────────────────────────────────────────────────
v_result.success                := TRUE;
    v_result.filter_company_ids     := v_company_ids;
    v_result.filter_is_active       := v_is_active;
    v_result.filter_route_type      := v_route_type;
    v_result.filter_name_search     := v_name_search;
    v_result.filter_incomplete_only := v_incomplete_only;
    v_result.total_count            := COALESCE(array_length(v_items, 1), 0);
    v_result.routes                 := COALESCE(v_items, ARRAY[]::api.route_report_item[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_tenant_full(integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_tenant_full(p_tenant_id integer) RETURNS api.result_get_tenant_full_api
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result api.result_get_tenant_full_api;
    v_tenant_record RECORD;
BEGIN
    v_result.success := true;
    v_result.error_code := NULL;
    v_result.error_message := NULL;

    -- Obtener tenant
    SELECT * INTO v_tenant_record
    FROM identity.tenant
    WHERE tenant_id = p_tenant_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tenant no encontrado'
            USING ERRCODE = 'P0002';
    END IF;

    v_result.tenant_id := v_tenant_record.tenant_id;
    v_result.tenant_name := v_tenant_record.name;
    v_result.tenant_is_active := v_tenant_record.is_active;
    v_result.tenant_created_at := v_tenant_record.created_at;

    -- Obtener empresas como array de tipos compuestos
    SELECT ARRAY_AGG(
        ROW(
            tc.tenant_company_id,
            c.company_id,
            c.tax_id,
            c.legal_name,
            c.trade_name,
            c.email,
            c.phone,
            c.address,
            c.is_active,
            tc.is_active,
            tc.created_at
        )::api.tenant_company_detail
        ORDER BY tc.tenant_company_id
    )
    INTO v_result.companies
    FROM identity.tenant_company tc
    INNER JOIN shared.company c ON tc.company_id = c.company_id
    WHERE tc.tenant_id = p_tenant_id;

    RETURN v_result;

EXCEPTION
    WHEN no_data_found THEN
        v_result.success := false;
        v_result.error_code := 'TENANT_NOT_FOUND';
        v_result.error_message := 'El tenant no existe';
        RETURN v_result;
    WHEN OTHERS THEN
        v_result.success := false;
        v_result.error_code := SQLSTATE;
        v_result.error_message := SQLERRM;
        RETURN v_result;
END;
$$;


--
-- Name: get_tenant_roles_json(integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_tenant_roles_json(p_tenant_id integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result api.result_get_roles_api;
    v_tenant_name VARCHAR(255);
    v_role RECORD;
    v_roles api.role_detail[];
BEGIN
    v_result.success := true;
    v_result.error_code := NULL;
    v_result.error_message := NULL;

    -- Verificar tenant
SELECT name INTO v_tenant_name
FROM identity.tenant
WHERE tenant_id = p_tenant_id;

IF NOT FOUND THEN
        RAISE EXCEPTION 'Tenant no encontrado' USING ERRCODE = 'P0002';
END IF;

    v_result.tenant_id := p_tenant_id;
    v_result.tenant_name := v_tenant_name;

    -- =========================
    -- ROLES + PERMISOS
    -- =========================
FOR v_role IN
SELECT r.role_id, r.name, r.description, r.is_active,
       r.created_by, r.created_at
FROM identity.role r
WHERE r.tenant_id = p_tenant_id
ORDER BY r.role_id
    LOOP
        v_roles := array_append(v_roles, ROW(
            v_role.role_id,
            v_role.name,
            v_role.description,
            v_role.is_active,
            v_role.created_by,
            v_role.created_at,
            (
                SELECT ARRAY_AGG(
                    ROW(
                        p.permission_id,
                        p.code,
                        p.description,
                        p.module,
                        p.resource,
                        p.action
                    )::api.role_permission_detail
                    ORDER BY p.module, p.resource, p.action
                )
                FROM identity.role_permission rp
                JOIN identity.permission p
                    ON rp.permission_id = p.permission_id
                WHERE rp.role_id = v_role.role_id
                  AND rp.is_active = true
            )
        )::api.role_detail);
END LOOP;

    v_result.roles := v_roles;

    -- =========================
    -- 🔥 RESPUESTA FINAL JSON
    -- =========================
RETURN jsonb_build_object(
        'success', v_result.success,
        'errorCode', v_result.error_code,
        'errorMessage', v_result.error_message,
        'tenantId', v_result.tenant_id,
        'tenantName', v_result.tenant_name,

    -- ROLES
        'roles', (
            SELECT jsonb_agg(
                           jsonb_build_object(
                                   'roleId', r.role_id,
                                   'name', r.name,
                                   'description', r.description,
                                   'isActive', r.is_active,
                                   'createdBy', r.created_by,
                                   'createdAt', r.created_at,
                                   'permissions', (
                                       SELECT jsonb_agg(
                                                      jsonb_build_object(
                                                              'permissionId', p.permission_id,
                                                              'code', p.code,
                                                              'description', p.description,
                                                              'module', p.module,
                                                              'resource', p.resource,
                                                              'action', p.action
                                                      )
                                              )
                                       FROM unnest(r.permissions) p
                                   )
                           )
                   )
            FROM unnest(v_result.roles) r
        ),

    -- =========================
    -- USERS
    -- =========================
        'users', (
            SELECT jsonb_agg(
                           jsonb_build_object(
                                   'userId', u.user_id,
                                   'externalId', u.external_id,
                                   'username', u.username,
                                   'email', u.email,
                                   'fullName', u.full_name,
                                   'isActive', u.is_active,
                                   'lastLoginAt', u.last_login_at,
                                   'createdAt', u.created_at,
                                   'updatedAt', u.updated_at
                           )
                   )
            FROM identity."user" u
        ),

    -- =========================
    -- USER ROLES
    -- =========================
        'userRoles', (
            SELECT jsonb_agg(
                           jsonb_build_object(
                                   'userRoleId', ur.user_role_id,
                                   'userId', ur.user_id,
                                   'roleId', ur.role_id,
                                   'tenantId', ur.tenant_id,
                                   'isActive', ur.is_active,
                                   'assignedBy', ur.assigned_by,
                                   'assignedAt', ur.assigned_at,
                                   'expiresAt', ur.expires_at
                           )
                   )
            FROM identity.user_role ur
            WHERE ur.tenant_id = p_tenant_id
        )
       );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'errorCode', SQLSTATE,
            'errorMessage', SQLERRM,
            'tenantId', p_tenant_id,
            'tenantName', NULL,
            'roles', '[]'::jsonb,
            'users', '[]'::jsonb,
            'userRoles', '[]'::jsonb
        );
END;
$$;


--
-- Name: get_user_session(api.get_user_session_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_user_session(p_input api.get_user_session_input) RETURNS api.get_user_session_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result    api.get_user_session_result;
BEGIN

    -- ── Validación 1: tenant_id obligatorio ───────────────────────────────
    IF p_input.tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: exactamente un identificador de usuario ─────────────
    IF p_input.user_id IS NULL AND (p_input.external_id IS NULL
        OR TRIM(p_input.external_id) = '')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_USER_IDENTIFIER';
        v_result.error_message := 'Debe proveer user_id o external_id';
RETURN v_result;
END IF;

    IF p_input.user_id IS NOT NULL AND p_input.external_id IS NOT NULL
        AND TRIM(p_input.external_id) <> ''
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'AMBIGUOUS_USER_IDENTIFIER';
        v_result.error_message := 'Provea user_id o external_id, no ambos';
RETURN v_result;
END IF;

    -- ── Query único: JOIN directo user + user_tenant_access ───────────────
    -- Un solo round-trip a BD. Ambas columnas de búsqueda tienen índice btree.
    -- STABLE permite que el planner cachee el plan de ejecución.
SELECT
    u.user_id,
    u.external_id,
    u.username,
    u.email,
    u.full_name,
    u.is_active,
    u.last_login_at,
    u.created_at,
    uta.user_tenant_access_id,
    uta.tenant_id,
    uta.is_active,
    uta.granted_by,
    uta.granted_at
INTO
    v_result.user_id,
    v_result.external_id,
    v_result.username,
    v_result.email,
    v_result.full_name,
    v_result.is_active,
    v_result.last_login_at,
    v_result.user_created_at,
    v_result.user_tenant_access_id,
    v_result.tenant_id,
    v_result.tenant_is_active,
    v_result.granted_by,
    v_result.granted_at
FROM identity."user" u
         JOIN identity.user_tenant_access uta
              ON  uta.user_id   = u.user_id
                  AND uta.tenant_id = p_input.tenant_id
WHERE
    CASE
        WHEN p_input.user_id IS NOT NULL
            THEN u.user_id    = p_input.user_id
        ELSE u.external_id = TRIM(p_input.external_id)
        END;

IF NOT FOUND THEN
        -- Distinguir si no existe el usuario vs no tiene acceso al tenant
        IF NOT EXISTS (
            SELECT 1 FROM identity."user" u
            WHERE CASE
                      WHEN p_input.user_id IS NOT NULL
                          THEN u.user_id     = p_input.user_id
                      ELSE u.external_id = TRIM(p_input.external_id)
                      END
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'USER_NOT_FOUND';
            v_result.error_message := CASE
                                          WHEN p_input.user_id IS NOT NULL
                                              THEN 'user_id=' || p_input.user_id || ' no existe'
                                          ELSE 'external_id="' || p_input.external_id || '" no existe'
END;
ELSE
            v_result.success       := FALSE;
            v_result.error_code    := 'TENANT_ACCESS_NOT_FOUND';
            v_result.error_message := 'El usuario no tiene acceso al tenant_id='
                || p_input.tenant_id;
END IF;
RETURN v_result;
END IF;

    v_result.success := TRUE;
RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_vehicle_documents(api.get_vehicle_documents_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_vehicle_documents(p_input api.get_vehicle_documents_input) RETURNS api.get_vehicle_documents_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_vehicle_documents_result;
    v_vehicle_id        INT;
    v_status_filter     VARCHAR(20)[];
    v_restriction_filter VARCHAR(20)[];
    v_s                 VARCHAR(20);
    v_r                 VARCHAR(20);
BEGIN

    -- ── Validación 1: exactamente un identificador ────────────────────────
    IF p_input.vehicle_id IS NULL AND (
        p_input.plate_number IS NULL OR TRIM(p_input.plate_number) = ''
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_VEHICLE_IDENTIFIER';
        v_result.error_message := 'Debe proveer vehicle_id o plate_number';
RETURN v_result;
END IF;

    IF p_input.vehicle_id IS NOT NULL
       AND p_input.plate_number IS NOT NULL
       AND TRIM(p_input.plate_number) <> ''
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'AMBIGUOUS_VEHICLE_IDENTIFIER';
        v_result.error_message := 'Provea vehicle_id o plate_number, no ambos';
RETURN v_result;
END IF;

    -- ── Resolver vehicle_id ───────────────────────────────────────────────
    IF p_input.vehicle_id IS NOT NULL THEN
        -- Verificar que existe
        IF NOT EXISTS (
            SELECT 1 FROM fleet.vehicle WHERE vehicle_id = p_input.vehicle_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'VEHICLE_NOT_FOUND';
            v_result.error_message := 'vehicle_id=' || p_input.vehicle_id || ' no existe';
RETURN v_result;
END IF;
        v_vehicle_id := p_input.vehicle_id;
ELSE
        -- Lookup por placa usando idx_vehicle_plate (btree)
SELECT vehicle_id INTO v_vehicle_id
FROM fleet.vehicle
WHERE plate_number = UPPER(TRIM(p_input.plate_number));

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'VEHICLE_NOT_FOUND';
            v_result.error_message := 'No existe vehículo con placa "'
                                      || UPPER(TRIM(p_input.plate_number)) || '"';
RETURN v_result;
END IF;
END IF;

    -- ── Normalizar filtros ────────────────────────────────────────────────
    IF p_input.status IS NOT NULL
       AND array_length(p_input.status, 1) IS NOT NULL
    THEN
        v_status_filter := ARRAY[]::VARCHAR[];
        FOREACH v_s IN ARRAY p_input.status
        LOOP
            v_status_filter := v_status_filter || UPPER(TRIM(v_s));
END LOOP;

        IF EXISTS (
            SELECT 1 FROM unnest(v_status_filter) s
            WHERE s NOT IN ('VALID','EXPIRED','PENDING','REJECTED')
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_STATUS';
            v_result.error_message := 'status contiene valores inválidos. '
                                      || 'Válidos: VALID, EXPIRED, PENDING, REJECTED';
RETURN v_result;
END IF;
END IF;

    IF p_input.restriction_type IS NOT NULL
       AND array_length(p_input.restriction_type, 1) IS NOT NULL
    THEN
        v_restriction_filter := ARRAY[]::VARCHAR[];
        FOREACH v_r IN ARRAY p_input.restriction_type
        LOOP
            v_restriction_filter := v_restriction_filter || UPPER(TRIM(v_r));
END LOOP;

        IF EXISTS (
            SELECT 1 FROM unnest(v_restriction_filter) r
            WHERE r NOT IN ('CRITICAL','WARNING','NONE')
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_RESTRICTION_TYPE';
            v_result.error_message := 'restriction_type contiene valores inválidos. '
                                      || 'Válidos: CRITICAL, WARNING, NONE';
RETURN v_result;
END IF;
END IF;

    -- ── Query principal: un único CTE ─────────────────────────────────────
    -- Paso 1: datos del vehículo + empresa  (lookup por PK → O(1))
    -- Paso 2: documentos con tipo y verificador en un solo JOIN
    -- Paso 3: resumen agregado sobre el mismo conjunto
    -- Sin paginación: un vehículo tiene máximo ~15 documentos
WITH vehicle_data AS (
    SELECT
        v.vehicle_id,
        v.plate_number,
        v.internal_code,
        v.company_id,
        c.trade_name    AS company_name,
        v.brand,
        v.model,
        v.year,
        v.status,
        v.is_operational
    FROM fleet.vehicle v
             JOIN shared.company c ON c.company_id = v.company_id
    WHERE v.vehicle_id = v_vehicle_id
),
     docs AS (
         -- Todos los documentos del vehículo con su tipo y verificador
         -- Filtros opcionales de status y restriction_type
         SELECT
             vd.vehicle_document_id,
             vd.document_type_id,
             dt.code                     AS document_type_code,
             dt.name                     AS document_type_name,
             dt.entity_type,
             dt.restriction_type,
             dt.is_mandatory,
             dt.requires_expiry,
             dt.alert_days_before,
             vd.document_number,
             vd.issuing_entity,
             vd.issue_date,
             vd.expiry_date,
             vd.status,
             -- Días hasta vencimiento: negativo = ya vencido
             CASE
                 WHEN vd.expiry_date IS NOT NULL
                     THEN (vd.expiry_date - CURRENT_DATE)::INT
    ELSE NULL
END                         AS days_until_expiry,
            -- Alerta de vencimiento próximo
            CASE
                WHEN vd.expiry_date IS NOT NULL
                     AND dt.alert_days_before IS NOT NULL
                     AND vd.status = 'VALID'
                THEN (vd.expiry_date - CURRENT_DATE) <= dt.alert_days_before
                ELSE FALSE
END                         AS expiring_soon,
            vd.verified_by,
            u.full_name                 AS verified_by_name,
            vd.verified_at,
            vd.notes,
            vd.created_at,
            vd.updated_at
        FROM fleet.vehicle_document vd
        JOIN shared.document_type dt ON dt.document_type_id = vd.document_type_id
        LEFT JOIN identity."user" u   ON u.user_id           = vd.verified_by
        WHERE vd.vehicle_id = v_vehicle_id
          AND (v_status_filter      IS NULL OR vd.status           = ANY(v_status_filter))
          AND (v_restriction_filter IS NULL OR dt.restriction_type = ANY(v_restriction_filter))
    )
SELECT
    -- Datos del vehículo
    vd.vehicle_id,
    vd.plate_number,
    vd.internal_code,
    vd.company_id,
    vd.company_name,
    vd.brand,
    vd.model,
    vd.year,
    vd.status,
    vd.is_operational,
    -- Resumen (calculado sobre el universo completo, no sobre docs filtrados)
    (SELECT COUNT(*)::INT FROM fleet.vehicle_document
     WHERE vehicle_id = v_vehicle_id),
    (SELECT COUNT(*)::INT FROM fleet.vehicle_document
     WHERE vehicle_id = v_vehicle_id AND status = 'VALID'),
    (SELECT COUNT(*)::INT FROM fleet.vehicle_document
     WHERE vehicle_id = v_vehicle_id AND status = 'EXPIRED'),
    (SELECT COUNT(*)::INT FROM fleet.vehicle_document
     WHERE vehicle_id = v_vehicle_id AND status = 'PENDING'),
    (SELECT COUNT(*)::INT FROM fleet.vehicle_document
     WHERE vehicle_id = v_vehicle_id AND status = 'REJECTED'),
    EXISTS (
        SELECT 1
        FROM fleet.vehicle_document vdd
                 JOIN shared.document_type dtt ON dtt.document_type_id = vdd.document_type_id
        WHERE vdd.vehicle_id        = v_vehicle_id
          AND vdd.status            = 'EXPIRED'
          AND dtt.restriction_type  = 'CRITICAL'
    ),
    -- Filtros aplicados
    v_status_filter,
    v_restriction_filter,
    -- Documentos
    (
        SELECT array_agg(
                       (
                        d.vehicle_document_id,
                        d.document_type_id,
                        d.document_type_code,
                        d.document_type_name,
                        d.entity_type,
                        d.restriction_type,
                        d.is_mandatory,
                        d.requires_expiry,
                        d.alert_days_before,
                        d.document_number,
                        d.issuing_entity,
                        d.issue_date,
                        d.expiry_date,
                        d.status,
                        d.days_until_expiry,
                        d.expiring_soon,
                        d.verified_by,
                        d.verified_by_name,
                        d.verified_at,
                        d.notes,
                        d.created_at,
                        d.updated_at
                           )::api.vehicle_document_item
                           -- Ordenar: críticos primero, luego por fecha de vencimiento
                        ORDER BY
                        CASE d.restriction_type
                        WHEN 'CRITICAL' THEN 1
                        WHEN 'WARNING'  THEN 2
                        ELSE                 3
                        END,
                       d.expiry_date ASC NULLS LAST
               )
        FROM docs d
    )
INTO
    v_result.vehicle_id,
    v_result.plate_number,
    v_result.internal_code,
    v_result.company_id,
    v_result.company_name,
    v_result.brand,
    v_result.model,
    v_result.year,
    v_result.status,
    v_result.is_operational,
    v_result.total_documents,
    v_result.total_valid,
    v_result.total_expired,
    v_result.total_pending,
    v_result.total_rejected,
    v_result.has_critical_expired,
    v_result.filter_status,
    v_result.filter_restriction_type,
    v_result.documents
FROM vehicle_data vd;

v_result.success    := TRUE;
    v_result.documents  := COALESCE(v_result.documents, ARRAY[]::api.vehicle_document_item[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_vehicle_owners(api.get_vehicle_owners_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_vehicle_owners(p_input api.get_vehicle_owners_input) RETURNS api.get_vehicle_owners_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result            api.get_vehicle_owners_result;
    v_tenant_id          BIGINT;
    v_page_number         INT;
    v_page_size            INT;
    v_offset                INT;
    v_search                 TEXT;
    v_include_history         BOOLEAN;
    v_total                    BIGINT;
    v_total_pages                INT;
BEGIN

    -- ── Normalizar parámetros ─────────────────────────────────────────
    v_tenant_id        := p_input.tenant_id;
    v_page_number      := GREATEST(COALESCE(p_input.page_number, 1), 1);
    v_page_size        := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset           := (v_page_number - 1) * v_page_size;
    v_search           := NULLIF(TRIM(COALESCE(p_input.search, '')), '');
    v_include_history  := COALESCE(p_input.include_history, FALSE);

    -- ── Validaciones ──────────────────────────────────────────────────
    IF v_tenant_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_TENANT_ID';
        v_result.error_message := 'tenant_id es obligatorio';
RETURN v_result;
END IF;

    IF NOT EXISTS (
        SELECT 1 FROM identity.tenant WHERE tenant_id = v_tenant_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'TENANT_NOT_FOUND';
        v_result.error_message := 'El tenant_id=' || v_tenant_id || ' no existe';
RETURN v_result;
END IF;

    IF p_input.company_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM identity.tenant_company
            WHERE tenant_id  = v_tenant_id
              AND company_id = p_input.company_id
              AND is_active  = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COMPANY_NOT_IN_TENANT';
            v_result.error_message := 'company_id=' || p_input.company_id
                                      || ' no pertenece (o no está vinculado activamente) '
                                      || 'al tenant_id=' || v_tenant_id;
RETURN v_result;
END IF;
END IF;

    -- ════════════════════════════════════════════════════════════════
    -- QUERY PRINCIPAL
    --
    -- Flujo: identity.tenant_company → fleet.vehicle → fleet.vehicle_owner_share
    --        → fleet.vehicle_owner → hr.person
    --
    -- include_history = FALSE (default) → solo shares vigentes HOY
    --   (valid_from <= CURRENT_DATE AND (valid_until IS NULL OR valid_until >= CURRENT_DATE))
    --   y share_is_active = TRUE
    -- include_history = TRUE → todas las filas, vigentes y pasadas,
    --   con la bandera is_current calculada por fila
    -- ════════════════════════════════════════════════════════════════
WITH base AS (
    SELECT
        vo.vehicle_owner_id,
        vo.person_id,
        p.full_name,
        p.tax_id,
        p.email,
        p.phone_mobile,
        vo.bank_account,
        vo.is_active                       AS owner_is_active,
        v.vehicle_id,
        v.plate_number,
        v.company_id,
        vos.share_id,
        vos.ownership_percentage,
        vos.valid_from,
        vos.valid_until,
        vos.is_active                       AS share_is_active,
        (
            vos.valid_from <= CURRENT_DATE
                AND (vos.valid_until IS NULL OR vos.valid_until >= CURRENT_DATE)
                AND vos.is_active = TRUE
            )                                     AS is_current
    FROM identity.tenant_company tc
             JOIN fleet.vehicle v
                  ON  v.company_id = tc.company_id
                      AND tc.tenant_id = v_tenant_id
                      AND tc.is_active = TRUE
             JOIN fleet.vehicle_owner_share vos
                  ON  vos.vehicle_id = v.vehicle_id
             JOIN fleet.vehicle_owner vo
                  ON  vo.vehicle_owner_id = vos.vehicle_owner_id
             JOIN hr.person p
                  ON  p.person_id = vo.person_id
    WHERE
      -- Filtro company_id opcional
        (p_input.company_id IS NULL OR v.company_id = p_input.company_id)
      -- Filtro de vigencia según el flag
      AND (
        v_include_history = TRUE
            OR (
            vos.valid_from <= CURRENT_DATE
                AND (vos.valid_until IS NULL OR vos.valid_until >= CURRENT_DATE)
                AND vos.is_active = TRUE
            )
        )
      -- Filtro de búsqueda: nombre, tax_id o placa
      AND (
        v_search IS NULL
            OR p.full_name    ILIKE '%' || v_search || '%'
                OR p.tax_id       ILIKE '%' || v_search || '%'
                OR v.plate_number ILIKE '%' || v_search || '%'
        )
),
     counted AS (
         SELECT COUNT(*) AS total FROM base
     ),
     paged AS (
         SELECT *
         FROM base
         ORDER BY
             full_name,
             plate_number,
             valid_from DESC
    LIMIT  v_page_size
OFFSET v_offset
    )
SELECT
    (SELECT total FROM counted),
    ARRAY_AGG(
            ROW(
                    pg.vehicle_owner_id,
                    pg.person_id,
                    pg.full_name,
                    pg.tax_id,
                    pg.email,
                    pg.phone_mobile,
                    pg.bank_account,
                    pg.owner_is_active,
                    pg.vehicle_id,
                    pg.plate_number,
                    pg.company_id,
                    pg.share_id,
                    pg.ownership_percentage,
                    pg.valid_from,
                    pg.valid_until,
                    pg.share_is_active,
                    pg.is_current
            )::api.vehicle_owner_share_row
            ORDER BY pg.full_name, pg.plate_number, pg.valid_from DESC
    )
INTO v_total, v_result.owners
FROM paged pg;

-- ── Metadata de paginación ────────────────────────────────────────
v_total_pages := GREATEST(
        CEIL(v_total::NUMERIC / v_page_size)::INT, 1
    );

    v_result.success        := TRUE;
    v_result.page_number    := v_page_number;
    v_result.page_size      := v_page_size;
    v_result.total_records  := COALESCE(v_total, 0);
    v_result.total_pages    := v_total_pages;
    v_result.has_next_page  := v_page_number < v_total_pages;
    v_result.has_prev_page  := v_page_number > 1;
    v_result.owners         := COALESCE(v_result.owners, ARRAY[]::api.vehicle_owner_share_row[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_vehicles(api.get_vehicles_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_vehicles(p_input api.get_vehicles_input DEFAULT ROW(NULL::integer[], NULL::character varying(20)[], NULL::character varying(20)[], NULL::boolean, NULL::character varying(20), NULL::character varying(100), NULL::integer, NULL::integer, 1, 20)::api.get_vehicles_input) RETURNS api.get_vehicles_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.get_vehicles_result;
    v_company_ids       INT[];
    v_status            VARCHAR(20)[];
    v_fuel_type         VARCHAR(20)[];
    v_is_operational    BOOLEAN;
    v_plate_search      VARCHAR(20);
    v_brand_search      VARCHAR(100);
    v_year_from         INT;
    v_year_to           INT;
    v_page              INT;
    v_page_size         INT;
    v_offset            INT;
    v_total_count       INT;
    v_total_pages       INT;
    v_items             api.vehicle_list_item[];
    v_s                 VARCHAR(20);
    v_f                 VARCHAR(20);
BEGIN

    -- ── Normalizar paginación ─────────────────────────────────────────────
    v_page      := GREATEST(COALESCE(p_input.page, 1), 1);
    v_page_size := LEAST(GREATEST(COALESCE(p_input.page_size, 20), 1), 100);
    v_offset    := (v_page - 1) * v_page_size;

    -- ── Normalizar filtros ────────────────────────────────────────────────
    v_company_ids := CASE
        WHEN p_input.company_ids IS NULL
          OR array_length(p_input.company_ids, 1) IS NULL
        THEN NULL
        ELSE p_input.company_ids
END;

    IF p_input.status IS NOT NULL
       AND array_length(p_input.status, 1) IS NOT NULL
    THEN
        v_status := ARRAY[]::VARCHAR[];
        FOREACH v_s IN ARRAY p_input.status
        LOOP
            v_status := v_status || UPPER(TRIM(v_s));
END LOOP;
END IF;

    IF p_input.fuel_type IS NOT NULL
       AND array_length(p_input.fuel_type, 1) IS NOT NULL
    THEN
        v_fuel_type := ARRAY[]::VARCHAR[];
        FOREACH v_f IN ARRAY p_input.fuel_type
        LOOP
            v_fuel_type := v_fuel_type || UPPER(TRIM(v_f));
END LOOP;
END IF;

    v_is_operational := p_input.is_operational;
    v_plate_search   := NULLIF(UPPER(TRIM(COALESCE(p_input.plate_search, ''))), '');
    v_brand_search   := NULLIF(TRIM(COALESCE(p_input.brand_search, '')), '');
    v_year_from      := p_input.year_from;
    v_year_to        := p_input.year_to;

    -- ── Validaciones ──────────────────────────────────────────────────────
    IF v_status IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_status) s
        WHERE s NOT IN ('ACTIVE','INACTIVE','MAINTENANCE','RETIRED')
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_STATUS';
        v_result.error_message := 'Válidos: ACTIVE, INACTIVE, MAINTENANCE, RETIRED';
RETURN v_result;
END IF;

    IF v_fuel_type IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_fuel_type) f
        WHERE f NOT IN ('DIESEL','GNV','HYBRID','ELECTRIC','GASOLINE')
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_FUEL_TYPE';
        v_result.error_message := 'Válidos: DIESEL, GNV, HYBRID, ELECTRIC, GASOLINE';
RETURN v_result;
END IF;

    IF v_year_from IS NOT NULL AND v_year_to IS NOT NULL
       AND v_year_from > v_year_to
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_YEAR_RANGE';
        v_result.error_message := 'year_from (' || v_year_from
                                  || ') no puede ser mayor que year_to ('
                                  || v_year_to || ')';
RETURN v_result;
END IF;

    IF v_company_ids IS NOT NULL AND EXISTS (
        SELECT 1 FROM unnest(v_company_ids) cid
        LEFT JOIN shared.company c ON c.company_id = cid
        WHERE c.company_id IS NULL
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'COMPANY_NOT_FOUND';
        v_result.error_message := 'Uno o más company_id del filtro no existen';
RETURN v_result;
END IF;

    -- ── Contar total ──────────────────────────────────────────────────────
SELECT COUNT(*)
INTO v_total_count
FROM fleet.vehicle v
WHERE (v_company_ids IS NULL    OR v.company_id     = ANY(v_company_ids))
  AND (v_status IS NULL         OR v.status         = ANY(v_status))
  AND (v_fuel_type IS NULL      OR v.fuel_type      = ANY(v_fuel_type))
  AND (v_is_operational IS NULL OR v.is_operational = v_is_operational)
  AND (v_plate_search IS NULL   OR v.plate_number   ILIKE '%' || v_plate_search || '%')
  AND (v_brand_search IS NULL   OR v.brand          ILIKE '%' || v_brand_search || '%')
  AND (v_year_from IS NULL      OR v.year >= v_year_from)
  AND (v_year_to IS NULL        OR v.year <= v_year_to);

v_total_pages := GREATEST(CEIL(v_total_count::NUMERIC / v_page_size)::INT, 1);

    -- ── Consulta principal ────────────────────────────────────────────────
    -- Patrón: CTE pagina primero, luego LEFT JOIN agrega datos derivados,
    -- finalmente array_agg construye el tipo compuesto sin conflicto de GROUP BY.
WITH paged AS (
    SELECT
        v.vehicle_id,
        v.plate_number,
        v.internal_code,
        v.company_id,
        c.trade_name            AS company_name,
        v.brand,
        v.model,
        v.year,
        v.fuel_type,
        v.seating_capacity,
        v.status,
        v.is_operational,
        v.created_at,
        v.updated_at
    FROM fleet.vehicle v
             JOIN shared.company c ON c.company_id = v.company_id
    WHERE (v_company_ids IS NULL    OR v.company_id     = ANY(v_company_ids))
      AND (v_status IS NULL         OR v.status         = ANY(v_status))
      AND (v_fuel_type IS NULL      OR v.fuel_type      = ANY(v_fuel_type))
      AND (v_is_operational IS NULL OR v.is_operational = v_is_operational)
      AND (v_plate_search IS NULL   OR v.plate_number   ILIKE '%' || v_plate_search || '%')
      AND (v_brand_search IS NULL   OR v.brand          ILIKE '%' || v_brand_search || '%')
      AND (v_year_from IS NULL      OR v.year >= v_year_from)
      AND (v_year_to IS NULL        OR v.year <= v_year_to)
    ORDER BY v.plate_number
    LIMIT v_page_size OFFSET v_offset
    ),
    owners AS (
-- Un JOIN lateral por vehículo de la página: máximo page_size filas
SELECT
    vos.vehicle_id,
    STRING_AGG(vo.full_name, ', ' ORDER BY vo.full_name) AS owners_list,
    COUNT(*)::INT                                          AS owner_count
FROM fleet.vehicle_owner_share vos
    JOIN fleet.vehicle_owner vo ON vo.vehicle_owner_id = vos.vehicle_owner_id
WHERE vos.vehicle_id = ANY(SELECT vehicle_id FROM paged)
  AND vos.is_active   = TRUE
  AND vo.is_active    = TRUE
GROUP BY vos.vehicle_id
    ),
    docs AS (
-- Resumen de documentos: un solo escaneo de vehicle_document
-- para todos los vehículos de la página
SELECT
    vd.vehicle_id,
    COUNT(*)::INT                                               AS total_documents,
    COUNT(*) FILTER (WHERE vd.status = 'EXPIRED')::INT         AS expired_documents,
    BOOL_OR(
    vd.status = 'EXPIRED'
    AND dt.restriction_type = 'CRITICAL'
    )                                                           AS has_critical_expired
FROM fleet.vehicle_document vd
    JOIN shared.document_type dt ON dt.document_type_id = vd.document_type_id
WHERE vd.vehicle_id = ANY(SELECT vehicle_id FROM paged)
GROUP BY vd.vehicle_id
    )
SELECT array_agg(
               (
                p.vehicle_id,
                p.plate_number,
                p.internal_code,
                p.company_id,
                p.company_name,
                p.brand,
                p.model,
                p.year,
                p.fuel_type,
                p.seating_capacity,
                p.status,
                p.is_operational,
                o.owners_list,
                COALESCE(o.owner_count, 0),
                COALESCE(d.total_documents, 0),
                COALESCE(d.expired_documents, 0),
                COALESCE(d.has_critical_expired, FALSE),
                p.created_at,
                p.updated_at
                   )::api.vehicle_list_item
                ORDER BY p.plate_number
       )
INTO v_items
FROM paged p
         LEFT JOIN owners o ON o.vehicle_id = p.vehicle_id
         LEFT JOIN docs   d ON d.vehicle_id = p.vehicle_id;

-- ── Resultado ─────────────────────────────────────────────────────────
v_result.success                := TRUE;
    v_result.page                   := v_page;
    v_result.page_size              := v_page_size;
    v_result.total_count            := v_total_count;
    v_result.total_pages            := v_total_pages;
    v_result.has_next_page          := v_page < v_total_pages;
    v_result.has_prev_page          := v_page > 1;
    v_result.filter_company_ids     := v_company_ids;
    v_result.filter_status          := v_status;
    v_result.filter_fuel_type       := v_fuel_type;
    v_result.filter_is_operational  := v_is_operational;
    v_result.filter_plate_search    := v_plate_search;
    v_result.filter_brand_search    := v_brand_search;
    v_result.filter_year_from       := v_year_from;
    v_result.filter_year_to         := v_year_to;
    v_result.vehicles               := COALESCE(v_items, ARRAY[]::api.vehicle_list_item[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: get_vehicles_last_position(api.get_vehicles_last_position_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.get_vehicles_last_position(p_input api.get_vehicles_last_position_input) RETURNS api.get_vehicles_last_position_result
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
v_result                    api.get_vehicles_last_position_result;
    v_signal_threshold_minutes  INT;
    v_cfg_value                 TEXT;
    v_positions                 api.vehicle_position_row[];
    v_now                       TIMESTAMPTZ := NOW();

    -- Inicio de la semana actual (lunes a las 00:00 UTC) para acotar la búsqueda
    v_week_start                TIMESTAMPTZ;
    v_prev_week_start           TIMESTAMPTZ;
BEGIN

    -- ── Validación 1: company_ids obligatorio y no vacío ──────────────────
    IF p_input.company_ids IS NULL OR array_length(p_input.company_ids, 1) IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_COMPANY_IDS';
        v_result.error_message := 'company_ids es obligatorio y no puede estar vacío';
RETURN v_result;
END IF;

    -- ── Leer umbral de señal perdida desde configuración ─────────────────
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'gps.max_signal_lost_minutes';

BEGIN
        v_signal_threshold_minutes := COALESCE(NULLIF(TRIM(v_cfg_value), ''), '15')::INT;
EXCEPTION WHEN OTHERS THEN
        v_signal_threshold_minutes := 15;  -- fallback: 15 min
END;

    -- ── Calcular ventanas de partición (semana actual + anterior) ─────────
    -- La partición es por semana (lunes). Para cubrir vehículos que no
    -- enviaron señal esta semana, también revisamos la semana anterior.
    v_week_start      := date_trunc('week', v_now);
    v_prev_week_start := v_week_start - INTERVAL '1 week';

    -- ── Query principal usando DISTINCT ON por vehicle_id ─────────────────
    -- Estrategia: DISTINCT ON (vehicle_id) ORDER BY gps_timestamp DESC
    -- obtiene el último evento por vehículo en un solo scan eficiente.
    -- El WHERE gps_timestamp >= v_prev_week_start limita a 2 semanas de datos,
    -- lo que garantiza que las particiones relevantes sean solo 1 o 2.
WITH

    -- Todos los vehículos activos de las empresas solicitadas
    vehicles_in_scope AS (
        SELECT
            v.vehicle_id,
            v.company_id,
            v.plate_number,
            v.internal_code,
            v.brand,
            v.model,
            v.status             AS vehicle_status,
            v.is_operational
        FROM fleet.vehicle v
        WHERE v.company_id = ANY(p_input.company_ids)
          AND (COALESCE(p_input.only_operational, FALSE) = FALSE
            OR v.is_operational = TRUE)
    ),

    -- GPS devices activos vinculados a esos vehículos
    active_devices AS (
        SELECT
            gd.vehicle_id,
            gd.gps_device_id,
            gd.device_id,
            gd.status           AS device_status,
            gd.last_communication_at
        FROM fleet.gps_device gd
        WHERE gd.vehicle_id = ANY(
            SELECT vehicle_id FROM vehicles_in_scope
        )
          AND gd.is_operational = TRUE
    ),

    -- Último evento GPS por vehicle_id (máximo 2 semanas hacia atrás)
    last_gps AS (
        SELECT DISTINCT ON (g.vehicle_id)
    g.raw_event_id,
    g.vehicle_id,
    g.gps_device_id,
    g.latitude,
    g.longitude,
    g.altitude,
    g.speed_kmh,
    g.heading,
    g.accuracy_meters,
    g.satellites,
    g.battery_level,
    g.gps_timestamp,
    g.server_timestamp
FROM fleet.gps_raw_event g
WHERE g.vehicle_id = ANY(
    SELECT vehicle_id FROM vehicles_in_scope
    )
  AND g.gps_timestamp >= v_prev_week_start  -- acota a 2 particiones semanales
ORDER BY g.vehicle_id, g.gps_timestamp DESC
    ),

    -- Asignación activa de conductor
    active_assignments AS (
SELECT
    va.vehicle_id,
    d.driver_id,
    d.driver_code,
    p.full_name          AS driver_full_name
FROM fleet.vehicle_assignment va
    JOIN hr.driver  d ON d.driver_id  = va.driver_id
    JOIN hr.person  p ON p.person_id  = d.person_id
WHERE va.is_active = TRUE
  AND va.vehicle_id = ANY(
    SELECT vehicle_id FROM vehicles_in_scope
    )
    )

-- Ensamblar resultado final
SELECT ARRAY_AGG(
               ROW(
                       vs.vehicle_id,
                       vs.company_id,
                       vs.plate_number,
                       vs.internal_code,
                       vs.brand,
                       vs.model,
                       vs.vehicle_status,
                       vs.is_operational,
                   -- GPS device
                       ad.gps_device_id,
                       ad.device_id,
                       ad.device_status,
                   -- Última posición
                       lg.raw_event_id,
                       lg.latitude,
                       lg.longitude,
                       lg.altitude,
                       lg.speed_kmh,
                       lg.heading,
                       lg.accuracy_meters,
                       lg.satellites,
                       lg.battery_level,
                       lg.gps_timestamp,
                       lg.server_timestamp,
                   -- Frescura de señal
                       CASE
                           WHEN lg.gps_timestamp IS NOT NULL
                               THEN ROUND(EXTRACT(EPOCH FROM (v_now - lg.gps_timestamp)) / 60.0, 2)
                           ELSE NULL
                           END,
                       CASE
                           WHEN lg.gps_timestamp IS NULL THEN FALSE  -- sin datos no es "señal perdida"
                           WHEN EXTRACT(EPOCH FROM (v_now - lg.gps_timestamp)) / 60.0
                               > v_signal_threshold_minutes THEN TRUE
                           ELSE FALSE
                           END,
                   -- Conductor activo
                       aa.driver_id,
                       aa.driver_code,
                       aa.driver_full_name,
                   -- Flag sin datos GPS
                       (lg.raw_event_id IS NULL)
               )::api.vehicle_position_row
        ORDER BY vs.company_id, vs.vehicle_id
       )
INTO v_positions
FROM vehicles_in_scope vs
         LEFT JOIN active_devices       ad  ON ad.vehicle_id = vs.vehicle_id
         LEFT JOIN last_gps             lg  ON lg.vehicle_id = vs.vehicle_id
         LEFT JOIN active_assignments   aa  ON aa.vehicle_id = vs.vehicle_id
WHERE (COALESCE(p_input.only_with_gps, FALSE) = FALSE
    OR lg.raw_event_id IS NOT NULL);

-- ── Calcular contadores de la respuesta ───────────────────────────────
SELECT
    COUNT(*)::INT,
    COUNT(*) FILTER (WHERE (r).raw_event_id IS NOT NULL)::INT,
    COUNT(*) FILTER (WHERE (r).signal_lost = TRUE)::INT,
    COUNT(*) FILTER (WHERE (r).no_gps_data = TRUE)::INT
INTO
    v_result.total_vehicles,
    v_result.total_with_position,
    v_result.total_signal_lost,
    v_result.total_no_gps_data
FROM UNNEST(COALESCE(v_positions, ARRAY[]::api.vehicle_position_row[])) r;

v_result.success                        := TRUE;
    v_result.signal_lost_threshold_minutes  := v_signal_threshold_minutes;
    v_result.positions                      := COALESCE(v_positions, ARRAY[]::api.vehicle_position_row[]);

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: ingest_gps_raw_event(api.ingest_gps_raw_event_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.ingest_gps_raw_event(p_input api.ingest_gps_raw_event_input) RETURNS api.ingest_gps_raw_event_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.ingest_gps_raw_event_result;
    v_device        fleet.gps_device%ROWTYPE;
    v_raw_event_id  BIGINT;
    v_server_ts     TIMESTAMPTZ := NOW();
    v_stale_hours   INT := 24;      -- umbral de descarte: 24 h en el pasado
    v_future_secs   INT := 60;      -- umbral de rechazo: 60 s en el futuro
BEGIN

    -- ── Inicializar flags ─────────────────────────────────────────────────
    v_result.device_not_registered := FALSE;
    v_result.discarded_stale       := FALSE;
    v_result.raw_event_id          := NULL;

    -- ── Validación 1: campos obligatorios ─────────────────────────────────
    IF p_input.device_id IS NULL OR TRIM(p_input.device_id) = '' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_DEVICE_ID';
        v_result.error_message := 'device_id es obligatorio';
RETURN v_result;
END IF;

    IF p_input.latitude IS NULL OR p_input.longitude IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_COORDINATES';
        v_result.error_message := 'latitude y longitude son obligatorios';
RETURN v_result;
END IF;

    IF p_input.gps_timestamp IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_GPS_TIMESTAMP';
        v_result.error_message := 'gps_timestamp es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: rango de coordenadas ───────────────────────────────
    IF p_input.latitude < -90 OR p_input.latitude > 90 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_LATITUDE';
        v_result.error_message := 'latitude fuera de rango [-90, 90]: '
                                  || p_input.latitude::TEXT;
RETURN v_result;
END IF;

    IF p_input.longitude < -180 OR p_input.longitude > 180 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_LONGITUDE';
        v_result.error_message := 'longitude fuera de rango [-180, 180]: '
                                  || p_input.longitude::TEXT;
RETURN v_result;
END IF;

    -- ── Validación 3: speed_kmh en [0, 250] si se proveyó ────────────────
    IF p_input.speed_kmh IS NOT NULL
       AND (p_input.speed_kmh < 0 OR p_input.speed_kmh > 250)
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_SPEED';
        v_result.error_message := 'speed_kmh fuera de rango [0, 250]: '
                                  || p_input.speed_kmh::TEXT;
RETURN v_result;
END IF;

    -- ── Validación 4: heading en [0, 360] si se proveyó ──────────────────
    IF p_input.heading IS NOT NULL
       AND (p_input.heading < 0 OR p_input.heading > 360)
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_HEADING';
        v_result.error_message := 'heading fuera de rango [0, 360]: '
                                  || p_input.heading::TEXT;
RETURN v_result;
END IF;

    -- ── Validación 5: battery_level en [0, 100] si se proveyó ────────────
    IF p_input.battery_level IS NOT NULL
       AND (p_input.battery_level < 0 OR p_input.battery_level > 100)
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_BATTERY_LEVEL';
        v_result.error_message := 'battery_level fuera de rango [0, 100]: '
                                  || p_input.battery_level::TEXT;
RETURN v_result;
END IF;

    -- ── Validación 6: timestamp futuro (reloj desincronizado) ─────────────
    IF p_input.gps_timestamp > v_server_ts + (v_future_secs || ' seconds')::INTERVAL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'FUTURE_GPS_TIMESTAMP';
        v_result.error_message := 'gps_timestamp ('
                                  || p_input.gps_timestamp::TEXT
                                  || ') está más de ' || v_future_secs::TEXT
                                  || ' segundos en el futuro. '
                                  || 'Verifique el reloj del dispositivo "'
                                  || p_input.device_id || '"';
RETURN v_result;
END IF;

    -- ── Validación 7: timestamp obsoleto → descartar con flag, no error ───
    IF p_input.gps_timestamp < v_server_ts - (v_stale_hours || ' hours')::INTERVAL THEN
        v_result.success        := TRUE;
        v_result.discarded_stale := TRUE;
        v_result.error_code     := NULL;
        v_result.error_message  := NULL;
        -- Actualizar heartbeat igualmente (el dispositivo está vivo aunque mande datos viejos)
        -- Se hace antes de retornar para no perder el ping
UPDATE fleet.gps_device
SET last_communication_at = v_server_ts,
    updated_at            = v_server_ts
WHERE device_id = TRIM(p_input.device_id);
RETURN v_result;
END IF;

    -- ── Resolver dispositivo GPS por device_id ────────────────────────────
SELECT * INTO v_device
FROM fleet.gps_device
WHERE device_id = TRIM(p_input.device_id);

IF NOT FOUND THEN
        -- DEVICE_NOT_REGISTERED: flag sin excepción, no bloquea el pipeline
        -- El backend puede decidir qué hacer (loguear, alertar, ignorar)
        v_result.success               := TRUE;
        v_result.device_not_registered := TRUE;
        v_result.error_code            := NULL;
        v_result.error_message         := NULL;
RETURN v_result;
END IF;

    -- ── Insertar en fleet.gps_raw_event (particionada por semana) ─────────
    -- La partición correcta se selecciona automáticamente por PostgreSQL
    -- según gps_timestamp. No se necesita lógica manual de particionamiento.
INSERT INTO fleet.gps_raw_event (
    gps_device_id,
    vehicle_id,
    beacon_mac_address,
    latitude,
    longitude,
    altitude,
    speed_kmh,
    heading,
    accuracy_meters,
    satellites,
    gps_timestamp,
    server_timestamp,
    battery_level,
    raw_data
)
VALUES (
           v_device.gps_device_id,
           v_device.vehicle_id,        -- se toma del dispositivo, no del payload
           p_input.beacon_mac_address,
           p_input.latitude,
           p_input.longitude,
           p_input.altitude,
           p_input.speed_kmh,
           p_input.heading,
           p_input.accuracy_meters,
           p_input.satellites,
           p_input.gps_timestamp,
           v_server_ts,
           p_input.battery_level,
           p_input.raw_data
       )
    RETURNING raw_event_id INTO v_raw_event_id;

-- ── Actualizar heartbeat del dispositivo ──────────────────────────────
-- Esta es la única escritura adicional permitida en el path crítico.
-- Se hace en el mismo bloque de transacción — si el INSERT falla,
-- el heartbeat tampoco se actualiza (correcto).
UPDATE fleet.gps_device
SET last_communication_at = v_server_ts,
    updated_at            = v_server_ts
WHERE gps_device_id = v_device.gps_device_id;

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success          := TRUE;
    v_result.raw_event_id     := v_raw_event_id;
    v_result.gps_device_id    := v_device.gps_device_id;
    v_result.vehicle_id       := v_device.vehicle_id;
    v_result.gps_timestamp    := p_input.gps_timestamp;
    v_result.server_timestamp := v_server_ts;
    v_result.device_status    := v_device.status;
    v_result.is_operational   := v_device.is_operational;

    -- NOTA DE ARQUITECTURA:
    -- La evaluación de alertas (velocidad excesiva, señal perdida, etc.)
    -- NO ocurre aquí. Se delega a api.evaluate_gps_alerts del Grupo G,
    -- invocada de forma asíncrona por el backend tras recibir este resultado,
    -- o mediante un trigger AFTER INSERT ON fleet.gps_raw_event.
    -- Mantener este path < 5ms es crítico con 200 eventos/minuto.

RETURN v_result;

EXCEPTION
    WHEN check_violation THEN
        -- Los CHECKs de la tabla (latitud, longitud, speed, heading, battery)
        -- ya fueron validados arriba, pero por defensa ante condiciones de carrera:
        v_result.success       := FALSE;
        v_result.error_code    := 'CONSTRAINT_VIOLATION';
        v_result.error_message := 'Violación de constraint en gps_raw_event: ' || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: invalidate_user_session(api.invalidate_user_session_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.invalidate_user_session(p_input api.invalidate_user_session_input) RETURNS api.invalidate_user_session_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.invalidate_user_session_result;
    v_session           identity.user_session%ROWTYPE;
    v_rows_updated      INT;
    v_detail            api.invalidated_session_detail[];
BEGIN

    -- ── Validación: debe venir token o session_id (al menos uno) ──────────
    IF p_input.session_id IS NULL AND (p_input.token IS NULL OR TRIM(p_input.token) = '') AND p_input.user_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_IDENTIFIER';
        v_result.error_message := 'Debe proveer session_id o token para identificar la sesión';
RETURN v_result;
END IF;

    -- ══════════════════════════════════════════════════════════════════════
    -- MODO GLOBAL: invalidar TODAS las sesiones activas del usuario
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.user_id IS NOT NULL THEN

        -- Validar que el usuario existe
        IF NOT EXISTS (
            SELECT 1 FROM identity.user WHERE user_id = p_input.user_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'USER_NOT_FOUND';
            v_result.error_message := 'El user_id=' || p_input.user_id
                                      || ' no existe';
RETURN v_result;
END IF;

        -- Capturar detalle de sesiones activas antes de invalidar
SELECT ARRAY_AGG(
               ROW(s.session_id, s.ip_address, s.started_at, s.last_activity_at)
                   ::api.invalidated_session_detail
            ORDER BY s.last_activity_at DESC
       )
INTO v_detail
FROM identity.user_session s
WHERE s.user_id   = p_input.user_id
  AND s.is_active = TRUE;

-- Invalidar todas
UPDATE identity.user_session
SET is_active = FALSE
WHERE user_id   = p_input.user_id
  AND is_active = TRUE;

GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

IF v_rows_updated = 0 THEN
            v_result.success              := TRUE;
            v_result.warning              := 'SESSION_ALREADY_INACTIVE: el usuario no tenía '
                                             || 'sesiones activas para invalidar';
            v_result.sessions_invalidated := 0;
            v_result.mode                 := 'GLOBAL';
            v_result.invalidated_sessions := ARRAY[]::api.invalidated_session_detail[];
RETURN v_result;
END IF;

        v_result.success              := TRUE;
        v_result.sessions_invalidated := v_rows_updated;
        v_result.mode                 := 'GLOBAL';
        v_result.invalidated_sessions := COALESCE(v_detail, ARRAY[]::api.invalidated_session_detail[]);

RETURN v_result;

END IF;

    -- ══════════════════════════════════════════════════════════════════════
    -- MODO SINGLE: invalidar una sesión específica por token o session_id
    -- ══════════════════════════════════════════════════════════════════════

    -- Buscar la sesión
SELECT * INTO v_session
FROM identity.user_session
WHERE
    (p_input.session_id IS NOT NULL AND session_id = p_input.session_id)
   OR
    (p_input.token IS NOT NULL AND token = p_input.token)
    LIMIT 1;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'SESSION_NOT_FOUND';
        v_result.error_message := CASE
            WHEN p_input.session_id IS NOT NULL
                THEN 'No existe sesión con session_id=' || p_input.session_id
            ELSE 'No existe sesión con el token proporcionado'
END;
RETURN v_result;
END IF;

    -- Sesión ya inactiva → warning, no error duro
    IF v_session.is_active = FALSE THEN
        v_result.success              := TRUE;
        v_result.warning              := 'SESSION_ALREADY_INACTIVE: la sesión session_id='
                                         || v_session.session_id
                                         || ' ya estaba cerrada';
        v_result.sessions_invalidated := 0;
        v_result.mode                 := 'SINGLE';
        v_result.invalidated_sessions := ARRAY[]::api.invalidated_session_detail[];
RETURN v_result;
END IF;

    -- Invalidar
UPDATE identity.user_session
SET is_active = FALSE
WHERE session_id = v_session.session_id;

v_result.success              := TRUE;
    v_result.sessions_invalidated := 1;
    v_result.mode                 := 'SINGLE';
    v_result.invalidated_sessions := ARRAY[
        ROW(
            v_session.session_id,
            v_session.ip_address,
            v_session.started_at,
            v_session.last_activity_at
        )::api.invalidated_session_detail
    ];

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: log_login_attempt(api.log_login_attempt_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.log_login_attempt(p_input api.log_login_attempt_input) RETURNS api.log_login_attempt_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.log_login_attempt_result;
    v_attempt_id            BIGINT;
    v_attempted_at          TIMESTAMPTZ;
    v_bf                    api.brute_force_summary;
    v_failed_15_min         INT;
    v_failed_hour_ip        INT;
BEGIN

    -- ── Validación 1: username obligatorio ────────────────────────────────
    IF p_input.username IS NULL OR TRIM(p_input.username) = '' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_USERNAME';
        v_result.error_message := 'username es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: ip_address obligatoria ──────────────────────────────
    IF p_input.ip_address IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_IP';
        v_result.error_message := 'ip_address es obligatoria';
RETURN v_result;
END IF;

    -- ── Validación 3: success obligatorio ────────────────────────────────
    IF p_input.success IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_SUCCESS_FLAG';
        v_result.error_message := 'success no puede ser NULL';
RETURN v_result;
END IF;

    -- ── Validación 4: failure_reason solo si success=false ────────────────
    IF p_input.success = TRUE AND p_input.failure_reason IS NOT NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_FAILURE_REASON';
        v_result.error_message := 'failure_reason debe ser NULL cuando success=true '
                                  || '(constraint chk_login_failure_reason)';
RETURN v_result;
END IF;

    -- ── Validación 5: failure_reason dentro del dominio permitido ─────────
    IF p_input.failure_reason IS NOT NULL
       AND p_input.failure_reason NOT IN (
           'INVALID_CREDENTIALS', 'ACCOUNT_LOCKED', 'ACCOUNT_DISABLED',
           'IP_BLOCKED', 'MFA_REQUIRED', 'MFA_FAILED',
           'SESSION_EXPIRED', 'UNAUTHORIZED'
       )
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_FAILURE_REASON';
        v_result.error_message := 'failure_reason "' || p_input.failure_reason
                                  || '" no es válido. Valores permitidos: '
                                  || 'INVALID_CREDENTIALS, ACCOUNT_LOCKED, ACCOUNT_DISABLED, '
                                  || 'IP_BLOCKED, MFA_REQUIRED, MFA_FAILED, '
                                  || 'SESSION_EXPIRED, UNAUTHORIZED';
RETURN v_result;
END IF;

    -- ── Insertar el intento ───────────────────────────────────────────────
INSERT INTO identity.login_attempt (
    username,
    ip_address,
    user_agent,
    success,
    failure_reason,
    attempted_at
)
VALUES (
           p_input.username,
           p_input.ip_address,
           p_input.user_agent,
           p_input.success,
           p_input.failure_reason,
           NOW()
       )
    RETURNING attempt_id, attempted_at
INTO v_attempt_id, v_attempted_at;

-- ── Análisis de fuerza bruta (post-insert, sobre datos reales) ────────

-- Fallos del mismo username en los últimos 15 minutos
SELECT COUNT(*) INTO v_failed_15_min
FROM identity.login_attempt
WHERE username     = p_input.username
  AND success      = FALSE
  AND attempted_at >= NOW() - INTERVAL '15 minutes';

-- Fallos desde la misma IP en la última hora
SELECT COUNT(*) INTO v_failed_hour_ip
FROM identity.login_attempt
WHERE ip_address   = p_input.ip_address
  AND success      = FALSE
  AND attempted_at >= NOW() - INTERVAL '1 hour';

-- Calcular nivel de riesgo
v_bf.failed_last_15_min  := v_failed_15_min;
    v_bf.failed_last_hour_ip := v_failed_hour_ip;
    v_bf.risk_level :=
        CASE
            WHEN v_failed_15_min >= 10 OR v_failed_hour_ip >= 20 THEN 'CRITICAL'
            WHEN v_failed_15_min >= 5  OR v_failed_hour_ip >= 10 THEN 'HIGH'
            WHEN v_failed_15_min >= 3  OR v_failed_hour_ip >= 5  THEN 'MEDIUM'
            WHEN v_failed_15_min >= 1  OR v_failed_hour_ip >= 1  THEN 'LOW'
            ELSE 'NONE'
END;

    -- ── Poblar resultado ──────────────────────────────────────────────────
    v_result.success          := TRUE;
    v_result.attempt_id       := v_attempt_id;
    v_result.username         := p_input.username;
    v_result.ip_address       := p_input.ip_address;
    v_result.attempt_success  := p_input.success;
    v_result.failure_reason   := p_input.failure_reason;
    v_result.attempted_at     := v_attempted_at;
    v_result.brute_force      := v_bf;

RETURN v_result;

EXCEPTION
    WHEN check_violation THEN
        -- El check de la tabla disparó (failure_reason en login exitoso, etc.)
        v_result.success       := FALSE;
        v_result.error_code    := 'CONSTRAINT_VIOLATION';
        v_result.error_message := 'Violación de constraint en login_attempt: ' || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: rebuild_alert_daily_summary(date); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.rebuild_alert_daily_summary(p_date date DEFAULT NULL::date) RETURNS api.rebuild_alert_daily_summary_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.rebuild_alert_daily_summary_result;
    v_date          DATE;
    v_ts_from       TIMESTAMPTZ;
    v_ts_to         TIMESTAMPTZ;

    v_total         INTEGER := 0;
    v_critical      INTEGER := 0;
    v_high          INTEGER := 0;
    v_medium        INTEGER := 0;
    v_low           INTEGER := 0;
    v_active        INTEGER := 0;
    v_acknowledged  INTEGER := 0;
    v_resolved      INTEGER := 0;

    v_avg_ack_min   NUMERIC(8,2);
    v_avg_res_min   NUMERIC(8,2);
    v_top_types     JSONB;
    v_top_vehicles  JSONB;
    v_operation     VARCHAR(10);
BEGIN
    v_date    := COALESCE(p_date, CURRENT_DATE - 1);

    IF v_date >= CURRENT_DATE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DATE';
        v_result.error_message := 'No se puede generar el resumen para una fecha futura o el día en curso. '
                                  || 'Recibido: ' || v_date::TEXT
                                  || '. Máximo permitido: ' || (CURRENT_DATE - 1)::TEXT;
RETURN v_result;
END IF;

    v_ts_from := v_date::TIMESTAMPTZ AT TIME ZONE 'UTC';
    v_ts_to   := v_ts_from + INTERVAL '1 day';

    -- ── Contadores: un solo scan sobre la partición del día ───────────────
SELECT
    COUNT(*)                                                      AS total,
    COUNT(*) FILTER (WHERE severity = 'CRITICAL')                AS critical,
        COUNT(*) FILTER (WHERE severity = 'HIGH')                    AS high,
        COUNT(*) FILTER (WHERE severity = 'MEDIUM')                  AS medium,
        COUNT(*) FILTER (WHERE severity = 'LOW')                     AS low,
        COUNT(*) FILTER (WHERE status  = 'ACTIVE')                   AS active,
        COUNT(*) FILTER (WHERE status  = 'ACKNOWLEDGED')             AS acknowledged,
        COUNT(*) FILTER (WHERE status  IN ('RESOLVED','AUTO_CLOSED')) AS resolved
INTO
    v_total, v_critical, v_high, v_medium, v_low,
    v_active, v_acknowledged, v_resolved
FROM core_operations.alert
WHERE alert_timestamp >= v_ts_from
  AND alert_timestamp <  v_ts_to;

-- ── Tiempos promedio en minutos ───────────────────────────────────────
SELECT
    ROUND(AVG(
                  EXTRACT(EPOCH FROM (acknowledged_at - alert_timestamp)) / 60.0
          )::NUMERIC, 2),
    ROUND(AVG(
                  EXTRACT(EPOCH FROM (
                      COALESCE(resolved_at, auto_closed_at) - alert_timestamp
                      )) / 60.0
          )::NUMERIC, 2)
INTO v_avg_ack_min, v_avg_res_min
FROM core_operations.alert
WHERE alert_timestamp >= v_ts_from
  AND alert_timestamp <  v_ts_to
  AND acknowledged_at IS NOT NULL;

-- ── Top 5 tipos de alerta ─────────────────────────────────────────────
SELECT jsonb_agg(row_data ORDER BY cnt DESC)
INTO   v_top_types
FROM (
         SELECT jsonb_build_object(
                        'alert_type_id', a.alert_type_id,
                        'code',          at.code,
                        'name',          at.name,
                        'count',         COUNT(*)
                ) AS row_data,
                COUNT(*) AS cnt
         FROM core_operations.alert a
                  JOIN core_operations.alert_type at USING (alert_type_id)
         WHERE a.alert_timestamp >= v_ts_from
           AND a.alert_timestamp <  v_ts_to
         GROUP BY a.alert_type_id, at.code, at.name
         ORDER BY cnt DESC
             LIMIT 5
     ) sub;

-- ── Top 5 vehículos ───────────────────────────────────────────────────
SELECT jsonb_agg(row_data ORDER BY cnt DESC)
INTO   v_top_vehicles
FROM (
         SELECT jsonb_build_object(
                        'vehicle_id', vehicle_id,
                        'count',      COUNT(*)
                ) AS row_data,
                COUNT(*) AS cnt
         FROM core_operations.alert
         WHERE alert_timestamp >= v_ts_from
           AND alert_timestamp <  v_ts_to
           AND vehicle_id IS NOT NULL
         GROUP BY vehicle_id
         ORDER BY cnt DESC
             LIMIT 5
     ) sub;

-- ── Upsert idempotente ────────────────────────────────────────────────
INSERT INTO core_operations.alert_daily_summary (
    summary_date,
    total_alerts,
    critical_count,
    high_count,
    medium_count,
    low_count,
    active_count,
    acknowledged_count,
    resolved_count,
    avg_acknowledgment_min,
    avg_resolution_min,
    top_alert_types,
    top_vehicles
) VALUES (
             v_date,
             v_total,
             v_critical,
             v_high,
             v_medium,
             v_low,
             v_active,
             v_acknowledged,
             v_resolved,
             v_avg_ack_min,
             v_avg_res_min,
             COALESCE(v_top_types,    '[]'::JSONB),
             COALESCE(v_top_vehicles, '[]'::JSONB)
         )
    ON CONFLICT (summary_date) DO UPDATE SET
    total_alerts           = EXCLUDED.total_alerts,
                                      critical_count         = EXCLUDED.critical_count,
                                      high_count             = EXCLUDED.high_count,
                                      medium_count           = EXCLUDED.medium_count,
                                      low_count              = EXCLUDED.low_count,
                                      active_count           = EXCLUDED.active_count,
                                      acknowledged_count     = EXCLUDED.acknowledged_count,
                                      resolved_count         = EXCLUDED.resolved_count,
                                      avg_acknowledgment_min = EXCLUDED.avg_acknowledgment_min,
                                      avg_resolution_min     = EXCLUDED.avg_resolution_min,
                                      top_alert_types        = EXCLUDED.top_alert_types,
                                      top_vehicles           = EXCLUDED.top_vehicles;

-- ── Detectar INSERT vs UPDATE con xmax ───────────────────────────────
SELECT CASE WHEN xmax = 0 THEN 'INSERTED' ELSE 'UPDATED' END
INTO   v_operation
FROM   core_operations.alert_daily_summary
WHERE  summary_date = v_date;

v_result.success       := TRUE;
    v_result.error_code    := NULL;
    v_result.error_message := NULL;
    v_result.summary_date  := v_date;
    v_result.operation     := v_operation;
    v_result.total_alerts  := v_total;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.summary_date  := v_date;
RETURN v_result;
END;
$$;


--
-- Name: FUNCTION rebuild_alert_daily_summary(p_date date); Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON FUNCTION api.rebuild_alert_daily_summary(p_date date) IS 'Job nocturno. Agrega alertas del día p_date (default: ayer) en alert_daily_summary.
Idempotente: ON CONFLICT (summary_date) DO UPDATE. Se puede re-ejecutar para corregir.
Si no hay alertas para el día, inserta el registro en ceros para mantener la serie histórica.
INVALID_DATE si la fecha es hoy o futura.';


--
-- Name: register_gps_raw_event(api.register_gps_raw_event_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.register_gps_raw_event(p_input api.register_gps_raw_event_input) RETURNS api.register_gps_raw_event_result
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result         api.register_gps_raw_event_result;
    v_raw_event_id   BIGINT;
    v_gps_device_id  INTEGER;
    v_vehicle_id     INTEGER;
BEGIN
    -- Resolver gps_device_id
    IF p_input.gps_device_id IS NOT NULL THEN
        v_gps_device_id := p_input.gps_device_id;
    ELSE
        SELECT gps_device_id
        INTO v_gps_device_id
        FROM fleet.gps_device
        LIMIT 1;
    END IF;

    -- Resolver vehicle_id
    IF p_input.vehicle_id IS NOT NULL THEN
        v_vehicle_id := p_input.vehicle_id;
    ELSE
        SELECT vehicle_id
        INTO v_vehicle_id
        FROM fleet.gps_device
        WHERE vehicle_id IS NOT NULL
        LIMIT 1;
    END IF;

    -- Si no hay ningún gps_device en BD
    IF v_gps_device_id IS NULL THEN
        v_result.success := FALSE;
        v_result.error_code := 'NO_DEVICE_FOUND';
        v_result.error_message := 'No hay gps_device disponibles';
        RETURN v_result;
    END IF;

    -- Validar coordenadas
    IF p_input.latitude NOT BETWEEN -90 AND 90 THEN
        v_result.success := FALSE;
        v_result.error_code := 'INVALID_LATITUDE';
        RETURN v_result;
    END IF;

    IF p_input.longitude NOT BETWEEN -180 AND 180 THEN
        v_result.success := FALSE;
        v_result.error_code := 'INVALID_LONGITUDE';
        RETURN v_result;
    END IF;

    -- TODO: validar reglas de negocio de track_id (existencia, estado, pertenencia
    --       al vehículo/dispositivo, etc.) cuando exista fleet.track.

    -- Crear partición
    PERFORM utilities.create_gps_partition(p_input.gps_timestamp);

    -- Insert
    INSERT INTO fleet.gps_raw_event (
        gps_device_id,
        vehicle_id,
        beacon_mac_address,
        latitude,
        longitude,
        altitude,
        speed_kmh,
        heading,
        accuracy_meters,
        satellites,
        gps_timestamp,
        battery_level,
        raw_data,
        track_id
    )
    VALUES (
               v_gps_device_id,
               v_vehicle_id,
               p_input.beacon_mac_address,
               p_input.latitude,
               p_input.longitude,
               p_input.altitude,
               p_input.speed_kmh,
               p_input.heading,
               p_input.accuracy_meters,
               p_input.satellites,
               p_input.gps_timestamp,
               p_input.battery_level,
               p_input.raw_data,
               p_input.track_id
           )
    RETURNING raw_event_id INTO v_raw_event_id;

    -- Resultado
    v_result.success := TRUE;
    v_result.raw_event_id := v_raw_event_id;
    v_result.gps_device_id := v_gps_device_id;
    v_result.gps_timestamp := p_input.gps_timestamp;
    v_result.created_at := NOW();
    v_result.track_id := p_input.track_id;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success := FALSE;
        v_result.error_code := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        RETURN v_result;
END;
$$;


--
-- Name: resolve_alert(api.resolve_alert_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.resolve_alert(p_input api.resolve_alert_input) RETURNS api.resolve_alert_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.resolve_alert_result;
    v_alert         core_operations.alert%ROWTYPE;
    v_alert_type    core_operations.alert_type%ROWTYPE;
    v_now           TIMESTAMPTZ := NOW();
    v_log_id        BIGINT;
    v_changes       JSONB;
    v_min_to_ack    NUMERIC(10,2);
    v_min_to_res    NUMERIC(10,2);
BEGIN

    -- ── Val: campos obligatorios ──────────────────────────────────────────
    IF p_input.alert_id IS NULL OR p_input.alert_timestamp IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ALERT_KEY';
        v_result.error_message := 'alert_id y alert_timestamp son obligatorios';
RETURN v_result;
END IF;

    IF p_input.resolved_by IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_USER';
        v_result.error_message := 'resolved_by (user_id) es obligatorio';
RETURN v_result;
END IF;

    -- ── Val: usuario existe y está activo ─────────────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM identity."user"
        WHERE user_id = p_input.resolved_by AND is_active = TRUE
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'USER_NOT_FOUND';
        v_result.error_message := 'user_id=' || p_input.resolved_by
                                  || ' no existe o está inactivo';
RETURN v_result;
END IF;

    -- ── Buscar alerta ─────────────────────────────────────────────────────
SELECT * INTO v_alert
FROM core_operations.alert
WHERE alert_id        = p_input.alert_id
  AND alert_timestamp = p_input.alert_timestamp;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ALERT_NOT_FOUND';
        v_result.error_message := 'Alerta alert_id=' || p_input.alert_id
                                  || ' con alert_timestamp='
                                  || p_input.alert_timestamp::TEXT || ' no existe';
RETURN v_result;
END IF;

SELECT * INTO v_alert_type
FROM core_operations.alert_type
WHERE alert_type_id = v_alert.alert_type_id;

-- ── Casos especiales: ya cerrada → warning, no error duro ─────────────
IF v_alert.status = 'RESOLVED' THEN
        v_result.success          := TRUE;
        v_result.warning          := 'ALERT_ALREADY_RESOLVED: La alerta ya fue resuelta '
                                     || 'el ' || v_alert.resolved_at::TEXT;
        v_result.alert_id         := v_alert.alert_id;
        v_result.alert_type_code  := v_alert_type.code;
        v_result.entity_type      := v_alert.entity_type;
        v_result.vehicle_id       := v_alert.vehicle_id;
        v_result.driver_id        := v_alert.driver_id;
        v_result.severity         := v_alert.severity;
        v_result.previous_status  := 'RESOLVED';
        v_result.current_status   := 'RESOLVED';
        v_result.acknowledged_by  := v_alert.acknowledged_by;
        v_result.acknowledged_at  := v_alert.acknowledged_at;
        v_result.resolved_at      := v_alert.resolved_at;
RETURN v_result;
END IF;

    IF v_alert.status = 'AUTO_CLOSED' THEN
        v_result.success         := TRUE;
        v_result.warning         := 'ALERT_AUTO_CLOSED: La alerta fue cerrada '
                                    || 'automáticamente el ' || v_alert.auto_closed_at::TEXT;
        v_result.alert_id        := v_alert.alert_id;
        v_result.alert_type_code := v_alert_type.code;
        v_result.previous_status := 'AUTO_CLOSED';
        v_result.current_status  := 'AUTO_CLOSED';
RETURN v_result;
END IF;

    -- ── Val: solo ACTIVE o ACKNOWLEDGED pueden resolverse ─────────────────
    IF v_alert.status NOT IN ('ACTIVE', 'ACKNOWLEDGED') THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ALERT_INVALID_STATUS';
        v_result.error_message := 'La alerta está en estado ' || v_alert.status
                                  || ' y no puede resolverse';
RETURN v_result;
END IF;

    -- ── Val: si requires_acknowledgment=TRUE, debe estar ACKNOWLEDGED ──────
    IF v_alert_type.requires_acknowledgment = TRUE
       AND v_alert.status = 'ACTIVE'
       AND v_alert.acknowledged_by IS NULL
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ACKNOWLEDGMENT_REQUIRED';
        v_result.error_message := 'El tipo de alerta "' || v_alert_type.name
                                  || '" requiere reconocimiento previo antes de resolver. '
                                  || 'Use acknowledge_alert primero';
RETURN v_result;
END IF;

    -- ── Calcular métricas de tiempo de respuesta ──────────────────────────
    IF v_alert.acknowledged_at IS NOT NULL THEN
        v_min_to_ack := ROUND(
            EXTRACT(EPOCH FROM (v_alert.acknowledged_at - v_alert.alert_timestamp)) / 60.0, 2
        );
END IF;

    v_min_to_res := ROUND(
        EXTRACT(EPOCH FROM (v_now - v_alert.alert_timestamp)) / 60.0, 2
    );

    -- ── Actualizar alerta ─────────────────────────────────────────────────
UPDATE core_operations.alert
SET status      = 'RESOLVED',
    resolved_at = v_now,
    description = CASE
                      WHEN p_input.resolution_notes IS NOT NULL
                          THEN COALESCE(description || E'\n', '')
                          || '[RESOLVED] ' || p_input.resolution_notes
                      ELSE description
        END
WHERE alert_id        = p_input.alert_id
  AND alert_timestamp = p_input.alert_timestamp;

-- resolve_alert
-- PERFORM pg_notify(
--     'alert_updated',
--     jsonb_build_object(
--         'alert_id',          p_input.alert_id,
--         'new_status',        'RESOLVED',
--         'resolved_at',       v_now,
--         'severity',          v_alert.severity,
--         'entity_type',       v_alert.entity_type,
--         'vehicle_id',        v_alert.vehicle_id,
--         'minutes_to_resolve', v_min_to_res
--     )::TEXT
-- );
-- ── Registrar en activity_log ─────────────────────────────────────────
v_changes := jsonb_build_object(
        'before', jsonb_build_object('status', v_alert.status),
        'after',  jsonb_build_object('status', 'RESOLVED',
                                     'resolved_at', v_now,
                                     'resolved_by', p_input.resolved_by),
        'fields_changed',       jsonb_build_array('status', 'resolved_at'),
        'alert_type_code',      v_alert_type.code,
        'minutes_to_resolve',   v_min_to_res,
        'minutes_to_acknowledge', v_min_to_ack,
        'resolution_notes',     p_input.resolution_notes
    );

INSERT INTO identity.activity_log (
    user_id, action, resource_type, resource_id,
    changes, status, created_at
)
VALUES (
           p_input.resolved_by,
           'ALERT_RESOLVE',
           'core_operations.alert',
           p_input.alert_id,
           v_changes, 'SUCCESS', v_now
       )
    RETURNING log_id INTO v_log_id;

-- ── Poblar resultado ──────────────────────────────────────────────────
v_result.success                := TRUE;
    v_result.alert_id               := v_alert.alert_id;
    v_result.alert_type_code        := v_alert_type.code;
    v_result.entity_type            := v_alert.entity_type;
    v_result.vehicle_id             := v_alert.vehicle_id;
    v_result.driver_id              := v_alert.driver_id;
    v_result.severity               := v_alert.severity;
    v_result.previous_status        := v_alert.status;
    v_result.current_status         := 'RESOLVED';
    v_result.acknowledged_by        := v_alert.acknowledged_by;
    v_result.acknowledged_at        := v_alert.acknowledged_at;
    v_result.resolved_by            := p_input.resolved_by;
    v_result.resolved_at            := v_now;
    v_result.minutes_to_acknowledge := v_min_to_ack;
    v_result.minutes_to_resolve     := v_min_to_res;
    v_result.activity_log_id        := v_log_id;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: seed_alert_types(api.seed_alert_types_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.seed_alert_types(p_input api.seed_alert_types_input) RETURNS api.seed_alert_types_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.seed_alert_types_result;
    v_item              api.alert_type_item;
    v_item_result       api.alert_type_item_result;
    v_item_results      api.alert_type_item_result[] := ARRAY[]::api.alert_type_item_result[];

    v_total_processed   INTEGER := 0;
    v_total_inserted    INTEGER := 0;
    v_total_updated     INTEGER := 0;
    v_total_errors      INTEGER := 0;

    v_valid_severities  TEXT[]  := ARRAY['CRITICAL','HIGH','MEDIUM','LOW','INFO'];
    v_valid_channels    TEXT[]  := ARRAY['EMAIL','SMS','PUSH','WEBHOOK','WHATSAPP'];
    v_valid_categories  TEXT[]  := ARRAY['TRACKER','PANIC','VEHICLE','DISPATCH','DRIVER','SYSTEM'];

    v_returned_id       INTEGER;
    v_operation         VARCHAR(10);
    v_bad_channel       TEXT;
BEGIN
    -- ── Guardia: array vacío ──────────────────────────────────────────────
    IF p_input.items IS NULL OR array_length(p_input.items, 1) IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'EMPTY_ITEMS';
        v_result.error_message := 'El array items no puede estar vacío.';
        v_result.total_processed := 0;
        v_result.total_inserted  := 0;
        v_result.total_updated   := 0;
        v_result.total_errors    := 0;
        v_result.detail          := ARRAY[]::api.alert_type_item_result[];
RETURN v_result;
END IF;

    FOREACH v_item IN ARRAY p_input.items
    LOOP
        v_total_processed := v_total_processed + 1;

        -- Inicializar resultado del ítem
        v_item_result.code          := v_item.code;
        v_item_result.name          := v_item.name;
        v_item_result.alert_type_id := NULL;
        v_item_result.operation     := NULL;
        v_item_result.error_code    := NULL;
        v_item_result.error_message := NULL;

        -- ── Validación 1: code obligatorio ───────────────────────────────
        IF v_item.code IS NULL OR trim(v_item.code) = '' THEN
            v_item_result.operation     := 'SKIPPED';
            v_item_result.error_code    := 'MISSING_CODE';
            v_item_result.error_message := 'El campo code es obligatorio.';
            v_total_errors   := v_total_errors + 1;
            v_item_results   := v_item_results || v_item_result;
CONTINUE;
END IF;

        -- ── Validación 2: name obligatorio ───────────────────────────────
        IF v_item.name IS NULL OR trim(v_item.name) = '' THEN
            v_item_result.operation     := 'SKIPPED';
            v_item_result.error_code    := 'MISSING_NAME';
            v_item_result.error_message := 'El campo name es obligatorio para code="'
                                           || v_item.code || '".';
            v_total_errors   := v_total_errors + 1;
            v_item_results   := v_item_results || v_item_result;
CONTINUE;
END IF;

        -- ── Validación 3: severity dentro del dominio ────────────────────
        IF v_item.severity IS NULL
           OR NOT (v_item.severity = ANY(v_valid_severities)) THEN
            v_item_result.operation     := 'SKIPPED';
            v_item_result.error_code    := 'INVALID_SEVERITY';
            v_item_result.error_message := 'severity inválido: "'
                                           || COALESCE(v_item.severity, 'NULL')
                                           || '". Válidos: '
                                           || array_to_string(v_valid_severities, ', ');
            v_total_errors   := v_total_errors + 1;
            v_item_results   := v_item_results || v_item_result;
CONTINUE;
END IF;

        -- ── Validación 4: category dentro del dominio ────────────────────
        IF v_item.category IS NOT NULL
           AND NOT (v_item.category = ANY(v_valid_categories)) THEN
            v_item_result.operation     := 'SKIPPED';
            v_item_result.error_code    := 'INVALID_CATEGORY';
            v_item_result.error_message := 'category inválida: "'
                                           || v_item.category
                                           || '". Válidas: '
                                           || array_to_string(v_valid_categories, ', ');
            v_total_errors   := v_total_errors + 1;
            v_item_results   := v_item_results || v_item_result;
CONTINUE;
END IF;

        -- ── Validación 5: notification_channels — cada elemento válido ───
        IF v_item.notification_channels IS NOT NULL THEN
SELECT ch INTO v_bad_channel
FROM unnest(v_item.notification_channels) AS ch
WHERE ch != ALL(v_valid_channels)
            LIMIT 1;

IF FOUND THEN
                v_item_result.operation     := 'SKIPPED';
                v_item_result.error_code    := 'INVALID_NOTIFICATION_CHANNEL';
                v_item_result.error_message := 'Canal inválido: "' || v_bad_channel
                                               || '" en code="' || v_item.code
                                               || '". Válidos: '
                                               || array_to_string(v_valid_channels, ', ');
                v_total_errors   := v_total_errors + 1;
                v_item_results   := v_item_results || v_item_result;
CONTINUE;
END IF;
END IF;

        -- ── Validación 6: auto_close_after_min > 0 si se provee ──────────
        IF v_item.auto_close_after_min IS NOT NULL
           AND v_item.auto_close_after_min <= 0 THEN
            v_item_result.operation     := 'SKIPPED';
            v_item_result.error_code    := 'INVALID_AUTO_CLOSE_MIN';
            v_item_result.error_message := 'auto_close_after_min debe ser > 0. '
                                           || 'Recibido: ' || v_item.auto_close_after_min::TEXT
                                           || ' en code="' || v_item.code || '".';
            v_total_errors   := v_total_errors + 1;
            v_item_results   := v_item_results || v_item_result;
CONTINUE;
END IF;

        -- ── Upsert ───────────────────────────────────────────────────────
BEGIN
INSERT INTO core_operations.alert_type (
    code,
    name,
    description,
    category,
    severity,
    requires_acknowledgment,
    auto_close_after_min,
    notification_channels,
    display_order,
    is_active
) VALUES (
             v_item.code,
             v_item.name,
             v_item.description,
             v_item.category,
             v_item.severity,
             COALESCE(v_item.requires_acknowledgment, false),
             v_item.auto_close_after_min,
             v_item.notification_channels,
             COALESCE(v_item.display_order, 0),
             COALESCE(v_item.is_active, true)
         )
    ON CONFLICT (code) DO UPDATE SET
    name                    = EXCLUDED.name,
                              description             = EXCLUDED.description,
                              category                = EXCLUDED.category,
                              severity                = EXCLUDED.severity,
                              requires_acknowledgment = EXCLUDED.requires_acknowledgment,
                              auto_close_after_min    = EXCLUDED.auto_close_after_min,
                              notification_channels   = EXCLUDED.notification_channels,
                              display_order           = EXCLUDED.display_order
                              -- is_active NO se actualiza: preserva desactivaciones manuales
                              RETURNING
                              alert_type_id,
                              CASE WHEN xmax = 0 THEN 'INSERTED' ELSE 'UPDATED' END
            INTO v_returned_id, v_operation;

            v_item_result.alert_type_id := v_returned_id;
            v_item_result.operation     := v_operation;

            IF v_operation = 'INSERTED' THEN
                v_total_inserted := v_total_inserted + 1;
ELSE
                v_total_updated  := v_total_updated  + 1;
END IF;

EXCEPTION
            WHEN OTHERS THEN
                v_item_result.operation     := 'SKIPPED';
                v_item_result.error_code    := 'DB_ERROR';
                v_item_result.error_message := SQLERRM;
                v_total_errors := v_total_errors + 1;
END;

        v_item_results := v_item_results || v_item_result;
END LOOP;

    -- ── Resultado global ─────────────────────────────────────────────────
    v_result.success         := (v_total_errors = 0);
    v_result.error_code      := CASE WHEN v_total_errors > 0 THEN 'PARTIAL_ERRORS' ELSE NULL END;
    v_result.error_message   := CASE WHEN v_total_errors > 0
                                     THEN v_total_errors::TEXT || ' ítem(s) no se procesaron. Revise detail.'
                                     ELSE NULL END;
    v_result.total_processed := v_total_processed;
    v_result.total_inserted  := v_total_inserted;
    v_result.total_updated   := v_total_updated;
    v_result.total_errors    := v_total_errors;
    v_result.detail          := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success         := FALSE;
        v_result.error_code      := 'INTERNAL_ERROR';
        v_result.error_message   := SQLERRM;
        v_result.total_processed := v_total_processed;
        v_result.total_inserted  := v_total_inserted;
        v_result.total_updated   := v_total_updated;
        v_result.total_errors    := v_total_errors;
        v_result.detail          := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: FUNCTION seed_alert_types(p_input api.seed_alert_types_input); Type: COMMENT; Schema: api; Owner: -
--

COMMENT ON FUNCTION api.seed_alert_types(p_input api.seed_alert_types_input) IS 'Grupo A — Inicialización. Idempotente por ON CONFLICT (code).
INSERT en primer run, UPDATE de campos de configuración en runs posteriores.
is_active NO se toca en UPDATE para preservar desactivaciones manuales.
Fallo por ítem: continúa con los demás y reporta errores en detail[].';


--
-- Name: seed_catalog(api.seed_catalog_input[]); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.seed_catalog(p_inputs api.seed_catalog_input[]) RETURNS api.seed_catalog_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.seed_catalog_result;
    v_cat_result        api.seed_catalog_category_result;
    v_cat_results       api.seed_catalog_category_result[] := ARRAY[]::api.seed_catalog_category_result[];

    v_input             api.seed_catalog_input;
    v_item              api.catalog_item;

    v_total_inserted    INT := 0;
    v_total_skipped     INT := 0;
    v_cats_processed    INT := 0;

    -- Categorías válidas del sistema (añadir más segun demanda)
    v_valid_categories  TEXT[] := ARRAY[
        'vehicle_status',
        'fuel_type',
        'trip_status',
        'incident_type',
        'employment_type',
        'employment_status',
        'payment_method',
        'document_restriction_type',
        'schedule_type',
        'exception_type',
        'job_title'
    ];

    v_inserted          INT;
    v_skipped           INT;
    v_before_count      INT;
    v_after_count       INT;
BEGIN

    -- Iterar cada lote de categoría
    FOREACH v_input IN ARRAY p_inputs
    LOOP
        v_cats_processed := v_cats_processed + 1;

        -- Inicializar resultado de esta categoría
        v_cat_result.category      := v_input.category;
        v_cat_result.inserted      := 0;
        v_cat_result.skipped       := 0;
        v_cat_result.success       := TRUE;
        v_cat_result.error_code    := NULL;
        v_cat_result.error_message := NULL;

        -- Validar que la categoría sea conocida
        IF NOT (v_input.category = ANY(v_valid_categories)) THEN
            v_cat_result.success       := FALSE;
            v_cat_result.error_code    := 'INVALID_CATEGORY_CODE';
            v_cat_result.error_message := 'Categoría desconocida: ' || v_input.category
                                          || '. Válidas: ' || array_to_string(v_valid_categories, ', ');
            v_cat_results := v_cat_results || v_cat_result;
CONTINUE; -- Saltar al siguiente lote, no abortar todo
END IF;

        -- Contar existentes antes de insertar
SELECT COUNT(*) INTO v_before_count
FROM shared.catalog
WHERE category = v_input.category;

-- Insertar cada ítem del lote con ON CONFLICT DO NOTHING
FOREACH v_item IN ARRAY v_input.items
        LOOP
            INSERT INTO shared.catalog (category, code, name, description, display_order)
            VALUES (
                v_input.category,
                v_item.code,
                v_item.name,
                v_item.description,
                COALESCE(v_item.display_order, 0)
            )
            ON CONFLICT (category, code) DO NOTHING;
END LOOP;

        -- Contar existentes después de insertar para derivar inserted vs skipped
SELECT COUNT(*) INTO v_after_count
FROM shared.catalog
WHERE category = v_input.category;

v_inserted := v_after_count - v_before_count;
        v_skipped  := array_length(v_input.items, 1) - v_inserted;

        v_cat_result.inserted := v_inserted;
        v_cat_result.skipped  := v_skipped;

        v_total_inserted := v_total_inserted + v_inserted;
        v_total_skipped  := v_total_skipped  + v_skipped;

        v_cat_results := v_cat_results || v_cat_result;
END LOOP;

    -- Resultado global
    v_result.success              := TRUE;
    v_result.error_code           := NULL;
    v_result.error_message        := NULL;
    v_result.categories_processed := v_cats_processed;
    v_result.total_inserted       := v_total_inserted;
    v_result.total_skipped        := v_total_skipped;
    v_result.detail               := v_cat_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_cat_results; -- lo que alcanzó a procesar
RETURN v_result;
END;
$$;


--
-- Name: seed_document_type(api.seed_document_type_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.seed_document_type(p_input api.seed_document_type_input) RETURNS api.seed_document_type_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.seed_document_type_result;
    v_item              api.document_type_item;
    v_item_result       api.document_type_item_result;
    v_item_results      api.document_type_item_result[]
                            := ARRAY[]::api.document_type_item_result[];
    -- Contadores
    v_total_inserted    INT := 0;
    v_total_updated     INT := 0;
    v_total_skipped     INT := 0;
    v_total_errors      INT := 0;
    -- Trabajo
    v_existing          shared.document_type%ROWTYPE;
    v_has_changes       BOOLEAN;
    v_new_requires_exp  BOOLEAN;
    v_new_alert_days    INT;
    v_processed_codes   VARCHAR(50)[] := ARRAY[]::VARCHAR[];
BEGIN

    -- ── Validación global: array no nulo ──────────────────────────────────
    IF p_input.items IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_ITEMS_ARRAY';
        v_result.error_message := 'El array de ítems es NULL. Provea al menos un tipo de documento';
RETURN v_result;
END IF;

    IF array_length(p_input.items, 1) IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NO_ITEMS_PROVIDED';
        v_result.error_message := 'El array de ítems está vacío. Provea al menos un tipo de documento';
RETURN v_result;
END IF;

    -- ── Iterar sobre cada ítem ────────────────────────────────────────────
    FOREACH v_item IN ARRAY p_input.items
    LOOP
        v_item_result.code             := v_item.code;
        v_item_result.name             := v_item.name;
        v_item_result.document_type_id := NULL;
        v_item_result.status           := NULL;
        v_item_result.error_code       := NULL;
        v_item_result.error_message    := NULL;

        -- ── Val: code obligatorio ─────────────────────────────────────────
        IF v_item.code IS NULL OR TRIM(v_item.code) = '' THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'MISSING_CODE';
            v_item_result.error_message := 'code es obligatorio en cada ítem';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: code no duplicado dentro del batch ───────────────────────
        IF v_item.code = ANY(v_processed_codes) THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'DUPLICATE_CODE_IN_BATCH';
            v_item_result.error_message := 'code="' || v_item.code
                                           || '" aparece más de una vez en el mismo lote';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: restriction_type válido ──────────────────────────────────
        IF v_item.restriction_type IS NOT NULL
           AND v_item.restriction_type NOT IN ('CRITICAL', 'WARNING', 'NONE')
        THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'INVALID_RESTRICTION_TYPE';
            v_item_result.error_message := 'restriction_type inválido: "' || v_item.restriction_type
                                           || '". Válidos: CRITICAL, WARNING, NONE';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: entity_type válido ───────────────────────────────────────
        IF v_item.entity_type IS NOT NULL
           AND v_item.entity_type NOT IN ('DRIVER', 'VEHICLE', 'COMPANY', 'GENERAL')
        THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'INVALID_ENTITY_TYPE';
            v_item_result.error_message := 'entity_type inválido: "' || v_item.entity_type
                                           || '". Válidos: DRIVER, VEHICLE, COMPANY, GENERAL';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: alert_days_before > 0 cuando se provee ───────────────────
        IF v_item.alert_days_before IS NOT NULL AND v_item.alert_days_before <= 0 THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'INVALID_ALERT_DAYS';
            v_item_result.error_message := 'alert_days_before debe ser mayor a 0 '
                                           || 'en "' || v_item.code || '". '
                                           || 'Recibido: ' || v_item.alert_days_before::TEXT;
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Buscar si el tipo de documento ya existe ──────────────────────
SELECT * INTO v_existing
FROM shared.document_type
WHERE code = v_item.code;

-- ═══════════════════════════════════════════════════════════════
-- RAMA UPDATE: el code ya existe en BD
-- ═══════════════════════════════════════════════════════════════
IF FOUND THEN

            -- Calcular el estado final de requires_expiry y alert_days_before
            -- considerando tanto el valor del payload como el existente en BD
            v_new_requires_exp := COALESCE(v_item.requires_expiry, v_existing.requires_expiry);
            v_new_alert_days   := COALESCE(v_item.alert_days_before, v_existing.alert_days_before);

            -- Val: coherencia final requires_expiry + alert_days_before
            IF v_new_requires_exp = TRUE AND v_new_alert_days IS NULL THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_ALERT_DAYS';
                v_item_result.error_message := '"' || v_item.code || '" quedaría con '
                                               || 'requires_expiry=TRUE pero sin alert_days_before. '
                                               || 'Incluya alert_days_before en el payload';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: name no vacío si viene
            IF v_item.name IS NOT NULL AND TRIM(v_item.name) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_NAME';
                v_item_result.error_message := 'name no puede ser una cadena vacía '
                                               || 'en "' || v_item.code || '"';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Detectar cambios reales (PATCH semántico)
            v_has_changes :=
                (v_item.name              IS NOT NULL AND TRIM(v_item.name)    IS DISTINCT FROM v_existing.name)              OR
                (v_item.description       IS NOT NULL AND v_item.description   IS DISTINCT FROM v_existing.description)       OR
                (v_item.is_mandatory      IS NOT NULL AND v_item.is_mandatory  IS DISTINCT FROM v_existing.is_mandatory)      OR
                (v_item.requires_expiry   IS NOT NULL AND v_new_requires_exp   IS DISTINCT FROM v_existing.requires_expiry)   OR
                (v_item.alert_days_before IS NOT NULL AND v_new_alert_days     IS DISTINCT FROM v_existing.alert_days_before) OR
                (v_item.restriction_type  IS NOT NULL AND v_item.restriction_type IS DISTINCT FROM v_existing.restriction_type) OR
                (v_item.entity_type       IS NOT NULL AND v_item.entity_type   IS DISTINCT FROM v_existing.entity_type)       OR
                (v_item.is_active         IS NOT NULL AND v_item.is_active     IS DISTINCT FROM v_existing.is_active);

            IF v_has_changes THEN
UPDATE shared.document_type
SET name              = COALESCE(NULLIF(TRIM(v_item.name), ''),  name),
    description       = COALESCE(v_item.description,             description),
    is_mandatory      = COALESCE(v_item.is_mandatory,            is_mandatory),
    requires_expiry   = v_new_requires_exp,
    alert_days_before = v_new_alert_days,
    restriction_type  = COALESCE(v_item.restriction_type,        restriction_type),
    entity_type       = COALESCE(v_item.entity_type,             entity_type),
    is_active         = COALESCE(v_item.is_active,               is_active)
WHERE code = v_item.code;

v_item_result.status           := 'UPDATED';
                v_item_result.document_type_id := v_existing.document_type_id;
                v_total_updated                := v_total_updated + 1;
ELSE
                v_item_result.status           := 'SKIPPED';
                v_item_result.document_type_id := v_existing.document_type_id;
                v_total_skipped                := v_total_skipped + 1;
END IF;

        -- ═══════════════════════════════════════════════════════════════
        -- RAMA INSERT: el code no existe en BD
        -- ═══════════════════════════════════════════════════════════════
ELSE

            -- Val: name obligatorio en INSERT
            IF v_item.name IS NULL OR TRIM(v_item.name) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_NAME';
                v_item_result.error_message := 'name es obligatorio al crear el tipo de documento "'
                                               || v_item.code || '"';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: coherencia requires_expiry + alert_days_before en INSERT
            IF COALESCE(v_item.requires_expiry, FALSE) = TRUE
               AND v_item.alert_days_before IS NULL
            THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_ALERT_DAYS';
                v_item_result.error_message := '"' || v_item.code
                                               || '" tiene requires_expiry=TRUE '
                                               || 'pero no se proporcionó alert_days_before';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

INSERT INTO shared.document_type (
    code,
    name,
    description,
    is_mandatory,
    requires_expiry,
    alert_days_before,
    restriction_type,
    entity_type,
    is_active
)
VALUES (
           UPPER(TRIM(v_item.code)),
           TRIM(v_item.name),
           v_item.description,
           COALESCE(v_item.is_mandatory,    TRUE),
           COALESCE(v_item.requires_expiry, FALSE),
           v_item.alert_days_before,
           v_item.restriction_type,
           COALESCE(v_item.entity_type,     'GENERAL'),
           COALESCE(v_item.is_active,       TRUE)
       )
    RETURNING document_type_id INTO v_item_result.document_type_id;

v_item_result.status := 'INSERTED';
            v_total_inserted     := v_total_inserted + 1;

END IF;

        v_item_result.name := COALESCE(v_item.name, v_existing.name);
        v_item_results     := v_item_results || v_item_result;
        v_processed_codes  := v_processed_codes || v_item.code;

END LOOP;

    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success         := TRUE;
    v_result.error_code      := NULL;
    v_result.error_message   := NULL;
    v_result.total_submitted := array_length(p_input.items, 1);
    v_result.total_inserted  := v_total_inserted;
    v_result.total_updated   := v_total_updated;
    v_result.total_skipped   := v_total_skipped;
    v_result.total_errors    := v_total_errors;
    v_result.detail          := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: set_vehicle_ownership_share(api.set_vehicle_ownership_share_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.set_vehicle_ownership_share(p_input api.set_vehicle_ownership_share_input) RETURNS api.set_vehicle_ownership_share_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.set_vehicle_ownership_share_result;
    v_share_id              INT;
    v_operation             VARCHAR(10);
    v_owner_name            VARCHAR(255);
    v_existing_share_id     INT;
    v_current_total         DECIMAL(5,2);
    v_current_own_pct       DECIMAL(5,2);   -- porcentaje actual del mismo propietario (si existe)
    v_projected_total       DECIMAL(5,2);
    v_valid_from            DATE;
BEGIN

    -- ── Validación 1: vehículo existe ─────────────────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM fleet.vehicle WHERE vehicle_id = p_input.vehicle_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_FOUND';
        v_result.error_message := 'El vehículo vehicle_id=' || p_input.vehicle_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 2: propietario existe y está activo ────────────────────
SELECT full_name INTO v_owner_name
FROM fleet.vehicle_owner
WHERE vehicle_owner_id = p_input.vehicle_owner_id
  AND is_active         = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'OWNER_NOT_FOUND';
        v_result.error_message := 'El propietario vehicle_owner_id='
                                  || p_input.vehicle_owner_id
                                  || ' no existe o está inactivo en fleet.vehicle_owner';
RETURN v_result;
END IF;

    -- ── Validación 3: porcentaje dentro del rango [0, 100] ────────────────
    IF p_input.ownership_percentage IS NULL
       OR p_input.ownership_percentage < 0
       OR p_input.ownership_percentage > 100
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_PERCENTAGE';
        v_result.error_message := 'ownership_percentage debe estar entre 0 y 100. '
                                  || 'Recibido: '
                                  || COALESCE(p_input.ownership_percentage::TEXT, 'NULL');
RETURN v_result;
END IF;

    -- ── Validación 4: valid_from obligatorio ──────────────────────────────
    v_valid_from := COALESCE(p_input.valid_from, CURRENT_DATE);

    -- ── Validación 5: rango de fechas coherente ───────────────────────────
    IF p_input.valid_until IS NOT NULL
       AND p_input.valid_until <= v_valid_from
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DATE_RANGE';
        v_result.error_message := 'valid_until (' || p_input.valid_until::TEXT
                                  || ') debe ser posterior a valid_from ('
                                  || v_valid_from::TEXT || ')';
RETURN v_result;
END IF;

    -- ── Validación 6: solapamiento de períodos para el mismo propietario ──
    -- Buscar si ya existe un share del mismo (vehicle_id, vehicle_owner_id)
    -- cuyo período se solapa con el nuevo
SELECT share_id, ownership_percentage
INTO v_existing_share_id, v_current_own_pct
FROM fleet.vehicle_owner_share
WHERE vehicle_id       = p_input.vehicle_id
  AND vehicle_owner_id = p_input.vehicle_owner_id
  AND is_active        = TRUE
  -- Solapamiento: dos rangos [A, B) y [C, D) se solapan si A < D AND C < B
  -- Tratamos valid_until=NULL como infinito
  AND v_valid_from < COALESCE(valid_until, '9999-12-31'::DATE)
  AND COALESCE(p_input.valid_until, '9999-12-31'::DATE) > valid_from
    LIMIT 1;

-- Si existe solapamiento pero es la misma combinación (vehicle_id, vehicle_owner_id, valid_from)
-- → es un UPDATE, no un OVERLAPPING_PERIOD
IF v_existing_share_id IS NOT NULL THEN
        -- Verificar si es exactamente el mismo valid_from (caso UPDATE)
        IF EXISTS (
            SELECT 1 FROM fleet.vehicle_owner_share
            WHERE share_id   = v_existing_share_id
              AND valid_from = v_valid_from
        ) THEN
            -- Es un UPDATE del período existente; continuar
            NULL;
ELSE
            -- Es un período distinto que se solapa → error
            v_result.success       := FALSE;
            v_result.error_code    := 'OVERLAPPING_PERIOD';
            v_result.error_message := 'Ya existe una participación activa del propietario '
                                      || v_owner_name
                                      || ' (share_id=' || v_existing_share_id::TEXT || ') '
                                      || 'cuyo período se solapa con ['
                                      || v_valid_from::TEXT || ', '
                                      || COALESCE(p_input.valid_until::TEXT, '∞') || ']';
RETURN v_result;
END IF;
END IF;

    -- ── Validación 7: suma de porcentajes no supera 100% ──────────────────
    -- Sumar porcentajes activos del vehículo, excluyendo el propietario actual
    -- (porque si está haciendo UPDATE, su porcentaje antiguo se reemplaza)
SELECT COALESCE(SUM(ownership_percentage), 0)
INTO v_current_total
FROM fleet.vehicle_owner_share
WHERE vehicle_id       = p_input.vehicle_id
  AND is_active        = TRUE
  AND vehicle_owner_id <> p_input.vehicle_owner_id  -- excluir al mismo propietario
  -- Solo shares vigentes en el período nuevo
  AND valid_from < COALESCE(p_input.valid_until, '9999-12-31'::DATE)
  AND COALESCE(valid_until, '9999-12-31'::DATE) > v_valid_from;

v_projected_total := v_current_total + p_input.ownership_percentage;

    IF v_projected_total > 100 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'OWNERSHIP_EXCEEDS_100';
        v_result.error_message := 'La suma de participaciones superaría 100%. '
                                  || 'Total actual de otros propietarios: '
                                  || v_current_total::TEXT || '%. '
                                  || 'Porcentaje solicitado: '
                                  || p_input.ownership_percentage::TEXT || '%. '
                                  || 'Proyectado: ' || v_projected_total::TEXT || '%. '
                                  || 'Disponible: ' || (100 - v_current_total)::TEXT || '%';
RETURN v_result;
END IF;

    -- ── UPSERT: INSERT o UPDATE según unique constraint ────────────────────
    -- Unique: (vehicle_id, vehicle_owner_id, valid_from)
INSERT INTO fleet.vehicle_owner_share (
    vehicle_id,
    vehicle_owner_id,
    ownership_percentage,
    valid_from,
    valid_until,
    is_active
)
VALUES (
           p_input.vehicle_id,
           p_input.vehicle_owner_id,
           p_input.ownership_percentage,
           v_valid_from,
           p_input.valid_until,
           TRUE
       )
    ON CONFLICT (vehicle_id, vehicle_owner_id, valid_from)
    DO UPDATE SET
    ownership_percentage = EXCLUDED.ownership_percentage,
               valid_until          = EXCLUDED.valid_until,
               is_active            = TRUE,
               updated_at           = NOW()
               RETURNING
               share_id,
               CASE WHEN xmax = 0 THEN 'INSERTED' ELSE 'UPDATED' END
    INTO v_share_id, v_operation;

    -- ── Calcular total final para el resultado ────────────────────────────
SELECT COALESCE(SUM(ownership_percentage), 0)
INTO v_projected_total
FROM fleet.vehicle_owner_share
WHERE vehicle_id  = p_input.vehicle_id
  AND is_active   = TRUE
  AND valid_from  < COALESCE(p_input.valid_until, '9999-12-31'::DATE)
  AND COALESCE(valid_until, '9999-12-31'::DATE) > v_valid_from;

-- ── Poblar resultado campo a campo ────────────────────────────────────
SELECT
    vos.share_id,
    vos.vehicle_id,
    vos.vehicle_owner_id,
    vos.ownership_percentage,
    vos.valid_from,
    vos.valid_until,
    vos.is_active,
    vos.created_at,
    vos.updated_at
INTO
    v_result.share_id,
    v_result.vehicle_id,
    v_result.vehicle_owner_id,
    v_result.ownership_percentage,
    v_result.valid_from,
    v_result.valid_until,
    v_result.is_active,
    v_result.created_at,
    v_result.updated_at
FROM fleet.vehicle_owner_share vos
WHERE vos.share_id = v_share_id;

v_result.success                := TRUE;
    v_result.owner_full_name        := v_owner_name;
    v_result.operation              := v_operation;
    v_result.total_percentage_after := v_projected_total;
    v_result.remaining_percentage   := ROUND(100 - v_projected_total, 2);

RETURN v_result;

EXCEPTION
    WHEN check_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'CONSTRAINT_VIOLATION';
        v_result.error_message := 'Violación de constraint en vehicle_owner_share: '
                                  || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: sync_checkpoints(api.sync_checkpoints_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_checkpoints(p_input api.sync_checkpoints_input) RETURNS api.sync_checkpoints_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                    api.sync_checkpoints_result;
    v_route_code                VARCHAR(20);
    v_route_type                VARCHAR(20);
    v_direction                 VARCHAR(10);
    v_cp                        api.sync_checkpoint_item;
    v_item_result                api.sync_checkpoint_item_result;
    v_item_results                api.sync_checkpoint_item_result[]
                                             := ARRAY[]::api.sync_checkpoint_item_result[];
    -- Contadores
    v_total_inserted            INT := 0;
    v_total_updated              INT := 0;
    v_total_deleted               INT := 0;
    v_total_skipped               INT := 0;
    v_total_errors                INT := 0;
    v_total_controls_deleted      INT := 0;
    v_total_trip_stops_deleted    INT := 0;
    -- Trabajo — upsert
    v_new_cp_id                  INT;
    v_geofence                   INT;
    v_cp_type                    core_operations.checkpoint_type_enum;
    v_is_endpoint                 BOOLEAN;
    v_existing_cp                 core_operations.checkpoint%ROWTYPE;
    v_has_changes                 BOOLEAN;
    -- Trabajo — validación distancias
    v_prev_distance                DECIMAL(8,2);
    v_prev_sequence                INT;
    v_batch_prev_dist              DECIMAL(8,2);
    v_batch_prev_seq               INT;
    v_found_in_batch                BOOLEAN;
    v_i                             INT;
    -- Acumuladores del batch (ya no necesitan dimensión "direction": es única)
    v_upserted_seqs                INT[]     := ARRAY[]::INT[];
    v_upserted_dists               DECIMAL[] := ARRAY[]::DECIMAL[];
    -- IDs procesados correctamente (para el diff del DELETE)
    v_submitted_cp_ids             INT[]     := ARRAY[]::INT[];
    -- Detección de duplicados en batch
    v_processed_seqs               INT[]     := ARRAY[]::INT[];
    v_processed_cp_ids             INT[]     := ARRAY[]::INT[];
    -- Validación endpoints (ahora un solo contador: ya hay una sola dirección)
    v_endpoint_count               INT;
    v_expected_endpoint_count       INT;
    -- DELETE
    v_del_cp_id                    INT;
    v_del_name                     VARCHAR(255);
    v_del_code                     VARCHAR(20);
    v_del_sequence                  INT;
    v_del_cp_type                    VARCHAR(20);
    v_del_control_exists             BOOLEAN;
    v_del_trip_count                 INT;
BEGIN

    -- ── Validación 1: ruta existe y está activa ───────────────────────────
SELECT code, route_type
INTO v_route_code, v_route_type
FROM core_operations.route
WHERE route_id = p_input.route_id
  AND is_active = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROUTE_NOT_FOUND';
        v_result.error_message := 'La ruta route_id=' || p_input.route_id
            || ' no existe o está inactiva';
RETURN v_result;
END IF;

    -- ── Validación 2: direction obligatorio y en dominio ──────────────────
    IF p_input.direction IS NULL OR TRIM(p_input.direction) = '' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_DIRECTION';
        v_result.error_message := 'direction es obligatorio. Valores válidos: IDA, VUELTA, CIRCULAR';
RETURN v_result;
END IF;

    v_direction := UPPER(TRIM(p_input.direction));

    IF v_direction NOT IN ('IDA', 'VUELTA', 'CIRCULAR') THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DIRECTION';
        v_result.error_message := 'direction="' || p_input.direction
            || '" inválido. Válidos: IDA, VUELTA, CIRCULAR';
RETURN v_result;
END IF;

    -- ── Validación 3: direction coherente con route_type ──────────────────
    IF v_route_type = 'CIRCULAR' AND v_direction <> 'CIRCULAR' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DIRECTION_ROUTE_TYPE_MISMATCH';
        v_result.error_message := 'Una ruta CIRCULAR solo admite direction=CIRCULAR. '
                                      || 'Se recibió: ' || v_direction;
RETURN v_result;
END IF;

    IF v_route_type = 'LINEAR' AND v_direction = 'CIRCULAR' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DIRECTION_ROUTE_TYPE_MISMATCH';
        v_result.error_message := 'Una ruta LINEAR no admite direction=CIRCULAR. Use IDA o VUELTA';
RETURN v_result;
END IF;

    -- ── Validación 4: NULL explícito rechazado ────────────────────────────
    IF p_input.checkpoints IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_CHECKPOINTS_ARRAY';
        v_result.error_message := 'El array de checkpoints es NULL. '
            || 'Para eliminar todos los de esta dirección, envíe un array vacío []';
RETURN v_result;
END IF;

    -- ── Validación 5: conteo de endpoints en el batch (para esta dirección) ─
    --    LINEAR (IDA o VUELTA): exactamente 2 terminales endpoint.
    --    CIRCULAR: exactamente 1 terminal endpoint.
SELECT COUNT(*) FILTER (
        WHERE LOWER(TRIM(c.checkpoint_type)) = 'terminal'
            AND COALESCE(c.is_route_endpoint, FALSE) = TRUE
        )
INTO v_endpoint_count
FROM unnest(p_input.checkpoints) AS c;

v_expected_endpoint_count := CASE WHEN v_direction = 'CIRCULAR' THEN 1 ELSE 2 END;

    IF v_endpoint_count <> v_expected_endpoint_count THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_ENDPOINT_COUNT';
        v_result.error_message := 'direction=' || v_direction || ' requiere exactamente '
                                      || v_expected_endpoint_count
                                      || ' terminal(es) con is_route_endpoint=true. '
                                      || 'Se recibieron: ' || v_endpoint_count;
RETURN v_result;
END IF;

    -- ════════════════════════════════════════════════════════
    -- FASE 1: Upsert de cada checkpoint enviado
    -- ════════════════════════════════════════════════════════
    IF array_length(p_input.checkpoints, 1) IS NOT NULL THEN

        FOREACH v_cp IN ARRAY p_input.checkpoints
            LOOP
                -- Inicializar resultado del ítem
                v_item_result.sequence_number    := v_cp.sequence_number;
                v_item_result.direction          := v_direction;
                v_item_result.checkpoint_code    := v_cp.checkpoint_code;
                v_item_result.name               := v_cp.name;
                v_item_result.checkpoint_type    := v_cp.checkpoint_type;
                v_item_result.checkpoint_id      := v_cp.checkpoint_id;
                v_item_result.status             := NULL;
                v_item_result.error_code         := NULL;
                v_item_result.error_message      := NULL;
                v_item_result.control_deleted    := FALSE;
                v_item_result.trip_stops_deleted := 0;

                -- ── Val: checkpoint_type obligatorio y en dominio ─────────────
                IF v_cp.checkpoint_type IS NULL OR TRIM(v_cp.checkpoint_type) = '' THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'MISSING_CHECKPOINT_TYPE';
                    v_item_result.error_message := 'checkpoint_type es obligatorio en "'
                                                       || COALESCE(v_cp.name, 'seq='
                            || COALESCE(v_cp.sequence_number::TEXT, '?'))
                        || '". Valores válidos: bus_stop, checkpoint, terminal';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF LOWER(TRIM(v_cp.checkpoint_type)) NOT IN ('bus_stop', 'checkpoint', 'terminal') THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_CHECKPOINT_TYPE';
                    v_item_result.error_message := 'checkpoint_type="' || v_cp.checkpoint_type
                                                       || '" inválido en "'
                                                       || COALESCE(v_cp.name, '')
                        || '". Válidos: bus_stop, checkpoint, terminal';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                v_cp_type     := LOWER(TRIM(v_cp.checkpoint_type))::core_operations.checkpoint_type_enum;
                v_is_endpoint := COALESCE(v_cp.is_route_endpoint, FALSE);

                -- ── Val: is_route_endpoint solo válido para terminal ──────────
                IF v_is_endpoint = TRUE AND v_cp_type <> 'terminal' THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_ENDPOINT_TYPE';
                    v_item_result.error_message := 'is_route_endpoint=true solo es válido cuando '
                                                       || 'checkpoint_type=terminal. '
                                                       || 'Tipo recibido: ' || v_cp.checkpoint_type
                                                       || ' en "' || COALESCE(v_cp.name, '') || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: name obligatorio ─────────────────────────────────────
                IF v_cp.name IS NULL OR TRIM(v_cp.name) = '' THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'MISSING_CHECKPOINT_NAME';
                    v_item_result.error_message := 'name es obligatorio en sequence='
                                                       || COALESCE(v_cp.sequence_number::TEXT, 'NULL')
                                                       || ' direction=' || v_direction
                                                       || ' type=' || v_cp.checkpoint_type;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: sequence_number obligatorio y positivo ───────────────
                IF v_cp.sequence_number IS NULL OR v_cp.sequence_number <= 0 THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_SEQUENCE_NUMBER';
                    v_item_result.error_message := 'sequence_number debe ser mayor a 0 '
                                                       || 'en "' || v_cp.name
                                                       || '" direction=' || v_direction;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: sequence_number no duplicado en el batch ─────────────
                IF v_cp.sequence_number = ANY(v_processed_seqs) THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_SEQUENCE_NUMBER';
                    v_item_result.error_message := 'sequence_number=' || v_cp.sequence_number
                                                       || ' (direction=' || v_direction
                        || ') aparece más de una vez en el mismo lote';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: checkpoint_id no duplicado en el batch ───────────────
                IF v_cp.checkpoint_id IS NOT NULL
                    AND v_cp.checkpoint_id = ANY(v_processed_cp_ids)
                THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_CHECKPOINT_ID_IN_BATCH';
                    v_item_result.error_message := 'checkpoint_id=' || v_cp.checkpoint_id
                        || ' aparece más de una vez en el mismo lote';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Resolución: buscar checkpoint existente ───────────────────
                --    Prioridad: checkpoint_id explícito > (route_id, direction, sequence_number)
                v_existing_cp := NULL;

                IF v_cp.checkpoint_id IS NOT NULL THEN
SELECT * INTO v_existing_cp
FROM core_operations.checkpoint
WHERE checkpoint_id = v_cp.checkpoint_id;

IF NOT FOUND THEN
                        v_item_result.status        := 'ERROR';
                        v_item_result.error_code    := 'CHECKPOINT_NOT_FOUND';
                        v_item_result.error_message := 'checkpoint_id=' || v_cp.checkpoint_id
                            || ' no existe';
                        v_item_results := v_item_results || v_item_result;
                        v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                    IF v_existing_cp.route_id <> p_input.route_id THEN
                        v_item_result.status        := 'ERROR';
                        v_item_result.error_code    := 'CHECKPOINT_NOT_IN_ROUTE';
                        v_item_result.error_message := 'checkpoint_id=' || v_cp.checkpoint_id
                                                           || ' pertenece a route_id='
                                                           || v_existing_cp.route_id
                            || ', no a la ruta solicitada';
                        v_item_results := v_item_results || v_item_result;
                        v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                    -- ── Val: checkpoint_id pertenece a la dirección solicitada ─
                    --    Defensivo: evita que la UI envíe por error un checkpoint
                    --    de IDA dentro de una llamada para VUELTA.
                    IF v_existing_cp.direction <> v_direction THEN
                        v_item_result.status        := 'ERROR';
                        v_item_result.error_code    := 'CHECKPOINT_DIRECTION_MISMATCH';
                        v_item_result.error_message := 'checkpoint_id=' || v_cp.checkpoint_id
                                                           || ' pertenece a direction='
                                                           || v_existing_cp.direction
                                                           || ', no a la dirección solicitada ('
                                                           || v_direction || ')';
                        v_item_results := v_item_results || v_item_result;
                        v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

ELSE
SELECT * INTO v_existing_cp
FROM core_operations.checkpoint
WHERE route_id        = p_input.route_id
  AND direction       = v_direction
  AND sequence_number = v_cp.sequence_number;
-- Si NOT FOUND → INSERT
END IF;

                -- ── Val: coordenadas obligatorias y en rango ──────────────────
                IF v_cp.latitude IS NULL OR v_cp.longitude IS NULL THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_COORDINATES';
                    v_item_result.error_message := 'latitude y longitude son obligatorios '
                                                       || 'en "' || v_cp.name || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF v_cp.latitude < -90 OR v_cp.latitude > 90 THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_COORDINATES';
                    v_item_result.error_message := 'Latitud fuera de rango en "'
                                                       || v_cp.name || '": ' || v_cp.latitude::TEXT;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF v_cp.longitude < -180 OR v_cp.longitude > 180 THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_COORDINATES';
                    v_item_result.error_message := 'Longitud fuera de rango en "'
                                                       || v_cp.name || '": ' || v_cp.longitude::TEXT;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: geofence obligatorio para checkpoint y terminal ───────
                v_geofence := COALESCE(v_cp.geofence_radius_meters, 50);

                IF v_geofence <= 0 THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_GEOFENCE_RADIUS';
                    v_item_result.error_message := 'geofence_radius_meters debe ser mayor a 0 '
                                                       || 'en "' || v_cp.name || '": '
                        || v_geofence::TEXT;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF v_cp_type IN ('checkpoint', 'terminal')
                    AND v_cp.geofence_radius_meters IS NULL
                THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'MISSING_GEOFENCE_RADIUS';
                    v_item_result.error_message := 'geofence_radius_meters es obligatorio '
                                                       || 'para checkpoint_type=' || v_cp.checkpoint_type
                                                       || ' en "' || v_cp.name || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: distancia negativa ───────────────────────────────────
                IF v_cp.distance_from_origin_km IS NOT NULL
                    AND v_cp.distance_from_origin_km < 0
                THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_DISTANCE';
                    v_item_result.error_message := 'distance_from_origin_km no puede ser negativa '
                                                       || 'en "' || v_cp.name || '": '
                        || v_cp.distance_from_origin_km::TEXT;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: duración > 0 si se proveyó ──────────────────────────
                IF v_cp.estimated_duration_minutes IS NOT NULL
                    AND v_cp.estimated_duration_minutes <= 0
                THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_DURATION';
                    v_item_result.error_message := 'estimated_duration_minutes debe ser mayor a 0 '
                                                       || 'en "' || v_cp.name || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: distancia creciente dentro de la misma dirección ──────
                IF v_cp.distance_from_origin_km IS NOT NULL THEN

SELECT sequence_number, distance_from_origin_km
INTO v_prev_sequence, v_prev_distance
FROM core_operations.checkpoint
WHERE route_id        = p_input.route_id
  AND direction       = v_direction
  AND sequence_number < v_cp.sequence_number
  AND (v_existing_cp IS NULL
    OR checkpoint_id <> v_existing_cp.checkpoint_id)
  AND distance_from_origin_km IS NOT NULL
ORDER BY sequence_number DESC
    LIMIT 1;

v_found_in_batch  := FALSE;
                    v_batch_prev_dist := NULL;
                    v_batch_prev_seq  := NULL;

                    IF array_length(v_upserted_seqs, 1) IS NOT NULL THEN
                        FOR v_i IN 1..array_length(v_upserted_seqs, 1)
                            LOOP
                                IF v_upserted_seqs[v_i] < v_cp.sequence_number THEN
                                    IF v_batch_prev_seq IS NULL
                                        OR v_upserted_seqs[v_i] > v_batch_prev_seq
                                    THEN
                                        v_batch_prev_seq  := v_upserted_seqs[v_i];
                                        v_batch_prev_dist := v_upserted_dists[v_i];
                                        v_found_in_batch  := TRUE;
END IF;
END IF;
END LOOP;
END IF;

                    IF v_found_in_batch AND v_batch_prev_dist IS NOT NULL THEN
                        IF v_batch_prev_seq > COALESCE(v_prev_sequence, -1) THEN
                            v_prev_distance := v_batch_prev_dist;
                            v_prev_sequence := v_batch_prev_seq;
END IF;
END IF;

                    IF v_prev_distance IS NOT NULL
                        AND v_cp.distance_from_origin_km <= v_prev_distance
                    THEN
                        v_item_result.status        := 'ERROR';
                        v_item_result.error_code    := 'DISTANCE_NOT_INCREASING';
                        v_item_result.error_message := 'distance_from_origin_km ('
                                                           || v_cp.distance_from_origin_km::TEXT
                                                           || ' km) debe ser mayor que el checkpoint anterior '
                                                           || '(seq=' || v_prev_sequence::TEXT
                                                           || ', dist=' || v_prev_distance::TEXT
                                                           || ' km, direction=' || v_direction
                                                           || ') en "' || v_cp.name || '"';
                        v_item_results := v_item_results || v_item_result;
                        v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

END IF;

                -- ════════════════════════════════════════════════════════
                -- UPSERT
                -- ════════════════════════════════════════════════════════
                IF v_existing_cp IS NOT NULL THEN

                    v_has_changes :=
                            TRIM(v_existing_cp.name)                    IS DISTINCT FROM TRIM(v_cp.name)                 OR
                            v_existing_cp.checkpoint_type                IS DISTINCT FROM v_cp_type                       OR
                            v_existing_cp.is_route_endpoint              IS DISTINCT FROM v_is_endpoint                   OR
                            v_existing_cp.latitude                       IS DISTINCT FROM v_cp.latitude                   OR
                            v_existing_cp.longitude                      IS DISTINCT FROM v_cp.longitude                  OR
                            v_existing_cp.sequence_number                IS DISTINCT FROM v_cp.sequence_number            OR
                            v_existing_cp.distance_from_origin_km        IS DISTINCT FROM v_cp.distance_from_origin_km    OR
                            v_existing_cp.estimated_duration_minutes     IS DISTINCT FROM v_cp.estimated_duration_minutes OR
                            v_existing_cp.geofence_radius_meters         IS DISTINCT FROM v_geofence                      OR
                            NULLIF(UPPER(TRIM(COALESCE(v_existing_cp.checkpoint_code, ''))), '')
                                IS DISTINCT FROM
                                NULLIF(UPPER(TRIM(COALESCE(v_cp.checkpoint_code, ''))), '');

                    IF v_has_changes THEN

                        -- Colisión de (direction, sequence_number) con otro registro
                        IF v_existing_cp.sequence_number <> v_cp.sequence_number THEN
                            IF EXISTS (
                                SELECT 1 FROM core_operations.checkpoint
                                WHERE route_id        = p_input.route_id
                                  AND direction       = v_direction
                                  AND sequence_number = v_cp.sequence_number
                                  AND checkpoint_id  <> v_existing_cp.checkpoint_id
                            ) THEN
                                v_item_result.status        := 'ERROR';
                                v_item_result.error_code    := 'DUPLICATE_SEQUENCE_NUMBER';
                                v_item_result.error_message := '(direction=' || v_direction
                                                                   || ', sequence_number='
                                                                   || v_cp.sequence_number
                                                                   || ') ya está en uso por otro checkpoint '
                                                                   || 'en la ruta "' || v_route_code || '"';
                                v_item_results := v_item_results || v_item_result;
                                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

                        -- checkpoint_code no colisiona con otro registro
                        IF v_cp.checkpoint_code IS NOT NULL
                            AND TRIM(v_cp.checkpoint_code) <> ''
                        THEN
                            IF EXISTS (
                                SELECT 1 FROM core_operations.checkpoint
                                WHERE route_id        = p_input.route_id
                                  AND checkpoint_code = UPPER(TRIM(v_cp.checkpoint_code))
                                  AND checkpoint_id  <> v_existing_cp.checkpoint_id
                            ) THEN
                                v_item_result.status        := 'ERROR';
                                v_item_result.error_code    := 'DUPLICATE_CHECKPOINT_CODE';
                                v_item_result.error_message := 'checkpoint_code "' || v_cp.checkpoint_code
                                                                   || '" ya existe en otro checkpoint '
                                                                   || 'de la ruta "' || v_route_code || '"';
                                v_item_results := v_item_results || v_item_result;
                                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

UPDATE core_operations.checkpoint
SET checkpoint_code             = NULLIF(UPPER(TRIM(COALESCE(v_cp.checkpoint_code, ''))), ''),
    name                        = TRIM(v_cp.name),
    checkpoint_type             = v_cp_type,
    is_route_endpoint           = v_is_endpoint,
    sequence_number             = v_cp.sequence_number,
    latitude                    = v_cp.latitude,
    longitude                   = v_cp.longitude,
    distance_from_origin_km     = v_cp.distance_from_origin_km,
    estimated_duration_minutes  = v_cp.estimated_duration_minutes,
    geofence_radius_meters      = v_geofence
WHERE checkpoint_id = v_existing_cp.checkpoint_id;

v_item_result.status        := 'UPDATED';
                        v_item_result.checkpoint_id := v_existing_cp.checkpoint_id;
                        v_total_updated             := v_total_updated + 1;

ELSE
                        v_item_result.status        := 'SKIPPED';
                        v_item_result.checkpoint_id := v_existing_cp.checkpoint_id;
                        v_total_skipped             := v_total_skipped + 1;
END IF;

                    v_submitted_cp_ids := v_submitted_cp_ids || v_existing_cp.checkpoint_id;
                    v_processed_cp_ids := v_processed_cp_ids || v_existing_cp.checkpoint_id;

ELSE
                    -- ── INSERT nuevo checkpoint ───────────────────────────────

                    IF v_cp.checkpoint_code IS NOT NULL
                        AND TRIM(v_cp.checkpoint_code) <> ''
                    THEN
                        IF EXISTS (
                            SELECT 1 FROM core_operations.checkpoint
                            WHERE route_id        = p_input.route_id
                              AND checkpoint_code = UPPER(TRIM(v_cp.checkpoint_code))
                        ) THEN
                            v_item_result.status        := 'ERROR';
                            v_item_result.error_code    := 'DUPLICATE_CHECKPOINT_CODE';
                            v_item_result.error_message := 'checkpoint_code "' || v_cp.checkpoint_code
                                                               || '" ya existe en la ruta "' || v_route_code || '"';
                            v_item_results := v_item_results || v_item_result;
                            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

                    IF EXISTS (
                        SELECT 1 FROM core_operations.checkpoint
                        WHERE route_id        = p_input.route_id
                          AND direction       = v_direction
                          AND sequence_number = v_cp.sequence_number
                    ) THEN
                        v_item_result.status        := 'ERROR';
                        v_item_result.error_code    := 'DUPLICATE_SEQUENCE_NUMBER';
                        v_item_result.error_message := '(direction=' || v_direction
                                                           || ', sequence_number=' || v_cp.sequence_number
                                                           || ') ya existe en la ruta "' || v_route_code || '"';
                        v_item_results := v_item_results || v_item_result;
                        v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

INSERT INTO core_operations.checkpoint (
    route_id,
    checkpoint_code,
    name,
    checkpoint_type,
    is_route_endpoint,
    direction,
    sequence_number,
    latitude,
    longitude,
    distance_from_origin_km,
    estimated_duration_minutes,
    geofence_radius_meters,
    is_active
)
VALUES (
           p_input.route_id,
           NULLIF(UPPER(TRIM(COALESCE(v_cp.checkpoint_code, ''))), ''),
           TRIM(v_cp.name),
           v_cp_type,
           v_is_endpoint,
           v_direction,
           v_cp.sequence_number,
           v_cp.latitude,
           v_cp.longitude,
           v_cp.distance_from_origin_km,
           v_cp.estimated_duration_minutes,
           v_geofence,
           TRUE
       )
    RETURNING checkpoint_id INTO v_new_cp_id;

v_item_result.status        := 'INSERTED';
                    v_item_result.checkpoint_id := v_new_cp_id;
                    v_total_inserted            := v_total_inserted + 1;

                    v_submitted_cp_ids := v_submitted_cp_ids || v_new_cp_id;
                    v_processed_cp_ids := v_processed_cp_ids || v_new_cp_id;

END IF;

                -- Acumuladores comunes a INSERT y UPDATE/SKIPPED
                v_upserted_seqs  := v_upserted_seqs  || v_cp.sequence_number;
                v_upserted_dists := v_upserted_dists || COALESCE(v_cp.distance_from_origin_km, -1);
                v_processed_seqs := v_processed_seqs || v_cp.sequence_number;

                v_item_results := v_item_results || v_item_result;

END LOOP;

END IF; -- fin FASE 1


    -- ════════════════════════════════════════════════════════
    -- FASE 2: Eliminar checkpoints ausentes del payload
    --         ACOTADO a (route_id, direction) — ya no toca la otra dirección
    -- ════════════════════════════════════════════════════════
FOR v_del_cp_id, v_del_name, v_del_code, v_del_sequence, v_del_cp_type IN
SELECT checkpoint_id, name, checkpoint_code,
       sequence_number, checkpoint_type::TEXT
FROM core_operations.checkpoint
WHERE route_id      = p_input.route_id
  AND direction     = v_direction
  AND checkpoint_id <> ALL(v_submitted_cp_ids)
ORDER BY sequence_number
    LOOP
SELECT EXISTS (
    SELECT 1 FROM core_operations.route_control
    WHERE checkpoint_id = v_del_cp_id
) INTO v_del_control_exists;

SELECT COUNT(*)
INTO v_del_trip_count
FROM core_operations.trip_stop
WHERE checkpoint_id = v_del_cp_id;

DELETE FROM core_operations.checkpoint
WHERE checkpoint_id = v_del_cp_id;

IF v_del_control_exists THEN
                v_total_controls_deleted := v_total_controls_deleted + 1;
END IF;
            v_total_trip_stops_deleted := v_total_trip_stops_deleted + v_del_trip_count;
            v_total_deleted            := v_total_deleted + 1;

            v_item_result.sequence_number    := v_del_sequence;
            v_item_result.direction          := v_direction;
            v_item_result.checkpoint_code    := v_del_code;
            v_item_result.name               := v_del_name;
            v_item_result.checkpoint_type    := v_del_cp_type;
            v_item_result.checkpoint_id      := v_del_cp_id;
            v_item_result.status             := 'DELETED';
            v_item_result.error_code         := NULL;
            v_item_result.error_message      := NULL;
            v_item_result.control_deleted    := v_del_control_exists;
            v_item_result.trip_stops_deleted := v_del_trip_count;
            v_item_results := v_item_results || v_item_result;

END LOOP;


    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success                  := TRUE;
    v_result.route_id                 := p_input.route_id;
    v_result.route_code               := v_route_code;
    v_result.direction                := v_direction;
    v_result.total_submitted          := COALESCE(array_length(p_input.checkpoints, 1), 0);
    v_result.total_inserted           := v_total_inserted;
    v_result.total_updated            := v_total_updated;
    v_result.total_deleted            := v_total_deleted;
    v_result.total_skipped            := v_total_skipped;
    v_result.total_errors             := v_total_errors;
    v_result.total_controls_deleted   := v_total_controls_deleted;
    v_result.total_trip_stops_deleted := v_total_trip_stops_deleted;
    v_result.detail                   := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: sync_permission_templates(api.sync_permission_templates_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_permission_templates(p_input api.sync_permission_templates_input) RETURNS api.sync_permission_templates_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.sync_permission_templates_result;
    v_tpl                   api.permission_template_item;
    v_tpl_result            api.permission_template_item_result;
    v_tpl_results           api.permission_template_item_result[]
                                := ARRAY[]::api.permission_template_item_result[];
    v_total_inserted        INT := 0;
    v_total_updated         INT := 0;
    v_total_skipped         INT := 0;
    v_total_errors          INT := 0;
    -- Trabajo — template header
    v_template_id           INT;
    v_is_active             BOOLEAN;
    v_role_type             VARCHAR(50);
    v_existing              identity.permission_template%ROWTYPE;
    v_has_changes           BOOLEAN;
    v_new_id                INT;
    -- Trabajo — detail
    v_perm_id               INT;
    v_perm_code             VARCHAR(100);
    v_detail_results        api.permission_template_detail_result[]
                                := ARRAY[]::api.permission_template_detail_result[];
    v_detail_item           api.permission_template_detail_result;
    v_perms_inserted        INT;
    v_perms_deleted         INT;
    v_perms_kept            INT;
    -- Dedup en batch
    v_processed_ids         INT[]        := ARRAY[]::INT[];
    v_processed_names       VARCHAR(100)[]  := ARRAY[]::VARCHAR[];

    v_valid_role_types      TEXT[] := ARRAY[
        'ADMIN','SUPERVISOR','DISPATCHER','CASHIER',
        'FLEET_MANAGER','HR_MANAGER','OPERATOR','AUDITOR'
    ];
BEGIN

    -- ── Validación global: array no puede ser NULL ────────────────────────
    IF p_input.templates IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_TEMPLATES_ARRAY';
        v_result.error_message := 'El array de plantillas es NULL';
RETURN v_result;
END IF;

    IF array_length(p_input.templates, 1) IS NULL THEN
        v_result.success         := TRUE;
        v_result.total_submitted := 0;
        v_result.total_inserted  := 0;
        v_result.total_updated   := 0;
        v_result.total_skipped   := 0;
        v_result.total_errors    := 0;
        v_result.detail          := v_tpl_results;
RETURN v_result;
END IF;


    -- ════════════════════════════════════════════════════════
    -- Loop principal: un ítem = una plantilla completa
    -- ════════════════════════════════════════════════════════
    FOREACH v_tpl IN ARRAY p_input.templates
    LOOP
        v_tpl_result.template_id          := v_tpl.template_id;
        v_tpl_result.name                 := v_tpl.name;
        v_tpl_result.role_type            := v_tpl.role_type;
        v_tpl_result.status               := NULL;
        v_tpl_result.is_active            := NULL;
        v_tpl_result.total_permissions    := 0;
        v_tpl_result.permissions_inserted := 0;
        v_tpl_result.permissions_deleted  := 0;
        v_tpl_result.permissions_kept     := 0;
        v_tpl_result.error_code           := NULL;
        v_tpl_result.error_message        := NULL;
        v_tpl_result.detail               := ARRAY[]::api.permission_template_detail_result[];
        v_detail_results                  := ARRAY[]::api.permission_template_detail_result[];

        -- ── Val: template_id duplicado en batch (UPDATE) ──────────────────
        IF v_tpl.template_id IS NOT NULL
           AND v_tpl.template_id = ANY(v_processed_ids)
        THEN
            v_tpl_result.status        := 'ERROR';
            v_tpl_result.error_code    := 'DUPLICATE_TEMPLATE_ID_IN_BATCH';
            v_tpl_result.error_message := 'template_id=' || v_tpl.template_id
                                          || ' aparece más de una vez en el lote';
            v_tpl_results  := v_tpl_results || v_tpl_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: name obligatorio en INSERT ───────────────────────────────
        IF v_tpl.template_id IS NULL THEN
            IF v_tpl.name IS NULL OR TRIM(v_tpl.name) = '' THEN
                v_tpl_result.status        := 'ERROR';
                v_tpl_result.error_code    := 'MISSING_TEMPLATE_NAME';
                v_tpl_result.error_message := 'name es obligatorio al crear una plantilla';
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- name duplicado en batch
            IF TRIM(v_tpl.name) = ANY(v_processed_names) THEN
                v_tpl_result.status        := 'ERROR';
                v_tpl_result.error_code    := 'DUPLICATE_NAME_IN_BATCH';
                v_tpl_result.error_message := 'name="' || v_tpl.name
                                              || '" aparece más de una vez en el lote';
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- name duplicado en BD
            IF EXISTS (
                SELECT 1 FROM identity.permission_template
                WHERE name = TRIM(v_tpl.name)
            ) THEN
                v_tpl_result.status        := 'ERROR';
                v_tpl_result.error_code    := 'DUPLICATE_TEMPLATE_NAME';
                v_tpl_result.error_message := 'Ya existe una plantilla con name="'
                                              || v_tpl.name || '"';
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

        -- ── Val: role_type si se proveyó ──────────────────────────────────
        IF v_tpl.role_type IS NOT NULL AND TRIM(v_tpl.role_type) <> '' THEN
            v_role_type := UPPER(TRIM(v_tpl.role_type));
            IF v_role_type NOT IN (
                'ADMIN','SUPERVISOR','DISPATCHER','CASHIER',
                'FLEET_MANAGER','HR_MANAGER','OPERATOR','AUDITOR'
            ) THEN
                v_tpl_result.status        := 'ERROR';
                v_tpl_result.error_code    := 'INVALID_ROLE_TYPE';
                v_tpl_result.error_message := 'role_type="' || v_tpl.role_type
                                              || '" inválido. Válidos: '
                                              || ARRAY_TO_STRING(v_valid_role_types, ', ');
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
ELSE
            v_role_type := NULL;
END IF;

        -- ── Val: permission_ids — todos deben existir y estar activos ──────
        IF v_tpl.permission_ids IS NOT NULL
           AND array_length(v_tpl.permission_ids, 1) IS NOT NULL
        THEN
            IF EXISTS (
                SELECT 1 FROM unnest(v_tpl.permission_ids) pid
                LEFT JOIN identity.permission p
                    ON p.permission_id = pid -- AND p.is_active = TRUE
                WHERE p.permission_id IS NULL
            ) THEN
                v_tpl_result.status        := 'ERROR';
                v_tpl_result.error_code    := 'INVALID_PERMISSION_IDS';
                v_tpl_result.error_message := 'permission_ids contiene uno o más ids '
                                              || 'que no existen';
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Duplicados en el array de permisos
            IF (SELECT COUNT(*) FROM unnest(v_tpl.permission_ids))
               > (SELECT COUNT(DISTINCT pid) FROM unnest(v_tpl.permission_ids) pid)
            THEN
                v_tpl_result.status        := 'ERROR';
v_tpl_result.error_code    := 'DUPLICATE_PERMISSION_IDS';
                v_tpl_result.error_message := 'permission_ids contiene valores duplicados';
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

        v_is_active := COALESCE(v_tpl.is_active, TRUE);

        -- ════════════════════════════════════════════════════════
        -- RAMA UPDATE: template_id NOT NULL
        -- ════════════════════════════════════════════════════════
        IF v_tpl.template_id IS NOT NULL THEN

SELECT * INTO v_existing
FROM identity.permission_template
WHERE template_id = v_tpl.template_id;

IF NOT FOUND THEN
                v_tpl_result.status        := 'ERROR';
                v_tpl_result.error_code    := 'TEMPLATE_NOT_FOUND';
                v_tpl_result.error_message := 'template_id=' || v_tpl.template_id
                                              || ' no existe';
                v_tpl_results  := v_tpl_results || v_tpl_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Validar name único si cambia
            IF v_tpl.name IS NOT NULL
               AND TRIM(v_tpl.name) <> v_existing.name
            THEN
                IF EXISTS (
                    SELECT 1 FROM identity.permission_template
                    WHERE name        = TRIM(v_tpl.name)
                      AND template_id <> v_tpl.template_id
                ) THEN
                    v_tpl_result.status        := 'ERROR';
                    v_tpl_result.error_code    := 'DUPLICATE_TEMPLATE_NAME';
                    v_tpl_result.error_message := 'Ya existe otra plantilla con name="'
                                                  || v_tpl.name || '"';
                    v_tpl_results  := v_tpl_results || v_tpl_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

            v_has_changes :=
                (v_tpl.name IS NOT NULL
                    AND TRIM(v_tpl.name) IS DISTINCT FROM v_existing.name)
                OR (v_tpl.description IS NOT NULL
                    AND v_tpl.description IS DISTINCT FROM v_existing.description)
                OR (v_role_type IS NOT NULL
                    AND v_role_type IS DISTINCT FROM v_existing.role_type)
                OR (v_is_active IS DISTINCT FROM v_existing.is_active);

            IF v_has_changes THEN
UPDATE identity.permission_template
SET name        = COALESCE(NULLIF(TRIM(v_tpl.name), ''), name),
    description = COALESCE(v_tpl.description,             description),
    role_type   = COALESCE(v_role_type,                   role_type),
    is_active   = v_is_active
WHERE template_id = v_tpl.template_id;

v_tpl_result.status     := 'UPDATED';
                v_tpl_result.is_active  := v_is_active;
                v_total_updated         := v_total_updated + 1;
ELSE
                v_tpl_result.status     := 'SKIPPED';
                v_tpl_result.is_active  := v_existing.is_active;
                v_total_skipped         := v_total_skipped + 1;
END IF;

            v_template_id := v_tpl.template_id;

        -- ════════════════════════════════════════════════════════
        -- RAMA INSERT: template_id NULL
        -- ════════════════════════════════════════════════════════
ELSE
            INSERT INTO identity.permission_template (
                name, description, role_type, is_active
            )
            VALUES (
                TRIM(v_tpl.name),
                v_tpl.description,
                v_role_type,
                v_is_active
            )
            RETURNING template_id INTO v_new_id;

            v_template_id           := v_new_id;
            v_tpl_result.template_id := v_new_id;
            v_tpl_result.status      := 'INSERTED';
            v_tpl_result.is_active   := v_is_active;
            v_total_inserted         := v_total_inserted + 1;
END IF;

        -- ════════════════════════════════════════════════════════
        -- Sincronizar detail: INSERT nuevos + DELETE ausentes
        -- Solo se ejecuta si permission_ids viene en el payload
        -- (NULL = no tocar el detail; [] = borrar todos)
        -- ════════════════════════════════════════════════════════
        v_perms_inserted := 0;
        v_perms_deleted  := 0;
        v_perms_kept     := 0;

        IF v_tpl.permission_ids IS NOT NULL THEN

            -- INSERT permisos nuevos (no existían en el detail)
            WITH new_perms AS (
                INSERT INTO identity.permission_template_detail (template_id, permission_id)
                SELECT v_template_id, pid
                FROM unnest(v_tpl.permission_ids) AS pid
                WHERE NOT EXISTS (
                    SELECT 1 FROM identity.permission_template_detail
                    WHERE template_id  = v_template_id
                      AND permission_id = pid
                )
                RETURNING permission_id
            )
SELECT array_agg(
               (np.permission_id, p.code, 'INSERTED')::api.permission_template_detail_result
       )
INTO v_detail_results
FROM new_perms np
         JOIN identity.permission p ON p.permission_id = np.permission_id;

GET DIAGNOSTICS v_perms_inserted = ROW_COUNT;
v_detail_results := COALESCE(v_detail_results,
                                         ARRAY[]::api.permission_template_detail_result[]);

            -- DELETE permisos que ya no vienen en el payload
            -- (el detail no tiene is_active, se elimina físicamente)
FOR v_perm_id, v_perm_code IN
SELECT ptd.permission_id, p.code
FROM identity.permission_template_detail ptd
         JOIN identity.permission p ON p.permission_id = ptd.permission_id
WHERE ptd.template_id  = v_template_id
  AND ptd.permission_id <> ALL(
    COALESCE(v_tpl.permission_ids, ARRAY[]::INT[])
    )
ORDER BY p.code
    LOOP
DELETE FROM identity.permission_template_detail
WHERE template_id  = v_template_id
  AND permission_id = v_perm_id;

v_perms_deleted  := v_perms_deleted + 1;
                v_detail_item.permission_id := v_perm_id;
                v_detail_item.code          := v_perm_code;
                v_detail_item.status        := 'DELETED';
                v_detail_results := v_detail_results || v_detail_item;
END LOOP;

            -- KEPT: permisos que ya existían y siguen en el payload
SELECT COUNT(*)::INT
INTO v_perms_kept
FROM identity.permission_template_detail
WHERE template_id   = v_template_id
  AND permission_id  = ANY(v_tpl.permission_ids);

-- Agregar los KEPT al detalle
FOR v_perm_id, v_perm_code IN
SELECT ptd.permission_id, p.code
FROM identity.permission_template_detail ptd
         JOIN identity.permission p ON p.permission_id = ptd.permission_id
WHERE ptd.template_id  = v_template_id
  AND ptd.permission_id = ANY(v_tpl.permission_ids)
  AND NOT EXISTS (
    SELECT 1 FROM unnest(v_detail_results) dr
    WHERE (dr).permission_id = ptd.permission_id
)
ORDER BY p.code
    LOOP
                v_detail_item.permission_id := v_perm_id;
v_detail_item.code          := v_perm_code;
                v_detail_item.status        := 'KEPT';
                v_detail_results := v_detail_results || v_detail_item;
END LOOP;

END IF;

        v_tpl_result.total_permissions    := v_perms_inserted + v_perms_kept;
        v_tpl_result.permissions_inserted := v_perms_inserted;
        v_tpl_result.permissions_deleted  := v_perms_deleted;
        v_tpl_result.permissions_kept     := v_perms_kept;
        v_tpl_result.detail               := v_detail_results;

        v_tpl_results := v_tpl_results || v_tpl_result;

        -- Acumular para dedup
        IF v_tpl.template_id IS NOT NULL THEN
            v_processed_ids := v_processed_ids || v_tpl.template_id;
END IF;
        IF v_tpl.name IS NOT NULL THEN
            v_processed_names := v_processed_names || TRIM(v_tpl.name);
END IF;

END LOOP;


    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success         := TRUE;
    v_result.total_submitted := array_length(p_input.templates, 1);
    v_result.total_inserted  := v_total_inserted;
    v_result.total_updated   := v_total_updated;
    v_result.total_skipped   := v_total_skipped;
    v_result.total_errors    := v_total_errors;
    v_result.detail          := v_tpl_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_tpl_results;
RETURN v_result;
END;
$$;


--
-- Name: sync_permissions(api.sync_permissions_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_permissions(p_input api.sync_permissions_input) RETURNS api.sync_permissions_result
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_result            api.sync_permissions_result;
    v_item              api.permission_item;
    v_item_result       api.permission_item_result;
    v_item_results      api.permission_item_result[]
                            := ARRAY[]::api.permission_item_result[];
    v_total_inserted    INT := 0;
    v_total_updated     INT := 0;
    v_total_deactivated INT := 0;
    v_total_skipped     INT := 0;
    v_total_errors      INT := 0;
    -- Trabajo
    v_code              VARCHAR(100);
    v_module            VARCHAR(50);
    v_is_active         BOOLEAN;
    v_has_changes       BOOLEAN;
    v_existing          identity.permission%ROWTYPE;
    v_new_id            INT;
    -- Dedup en batch
    v_processed_codes   VARCHAR(100)[] := ARRAY[]::VARCHAR[];
    -- Para fase de deactivación
    v_submitted_codes   VARCHAR(100)[] := ARRAY[]::VARCHAR[];
    -- Deactivación
    v_deact_id          INT;
    v_deact_code        VARCHAR(100);
    v_deact_module      VARCHAR(50);

    v_valid_modules     TEXT[] := ARRAY[
        'operations','finance','fleet','hr',
        'admin','reports','system','gps','dispatch'
    ];
BEGIN

    -- ── Validación 1: array no puede ser NULL ─────────────────────────────
    IF p_input.permissions IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_PERMISSIONS_ARRAY';
        v_result.error_message := 'El array de permisos es NULL. '
                                  || 'Para desactivar todos envíe un array vacío []';
RETURN v_result;
END IF;


    -- ════════════════════════════════════════════════════════
    -- FASE 1: Upsert de cada permiso enviado
    -- ════════════════════════════════════════════════════════
    IF array_length(p_input.permissions, 1) IS NOT NULL THEN

        FOREACH v_item IN ARRAY p_input.permissions
        LOOP
            v_item_result.permission_id := NULL;
            v_item_result.code          := v_item.code;
            v_item_result.module        := v_item.module;
            v_item_result.status        := NULL;
            v_item_result.is_active     := NULL;
            v_item_result.error_code    := NULL;
            v_item_result.error_message := NULL;

            -- ── Val: code obligatorio ─────────────────────────────────────
            IF v_item.code IS NULL OR TRIM(v_item.code) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_CODE';
                v_item_result.error_message := 'code es obligatorio en cada ítem';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_code := LOWER(TRIM(v_item.code));

            -- ── Val: formato code = module.resource.action ────────────────
            IF v_code !~ '^[a-z_]+\.[a-z_]+\.[a-z_]+$' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'INVALID_CODE_FORMAT';
                v_item_result.error_message := 'code="' || v_item.code
                                               || '" debe tener formato module.resource.action '
                                               || '(ej: logistics.route.view)';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: code no duplicado en el batch ────────────────────────
            IF v_code = ANY(v_processed_codes) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_CODE_IN_BATCH';
                v_item_result.error_message := 'code="' || v_item.code
                                               || '" aparece más de una vez en el lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Resolver o validar module ─────────────────────────────────
            -- Si no viene module explícito, se infiere del primer segmento del code
            IF v_item.module IS NOT NULL AND TRIM(v_item.module) <> '' THEN
                v_module := LOWER(TRIM(v_item.module));
ELSE
                v_module := SPLIT_PART(v_code, '.', 1);
END IF;

            IF v_module NOT IN (
                'operations','finance','fleet','hr',
                'admin','reports','system','gps','dispatch'
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'INVALID_MODULE';
                v_item_result.error_message := 'module="' || v_module
                                               || '" inválido. Válidos: '
                                               || ARRAY_TO_STRING(v_valid_modules, ', ');
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_item_result.module := v_module;
            v_is_active := COALESCE(v_item.is_active, TRUE);

            -- ── Buscar si el permiso ya existe por code ───────────────────
SELECT * INTO v_existing
FROM identity.permission
WHERE code = v_code;

IF FOUND THEN

                -- Detectar cambios reales
                v_has_changes :=
                    v_existing.is_active IS DISTINCT FROM v_is_active
                    OR (v_item.description IS NOT NULL
                        AND v_item.description IS DISTINCT FROM v_existing.description)
                    OR v_module IS DISTINCT FROM v_existing.module
                    OR (v_item.resource IS NOT NULL
                        AND v_item.resource IS DISTINCT FROM v_existing.resource)
                    OR (v_item.action IS NOT NULL
                        AND v_item.action IS DISTINCT FROM v_existing.action);

                IF v_has_changes THEN
UPDATE identity.permission
SET description = COALESCE(v_item.description, description),
    module      = v_module,
    resource    = COALESCE(v_item.resource,    resource),
    action      = COALESCE(v_item.action,      action),
    is_active   = v_is_active
WHERE permission_id = v_existing.permission_id;

v_item_result.status        := 'UPDATED';
                    v_item_result.permission_id := v_existing.permission_id;
                    v_item_result.is_active     := v_is_active;
                    v_total_updated := v_total_updated + 1;
ELSE
                    v_item_result.status        := 'SKIPPED';
                    v_item_result.permission_id := v_existing.permission_id;
                    v_item_result.is_active     := v_existing.is_active;
                    v_total_skipped := v_total_skipped + 1;
END IF;

ELSE
                -- INSERT
                INSERT INTO identity.permission (
                    code, description, module, resource, action, is_active
                )
                VALUES (
                    v_code,
                    v_item.description,
                    v_module,
                    COALESCE(NULLIF(TRIM(COALESCE(v_item.resource, '')), ''),
                             SPLIT_PART(v_code, '.', 2)),
                    COALESCE(NULLIF(TRIM(COALESCE(v_item.action, '')), ''),
                             SPLIT_PART(v_code, '.', 3)),
                    v_is_active
                )
                RETURNING permission_id INTO v_new_id;

                v_item_result.status        := 'INSERTED';
                v_item_result.permission_id := v_new_id;
                v_item_result.is_active     := v_is_active;
                v_total_inserted := v_total_inserted + 1;
END IF;

            v_item_results    := v_item_results    || v_item_result;
            v_processed_codes := v_processed_codes || v_code;
            v_submitted_codes := v_submitted_codes || v_code;

END LOOP;

END IF; -- fin FASE 1


    -- ════════════════════════════════════════════════════════
    -- FASE 2: Desactivar permisos activos no presentes en el payload
    -- NUNCA se eliminan: solo is_active = FALSE (soft deactivation)
    -- ════════════════════════════════════════════════════════
FOR v_deact_id, v_deact_code, v_deact_module IN
SELECT permission_id, code, module
FROM identity.permission
WHERE is_active = TRUE
  AND code <> ALL(v_submitted_codes)
ORDER BY module, code
    LOOP
UPDATE identity.permission
SET is_active = FALSE
WHERE permission_id = v_deact_id;

v_total_deactivated := v_total_deactivated + 1;

        v_item_result.permission_id := v_deact_id;
        v_item_result.code          := v_deact_code;
        v_item_result.module        := v_deact_module;
        v_item_result.status        := 'DEACTIVATED';
        v_item_result.is_active     := FALSE;
        v_item_result.error_code    := NULL;
        v_item_result.error_message := NULL;
        v_item_results := v_item_results || v_item_result;

END LOOP;


    -- ── Resultado ─────────────────────────────────────────────────────────
    v_result.success            := TRUE;
    v_result.total_submitted    := COALESCE(array_length(p_input.permissions, 1), 0);
    v_result.total_inserted     := v_total_inserted;
    v_result.total_updated      := v_total_updated;
    v_result.total_deactivated  := v_total_deactivated;
    v_result.total_skipped      := v_total_skipped;
    v_result.total_errors       := v_total_errors;
    v_result.detail             := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$_$;


--
-- Name: sync_role_permission_scopes(api.sync_role_permission_scopes_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_role_permission_scopes(p_input api.sync_role_permission_scopes_input) RETURNS api.sync_role_permission_scopes_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.sync_role_permission_scopes_result;
    v_permission_code       VARCHAR(100);
    v_item                  api.scope_item;
    v_item_result           api.scope_item_result;
    v_item_results          api.scope_item_result[]
                                := ARRAY[]::api.scope_item_result[];
    v_total_inserted        INT := 0;
    v_total_updated         INT := 0;
    v_total_deactivated     INT := 0;
    v_total_skipped         INT := 0;
    v_total_errors          INT := 0;
    -- Trabajo
    v_scope_type_code       VARCHAR(50);
    v_is_active             BOOLEAN;
    v_existing_rps_id       BIGINT;
    v_existing_rps_active   BOOLEAN;
    v_new_rps_id            BIGINT;
    -- Llave natural: (role_permission_id, scope_type_id, scope_id, company_id)
    -- scope_id puede ser NULL → se compara con IS NOT DISTINCT FROM
    v_submitted_rps_ids     BIGINT[] := ARRAY[]::BIGINT[];
    -- Dedup en batch: array de composite para detectar duplicados
    v_processed_keys        TEXT[]   := ARRAY[]::TEXT[];
    v_item_key              TEXT;
    -- Deactivación
    v_deact_id              BIGINT;
    v_deact_scope_type_id   SMALLINT;
    v_deact_scope_type_code VARCHAR(50);
    v_deact_scope_id        BIGINT;
    v_deact_company_id      INT;
BEGIN

    -- ── Validación 1: role_permission_id obligatorio ──────────────────────
    IF p_input.role_permission_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ROLE_PERMISSION_ID';
        v_result.error_message := 'role_permission_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: role_permission existe y está activo ────────────────
SELECT p.code
INTO v_permission_code
FROM identity.role_permission rp
         JOIN identity.permission p ON p.permission_id = rp.permission_id
WHERE rp.role_permission_id = p_input.role_permission_id
  AND rp.is_active = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_PERMISSION_NOT_FOUND';
        v_result.error_message := 'role_permission_id=' || p_input.role_permission_id
                                  || ' no existe o está inactivo';
RETURN v_result;
END IF;

    -- ── Validación 3: array no puede ser NULL ─────────────────────────────
    IF p_input.scopes IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_SCOPES_ARRAY';
        v_result.error_message := 'El array de scopes es NULL. '
                                  || 'Para desactivar todos los scopes envíe un array vacío []';
RETURN v_result;
END IF;


    -- ════════════════════════════════════════════════════════
    -- FASE 1: Upsert de cada scope enviado
    -- ════════════════════════════════════════════════════════
    IF array_length(p_input.scopes, 1) IS NOT NULL THEN

        FOREACH v_item IN ARRAY p_input.scopes
        LOOP
            v_item_result.role_permission_scope_id := NULL;
            v_item_result.scope_type_id            := v_item.scope_type_id;
            v_item_result.scope_type_code          := NULL;
            v_item_result.scope_id                 := v_item.scope_id;
            v_item_result.company_id               := v_item.company_id;
            v_item_result.is_active                := NULL;
            v_item_result.status                   := NULL;
            v_item_result.error_code               := NULL;
            v_item_result.error_message            := NULL;

            -- ── Val: scope_type_id obligatorio ────────────────────────────
            IF v_item.scope_type_id IS NULL THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_SCOPE_TYPE_ID';
                v_item_result.error_message := 'scope_type_id es obligatorio en cada ítem';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: company_id obligatorio ───────────────────────────────
            IF v_item.company_id IS NULL THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_COMPANY_ID';
                v_item_result.error_message := 'company_id es obligatorio en cada ítem. '
                                               || 'scope_type_id=' || v_item.scope_type_id;
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: scope_type existe ────────────────────────────────────
SELECT code
INTO v_scope_type_code
FROM identity.scope_type
WHERE scope_type_id = v_item.scope_type_id;

IF NOT FOUND THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'SCOPE_TYPE_NOT_FOUND';
                v_item_result.error_message := 'scope_type_id=' || v_item.scope_type_id
                                               || ' no existe en el catálogo';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_item_result.scope_type_code := v_scope_type_code;

            -- ── Val: company_id existe ────────────────────────────────────
            IF NOT EXISTS (
                SELECT 1 FROM shared.company
                WHERE company_id = v_item.company_id
                  AND is_active   = TRUE
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'COMPANY_NOT_FOUND';
                v_item_result.error_message := 'company_id=' || v_item.company_id
                                               || ' no existe o está inactiva '
                                               || '(scope_type=' || v_scope_type_code || ')';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: duplicado en batch ───────────────────────────────────
            -- Clave natural: scope_type_id + scope_id (NULL seguro) + company_id
            v_item_key := v_item.scope_type_id::TEXT
                          || '|' || COALESCE(v_item.scope_id::TEXT, 'NULL')
                          || '|' || v_item.company_id::TEXT;

            IF v_item_key = ANY(v_processed_keys) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_SCOPE_IN_BATCH';
                v_item_result.error_message := 'La combinación (scope_type='
                                               || v_scope_type_code
                                               || ', scope_id='
                                               || COALESCE(v_item.scope_id::TEXT, 'NULL')
                                               || ', company_id=' || v_item.company_id
                                               || ') aparece más de una vez en el lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_is_active := COALESCE(v_item.is_active, TRUE);

            -- ── Buscar si ya existe el scope (activo o inactivo) ──────────
            -- scope_id puede ser NULL: usar IS NOT DISTINCT FROM
SELECT role_permission_scope_id, is_active
INTO v_existing_rps_id, v_existing_rps_active
FROM identity.role_permission_scope
WHERE role_permission_id = p_input.role_permission_id
  AND scope_type_id      = v_item.scope_type_id
  AND scope_id           IS NOT DISTINCT FROM v_item.scope_id
    AND company_id         = v_item.company_id;

IF FOUND THEN
                -- Existe: actualizar is_active solo si cambia
                IF v_existing_rps_active IS DISTINCT FROM v_is_active THEN
UPDATE identity.role_permission_scope
SET is_active = v_is_active
WHERE role_permission_scope_id = v_existing_rps_id;

v_item_result.status                   := 'UPDATED';
                    v_item_result.role_permission_scope_id := v_existing_rps_id;
                    v_item_result.is_active                := v_is_active;
                    v_total_updated := v_total_updated + 1;
ELSE
                    v_item_result.status                   := 'SKIPPED';
                    v_item_result.role_permission_scope_id := v_existing_rps_id;
                    v_item_result.is_active                := v_existing_rps_active;
                    v_total_skipped := v_total_skipped + 1;
END IF;

                v_submitted_rps_ids := v_submitted_rps_ids || v_existing_rps_id;

ELSE
                -- No existe: INSERT
                INSERT INTO identity.role_permission_scope (
                    role_permission_id,
                    scope_type_id,
                    scope_id,
                    company_id,
                    is_active
                )
                VALUES (
                    p_input.role_permission_id,
                    v_item.scope_type_id,
                    v_item.scope_id,
                    v_item.company_id,
                    v_is_active
                )
                RETURNING role_permission_scope_id INTO v_new_rps_id;

                v_item_result.status                   := 'INSERTED';
                v_item_result.role_permission_scope_id := v_new_rps_id;
                v_item_result.is_active                := v_is_active;
                v_total_inserted  := v_total_inserted + 1;
                v_submitted_rps_ids := v_submitted_rps_ids || v_new_rps_id;
END IF;

            v_item_results   := v_item_results   || v_item_result;
            v_processed_keys := v_processed_keys || v_item_key;

END LOOP;

END IF; -- fin FASE 1


    -- ════════════════════════════════════════════════════════
    -- FASE 2: Desactivar scopes activos no enviados en el payload
    -- ════════════════════════════════════════════════════════
FOR v_deact_id,
        v_deact_scope_type_id,
        v_deact_scope_type_code,
        v_deact_scope_id,
        v_deact_company_id
    IN
SELECT
    rps.role_permission_scope_id,
    rps.scope_type_id,
    st.code,
    rps.scope_id,
    rps.company_id
FROM identity.role_permission_scope rps
         JOIN identity.scope_type st ON st.scope_type_id = rps.scope_type_id
WHERE rps.role_permission_id = p_input.role_permission_id
  AND rps.is_active           = TRUE
  AND rps.role_permission_scope_id <> ALL(v_submitted_rps_ids)
ORDER BY st.code, rps.company_id, rps.scope_id NULLS FIRST
    LOOP
UPDATE identity.role_permission_scope
SET is_active = FALSE
WHERE role_permission_scope_id = v_deact_id;

v_total_deactivated := v_total_deactivated + 1;

        v_item_result.role_permission_scope_id := v_deact_id;
        v_item_result.scope_type_id            := v_deact_scope_type_id;
        v_item_result.scope_type_code          := v_deact_scope_type_code;
        v_item_result.scope_id                 := v_deact_scope_id;
        v_item_result.company_id               := v_deact_company_id;
        v_item_result.is_active                := FALSE;
        v_item_result.status                   := 'DEACTIVATED';
        v_item_result.error_code               := NULL;
        v_item_result.error_message            := NULL;
        v_item_results := v_item_results || v_item_result;

END LOOP;


    -- ── Resultado ─────────────────────────────────────────────────────────
    v_result.success            := TRUE;
    v_result.role_permission_id := p_input.role_permission_id;
    v_result.permission_code    := v_permission_code;
    v_result.total_submitted    := COALESCE(array_length(p_input.scopes, 1), 0);
    v_result.total_inserted     := v_total_inserted;
    v_result.total_updated      := v_total_updated;
    v_result.total_deactivated  := v_total_deactivated;
    v_result.total_skipped      := v_total_skipped;
    v_result.total_errors       := v_total_errors;
    v_result.detail             := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: sync_role_permissions(api.sync_role_permissions_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_role_permissions(p_input api.sync_role_permissions_input) RETURNS api.sync_role_permissions_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.sync_role_permissions_result;
    v_item                  api.role_permission_item;
    v_item_result           api.role_permission_item_result;
    v_item_results          api.role_permission_item_result[]
                                := ARRAY[]::api.role_permission_item_result[];
    v_role                  identity.role%ROWTYPE;
    -- Contadores
    v_total_inserted        INT := 0;
    v_total_updated         INT := 0;
    v_total_deactivated     INT := 0;
    v_total_skipped         INT := 0;
    v_total_errors          INT := 0;
    -- Trabajo — upsert
    v_permission_code       VARCHAR(100);
    v_permission_active     BOOLEAN;
    v_existing_rp_id        BIGINT;
    v_existing_rp_active    BOOLEAN;
    v_new_rp_id             BIGINT;
    v_is_active             BOOLEAN;
    -- IDs procesados exitosamente (para fase de deactivación)
    v_submitted_rp_ids      BIGINT[] := ARRAY[]::BIGINT[];
    -- Detección de duplicados en batch
    v_processed_perm_ids    INT[]    := ARRAY[]::INT[];
    -- Deactivación
    v_deact_rp_id           BIGINT;
    v_deact_perm_id         INT;
    v_deact_perm_code       VARCHAR(100);
BEGIN

    -- ── Validación 1: role_id obligatorio ─────────────────────────────────
    IF p_input.role_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ROLE_ID';
        v_result.error_message := 'role_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: rol existe y está activo ────────────────────────────
SELECT * INTO v_role
FROM identity.role
WHERE role_id = p_input.role_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_NOT_FOUND';
        v_result.error_message := 'role_id=' || p_input.role_id || ' no existe';
RETURN v_result;
END IF;

    IF v_role.is_active = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROLE_INACTIVE';
        v_result.error_message := 'El rol "' || v_role.name || '" está inactivo';
RETURN v_result;
END IF;

    -- ── Validación 3: array no puede ser NULL ─────────────────────────────
    IF p_input.permissions IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_PERMISSIONS_ARRAY';
        v_result.error_message := 'El array de permisos es NULL. '
                                  || 'Para desactivar todos los permisos envíe un array vacío []';
RETURN v_result;
END IF;


    -- ════════════════════════════════════════════════════════
    -- FASE 1: Upsert de cada permiso enviado
    -- ════════════════════════════════════════════════════════
    IF array_length(p_input.permissions, 1) IS NOT NULL THEN

        FOREACH v_item IN ARRAY p_input.permissions
        LOOP
            v_item_result.permission_id      := v_item.permission_id;
            v_item_result.permission_code    := NULL;
            v_item_result.role_permission_id := NULL;
            v_item_result.status             := NULL;
            v_item_result.is_active          := NULL;
            v_item_result.error_code         := NULL;
            v_item_result.error_message      := NULL;

            -- ── Val: permission_id obligatorio ────────────────────────────
            IF v_item.permission_id IS NULL THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_PERMISSION_ID';
                v_item_result.error_message := 'permission_id es obligatorio en cada ítem';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: permission_id no duplicado en el batch ───────────────
            IF v_item.permission_id = ANY(v_processed_perm_ids) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_PERMISSION_IN_BATCH';
                v_item_result.error_message := 'permission_id=' || v_item.permission_id
                                               || ' aparece más de una vez en el mismo lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── Val: permiso existe en el catálogo ────────────────────────
SELECT code, is_active
INTO v_permission_code, v_permission_active
FROM identity.permission
WHERE permission_id = v_item.permission_id;

IF NOT FOUND THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'PERMISSION_NOT_FOUND';
                v_item_result.error_message := 'permission_id=' || v_item.permission_id
                                               || ' no existe en el catálogo';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_item_result.permission_code := v_permission_code;

            -- ── Val: permiso activo en el catálogo ────────────────────────
            IF v_permission_active = FALSE THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'PERMISSION_INACTIVE';
                v_item_result.error_message := 'El permiso "' || v_permission_code
                                               || '" está inactivo en el catálogo '
                                               || 'y no puede asignarse a un rol';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_is_active := COALESCE(v_item.is_active, TRUE);

            -- ── Buscar si ya existe el vínculo (activo o inactivo) ────────
SELECT role_permission_id, is_active
INTO v_existing_rp_id, v_existing_rp_active
FROM identity.role_permission
WHERE role_id       = p_input.role_id
  AND permission_id = v_item.permission_id;

IF FOUND THEN
                -- Existe: actualizar is_active solo si cambia
                IF v_existing_rp_active IS DISTINCT FROM v_is_active THEN
UPDATE identity.role_permission
SET is_active = v_is_active
WHERE role_permission_id = v_existing_rp_id;

v_item_result.status             := 'UPDATED';
                    v_item_result.role_permission_id := v_existing_rp_id;
                    v_item_result.is_active          := v_is_active;
                    v_total_updated := v_total_updated + 1;
ELSE
                    v_item_result.status             := 'SKIPPED';
                    v_item_result.role_permission_id := v_existing_rp_id;
                    v_item_result.is_active          := v_existing_rp_active;
                    v_total_skipped := v_total_skipped + 1;
END IF;

                v_submitted_rp_ids := v_submitted_rp_ids || v_existing_rp_id;

ELSE
                -- No existe: INSERT
                INSERT INTO identity.role_permission (
                    role_id, permission_id, is_active, created_at
                )
                VALUES (
                    p_input.role_id, v_item.permission_id, v_is_active, NOW()
                )
                RETURNING role_permission_id INTO v_new_rp_id;

                v_item_result.status             := 'INSERTED';
                v_item_result.role_permission_id := v_new_rp_id;
                v_item_result.is_active          := v_is_active;
                v_total_inserted  := v_total_inserted + 1;
                v_submitted_rp_ids := v_submitted_rp_ids || v_new_rp_id;
END IF;

            v_item_results       := v_item_results || v_item_result;
            v_processed_perm_ids := v_processed_perm_ids || v_item.permission_id;

END LOOP;

END IF; -- fin FASE 1


    -- ════════════════════════════════════════════════════════
    -- FASE 2: Desactivar permisos activos no enviados en el payload
    -- Solo afecta los que están is_active=TRUE y no fueron procesados.
    -- No se eliminan registros — se desactivan (soft delete).
    -- ════════════════════════════════════════════════════════
FOR v_deact_rp_id, v_deact_perm_id, v_deact_perm_code IN
SELECT rp.role_permission_id,
       rp.permission_id,
       p.code
FROM identity.role_permission rp
         JOIN identity.permission p ON p.permission_id = rp.permission_id
WHERE rp.role_id   = p_input.role_id
  AND rp.is_active  = TRUE
  AND rp.role_permission_id <> ALL(v_submitted_rp_ids)
ORDER BY p.code
    LOOP
UPDATE identity.role_permission
SET is_active = FALSE
WHERE role_permission_id = v_deact_rp_id;

v_total_deactivated := v_total_deactivated + 1;

        v_item_result.permission_id      := v_deact_perm_id;
        v_item_result.permission_code    := v_deact_perm_code;
        v_item_result.role_permission_id := v_deact_rp_id;
        v_item_result.status             := 'DEACTIVATED';
        v_item_result.is_active          := FALSE;
        v_item_result.error_code         := NULL;
        v_item_result.error_message      := NULL;
        v_item_results := v_item_results || v_item_result;

END LOOP;


    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success            := TRUE;
    v_result.role_id            := p_input.role_id;
    v_result.role_name          := v_role.name;
    v_result.total_submitted    := COALESCE(array_length(p_input.permissions, 1), 0);
    v_result.total_inserted     := v_total_inserted;
    v_result.total_updated      := v_total_updated;
    v_result.total_deactivated  := v_total_deactivated;
    v_result.total_skipped      := v_total_skipped;
    v_result.total_errors       := v_total_errors;
    v_result.detail             := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: sync_route_control_points(api.sync_route_control_points_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.sync_route_control_points(p_input api.sync_route_control_points_input) RETURNS api.sync_route_control_points_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                    api.sync_route_control_points_result;
    v_route_code                VARCHAR(20);
    v_point                     api.route_control_point_item;
    v_item_result               api.sync_control_point_item_result;
    v_item_results              api.sync_control_point_item_result[]
                                      := ARRAY[]::api.sync_control_point_item_result[];
    -- Contadores
    v_total_inserted            INT := 0;
    v_total_updated             INT := 0;
    v_total_deleted             INT := 0;
    v_total_skipped             INT := 0;
    v_total_errors              INT := 0;
    -- Trabajo
    v_control_id                INT;
    v_tolerance                 INT;
    v_is_mandatory              BOOLEAN;
    v_checkpoint                core_operations.checkpoint%ROWTYPE;
    v_existing_ctrl             core_operations.route_control%ROWTYPE;
    v_submitted_checkpoint_ids  INT[] := ARRAY[]::INT[];
    v_processed_checkpoint_ids  INT[] := ARRAY[]::INT[];
    v_has_changes               BOOLEAN;
    -- DELETE
    v_del_checkpoint_id         INT;
    v_del_checkpoint_name       VARCHAR(255);
    v_del_checkpoint_type       VARCHAR(20);
    v_del_direction             VARCHAR(10);
    v_del_sequence              INT;
    v_del_control_id            INT;
BEGIN

    -- ── Validación 1: ruta existe y está activa ───────────────────────────
SELECT code INTO v_route_code
FROM core_operations.route
WHERE route_id = p_input.route_id
  AND is_active = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROUTE_NOT_FOUND';
        v_result.error_message := 'La ruta route_id=' || p_input.route_id
            || ' no existe o está inactiva';
RETURN v_result;
END IF;

    -- ── Validación 2: NULL rechazado; array vacío = borrar todo ───────────
    IF p_input.points IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_POINTS_ARRAY';
        v_result.error_message := 'El array de puntos de control es NULL. '
            || 'Para eliminar todos los controles envíe un array vacío []';
RETURN v_result;
END IF;


    -- ════════════════════════════════════════════════════════
    -- FASE 1: Validar y procesar cada punto enviado
    -- ════════════════════════════════════════════════════════
    IF array_length(p_input.points, 1) IS NOT NULL THEN

        FOREACH v_point IN ARRAY p_input.points
            LOOP
                -- Inicializar resultado del ítem
                v_item_result.checkpoint_id     := v_point.checkpoint_id;
                v_item_result.checkpoint_name   := NULL;
                v_item_result.checkpoint_type   := NULL;
                v_item_result.direction         := NULL;
                v_item_result.sequence_number   := NULL;
                v_item_result.status            := NULL;
                v_item_result.control_id        := NULL;
                v_item_result.error_code        := NULL;
                v_item_result.error_message     := NULL;

                -- ── Val: checkpoint_id obligatorio ────────────────────────────
                IF v_point.checkpoint_id IS NULL THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'MISSING_CHECKPOINT_ID';
                    v_item_result.error_message := 'checkpoint_id es obligatorio en cada punto de control';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: checkpoint_id no duplicado dentro del batch ──────────
                IF v_point.checkpoint_id = ANY(v_processed_checkpoint_ids) THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_IN_BATCH';
                    v_item_result.error_message := 'checkpoint_id=' || v_point.checkpoint_id
                        || ' aparece más de una vez en el mismo lote';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: checkpoint existe ────────────────────────────────────
SELECT * INTO v_checkpoint
FROM core_operations.checkpoint
WHERE checkpoint_id = v_point.checkpoint_id;

IF NOT FOUND THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'CHECKPOINT_NOT_FOUND';
                    v_item_result.error_message := 'checkpoint_id=' || v_point.checkpoint_id
                        || ' no existe';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                v_item_result.checkpoint_name := v_checkpoint.name;
                v_item_result.checkpoint_type := v_checkpoint.checkpoint_type::VARCHAR;
                v_item_result.direction       := v_checkpoint.direction;
                v_item_result.sequence_number := v_checkpoint.sequence_number;

                -- ── Val: checkpoint pertenece a la ruta ───────────────────────
                IF v_checkpoint.route_id <> p_input.route_id THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'CHECKPOINT_NOT_IN_ROUTE';
                    v_item_result.error_message := 'El checkpoint "' || v_checkpoint.name
                                                       || '" pertenece a route_id='
                                                       || v_checkpoint.route_id
                                                       || ', no a la ruta solicitada (route_id='
                                                       || p_input.route_id || ')';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: solo bus_stop y checkpoint admiten control de tiempo ──
                --    Los terminales (type=terminal) son endpoints de ruta,
                --    no puntos de control operativo con ventana de tiempo.
                IF v_checkpoint.checkpoint_type = 'terminal' THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'TERMINAL_NOT_ALLOWED_AS_CONTROL';
                    v_item_result.error_message := 'Los checkpoints de tipo terminal no pueden '
                                                       || 'configurarse como puntos de control de tiempo. '
                                                       || 'Use checkpoint_type=checkpoint para ese propósito '
                                                       || 'en "' || v_checkpoint.name || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: min_time_minutes > 0 ─────────────────────────────────
                IF v_point.min_time_minutes IS NULL OR v_point.min_time_minutes <= 0 THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_MIN_TIME';
                    v_item_result.error_message := 'min_time_minutes debe ser mayor a 0 '
                                                       || 'en "' || v_checkpoint.name || '". '
                                                       || 'Recibido: '
                        || COALESCE(v_point.min_time_minutes::TEXT, 'NULL');
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: max_time_minutes >= min_time_minutes ─────────────────
                IF v_point.max_time_minutes IS NULL
                    OR v_point.max_time_minutes < v_point.min_time_minutes
                THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_TIME_RANGE';
                    v_item_result.error_message := 'max_time_minutes ('
                                                       || COALESCE(v_point.max_time_minutes::TEXT, 'NULL')
                                                       || ') debe ser >= min_time_minutes ('
                                                       || v_point.min_time_minutes::TEXT
                                                       || ') en "' || v_checkpoint.name || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ── Val: tolerance_minutes >= 0 ───────────────────────────────
                v_tolerance    := COALESCE(v_point.tolerance_minutes, 2);
                v_is_mandatory := COALESCE(v_point.is_mandatory, TRUE);

                IF v_tolerance < 0 THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_TOLERANCE';
                    v_item_result.error_message := 'tolerance_minutes no puede ser negativo '
                                                       || 'en "' || v_checkpoint.name || '": '
                        || v_tolerance::TEXT;
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                -- ════════════════════════════════════════════════════════
                -- UPSERT
                -- ════════════════════════════════════════════════════════
SELECT * INTO v_existing_ctrl
FROM core_operations.route_control
WHERE route_id      = p_input.route_id
  AND checkpoint_id = v_point.checkpoint_id;

IF FOUND THEN

                    v_has_changes :=
                            v_existing_ctrl.min_time_minutes  <> v_point.min_time_minutes  OR
                            v_existing_ctrl.max_time_minutes  <> v_point.max_time_minutes  OR
                            v_existing_ctrl.tolerance_minutes <> v_tolerance               OR
                            v_existing_ctrl.is_mandatory      <> v_is_mandatory;

                    IF v_has_changes THEN
UPDATE core_operations.route_control
SET min_time_minutes  = v_point.min_time_minutes,
    max_time_minutes  = v_point.max_time_minutes,
    tolerance_minutes = v_tolerance,
    is_mandatory      = v_is_mandatory
WHERE control_id = v_existing_ctrl.control_id;

v_item_result.status     := 'UPDATED';
                        v_item_result.control_id := v_existing_ctrl.control_id;
                        v_total_updated          := v_total_updated + 1;
ELSE
                        v_item_result.status     := 'SKIPPED';
                        v_item_result.control_id := v_existing_ctrl.control_id;
                        v_total_skipped          := v_total_skipped + 1;
END IF;

ELSE
                    -- ── INSERT ───────────────────────────────────────────────
                    INSERT INTO core_operations.route_control (
                        route_id,
                        checkpoint_id,
                        sequence_number,
                        min_time_minutes,
                        max_time_minutes,
                        tolerance_minutes,
                        is_mandatory
                    )
                    VALUES (
                               p_input.route_id,
                               v_point.checkpoint_id,
                               v_checkpoint.sequence_number,
                               v_point.min_time_minutes,
                               v_point.max_time_minutes,
                               v_tolerance,
                               v_is_mandatory
                           )
                    RETURNING control_id INTO v_control_id;

                    v_item_result.status     := 'INSERTED';
                    v_item_result.control_id := v_control_id;
                    v_total_inserted         := v_total_inserted + 1;
END IF;

                v_item_results             := v_item_results || v_item_result;
                v_processed_checkpoint_ids := v_processed_checkpoint_ids || v_point.checkpoint_id;
                v_submitted_checkpoint_ids := v_submitted_checkpoint_ids || v_point.checkpoint_id;

END LOOP;

END IF; -- fin FASE 1


    -- ════════════════════════════════════════════════════════
    -- FASE 2: Eliminar controles ausentes del payload
    -- ════════════════════════════════════════════════════════
FOR v_del_control_id,
        v_del_checkpoint_id,
        v_del_checkpoint_name,
        v_del_checkpoint_type,
        v_del_direction,
        v_del_sequence
        IN
SELECT rc.control_id,
       cp.checkpoint_id,
       cp.name,
       cp.checkpoint_type::VARCHAR,
    cp.direction,
       cp.sequence_number
FROM core_operations.route_control rc
         JOIN core_operations.checkpoint cp
              ON cp.checkpoint_id = rc.checkpoint_id
WHERE rc.route_id      = p_input.route_id
  AND rc.checkpoint_id <> ALL(v_submitted_checkpoint_ids)
ORDER BY cp.direction, cp.sequence_number
    LOOP
DELETE FROM core_operations.route_control
WHERE control_id = v_del_control_id;

v_total_deleted := v_total_deleted + 1;

            v_item_result.checkpoint_id     := v_del_checkpoint_id;
            v_item_result.checkpoint_name   := v_del_checkpoint_name;
            v_item_result.checkpoint_type   := v_del_checkpoint_type;
            v_item_result.direction         := v_del_direction;
            v_item_result.sequence_number   := v_del_sequence;
            v_item_result.status            := 'DELETED';
            v_item_result.control_id        := v_del_control_id;
            v_item_result.error_code        := NULL;
            v_item_result.error_message     := NULL;
            v_item_results := v_item_results || v_item_result;

END LOOP;


    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success         := TRUE;
    v_result.route_id        := p_input.route_id;
    v_result.route_code      := v_route_code;
    v_result.total_submitted := COALESCE(array_length(p_input.points, 1), 0);
    v_result.total_inserted  := v_total_inserted;
    v_result.total_updated   := v_total_updated;
    v_result.total_deleted   := v_total_deleted;
    v_result.total_skipped   := v_total_skipped;
    v_result.total_errors    := v_total_errors;
    v_result.detail          := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: unassign_vehicle_from_driver(api.unassign_vehicle_from_driver_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.unassign_vehicle_from_driver(p_input api.unassign_vehicle_from_driver_input) RETURNS api.unassign_vehicle_from_driver_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.unassign_vehicle_from_driver_result;
    v_assignment        fleet.vehicle_assignment%ROWTYPE;
    v_vehicle           fleet.vehicle%ROWTYPE;
    v_driver            hr.driver%ROWTYPE;
    v_driver_full_name  VARCHAR(255);
    v_unassigned_at     TIMESTAMPTZ;
BEGIN

    -- ── Validación 1: unassigned_by existe ───────────────────────────────
    IF p_input.unassigned_by IS NULL
       OR NOT EXISTS (
           SELECT 1 FROM identity.user
           WHERE user_id  = p_input.unassigned_by
             AND is_active = TRUE
       )
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'UNASSIGNING_USER_NOT_FOUND';
        v_result.error_message := 'El usuario unassigned_by='
                                  || COALESCE(p_input.unassigned_by::TEXT, 'NULL')
                                  || ' no existe o está inactivo';
RETURN v_result;
END IF;

    -- ── Validación 2: vehículo existe ─────────────────────────────────────
SELECT * INTO v_vehicle
FROM fleet.vehicle
WHERE vehicle_id = p_input.vehicle_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_FOUND';
        v_result.error_message := 'El vehículo vehicle_id=' || p_input.vehicle_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 3: conductor existe ────────────────────────────────────
SELECT * INTO v_driver
FROM hr.driver
WHERE driver_id = p_input.driver_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DRIVER_NOT_FOUND';
        v_result.error_message := 'El conductor driver_id=' || p_input.driver_id
                                  || ' no existe';
RETURN v_result;
END IF;

SELECT full_name INTO v_driver_full_name
FROM hr.person
WHERE person_id = v_driver.person_id;

-- ── Validación 4: existe asignación activa para ese par ───────────────
SELECT * INTO v_assignment
FROM fleet.vehicle_assignment
WHERE vehicle_id  = p_input.vehicle_id
  AND driver_id   = p_input.driver_id
  AND is_active   = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NO_ACTIVE_ASSIGNMENT';
        v_result.error_message := 'No existe asignación activa para el par '
                                  || '(vehicle_id=' || p_input.vehicle_id
                                  || ', driver_id=' || p_input.driver_id || ')';
RETURN v_result;
END IF;

    -- ── Cerrar la asignación ──────────────────────────────────────────────
    v_unassigned_at := NOW();

UPDATE fleet.vehicle_assignment
SET
    unassigned_at  = v_unassigned_at,
    unassigned_by  = p_input.unassigned_by,
    is_active      = FALSE,
    notes          = CASE
                         WHEN p_input.notes IS NOT NULL
                             THEN COALESCE(notes || E'\n', '') || p_input.notes
                         ELSE notes
        END
WHERE assignment_id = v_assignment.assignment_id;

-- ── Limpiar current_vehicle_id del conductor ──────────────────────────
-- El GPS sigue vinculado al vehículo; no se toca gps_device
UPDATE hr.driver
SET
    current_vehicle_id = NULL,
    updated_at         = NOW()
WHERE driver_id = p_input.driver_id;

-- ── Poblar resultado campo a campo ────────────────────────────────────
v_result.success            := TRUE;
    v_result.assignment_id      := v_assignment.assignment_id;
    v_result.vehicle_id         := v_assignment.vehicle_id;
    v_result.driver_id          := v_assignment.driver_id;
    v_result.assignment_type    := v_assignment.assignment_type;
    v_result.assigned_at        := v_assignment.assigned_at;
    v_result.unassigned_at      := v_unassigned_at;
    v_result.unassigned_by      := p_input.unassigned_by;
    v_result.plate_number       := v_vehicle.plate_number;
    v_result.internal_code      := v_vehicle.internal_code;
    v_result.driver_code        := v_driver.driver_code;
    v_result.driver_full_name   := v_driver_full_name;
    v_result.duration_hours     := ROUND(
        EXTRACT(EPOCH FROM (v_unassigned_at - v_assignment.assigned_at)) / 3600.0,
        2
    );

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: update_driver_status(api.update_driver_status_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.update_driver_status(p_input api.update_driver_status_input) RETURNS api.update_driver_status_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.update_driver_status_result;
    v_driver            hr.driver%ROWTYPE;
    v_person            hr.person%ROWTYPE;
    v_new_is_available  BOOLEAN;
    v_new_term_date     DATE;
    v_allow_reactivate  BOOLEAN;
    v_cfg_value         TEXT;
    v_log_id            BIGINT;
    v_changes           JSONB;
BEGIN

    -- ── Validación 1: new_status dentro del dominio ───────────────────────
    IF p_input.new_status IS NULL
       OR p_input.new_status NOT IN ('ACTIVE', 'SUSPENDED', 'TERMINATED')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_EMPLOYMENT_STATUS';
        v_result.error_message := 'new_status inválido: "'
                                  || COALESCE(p_input.new_status, 'NULL')
                                  || '". Válidos: ACTIVE, SUSPENDED, TERMINATED';
RETURN v_result;
END IF;

    -- ── Validación 2: conductor existe ────────────────────────────────────
SELECT * INTO v_driver
FROM hr.driver
WHERE driver_id = p_input.driver_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DRIVER_NOT_FOUND';
        v_result.error_message := 'El conductor driver_id=' || p_input.driver_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- Datos de la persona para el log y el result
SELECT * INTO v_person
FROM hr.person
WHERE person_id = v_driver.person_id;

-- ── Validación 3: no es un no-op ──────────────────────────────────────
IF v_driver.employment_status = p_input.new_status THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_STATUS_TRANSITION';
        v_result.error_message := 'El conductor ya tiene el estado "'
                                  || p_input.new_status || '". No hay cambio que aplicar';
RETURN v_result;
END IF;

    -- ── Validación 4: transición TERMINATED → ACTIVE requiere configuración
    IF v_driver.employment_status = 'TERMINATED'
       AND p_input.new_status = 'ACTIVE'
    THEN
SELECT value INTO v_cfg_value
FROM shared.configuration
WHERE key = 'hr.allow_driver_reactivation';

BEGIN
            v_allow_reactivate := COALESCE(v_cfg_value, 'false')::BOOLEAN;
EXCEPTION
            WHEN OTHERS THEN
                v_allow_reactivate := FALSE;
END;

        IF v_allow_reactivate = FALSE THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_STATUS_TRANSITION';
            v_result.error_message := 'La transición TERMINATED → ACTIVE no está permitida. '
                                      || 'Para habilitar, configure '
                                      || '''hr.allow_driver_reactivation'' = ''true''';
RETURN v_result;
END IF;
END IF;

    -- ── Validación 5: TERMINATED → SUSPENDED también bloqueado ───────────
    IF v_driver.employment_status = 'TERMINATED'
       AND p_input.new_status = 'SUSPENDED'
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_STATUS_TRANSITION';
        v_result.error_message := 'No se puede suspender un conductor ya TERMINATED. '
                                  || 'Reactivar primero a ACTIVE si es necesario';
RETURN v_result;
END IF;

    -- ── Resolver campos derivados según el nuevo estado ───────────────────
CASE p_input.new_status
        WHEN 'TERMINATED' THEN
            v_new_is_available := FALSE;
            v_new_term_date    := COALESCE(
                                      p_input.termination_date,
                                      CURRENT_DATE
                                  );

WHEN 'SUSPENDED' THEN
            v_new_is_available := FALSE;
            v_new_term_date    := v_driver.termination_date; -- conservar si existía

WHEN 'ACTIVE' THEN
            v_new_is_available := TRUE;
            v_new_term_date    := NULL;  -- limpiar termination_date al reactivar
END CASE;

    -- ── Construir JSON before/after para activity_log ─────────────────────
    v_changes := JSONB_BUILD_OBJECT(
        'before', JSONB_BUILD_OBJECT(
            'employment_status',    v_driver.employment_status,
            'is_available',         v_driver.is_available,
            'termination_date',     v_driver.termination_date
        ),
        'after', JSONB_BUILD_OBJECT(
            'employment_status',    p_input.new_status,
            'is_available',         v_new_is_available,
            'termination_date',     v_new_term_date
        ),
        'reason', p_input.reason
    );

    -- ── Actualizar hr.driver ──────────────────────────────────────────────
UPDATE hr.driver
SET
    employment_status   = p_input.new_status,
    is_available        = v_new_is_available,
    termination_date    = v_new_term_date,
    notes               = CASE
                              WHEN p_input.reason IS NOT NULL
                                  THEN COALESCE(notes || E'\n', '')
                                  || TO_CHAR(NOW(), 'YYYY-MM-DD HH24:MI')
                                  || ' [' || p_input.new_status || '] '
                                  || p_input.reason
                              ELSE notes
        END,
    updated_at          = NOW()
WHERE driver_id = p_input.driver_id;

-- ── Registrar en identity.activity_log ───────────────────────────────
INSERT INTO identity.activity_log (
    user_id,
    action,
    resource_type,
    resource_id,
    changes,
    status,
    created_at
)
VALUES (
           p_input.changed_by,
           'DRIVER_STATUS_CHANGE',
           'hr.driver',
           p_input.driver_id,
           v_changes,
           'SUCCESS',
           NOW()
       )
    RETURNING log_id INTO v_log_id;

-- ── Poblar resultado campo a campo ────────────────────────────────────
v_result.success            := TRUE;
    v_result.driver_id          := p_input.driver_id;
    v_result.driver_code        := v_driver.driver_code;
    v_result.full_name          := v_person.full_name;
    v_result.previous_status    := v_driver.employment_status;
    v_result.new_status         := p_input.new_status;
    v_result.employment_type    := v_driver.employment_type;
    v_result.is_available       := v_new_is_available;
    v_result.termination_date   := v_new_term_date;
    v_result.activity_log_id    := v_log_id;
    v_result.changed_by         := p_input.changed_by;
    v_result.updated_at         := NOW();

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: update_gps_device_heartbeat(api.update_gps_device_heartbeat_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.update_gps_device_heartbeat(p_input api.update_gps_device_heartbeat_input) RETURNS api.update_gps_device_heartbeat_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.update_gps_device_heartbeat_result;
    v_device        fleet.gps_device%ROWTYPE;
    v_received_at   TIMESTAMPTZ := COALESCE(p_input.received_at, NOW());
    v_new_status    VARCHAR(20);
    v_status_changed BOOLEAN := FALSE;
BEGIN

    -- ── Inicializar flags ─────────────────────────────────────────────────
    v_result.device_not_registered := FALSE;
    v_result.device_in_maintenance := FALSE;
    v_result.status_restored       := FALSE;

    -- ── Validación: device_id obligatorio ─────────────────────────────────
    IF p_input.device_id IS NULL OR TRIM(p_input.device_id) = '' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_DEVICE_ID';
        v_result.error_message := 'device_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Buscar dispositivo por device_id ──────────────────────────────────
SELECT * INTO v_device
FROM fleet.gps_device
WHERE device_id = TRIM(p_input.device_id);

IF NOT FOUND THEN
        -- DEVICE_NOT_REGISTERED: flag sin excepción, no bloquea el pipeline.
        -- El heartbeat puede llegar de un dispositivo aún no dado de alta.
        v_result.success               := TRUE;
        v_result.device_not_registered := TRUE;
RETURN v_result;
END IF;

    -- ── DEVICE_INACTIVE: en MAINTENANCE no se restaura automáticamente ────
    -- MAINTENANCE es una desactivación deliberada del operador (ej: vehículo
    -- en taller). Que el dispositivo envíe señal no significa que deba volver
    -- a ACTIVE — solo el operador puede sacarlo de MAINTENANCE.
    IF v_device.status = 'MAINTENANCE' THEN
        -- Solo actualizar last_communication_at para registrar que está vivo,
        -- pero NO cambiar status ni is_operational.
UPDATE fleet.gps_device
SET last_communication_at = v_received_at,
    updated_at            = v_received_at
WHERE gps_device_id = v_device.gps_device_id;

v_result.success               := TRUE;
        v_result.device_in_maintenance := TRUE;
        v_result.gps_device_id         := v_device.gps_device_id;
        v_result.device_id             := v_device.device_id;
        v_result.vehicle_id            := v_device.vehicle_id;
        v_result.previous_status       := v_device.status;
        v_result.current_status        := v_device.status;  -- sin cambio
        v_result.is_operational        := v_device.is_operational;
        v_result.last_communication_at := v_received_at;
RETURN v_result;
END IF;

    -- ── Determinar nuevo status ───────────────────────────────────────────
    -- Solo se restaura si estaba en ERROR (pérdida de señal automática).
    -- INACTIVE no se restaura aquí — esa transición la hace el operador.
    IF v_device.status = 'ERROR' THEN
        v_new_status     := 'ACTIVE';
        v_status_changed := TRUE;
ELSE
        v_new_status := v_device.status;   -- ACTIVE o INACTIVE: sin cambio de status
END IF;

    -- ── Actualizar dispositivo ────────────────────────────────────────────
    -- Operación mínima: last_communication_at + status si cambió + updated_at.
    -- Sin activity_log — el volumen (200 eventos/min) lo hace inviable.
UPDATE fleet.gps_device
SET last_communication_at = v_received_at,
    status                = v_new_status,
    is_operational        = CASE v_new_status
                                WHEN 'ACTIVE' THEN TRUE
                                ELSE is_operational   -- preservar si no cambia
        END,
    updated_at            = v_received_at
WHERE gps_device_id = v_device.gps_device_id;

-- ── Si se restauró de ERROR → restaurar vehículo vinculado ───────────
-- Solo si el vehículo estaba bloqueado exclusivamente por el GPS
-- (no verificamos documentos aquí — eso va en update_gps_device_status).
-- La lógica completa de restauración de vehículo con chequeo de documentos
-- pertenece al path administrativo (update_gps_device_status), no al
-- heartbeat de alto volumen.
IF v_status_changed AND v_device.vehicle_id IS NOT NULL THEN
UPDATE fleet.vehicle
SET is_operational = TRUE,
    updated_at     = v_received_at
WHERE vehicle_id      = v_device.vehicle_id
  AND is_operational  = FALSE;
-- Solo restaura si estaba bloqueado. Si ya era TRUE no hace nada.
-- No verifica documentos — esa responsabilidad es de update_gps_device_status.
END IF;

    -- ── Poblar resultado ──────────────────────────────────────────────────
    v_result.success               := TRUE;
    v_result.gps_device_id         := v_device.gps_device_id;
    v_result.device_id             := v_device.device_id;
    v_result.vehicle_id            := v_device.vehicle_id;
    v_result.previous_status       := v_device.status;
    v_result.current_status        := v_new_status;
    v_result.is_operational        := (v_new_status = 'ACTIVE');
    v_result.last_communication_at := v_received_at;
    v_result.status_restored       := v_status_changed;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_companies(api.upsert_companies_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_companies(p_input api.upsert_companies_input) RETURNS api.upsert_companies_result
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_result            api.upsert_companies_result;
    v_company           api.company_item;
    v_item_result       api.company_item_result;
    v_item_results      api.company_item_result[]
                            := ARRAY[]::api.company_item_result[];
    -- Contadores
    v_total_inserted    INT := 0;
    v_total_updated     INT := 0;
    v_total_skipped     INT := 0;
    v_total_errors      INT := 0;
    -- Trabajo
    v_new_id            INT;
    v_existing          shared.company%ROWTYPE;
    v_has_changes       BOOLEAN;
    -- Detección de duplicados dentro del batch
    v_processed_ids     INT[]         := ARRAY[]::INT[];
    v_processed_tax_ids VARCHAR(20)[] := ARRAY[]::VARCHAR[];
BEGIN

    -- ── Validación global: array no nulo ──────────────────────────────────
    IF p_input.companies IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_COMPANIES_ARRAY';
        v_result.error_message := 'El array de compañías es NULL. '
                                  || 'Provea al menos una compañía';
RETURN v_result;
END IF;

    IF array_length(p_input.companies, 1) IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NO_COMPANIES_PROVIDED';
        v_result.error_message := 'El array de compañías está vacío. '
                                  || 'Provea al menos una compañía';
RETURN v_result;
END IF;

    -- ── Iterar sobre cada compañía del lote ───────────────────────────────
    FOREACH v_company IN ARRAY p_input.companies
    LOOP
        -- Inicializar resultado del ítem
        v_item_result.company_id    := v_company.company_id;
        v_item_result.tax_id        := v_company.tax_id;
        v_item_result.legal_name    := v_company.legal_name;
        v_item_result.status        := NULL;
        v_item_result.error_code    := NULL;
        v_item_result.error_message := NULL;

        -- ── Rama UPDATE: viene company_id ─────────────────────────────────
        IF v_company.company_id IS NOT NULL THEN

            -- Val: company_id no duplicado en el batch
            IF v_company.company_id = ANY(v_processed_ids) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_COMPANY_ID_IN_BATCH';
                v_item_result.error_message := 'company_id=' || v_company.company_id
                                               || ' aparece más de una vez en el mismo lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: la compañía existe
SELECT * INTO v_existing
FROM shared.company
WHERE company_id = v_company.company_id;

IF NOT FOUND THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'COMPANY_NOT_FOUND';
                v_item_result.error_message := 'company_id=' || v_company.company_id
                                               || ' no existe';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: si viene nuevo tax_id, validar formato y unicidad
            IF v_company.tax_id IS NOT NULL THEN
                IF v_company.tax_id !~ '^[0-9]{11}$' THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                    v_item_result.error_message := 'tax_id debe tener exactamente 11 dígitos '
                                                   || 'numéricos. Recibido: "' || v_company.tax_id || '"';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF v_company.tax_id <> v_existing.tax_id THEN
                    -- Verificar que el nuevo tax_id no esté en uso por otra compañía
                    IF EXISTS (
                        SELECT 1 FROM shared.company
                        WHERE tax_id    = v_company.tax_id
                          AND company_id <> v_company.company_id
                    ) THEN
                        v_item_result.status        := 'ERROR';
                        v_item_result.error_code    := 'DUPLICATE_TAX_ID';
                        v_item_result.error_message := 'tax_id "' || v_company.tax_id
                                                       || '" ya está registrado en otra compañía';
                        v_item_results := v_item_results || v_item_result;
                        v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;
END IF;

            -- Val: legal_name no vacío si se envía
            IF v_company.legal_name IS NOT NULL
               AND TRIM(v_company.legal_name) = ''
            THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_LEGAL_NAME';
                v_item_result.error_message := 'legal_name no puede ser una cadena vacía '
                                               || 'en company_id=' || v_company.company_id;
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Detectar cambios reales (solo campos que vienen NOT NULL en el payload)
            v_has_changes :=
                (v_company.tax_id       IS NOT NULL AND v_company.tax_id       IS DISTINCT FROM v_existing.tax_id)       OR
                (v_company.legal_name   IS NOT NULL AND TRIM(v_company.legal_name) IS DISTINCT FROM v_existing.legal_name) OR
                (v_company.trade_name   IS NOT NULL AND v_company.trade_name   IS DISTINCT FROM v_existing.trade_name)   OR
                (v_company.address      IS NOT NULL AND v_company.address       IS DISTINCT FROM v_existing.address)      OR
                (v_company.phone        IS NOT NULL AND v_company.phone         IS DISTINCT FROM v_existing.phone)        OR
                (v_company.email        IS NOT NULL AND v_company.email         IS DISTINCT FROM v_existing.email)        OR
                (v_company.logo_url     IS NOT NULL AND v_company.logo_url      IS DISTINCT FROM v_existing.logo_url)     OR
                (v_company.is_active    IS NOT NULL AND v_company.is_active     IS DISTINCT FROM v_existing.is_active);

            IF v_has_changes THEN
                -- PATCH semántico: solo sobreescribe los campos que vienen NOT NULL
UPDATE shared.company
SET tax_id      = COALESCE(v_company.tax_id,                  tax_id),
    legal_name  = COALESCE(NULLIF(TRIM(v_company.legal_name), ''), legal_name),
    trade_name  = COALESCE(v_company.trade_name,               trade_name),
    address     = COALESCE(v_company.address,                  address),
    phone       = COALESCE(v_company.phone,                    phone),
    email       = COALESCE(v_company.email,                    email),
    logo_url    = COALESCE(v_company.logo_url,                 logo_url),
    is_active   = COALESCE(v_company.is_active,                is_active),
    updated_at  = NOW()
WHERE company_id = v_company.company_id;

v_item_result.tax_id     := COALESCE(v_company.tax_id, v_existing.tax_id);
                v_item_result.legal_name := COALESCE(v_company.legal_name, v_existing.legal_name);
                v_item_result.status     := 'UPDATED';
                v_total_updated          := v_total_updated + 1;
ELSE
                v_item_result.tax_id     := v_existing.tax_id;
                v_item_result.legal_name := v_existing.legal_name;
                v_item_result.status     := 'SKIPPED';
                v_total_skipped          := v_total_skipped + 1;
END IF;

            v_processed_ids     := v_processed_ids     || v_company.company_id;
            v_processed_tax_ids := v_processed_tax_ids || COALESCE(v_company.tax_id, v_existing.tax_id);

        -- ── Rama INSERT: company_id es NULL ───────────────────────────────
ELSE

            -- Val: tax_id obligatorio en INSERT
            IF v_company.tax_id IS NULL OR TRIM(v_company.tax_id) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_TAX_ID';
                v_item_result.error_message := 'tax_id es obligatorio al crear una compañía';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: formato RUC 11 dígitos
            IF v_company.tax_id !~ '^[0-9]{11}$' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                v_item_result.error_message := 'tax_id debe tener exactamente 11 dígitos '
                                               || 'numéricos. Recibido: "' || v_company.tax_id || '"';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: tax_id no duplicado en el batch
            IF v_company.tax_id = ANY(v_processed_tax_ids) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_TAX_ID_IN_BATCH';
                v_item_result.error_message := 'tax_id "' || v_company.tax_id
                                               || '" aparece más de una vez en el mismo lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: tax_id no duplicado en BD
            IF EXISTS (
                SELECT 1 FROM shared.company WHERE tax_id = v_company.tax_id
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_TAX_ID';
                v_item_result.error_message := 'tax_id "' || v_company.tax_id
                                               || '" ya está registrado en el sistema';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- Val: legal_name obligatorio en INSERT
            IF v_company.legal_name IS NULL OR TRIM(v_company.legal_name) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_LEGAL_NAME';
                v_item_result.error_message := 'legal_name es obligatorio al crear una compañía '
                                               || '(tax_id="' || v_company.tax_id || '")';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            -- ── INSERT ────────────────────────────────────────────────────
INSERT INTO shared.company (
    tax_id,
    legal_name,
    trade_name,
    address,
    phone,
    email,
    logo_url,
    is_active,
    created_at,
    updated_at
)
VALUES (
           v_company.tax_id,
           TRIM(v_company.legal_name),
           v_company.trade_name,
           v_company.address,
           v_company.phone,
           v_company.email,
           v_company.logo_url,
           COALESCE(v_company.is_active, TRUE),
           NOW(),
           NOW()
       )
    RETURNING company_id INTO v_new_id;

v_item_result.company_id := v_new_id;
            v_item_result.status     := 'INSERTED';
            v_total_inserted         := v_total_inserted + 1;

            v_processed_tax_ids := v_processed_tax_ids || v_company.tax_id;

END IF;

        v_item_results := v_item_results || v_item_result;

END LOOP;

    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success         := TRUE;
    v_result.total_submitted := array_length(p_input.companies, 1);
    v_result.total_inserted  := v_total_inserted;
    v_result.total_updated   := v_total_updated;
    v_result.total_skipped   := v_total_skipped;
    v_result.total_errors    := v_total_errors;
    v_result.detail          := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$_$;


--
-- Name: upsert_driver(api.upsert_driver_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_driver(p_input api.upsert_driver_input) RETURNS api.upsert_driver_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.upsert_driver_result;
    v_existing_driver       hr.driver%ROWTYPE;
    v_person_id             INT;
    v_person_was_created    BOOLEAN := FALSE;
    v_person_was_updated    BOOLEAN := FALSE;
    v_driver_id             INT;
    v_driver_code           VARCHAR(20);
    v_code_was_generated    BOOLEAN := FALSE;
    v_employment_status     VARCHAR(20);
    v_employment_type       VARCHAR(20);
    v_has_changes           BOOLEAN;
    v_person_result         api.upsert_person_result;
    v_pd                    api.upsert_driver_person_inline;
BEGIN

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: driver_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.driver_id IS NOT NULL THEN

        -- 1. El conductor existe
SELECT * INTO v_existing_driver
FROM hr.driver
WHERE driver_id = p_input.driver_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DRIVER_NOT_FOUND';
            v_result.error_message := 'driver_id=' || p_input.driver_id || ' no existe';
RETURN v_result;
END IF;

        -- 2. Si viene person_data inline en UPDATE → actualizar persona vinculada
        IF p_input.person_data IS DISTINCT FROM NULL THEN
            v_pd := p_input.person_data;

SELECT * INTO v_person_result
FROM api.upsert_person(
        ROW(
                v_existing_driver.person_id,  -- UPDATE explícito por person_id
                NULL, v_pd.tax_id_type,       -- tax_id solo si viene en inline
                v_pd.given_names,
                v_pd.father_last_name,
                v_pd.mother_last_name,
                v_pd.gender,
                v_pd.birth_date,
                v_pd.nationality,
                v_pd.marital_status,
                NULL,                          -- blood_type
                v_pd.email,
                v_pd.phone_mobile,
                NULL,                          -- phone_home
                v_pd.emergency_contact_name,
                v_pd.emergency_contact_phone,
                NULL,                          -- photo_url
                NULL                           -- is_active
        )::api.upsert_person_input
     );

IF NOT v_person_result.success THEN
                v_result.success       := FALSE;
                v_result.error_code    := v_person_result.error_code;
                v_result.error_message := '[upsert_person] ' || v_person_result.error_message;
RETURN v_result;
END IF;

            v_person_was_updated := (v_person_result.person_status = 'UPDATED');
END IF;

        -- 3. Validar employment_type si cambia
        v_employment_type := COALESCE(p_input.employment_type, v_existing_driver.employment_type);

        IF p_input.employment_type IS NOT NULL
           AND p_input.employment_type NOT IN ('OWNER_OPERATOR', 'HIRED_DRIVER')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_TYPE';
            v_result.error_message := 'employment_type inválido: "' || p_input.employment_type
                                      || '". Válidos: OWNER_OPERATOR, HIRED_DRIVER';
RETURN v_result;
END IF;

        -- 4. Validar employment_status si cambia
        IF p_input.employment_status IS NOT NULL
           AND p_input.employment_status NOT IN ('ACTIVE', 'SUSPENDED', 'TERMINATED')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_STATUS';
            v_result.error_message := 'employment_status inválido: "' || p_input.employment_status
                                      || '". Válidos: ACTIVE, SUSPENDED, TERMINATED';
RETURN v_result;
END IF;

        -- 5. Validar owner_id si aplica al tipo efectivo
        IF v_employment_type = 'OWNER_OPERATOR' THEN
            DECLARE v_eff_owner INT := COALESCE(p_input.owner_id, v_existing_driver.owner_id);
BEGIN
                IF v_eff_owner IS NULL THEN
                    v_result.success       := FALSE;
                    v_result.error_code    := 'OWNER_OPERATOR_REQUIRES_OWNER_ID';
                    v_result.error_message := 'employment_type=OWNER_OPERATOR requiere owner_id';
RETURN v_result;
END IF;
                IF p_input.owner_id IS NOT NULL
                   AND NOT EXISTS (
                       SELECT 1 FROM fleet.vehicle_owner
                       WHERE vehicle_owner_id = p_input.owner_id AND is_active = TRUE
                   )
                THEN
                    v_result.success       := FALSE;
                    v_result.error_code    := 'OWNER_NOT_FOUND';
                    v_result.error_message := 'owner_id=' || p_input.owner_id
                                             || ' no existe o está inactivo';
RETURN v_result;
END IF;
END;
END IF;

        -- 6. Validar hired_by_owner_id si aplica al tipo efectivo
        IF v_employment_type = 'HIRED_DRIVER' THEN
            DECLARE v_eff_hired INT := COALESCE(p_input.hired_by_owner_id,
                                                v_existing_driver.hired_by_owner_id);
BEGIN
                IF v_eff_hired IS NULL THEN
                    v_result.success       := FALSE;
                    v_result.error_code    := 'HIRED_DRIVER_REQUIRES_OWNER';
                    v_result.error_message := 'employment_type=HIRED_DRIVER requiere hired_by_owner_id';
RETURN v_result;
END IF;
                IF p_input.hired_by_owner_id IS NOT NULL
                   AND NOT EXISTS (
                       SELECT 1 FROM fleet.vehicle_owner
                       WHERE vehicle_owner_id = p_input.hired_by_owner_id AND is_active = TRUE
                   )
                THEN
                    v_result.success       := FALSE;
                    v_result.error_code    := 'OWNER_NOT_FOUND';
                    v_result.error_message := 'hired_by_owner_id=' || p_input.hired_by_owner_id
                                             || ' no existe o está inactivo';
RETURN v_result;
END IF;
END;
END IF;

        -- 7. Validar license_points en rango [0-100]
        IF p_input.license_points IS NOT NULL
           AND (p_input.license_points < 0 OR p_input.license_points > 100)
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_LICENSE_POINTS';
            v_result.error_message := 'license_points debe estar entre 0 y 100. '
                                      || 'Recibido: ' || p_input.license_points::TEXT;
RETURN v_result;
END IF;

        -- 8. Validar user_id si cambia
        IF p_input.user_id IS NOT NULL
           AND p_input.user_id IS DISTINCT FROM v_existing_driver.user_id
        THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id = p_input.user_id AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_NOT_FOUND';
                v_result.error_message := 'user_id=' || p_input.user_id
                                          || ' no existe o está inactivo';
RETURN v_result;
END IF;
            IF EXISTS (
                SELECT 1 FROM hr.driver
                WHERE user_id  = p_input.user_id
                  AND driver_id <> p_input.driver_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_ALREADY_LINKED';
                v_result.error_message := 'user_id=' || p_input.user_id
                                          || ' ya está vinculado a otro conductor';
RETURN v_result;
END IF;
END IF;

        -- 9. Validar driver_code si cambia
        IF p_input.driver_code IS NOT NULL
           AND TRIM(p_input.driver_code) <> ''
           AND TRIM(p_input.driver_code) <> v_existing_driver.driver_code
        THEN
            IF EXISTS (
                SELECT 1 FROM hr.driver
                WHERE driver_code = TRIM(p_input.driver_code)
                  AND driver_id   <> p_input.driver_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_DRIVER_CODE';
                v_result.error_message := 'driver_code "' || TRIM(p_input.driver_code)
                                          || '" ya está en uso por otro conductor';
RETURN v_result;
END IF;
END IF;

        -- 10. Detectar cambios reales (PATCH semántico)
        v_has_changes :=
            (p_input.employment_type   IS NOT NULL AND p_input.employment_type   IS DISTINCT FROM v_existing_driver.employment_type)   OR
            (p_input.employment_status IS NOT NULL AND p_input.employment_status  IS DISTINCT FROM v_existing_driver.employment_status) OR
            (p_input.owner_id          IS NOT NULL AND p_input.owner_id           IS DISTINCT FROM v_existing_driver.owner_id)          OR
            (p_input.hired_by_owner_id IS NOT NULL AND p_input.hired_by_owner_id  IS DISTINCT FROM v_existing_driver.hired_by_owner_id) OR
            (p_input.user_id           IS NOT NULL AND p_input.user_id            IS DISTINCT FROM v_existing_driver.user_id)           OR
            (p_input.driver_code       IS NOT NULL AND TRIM(p_input.driver_code)  IS DISTINCT FROM v_existing_driver.driver_code)       OR
            (p_input.hire_date         IS NOT NULL AND p_input.hire_date           IS DISTINCT FROM v_existing_driver.hire_date)         OR
            (p_input.termination_date  IS NOT NULL AND p_input.termination_date    IS DISTINCT FROM v_existing_driver.termination_date)  OR
            (p_input.license_points    IS NOT NULL AND p_input.license_points      IS DISTINCT FROM v_existing_driver.license_points)    OR
            (p_input.is_available      IS NOT NULL AND p_input.is_available        IS DISTINCT FROM v_existing_driver.is_available)      OR
            (p_input.notes             IS NOT NULL AND p_input.notes               IS DISTINCT FROM v_existing_driver.notes)             OR
            v_person_was_updated;

        IF v_has_changes THEN
UPDATE hr.driver
SET employment_type   = COALESCE(p_input.employment_type,                              employment_type),
    employment_status = COALESCE(p_input.employment_status,                            employment_status),
    owner_id          = COALESCE(p_input.owner_id,                                     owner_id),
    hired_by_owner_id = COALESCE(p_input.hired_by_owner_id,                            hired_by_owner_id),
    user_id           = COALESCE(p_input.user_id,                                      user_id),
    driver_code       = COALESCE(NULLIF(TRIM(p_input.driver_code), ''),               driver_code),
    hire_date         = COALESCE(p_input.hire_date,                                    hire_date),
    termination_date  = COALESCE(p_input.termination_date,                             termination_date),
    license_points    = COALESCE(p_input.license_points,                               license_points),
    is_available      = COALESCE(p_input.is_available,                                 is_available),
    notes             = COALESCE(p_input.notes,                                        notes),
    updated_at        = NOW()
WHERE driver_id = p_input.driver_id;

v_result.driver_status := 'UPDATED';
ELSE
            v_result.driver_status := 'SKIPPED';
END IF;

        v_driver_id          := p_input.driver_id;
        v_code_was_generated := FALSE;

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA INSERT: driver_id es NULL
    -- ══════════════════════════════════════════════════════════════════════
ELSE

        -- ── BLOQUE 1: Resolver person_id ──────────────────────────────────
        IF p_input.person_id IS NOT NULL THEN

            -- Vía 1: person_id explícito
            IF NOT EXISTS (
                SELECT 1 FROM hr.person WHERE person_id = p_input.person_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'PERSON_NOT_FOUND';
                v_result.error_message := 'person_id=' || p_input.person_id || ' no existe';
RETURN v_result;
END IF;
            v_person_id := p_input.person_id;

        ELSIF p_input.person_data IS DISTINCT FROM NULL THEN

            -- Vía 2: crear/upsert persona inline
            v_pd := p_input.person_data;

            IF v_pd.tax_id IS NULL OR TRIM(v_pd.tax_id) = ''
            OR v_pd.given_names IS NULL OR TRIM(v_pd.given_names) = ''
            OR v_pd.father_last_name IS NULL OR TRIM(v_pd.father_last_name) = ''
            OR v_pd.mother_last_name IS NULL OR TRIM(v_pd.mother_last_name) = ''
            THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_PERSON_DATA';
                v_result.error_message := 'person_data incompleto: tax_id, given_names, '
                                          || 'father_last_name y mother_last_name son obligatorios';
RETURN v_result;
END IF;

SELECT * INTO v_person_result
FROM api.upsert_person(
        ROW(
                NULL,               -- person_id=NULL → INSERT por tax_id
                v_pd.tax_id,
                v_pd.tax_id_type,
                v_pd.given_names,
                v_pd.father_last_name,
                v_pd.mother_last_name,
                v_pd.gender,
                v_pd.birth_date,
                v_pd.nationality,
                v_pd.marital_status,
                NULL,               -- blood_type
                v_pd.email,
                v_pd.phone_mobile,
                NULL,               -- phone_home
                v_pd.emergency_contact_name,
                v_pd.emergency_contact_phone,
                NULL,               -- photo_url
                NULL                -- is_active
        )::api.upsert_person_input
     );

IF NOT v_person_result.success THEN
                v_result.success       := FALSE;
                v_result.error_code    := v_person_result.error_code;
                v_result.error_message := '[upsert_person] ' || v_person_result.error_message;
RETURN v_result;
END IF;

            v_person_id          := v_person_result.person_id;
            v_person_was_created := NOT v_person_result.already_existed;

ELSE
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_PERSON_REFERENCE';
            v_result.error_message := 'Debe proveer person_id o person_data para crear un conductor';
RETURN v_result;
END IF;

        -- ── BLOQUE 2: Validaciones de negocio del conductor ───────────────

        -- Ya tiene registro como conductor
        IF EXISTS (SELECT 1 FROM hr.driver WHERE person_id = v_person_id) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DRIVER_ALREADY_EXISTS';
            v_result.error_message := 'La persona person_id=' || v_person_id
                                      || ' ya tiene un registro en hr.driver';
RETURN v_result;
END IF;

        -- Empresa obligatoria y activa
        IF p_input.company_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_COMPANY_ID';
            v_result.error_message := 'company_id es obligatorio al crear un conductor';
RETURN v_result;
END IF;

        IF NOT EXISTS (
            SELECT 1 FROM shared.company
            WHERE company_id = p_input.company_id AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COMPANY_NOT_FOUND';
            v_result.error_message := 'company_id=' || p_input.company_id
                                      || ' no existe o está inactiva';
RETURN v_result;
END IF;

        -- employment_type obligatorio
        IF p_input.employment_type IS NULL
           OR p_input.employment_type NOT IN ('OWNER_OPERATOR', 'HIRED_DRIVER')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_TYPE';
            v_result.error_message := 'employment_type inválido: "'
                                      || COALESCE(p_input.employment_type, 'NULL')
                                      || '". Válidos: OWNER_OPERATOR, HIRED_DRIVER';
RETURN v_result;
END IF;

        v_employment_status := COALESCE(p_input.employment_status, 'ACTIVE');

        IF v_employment_status NOT IN ('ACTIVE', 'SUSPENDED', 'TERMINATED') THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_STATUS';
            v_result.error_message := 'employment_status inválido: "' || v_employment_status
                                      || '". Válidos: ACTIVE, SUSPENDED, TERMINATED';
RETURN v_result;
END IF;

        IF p_input.employment_type = 'OWNER_OPERATOR' THEN
            IF p_input.owner_id IS NULL THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'OWNER_OPERATOR_REQUIRES_OWNER_ID';
                v_result.error_message := 'OWNER_OPERATOR requiere owner_id';
RETURN v_result;
END IF;
            IF NOT EXISTS (
                SELECT 1 FROM fleet.vehicle_owner
                WHERE vehicle_owner_id = p_input.owner_id AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'OWNER_NOT_FOUND';
                v_result.error_message := 'owner_id=' || p_input.owner_id
                                          || ' no existe o está inactivo';
RETURN v_result;
END IF;
END IF;

        IF p_input.employment_type = 'HIRED_DRIVER' THEN
            IF p_input.hired_by_owner_id IS NULL THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'HIRED_DRIVER_REQUIRES_OWNER';
                v_result.error_message := 'HIRED_DRIVER requiere hired_by_owner_id';
RETURN v_result;
END IF;
            IF NOT EXISTS (
                SELECT 1 FROM fleet.vehicle_owner
                WHERE vehicle_owner_id = p_input.hired_by_owner_id AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'OWNER_NOT_FOUND';
                v_result.error_message := 'hired_by_owner_id=' || p_input.hired_by_owner_id
                                          || ' no existe o está inactivo';
RETURN v_result;
END IF;
END IF;

        IF p_input.user_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id = p_input.user_id AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_NOT_FOUND';
                v_result.error_message := 'user_id=' || p_input.user_id
                                          || ' no existe o está inactivo';
RETURN v_result;
END IF;
            IF EXISTS (SELECT 1 FROM hr.driver WHERE user_id = p_input.user_id) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_ALREADY_LINKED';
                v_result.error_message := 'user_id=' || p_input.user_id
                                          || ' ya está vinculado a otro conductor';
RETURN v_result;
END IF;
END IF;

        -- ── BLOQUE 3: Resolver driver_code ────────────────────────────────
        IF p_input.driver_code IS NOT NULL AND TRIM(p_input.driver_code) <> '' THEN
            IF EXISTS (
                SELECT 1 FROM hr.driver WHERE driver_code = TRIM(p_input.driver_code)
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_DRIVER_CODE';
                v_result.error_message := 'driver_code "' || TRIM(p_input.driver_code)
                                          || '" ya está en uso';
RETURN v_result;
END IF;
            v_driver_code        := TRIM(p_input.driver_code);
            v_code_was_generated := FALSE;
ELSE
            v_driver_code        := api._generate_driver_code();
            v_code_was_generated := TRUE;
END IF;

        -- ── BLOQUE 4: INSERT ──────────────────────────────────────────────
INSERT INTO hr.driver (
    person_id,
    user_id,
    company_id,
    driver_code,
    hire_date,
    employment_status,
    employment_type,
    owner_id,
    hired_by_owner_id,
    license_points,
    total_trips,
    total_km_driven,
    is_available,
    notes
)
VALUES (
           v_person_id,
           p_input.user_id,
           p_input.company_id,
           v_driver_code,
           p_input.hire_date,
           v_employment_status,
           p_input.employment_type,
           p_input.owner_id,
           p_input.hired_by_owner_id,
           100,
           0,
           0.00,
           TRUE,
           p_input.notes
       )
    RETURNING driver_id INTO v_driver_id;

v_result.driver_status := 'INSERTED';

END IF;

    -- ── Poblar resultado desde BD ─────────────────────────────────────────
SELECT
    d.driver_id,
    d.person_id,
    d.company_id,
    d.driver_code,
    d.employment_type,
    d.employment_status,
    d.owner_id,
    d.hired_by_owner_id,
    d.user_id,
    d.license_points,
    d.is_available,
    d.hire_date,
    d.termination_date,
    d.created_at,
    d.updated_at,
    p.full_name,
    p.tax_id
INTO
    v_result.driver_id,
    v_result.person_id,
    v_result.company_id,
    v_result.driver_code,
    v_result.employment_type,
    v_result.employment_status,
    v_result.owner_id,
    v_result.hired_by_owner_id,
    v_result.user_id,
    v_result.license_points,
    v_result.is_available,
    v_result.hire_date,
    v_result.termination_date,
    v_result.created_at,
    v_result.updated_at,
    v_result.full_name,
    v_result.tax_id
FROM hr.driver d
         JOIN hr.person p ON p.person_id = d.person_id
WHERE d.driver_id = v_driver_id;

v_result.success                   := TRUE;
    v_result.person_was_created        := v_person_was_created;
    v_result.person_was_updated        := v_person_was_updated;
    v_result.driver_code_was_generated := v_code_was_generated;

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_DRIVER_CODE';
        v_result.error_message := 'Conflicto de unicidad por concurrencia: ' || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_gps_device(api.upsert_gps_device_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_gps_device(p_input api.upsert_gps_device_input) RETURNS api.upsert_gps_device_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result        api.upsert_gps_device_result;
    v_existing      fleet.gps_device%ROWTYPE;
    v_has_changes   BOOLEAN;
    v_interval      INT;
    v_installed_at  TIMESTAMPTZ;
    v_status        VARCHAR(20);
    -- Valor efectivo de vehicle_id en UPDATE (NULL puede ser intencional)
    v_new_vehicle_id INT;
    v_vehicle_changed BOOLEAN;
BEGIN

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: gps_device_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.gps_device_id IS NOT NULL THEN

        -- 1. El dispositivo existe
SELECT * INTO v_existing
FROM fleet.gps_device
WHERE gps_device_id = p_input.gps_device_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DEVICE_NOT_FOUND';
            v_result.error_message := 'gps_device_id=' || p_input.gps_device_id || ' no existe';
RETURN v_result;
END IF;

        -- 2. Validar device_id si cambia (unicidad)
        IF p_input.device_id IS NOT NULL
            AND TRIM(p_input.device_id) <> ''
            AND TRIM(p_input.device_id) <> v_existing.device_id
        THEN
            IF EXISTS (
                SELECT 1 FROM fleet.gps_device
                WHERE device_id    = TRIM(p_input.device_id)
                  AND gps_device_id <> p_input.gps_device_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_DEVICE_ID';
                v_result.error_message := 'El device_id "' || TRIM(p_input.device_id)
                    || '" ya está registrado en otro dispositivo';
RETURN v_result;
END IF;
END IF;

        -- 3. Validar IMEI si cambia (unicidad)
        IF p_input.imei IS NOT NULL
            AND TRIM(p_input.imei) <> ''
            AND TRIM(p_input.imei) IS DISTINCT FROM v_existing.imei
        THEN
            IF EXISTS (
                SELECT 1 FROM fleet.gps_device
                WHERE imei         = TRIM(p_input.imei)
                  AND gps_device_id <> p_input.gps_device_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_IMEI';
                v_result.error_message := 'El IMEI "' || TRIM(p_input.imei)
                    || '" ya está registrado en otro dispositivo';
RETURN v_result;
END IF;
END IF;

        -- 4. Validar device_type si viene
        IF p_input.device_type IS NOT NULL
            AND p_input.device_type NOT IN ('TRACKER_GPS', 'ANDROID_TABLET')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DEVICE_TYPE';
            v_result.error_message := 'device_type inválido: "' || p_input.device_type
                || '". Válidos: TRACKER_GPS, ANDROID_TABLET';
RETURN v_result;
END IF;

        -- 5. Validar status si viene
        IF p_input.status IS NOT NULL
            AND p_input.status NOT IN ('ACTIVE', 'INACTIVE', 'ERROR', 'MAINTENANCE')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_GPS_STATUS';
            v_result.error_message := 'status inválido: "' || p_input.status
                || '". Válidos: ACTIVE, INACTIVE, ERROR, MAINTENANCE';
RETURN v_result;
END IF;

        -- 6. Validar posting_interval_seconds si viene
        IF p_input.posting_interval_seconds IS NOT NULL THEN
            IF p_input.posting_interval_seconds <= 0
                OR p_input.posting_interval_seconds > 300
            THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_POSTING_INTERVAL';
                v_result.error_message := 'posting_interval_seconds debe estar entre 1 y 300. '
                                              || 'Recibido: ' || p_input.posting_interval_seconds::TEXT;
RETURN v_result;
END IF;
END IF;

        -- 7. Validar installed_by si viene
        IF p_input.installed_by IS NOT NULL
            AND p_input.installed_by IS DISTINCT FROM v_existing.installed_by
        THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id = p_input.installed_by AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INSTALLER_NOT_FOUND';
                v_result.error_message := 'El instalador user_id=' || p_input.installed_by
                    || ' no existe o está inactivo';
RETURN v_result;
END IF;
END IF;

        -- 8. Gestión de vehicle_id en UPDATE
        --    vehicle_id_explicit=TRUE distingue "asignar NULL" de "no tocar"
        v_vehicle_changed := FALSE;

        IF COALESCE(p_input.vehicle_id_explicit, FALSE) = TRUE THEN
            v_new_vehicle_id := p_input.vehicle_id;  -- puede ser NULL (desasignar)

            IF v_new_vehicle_id IS DISTINCT FROM v_existing.vehicle_id THEN
                v_vehicle_changed := TRUE;

                IF v_new_vehicle_id IS NOT NULL THEN
                    -- Vehículo destino existe
                    IF NOT EXISTS (
                        SELECT 1 FROM fleet.vehicle WHERE vehicle_id = v_new_vehicle_id
                    ) THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'VEHICLE_NOT_FOUND';
                        v_result.error_message := 'El vehículo vehicle_id=' || v_new_vehicle_id
                            || ' no existe';
RETURN v_result;
END IF;

                    -- Vehículo destino sin GPS activo ya (índice parcial único)
                    IF EXISTS (
                        SELECT 1 FROM fleet.gps_device
                        WHERE vehicle_id      = v_new_vehicle_id
                          AND is_operational  = TRUE
                          AND gps_device_id   <> p_input.gps_device_id
                    ) THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'VEHICLE_ALREADY_HAS_GPS';
                        v_result.error_message := 'El vehículo vehicle_id=' || v_new_vehicle_id
                                                      || ' ya tiene un GPS activo asignado. '
                            || 'Desactive el dispositivo actual primero';
RETURN v_result;
END IF;
END IF;
END IF;
ELSE
            -- No se tocó vehicle_id: mantener el actual
            v_new_vehicle_id := v_existing.vehicle_id;
END IF;

        -- 9. Actualizar installed_at si cambia el instalador
        v_installed_at := v_existing.installed_at;
        IF p_input.installed_by IS NOT NULL
            AND p_input.installed_by IS DISTINCT FROM v_existing.installed_by
        THEN
            v_installed_at := NOW();
END IF;

        -- 10. Detectar cambios reales (PATCH semántico)
        v_has_changes :=
                (p_input.device_id           IS NOT NULL AND TRIM(p_input.device_id)           IS DISTINCT FROM v_existing.device_id)           OR
                (p_input.device_type         IS NOT NULL AND p_input.device_type               IS DISTINCT FROM v_existing.device_type)         OR
                (p_input.imei                IS NOT NULL AND NULLIF(TRIM(p_input.imei), '')    IS DISTINCT FROM v_existing.imei)                OR
                (p_input.serial_number       IS NOT NULL AND NULLIF(TRIM(p_input.serial_number), '') IS DISTINCT FROM v_existing.serial_number) OR
                (p_input.model               IS NOT NULL AND p_input.model                     IS DISTINCT FROM v_existing.model)               OR
                (p_input.manufacturer        IS NOT NULL AND p_input.manufacturer              IS DISTINCT FROM v_existing.manufacturer)        OR
                (p_input.sim_card_number     IS NOT NULL AND NULLIF(TRIM(p_input.sim_card_number, ''), '') IS DISTINCT FROM v_existing.sim_card_number) OR
                (p_input.sim_provider        IS NOT NULL AND p_input.sim_provider              IS DISTINCT FROM v_existing.sim_provider)        OR
                (p_input.firmware_version    IS NOT NULL AND p_input.firmware_version          IS DISTINCT FROM v_existing.firmware_version)    OR
                v_vehicle_changed                                                                                                                OR
                (p_input.posting_interval_seconds IS NOT NULL AND p_input.posting_interval_seconds IS DISTINCT FROM v_existing.posting_interval_seconds) OR
                (p_input.status              IS NOT NULL AND p_input.status                    IS DISTINCT FROM v_existing.status)              OR
                (p_input.is_operational      IS NOT NULL AND p_input.is_operational            IS DISTINCT FROM v_existing.is_operational)      OR
                (p_input.installed_by        IS NOT NULL AND p_input.installed_by              IS DISTINCT FROM v_existing.installed_by);

        IF v_has_changes THEN
UPDATE fleet.gps_device
SET device_id               = COALESCE(NULLIF(TRIM(p_input.device_id), ''),            device_id),
    device_type             = COALESCE(p_input.device_type,                            device_type),
    imei                    = COALESCE(NULLIF(TRIM(COALESCE(p_input.imei,'')), ''),    imei),
    serial_number           = COALESCE(NULLIF(TRIM(COALESCE(p_input.serial_number,'')), ''), serial_number),
    model                   = COALESCE(p_input.model,                                  model),
    manufacturer            = COALESCE(p_input.manufacturer,                           manufacturer),
    sim_card_number         = COALESCE(NULLIF(TRIM(COALESCE(p_input.sim_card_number,'')), ''), sim_card_number),
    sim_provider            = COALESCE(p_input.sim_provider,                           sim_provider),
    firmware_version        = COALESCE(p_input.firmware_version,                       firmware_version),
    vehicle_id              = CASE WHEN COALESCE(p_input.vehicle_id_explicit, FALSE)
                                       THEN v_new_vehicle_id
                                   ELSE vehicle_id END,
    posting_interval_seconds = COALESCE(p_input.posting_interval_seconds,             posting_interval_seconds),
    status                  = COALESCE(p_input.status,                                status),
    is_operational          = COALESCE(p_input.is_operational,                         is_operational),
    installed_by            = COALESCE(p_input.installed_by,                           installed_by),
    installed_at            = v_installed_at,
    updated_at              = NOW()
WHERE gps_device_id = p_input.gps_device_id;

v_result.device_status := 'UPDATED';
ELSE
            v_result.device_status := 'SKIPPED';
END IF;

        -- ══════════════════════════════════════════════════════════════════════
        -- RAMA INSERT: gps_device_id es NULL
        -- ══════════════════════════════════════════════════════════════════════
ELSE

        -- 1. device_id obligatorio
        IF p_input.device_id IS NULL OR TRIM(p_input.device_id) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_DEVICE_ID';
            v_result.error_message := 'device_id es obligatorio (IMEI o Android ID)';
RETURN v_result;
END IF;

        -- 2. device_id no duplicado
        IF EXISTS (
            SELECT 1 FROM fleet.gps_device WHERE device_id = TRIM(p_input.device_id)
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DUPLICATE_DEVICE_ID';
            v_result.error_message := 'El device_id "' || TRIM(p_input.device_id)
                || '" ya está registrado en el sistema';
RETURN v_result;
END IF;

        -- 3. IMEI no duplicado si se proveyó
        IF p_input.imei IS NOT NULL AND TRIM(p_input.imei) <> '' THEN
            IF EXISTS (
                SELECT 1 FROM fleet.gps_device WHERE imei = TRIM(p_input.imei)
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_IMEI';
                v_result.error_message := 'El IMEI "' || TRIM(p_input.imei)
                    || '" ya está registrado para otro dispositivo';
RETURN v_result;
END IF;
END IF;

        -- 4. company_id obligatorio y activa
        IF p_input.company_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_COMPANY_ID';
            v_result.error_message := 'company_id es obligatorio al registrar un dispositivo GPS';
RETURN v_result;
END IF;

        IF NOT EXISTS (
            SELECT 1 FROM shared.company
            WHERE company_id = p_input.company_id AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COMPANY_NOT_FOUND';
            v_result.error_message := 'company_id=' || p_input.company_id
                || ' no existe o está inactiva';
RETURN v_result;
END IF;

        -- 5. device_type obligatorio y válido
        IF p_input.device_type IS NULL
            OR p_input.device_type NOT IN ('TRACKER_GPS', 'ANDROID_TABLET')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DEVICE_TYPE';
            v_result.error_message := 'device_type inválido: "'
                                          || COALESCE(p_input.device_type, 'NULL')
                || '". Válidos: TRACKER_GPS, ANDROID_TABLET';
RETURN v_result;
END IF;

        -- 6. status dentro del dominio
        v_status := COALESCE(NULLIF(TRIM(COALESCE(p_input.status, '')), ''), 'ACTIVE');

        IF v_status NOT IN ('ACTIVE', 'INACTIVE', 'ERROR', 'MAINTENANCE') THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_GPS_STATUS';
            v_result.error_message := 'status inválido: "' || v_status
                || '". Válidos: ACTIVE, INACTIVE, ERROR, MAINTENANCE';
RETURN v_result;
END IF;

        -- 7. posting_interval_seconds en rango [1, 300]
        v_interval := COALESCE(p_input.posting_interval_seconds, 30);

        IF v_interval <= 0 OR v_interval > 300 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_POSTING_INTERVAL';
            v_result.error_message := 'posting_interval_seconds debe estar entre 1 y 300. '
                                          || 'Recibido: ' || v_interval::TEXT;
RETURN v_result;
END IF;

        -- 8. Installer existe si se proveyó
        IF p_input.installed_by IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id = p_input.installed_by AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INSTALLER_NOT_FOUND';
                v_result.error_message := 'El instalador user_id=' || p_input.installed_by
                    || ' no existe o está inactivo';
RETURN v_result;
END IF;
            v_installed_at := NOW();
END IF;

        -- 9. vehicle_id: vehículo existe y sin GPS activo
        IF p_input.vehicle_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM fleet.vehicle WHERE vehicle_id = p_input.vehicle_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'VEHICLE_NOT_FOUND';
                v_result.error_message := 'El vehículo vehicle_id=' || p_input.vehicle_id
                    || ' no existe';
RETURN v_result;
END IF;

            IF EXISTS (
                SELECT 1 FROM fleet.gps_device
                WHERE vehicle_id     = p_input.vehicle_id
                  AND is_operational = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'VEHICLE_ALREADY_HAS_GPS';
                v_result.error_message := 'El vehículo vehicle_id=' || p_input.vehicle_id
                                              || ' ya tiene un GPS activo asignado. '
                    || 'Desactive el dispositivo actual antes de asignar uno nuevo';
RETURN v_result;
END IF;
END IF;

        -- 10. INSERT
INSERT INTO fleet.gps_device (
    device_id,
    device_type,
    company_id,
    imei,
    serial_number,
    model,
    manufacturer,
    sim_card_number,
    sim_provider,
    firmware_version,
    vehicle_id,
    posting_interval_seconds,
    status,
    is_operational,
    installed_at,
    installed_by
)
VALUES (
           TRIM(p_input.device_id),
           p_input.device_type,
           p_input.company_id,
           NULLIF(TRIM(COALESCE(p_input.imei,             '')), ''),
           NULLIF(TRIM(COALESCE(p_input.serial_number,    '')), ''),
           p_input.model,
           p_input.manufacturer,
           NULLIF(TRIM(COALESCE(p_input.sim_card_number,  '')), ''),
           p_input.sim_provider,
           p_input.firmware_version,
           p_input.vehicle_id,
           v_interval,
           v_status,
           TRUE,
           v_installed_at,
           p_input.installed_by
       )
    RETURNING gps_device_id INTO p_input.gps_device_id;

v_result.device_status := 'INSERTED';

END IF;

    -- ── Poblar resultado desde BD ─────────────────────────────────────────
SELECT
    g.gps_device_id,
    g.device_id,
    g.device_type,
    g.company_id,
    g.imei,
    g.serial_number,
    g.model,
    g.manufacturer,
    g.sim_card_number,
    g.sim_provider,
    g.firmware_version,
    g.vehicle_id,
    g.posting_interval_seconds,
    g.status,
    g.is_operational,
    g.installed_at,
    g.installed_by,
    g.created_at,
    g.updated_at
INTO
    v_result.gps_device_id,
    v_result.device_id,
    v_result.device_type,
    v_result.company_id,
    v_result.imei,
    v_result.serial_number,
    v_result.model,
    v_result.manufacturer,
    v_result.sim_card_number,
    v_result.sim_provider,
    v_result.firmware_version,
    v_result.vehicle_id,
    v_result.posting_interval_seconds,
    v_result.status,
    v_result.is_operational,
    v_result.installed_at,
    v_result.installed_by,
    v_result.created_at,
    v_result.updated_at
FROM fleet.gps_device g
WHERE g.gps_device_id = p_input.gps_device_id;

v_result.success := TRUE;
RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_DEVICE_ID';
        v_result.error_message := 'Conflicto de unicidad por concurrencia '
                                      || '(device_id o IMEI duplicado). '
                                      || 'Detalle: ' || SQLERRM;
RETURN v_result;
WHEN check_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'CONSTRAINT_VIOLATION';
        v_result.error_message := 'Violación de constraint en gps_device: ' || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_person(api.upsert_person_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_person(p_input api.upsert_person_input) RETURNS api.upsert_person_result
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_result        api.upsert_person_result;
    v_existing      hr.person%ROWTYPE;
    v_full_name     VARCHAR(255);
    v_has_changes   BOOLEAN;
    -- Valores efectivos para recalcular full_name en UPDATE
    v_eff_given_names      VARCHAR(150);
    v_eff_father_last_name VARCHAR(100);
    v_eff_mother_last_name VARCHAR(100);

    -- Helper: valida formato de tax_id según tipo
    -- (usamos bloque anidado para evitar duplicar el CASE)
    v_tax_id_ok     BOOLEAN;
BEGIN

    -- ══════════════════════════════════════════════════════════
    -- HELPER: validación de tax_id_type y formato
    -- Aplica a ambas ramas (en UPDATE solo si viene tax_id nuevo)
    -- ══════════════════════════════════════════════════════════

    -- Subfunción local usando etiqueta de bloque para reutilizar
    -- la lógica de validación sin duplicarla

<<validate_tax_id>>
        DECLARE
v_tid       VARCHAR(20) := p_input.tax_id;
        v_ttype     VARCHAR(20) := p_input.tax_id_type;
BEGIN

        -- Solo validar si hay tax_id en el payload
        IF v_tid IS NOT NULL AND TRIM(v_tid) <> '' THEN

            -- tax_id_type obligatorio cuando viene tax_id
            IF v_ttype IS NULL OR v_ttype NOT IN ('DNI','RUC','CE','PASSPORT','PTP','OTHER') THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_TAX_ID_TYPE';
                v_result.error_message := 'tax_id_type inválido: "' || COALESCE(v_ttype, 'NULL')
                    || '". Válidos: DNI, RUC, CE, PASSPORT, PTP, OTHER';
RETURN v_result;
END IF;

CASE v_ttype
                WHEN 'DNI' THEN
                    IF v_tid !~ '^\d{8}$' THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                        v_result.error_message := 'DNI debe tener exactamente 8 dígitos numéricos. '
                                                      || 'Recibido: "' || v_tid || '"';
RETURN v_result;
END IF;
WHEN 'RUC' THEN
                    IF v_tid !~ '^\d{11}$' THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                        v_result.error_message := 'RUC debe tener exactamente 11 dígitos numéricos. '
                                                      || 'Recibido: "' || v_tid || '"';
RETURN v_result;
END IF;
WHEN 'CE' THEN
                    IF v_tid !~ '^[A-Z0-9]{5,12}$' THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                        v_result.error_message := 'Carnet de Extranjería: 5-12 caracteres '
                                                      || 'alfanuméricos en mayúsculas. '
                                                      || 'Recibido: "' || v_tid || '"';
RETURN v_result;
END IF;
WHEN 'PASSPORT' THEN
                    IF v_tid !~ '^[A-Z0-9]{6,20}$' THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                        v_result.error_message := 'Pasaporte: 6-20 caracteres alfanuméricos '
                                                      || 'en mayúsculas. '
                                                      || 'Recibido: "' || v_tid || '"';
RETURN v_result;
END IF;
WHEN 'PTP' THEN
                    IF v_tid !~ '^[A-Z0-9\-]{5,20}$' THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                        v_result.error_message := 'PTP/PEP: 5-20 caracteres alfanuméricos. '
                                                      || 'Recibido: "' || v_tid || '"';
RETURN v_result;
END IF;
WHEN 'OTHER' THEN
                    IF LENGTH(TRIM(v_tid)) < 4 THEN
                        v_result.success       := FALSE;
                        v_result.error_code    := 'INVALID_TAX_ID_FORMAT';
                        v_result.error_message := 'El documento debe tener al menos 4 caracteres';
RETURN v_result;
END IF;
END CASE;

END IF;

END validate_tax_id;

    -- ── Val: género ───────────────────────────────────────────────────────
    IF p_input.gender IS NOT NULL
        AND p_input.gender NOT IN ('M', 'F', 'O')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_GENDER';
        v_result.error_message := 'gender debe ser M, F u O. Recibido: "' || p_input.gender || '"';
RETURN v_result;
END IF;

    -- ── Val: estado civil ─────────────────────────────────────────────────
    IF p_input.marital_status IS NOT NULL
        AND p_input.marital_status NOT IN ('SINGLE','MARRIED','DIVORCED','WIDOWED')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_MARITAL_STATUS';
        v_result.error_message := 'marital_status inválido: "' || p_input.marital_status
            || '". Válidos: SINGLE, MARRIED, DIVORCED, WIDOWED';
RETURN v_result;
END IF;

    -- ── Val: fecha de nacimiento ──────────────────────────────────────────
    IF p_input.birth_date IS NOT NULL THEN
        IF p_input.birth_date > CURRENT_DATE THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_BIRTH_DATE';
            v_result.error_message := 'birth_date no puede ser una fecha futura';
RETURN v_result;
END IF;
        IF (CURRENT_DATE - p_input.birth_date) / 365 < 18 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_BIRTH_DATE';
            v_result.error_message := 'La persona debe tener al menos 18 años. '
                                          || 'Fecha recibida: ' || p_input.birth_date::TEXT;
RETURN v_result;
END IF;
END IF;

    -- ── Val: formato de email ─────────────────────────────────────────────
    IF p_input.email IS NOT NULL
        AND p_input.email !~ '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$'
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_EMAIL_FORMAT';
        v_result.error_message := 'Formato de email inválido: "' || p_input.email || '"';
RETURN v_result;
END IF;

    -- ══════════════════════════════════════════════════════════
    -- RAMA UPDATE: person_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════
    IF p_input.person_id IS NOT NULL THEN

        -- 1. La persona existe
SELECT * INTO v_existing
FROM hr.person
WHERE person_id = p_input.person_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'PERSON_NOT_FOUND';
            v_result.error_message := 'person_id=' || p_input.person_id || ' no existe';
RETURN v_result;
END IF;

        -- 2. Validar campos de nombre no vacíos si vienen
        IF p_input.given_names IS NOT NULL AND TRIM(p_input.given_names) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_GIVEN_NAMES';
            v_result.error_message := 'given_names no puede ser una cadena vacía';
RETURN v_result;
END IF;
        IF p_input.father_last_name IS NOT NULL AND TRIM(p_input.father_last_name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_FATHER_LAST_NAME';
            v_result.error_message := 'father_last_name no puede ser una cadena vacía';
RETURN v_result;
END IF;
        IF p_input.mother_last_name IS NOT NULL AND TRIM(p_input.mother_last_name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_MOTHER_LAST_NAME';
            v_result.error_message := 'mother_last_name no puede ser una cadena vacía';
RETURN v_result;
END IF;

        -- 3. Si viene nuevo tax_id, validar que no lo use otra persona
        IF p_input.tax_id IS NOT NULL
            AND p_input.tax_id <> v_existing.tax_id
        THEN
            IF EXISTS (
                SELECT 1 FROM hr.person
                WHERE tax_id   = p_input.tax_id
                  AND person_id <> p_input.person_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_TAX_ID';
                v_result.error_message := 'El tax_id "' || p_input.tax_id
                    || '" ya está registrado para otra persona';
RETURN v_result;
END IF;
END IF;

        -- 4. Calcular full_name efectivo (componentes nuevos o existentes)
        v_eff_given_names      := COALESCE(NULLIF(TRIM(p_input.given_names), ''),
                                           v_existing.given_names);
        v_eff_father_last_name := COALESCE(NULLIF(TRIM(p_input.father_last_name), ''),
                                           v_existing.father_last_name);
        v_eff_mother_last_name := COALESCE(NULLIF(TRIM(p_input.mother_last_name), ''),
                                           v_existing.mother_last_name);

        v_full_name := TRIM(UPPER(v_eff_father_last_name))
                           || ' ' || TRIM(UPPER(v_eff_mother_last_name))
                           || ', ' || TRIM(INITCAP(v_eff_given_names));

        -- 5. Detectar cambios reales (PATCH semántico)
        v_has_changes :=
                (p_input.tax_id                  IS NOT NULL AND p_input.tax_id                  IS DISTINCT FROM v_existing.tax_id)                  OR
                (p_input.given_names             IS NOT NULL AND TRIM(p_input.given_names)        IS DISTINCT FROM v_existing.given_names)             OR
                (p_input.father_last_name        IS NOT NULL AND TRIM(p_input.father_last_name)   IS DISTINCT FROM v_existing.father_last_name)        OR
                (p_input.mother_last_name        IS NOT NULL AND TRIM(p_input.mother_last_name)   IS DISTINCT FROM v_existing.mother_last_name)        OR
                (p_input.gender                  IS NOT NULL AND p_input.gender                   IS DISTINCT FROM v_existing.gender)                  OR
                (p_input.birth_date              IS NOT NULL AND p_input.birth_date               IS DISTINCT FROM v_existing.birth_date)              OR
                (p_input.nationality             IS NOT NULL AND p_input.nationality              IS DISTINCT FROM v_existing.nationality)             OR
                (p_input.marital_status          IS NOT NULL AND p_input.marital_status           IS DISTINCT FROM v_existing.marital_status)          OR
                (p_input.blood_type              IS NOT NULL AND p_input.blood_type               IS DISTINCT FROM v_existing.blood_type)              OR
                (p_input.email                   IS NOT NULL AND p_input.email                    IS DISTINCT FROM v_existing.email)                   OR
                (p_input.phone_mobile            IS NOT NULL AND p_input.phone_mobile             IS DISTINCT FROM v_existing.phone_mobile)            OR
                (p_input.phone_home              IS NOT NULL AND p_input.phone_home               IS DISTINCT FROM v_existing.phone_home)              OR
                (p_input.emergency_contact_name  IS NOT NULL AND p_input.emergency_contact_name   IS DISTINCT FROM v_existing.emergency_contact_name)  OR
                (p_input.emergency_contact_phone IS NOT NULL AND p_input.emergency_contact_phone  IS DISTINCT FROM v_existing.emergency_contact_phone) OR
                (p_input.photo_url               IS NOT NULL AND p_input.photo_url                IS DISTINCT FROM v_existing.photo_url)               OR
                (p_input.is_active               IS NOT NULL AND p_input.is_active                IS DISTINCT FROM v_existing.is_active);

        IF v_has_changes THEN
UPDATE hr.person
SET tax_id                  = COALESCE(p_input.tax_id,                                               tax_id),
    given_names             = COALESCE(NULLIF(TRIM(p_input.given_names), ''),                        given_names),
    father_last_name        = COALESCE(NULLIF(TRIM(p_input.father_last_name), ''),                   father_last_name),
    mother_last_name        = COALESCE(NULLIF(TRIM(p_input.mother_last_name), ''),                   mother_last_name),
    full_name               = v_full_name,  -- siempre recalculado
    gender                  = COALESCE(p_input.gender,                                               gender),
    birth_date              = COALESCE(p_input.birth_date,                                           birth_date),
    nationality             = COALESCE(p_input.nationality,                                          nationality),
    marital_status          = COALESCE(p_input.marital_status,                                       marital_status),
    blood_type              = COALESCE(p_input.blood_type,                                           blood_type),
    email                   = COALESCE(p_input.email,                                                email),
    phone_mobile            = COALESCE(p_input.phone_mobile,                                         phone_mobile),
    phone_home              = COALESCE(p_input.phone_home,                                           phone_home),
    emergency_contact_name  = COALESCE(p_input.emergency_contact_name,                               emergency_contact_name),
    emergency_contact_phone = COALESCE(p_input.emergency_contact_phone,                              emergency_contact_phone),
    photo_url               = COALESCE(p_input.photo_url,                                            photo_url),
    is_active               = COALESCE(p_input.is_active,                                            is_active),
    updated_at              = NOW()
WHERE person_id = p_input.person_id;

v_result.person_status := 'UPDATED';
ELSE
            v_result.person_status := 'SKIPPED';
END IF;

        v_result.already_existed := TRUE;

        -- ══════════════════════════════════════════════════════════
        -- RAMA INSERT: person_id es NULL → llave natural = tax_id
        -- ══════════════════════════════════════════════════════════
ELSE

        -- 1. tax_id obligatorio en INSERT
        IF p_input.tax_id IS NULL OR TRIM(p_input.tax_id) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_TAX_ID';
            v_result.error_message := 'tax_id es obligatorio al crear una persona';
RETURN v_result;
END IF;

        -- 2. tax_id_type obligatorio en INSERT (ya validado arriba si tax_id viene)
        IF p_input.tax_id_type IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_TAX_ID_TYPE';
            v_result.error_message := 'tax_id_type es obligatorio al crear una persona';
RETURN v_result;
END IF;

        -- 3. Campos de nombre obligatorios en INSERT
        IF p_input.given_names IS NULL OR TRIM(p_input.given_names) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_GIVEN_NAMES';
            v_result.error_message := 'given_names es obligatorio al crear una persona';
RETURN v_result;
END IF;
        IF p_input.father_last_name IS NULL OR TRIM(p_input.father_last_name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_FATHER_LAST_NAME';
            v_result.error_message := 'father_last_name es obligatorio al crear una persona';
RETURN v_result;
END IF;
        IF p_input.mother_last_name IS NULL OR TRIM(p_input.mother_last_name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_MOTHER_LAST_NAME';
            v_result.error_message := 'mother_last_name es obligatorio al crear una persona';
RETURN v_result;
END IF;

        -- 4. Generar full_name (fuente de verdad estilo RENIEC)
        v_full_name := TRIM(UPPER(p_input.father_last_name))
                           || ' ' || TRIM(UPPER(p_input.mother_last_name))
                           || ', ' || TRIM(INITCAP(p_input.given_names));

        -- 5. DUPLICATE_TAX_ID → retornar existente como already_existed (sin error duro)
SELECT * INTO v_existing
FROM hr.person
WHERE tax_id = p_input.tax_id;

IF FOUND THEN
            -- Idempotente: devuelve el existente con flag, no falla
            v_result.success                := TRUE;
            v_result.person_status          := 'INSERTED';   -- semánticamente fue "creado" antes
            v_result.already_existed        := TRUE;
            v_result.tax_id_type            := p_input.tax_id_type;
            v_result.person_id              := v_existing.person_id;
            v_result.tax_id                 := v_existing.tax_id;
            v_result.given_names            := v_existing.given_names;
            v_result.father_last_name       := v_existing.father_last_name;
            v_result.mother_last_name       := v_existing.mother_last_name;
            v_result.full_name              := v_existing.full_name;
            v_result.gender                 := v_existing.gender;
            v_result.birth_date             := v_existing.birth_date;
            v_result.nationality            := v_existing.nationality;
            v_result.marital_status         := v_existing.marital_status;
            v_result.blood_type             := v_existing.blood_type;
            v_result.email                  := v_existing.email;
            v_result.phone_mobile           := v_existing.phone_mobile;
            v_result.phone_home             := v_existing.phone_home;
            v_result.emergency_contact_name  := v_existing.emergency_contact_name;
            v_result.emergency_contact_phone := v_existing.emergency_contact_phone;
            v_result.photo_url              := v_existing.photo_url;
            v_result.is_active              := v_existing.is_active;
            v_result.created_at             := v_existing.created_at;
            v_result.updated_at             := v_existing.updated_at;
RETURN v_result;
END IF;

        -- 6. INSERT
INSERT INTO hr.person (
    tax_id,
    given_names,
    father_last_name,
    mother_last_name,
    full_name,
    gender,
    birth_date,
    nationality,
    marital_status,
    blood_type,
    email,
    phone_mobile,
    phone_home,
    emergency_contact_name,
    emergency_contact_phone,
    photo_url,
    is_active
)
VALUES (
           TRIM(p_input.tax_id),
           TRIM(p_input.given_names),
           TRIM(p_input.father_last_name),
           TRIM(p_input.mother_last_name),
           v_full_name,
           p_input.gender,
           p_input.birth_date,
           p_input.nationality,
           p_input.marital_status,
           p_input.blood_type,
           p_input.email,
           p_input.phone_mobile,
           p_input.phone_home,
           p_input.emergency_contact_name,
           p_input.emergency_contact_phone,
           p_input.photo_url,
           TRUE
       )
    RETURNING person_id INTO v_result.person_id;

v_result.person_status   := 'INSERTED';
        v_result.already_existed := FALSE;

END IF;

    -- ── Poblar resultado leyendo desde BD ─────────────────────────────────
SELECT
    p.person_id,
    p.tax_id,
    p.given_names,
    p.father_last_name,
    p.mother_last_name,
    p.full_name,
    p.gender,
    p.birth_date,
    p.nationality,
    p.marital_status,
    p.blood_type,
    p.email,
    p.phone_mobile,
    p.phone_home,
    p.emergency_contact_name,
    p.emergency_contact_phone,
    p.photo_url,
    p.is_active,
    p.created_at,
    p.updated_at
INTO
    v_result.person_id,
    v_result.tax_id,
    v_result.given_names,
    v_result.father_last_name,
    v_result.mother_last_name,
    v_result.full_name,
    v_result.gender,
    v_result.birth_date,
    v_result.nationality,
    v_result.marital_status,
    v_result.blood_type,
    v_result.email,
    v_result.phone_mobile,
    v_result.phone_home,
    v_result.emergency_contact_name,
    v_result.emergency_contact_phone,
    v_result.photo_url,
    v_result.is_active,
    v_result.created_at,
    v_result.updated_at
FROM hr.person p
WHERE p.person_id = COALESCE(p_input.person_id, v_result.person_id);

v_result.success     := TRUE;
    v_result.tax_id_type := p_input.tax_id_type;   -- no persiste en tabla, refleja el enviado

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        -- Race condition en INSERT: tax_id insertado concurrentemente
SELECT * INTO v_existing FROM hr.person WHERE tax_id = p_input.tax_id;
v_result.success                 := TRUE;
        v_result.person_status           := 'INSERTED';
        v_result.already_existed         := TRUE;
        v_result.tax_id_type             := p_input.tax_id_type;
        v_result.person_id               := v_existing.person_id;
        v_result.tax_id                  := v_existing.tax_id;
        v_result.given_names             := v_existing.given_names;
        v_result.father_last_name        := v_existing.father_last_name;
        v_result.mother_last_name        := v_existing.mother_last_name;
        v_result.full_name               := v_existing.full_name;
        v_result.gender                  := v_existing.gender;
        v_result.birth_date              := v_existing.birth_date;
        v_result.nationality             := v_existing.nationality;
        v_result.marital_status          := v_existing.marital_status;
        v_result.blood_type              := v_existing.blood_type;
        v_result.email                   := v_existing.email;
        v_result.phone_mobile            := v_existing.phone_mobile;
        v_result.phone_home              := v_existing.phone_home;
        v_result.emergency_contact_name  := v_existing.emergency_contact_name;
        v_result.emergency_contact_phone := v_existing.emergency_contact_phone;
        v_result.photo_url               := v_existing.photo_url;
        v_result.is_active               := v_existing.is_active;
        v_result.created_at              := v_existing.created_at;
        v_result.updated_at              := v_existing.updated_at;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$_$;


--
-- Name: upsert_person_address(api.upsert_person_address_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_person_address(p_input api.upsert_person_address_input) RETURNS api.upsert_person_address_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                    api.upsert_person_address_result;
    v_existing                  hr.person_address%ROWTYPE;
    v_rows_affected             INT;
    v_previous_primary_unset    BOOLEAN := FALSE;
    v_has_changes               BOOLEAN;
    v_is_primary                BOOLEAN;
    v_country                   VARCHAR(50);
    -- Valores efectivos para validación de coordenadas en UPDATE
    v_eff_lat                   DECIMAL(10,8);
    v_eff_lon                   DECIMAL(11,8);
BEGIN

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: address_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.address_id IS NOT NULL THEN

        -- 1. La dirección existe
SELECT * INTO v_existing
FROM hr.person_address
WHERE address_id = p_input.address_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ADDRESS_NOT_FOUND';
            v_result.error_message := 'address_id=' || p_input.address_id || ' no existe';
RETURN v_result;
END IF;

        -- 2. address_type válido si viene
        IF p_input.address_type IS NOT NULL THEN
            IF TRIM(p_input.address_type) = ''
               OR p_input.address_type NOT IN ('HOME', 'WORK', 'TEMPORARY')
            THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_ADDRESS_TYPE';
                v_result.error_message := 'address_type inválido: "' || p_input.address_type
                                          || '". Válidos: HOME, WORK, TEMPORARY';
RETURN v_result;
END IF;
END IF;

        -- 3. address_line1 no vacío si viene
        IF p_input.address_line1 IS NOT NULL AND TRIM(p_input.address_line1) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ADDRESS_LINE1_REQUIRED';
            v_result.error_message := 'address_line1 no puede ser una cadena vacía';
RETURN v_result;
END IF;

        -- 4. Validar coherencia de coordenadas considerando estado final
        --    (nuevo payload combinado con lo que ya hay en BD)
        v_eff_lat := COALESCE(p_input.latitude,  v_existing.latitude);
        v_eff_lon := COALESCE(p_input.longitude, v_existing.longitude);

        IF (v_eff_lat IS NULL) <> (v_eff_lon IS NULL) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INCOMPLETE_COORDINATES';
            v_result.error_message := 'El estado final tendría latitud sin longitud o viceversa. '
                                      || 'Envíe ambas coordenadas juntas o ninguna';
RETURN v_result;
END IF;

        IF v_eff_lat IS NOT NULL THEN
            IF v_eff_lat < -90 OR v_eff_lat > 90 THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_LATITUDE';
                v_result.error_message := 'Latitud fuera de rango: ' || v_eff_lat::TEXT
                                          || '. Debe estar entre -90 y 90';
RETURN v_result;
END IF;
            IF v_eff_lon < -180 OR v_eff_lon > 180 THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_LONGITUDE';
                v_result.error_message := 'Longitud fuera de rango: ' || v_eff_lon::TEXT
                                          || '. Debe estar entre -180 y 180';
RETURN v_result;
END IF;
END IF;

        -- 5. Detectar cambios reales (PATCH semántico)
        v_has_changes :=
            (p_input.address_type IS NOT NULL AND p_input.address_type  IS DISTINCT FROM v_existing.address_type)  OR
            (p_input.address_line1 IS NOT NULL AND TRIM(p_input.address_line1) IS DISTINCT FROM v_existing.address_line1) OR
            (p_input.address_line2 IS NOT NULL AND p_input.address_line2 IS DISTINCT FROM v_existing.address_line2) OR
            (p_input.district      IS NOT NULL AND p_input.district      IS DISTINCT FROM v_existing.district)      OR
            (p_input.city          IS NOT NULL AND p_input.city          IS DISTINCT FROM v_existing.city)          OR
            (p_input.state         IS NOT NULL AND p_input.state         IS DISTINCT FROM v_existing.state)         OR
            (p_input.postal_code   IS NOT NULL AND p_input.postal_code   IS DISTINCT FROM v_existing.postal_code)   OR
            (p_input.country       IS NOT NULL AND p_input.country       IS DISTINCT FROM v_existing.country)       OR
            (p_input.latitude      IS NOT NULL AND p_input.latitude      IS DISTINCT FROM v_existing.latitude)      OR
            (p_input.longitude     IS NOT NULL AND p_input.longitude     IS DISTINCT FROM v_existing.longitude)     OR
            (p_input.is_primary    IS NOT NULL AND p_input.is_primary    IS DISTINCT FROM v_existing.is_primary)    OR
            (p_input.is_active     IS NOT NULL AND p_input.is_active     IS DISTINCT FROM v_existing.is_active);

        IF v_has_changes THEN

            -- 6. Gestión de is_primary en UPDATE
            --    Si se quiere marcar como principal y aún no lo era:
            --    desmarcar la principal actual de la persona (si existe una distinta)
            IF p_input.is_primary = TRUE AND v_existing.is_primary = FALSE THEN
UPDATE hr.person_address
SET is_primary = FALSE,
    updated_at = NOW()
WHERE person_id  = v_existing.person_id
  AND is_primary = TRUE
  AND address_id <> p_input.address_id;

GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
v_previous_primary_unset := (v_rows_affected > 0);
END IF;

            -- 7. Si se quiere desmarcar como principal (is_primary=FALSE) y era principal
            --    Se permite: la persona quedará sin dirección principal (válido en el modelo)
            -- (no requiere acción adicional, el UPDATE siguiente lo hace)

UPDATE hr.person_address
SET address_type  = COALESCE(p_input.address_type,               address_type),
    address_line1 = COALESCE(NULLIF(TRIM(p_input.address_line1), ''), address_line1),
    address_line2 = COALESCE(p_input.address_line2,               address_line2),
    district      = COALESCE(p_input.district,                    district),
    city          = COALESCE(p_input.city,                        city),
    state         = COALESCE(p_input.state,                       state),
    postal_code   = COALESCE(p_input.postal_code,                 postal_code),
    country       = COALESCE(p_input.country,                     country),
    latitude      = COALESCE(p_input.latitude,                    latitude),
    longitude     = COALESCE(p_input.longitude,                   longitude),
    is_primary    = COALESCE(p_input.is_primary,                  is_primary),
    is_active     = COALESCE(p_input.is_active,                   is_active),
    updated_at    = NOW()
WHERE address_id = p_input.address_id;

v_result.address_status := 'UPDATED';
ELSE
            v_result.address_status := 'SKIPPED';
END IF;

        -- Poblar person_id desde el existente (no viene en UPDATE input)
        v_result.person_id := v_existing.person_id;

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA INSERT: address_id es NULL
    -- ══════════════════════════════════════════════════════════════════════
ELSE

        -- 1. person_id obligatorio
        IF p_input.person_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_PERSON_ID';
            v_result.error_message := 'person_id es obligatorio al crear una dirección';
RETURN v_result;
END IF;

        -- 2. Persona existe
        IF NOT EXISTS (
            SELECT 1 FROM hr.person WHERE person_id = p_input.person_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'PERSON_NOT_FOUND';
            v_result.error_message := 'person_id=' || p_input.person_id || ' no existe';
RETURN v_result;
END IF;

        -- 3. address_type obligatorio y válido
        IF p_input.address_type IS NULL
           OR TRIM(p_input.address_type) = ''
           OR p_input.address_type NOT IN ('HOME', 'WORK', 'TEMPORARY')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_ADDRESS_TYPE';
            v_result.error_message := 'address_type inválido: "'
                                      || COALESCE(p_input.address_type, 'NULL')
                                      || '". Válidos: HOME, WORK, TEMPORARY';
RETURN v_result;
END IF;

        -- 4. address_line1 obligatorio
        IF p_input.address_line1 IS NULL OR TRIM(p_input.address_line1) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ADDRESS_LINE1_REQUIRED';
            v_result.error_message := 'address_line1 es obligatorio y no puede estar vacío';
RETURN v_result;
END IF;

        -- 5. Coordenadas: ambas o ninguna
        IF (p_input.latitude IS NULL) <> (p_input.longitude IS NULL) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INCOMPLETE_COORDINATES';
            v_result.error_message := 'Debe proveer latitude y longitude juntas, o ninguna. '
                                      || 'Latitud: ' || COALESCE(p_input.latitude::TEXT, 'NULL')
                                      || ', Longitud: ' || COALESCE(p_input.longitude::TEXT, 'NULL');
RETURN v_result;
END IF;

        -- 6. Rango de latitud
        IF p_input.latitude IS NOT NULL
           AND (p_input.latitude < -90 OR p_input.latitude > 90)
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_LATITUDE';
            v_result.error_message := 'Latitud fuera de rango: ' || p_input.latitude::TEXT
                                      || '. Debe estar entre -90 y 90';
RETURN v_result;
END IF;

        -- 7. Rango de longitud
        IF p_input.longitude IS NOT NULL
           AND (p_input.longitude < -180 OR p_input.longitude > 180)
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_LONGITUDE';
            v_result.error_message := 'Longitud fuera de rango: ' || p_input.longitude::TEXT
                                      || '. Debe estar entre -180 y 180';
RETURN v_result;
END IF;

        -- 8. Resolver defaults para INSERT
        v_is_primary := COALESCE(p_input.is_primary, FALSE);
        v_country    := COALESCE(NULLIF(TRIM(COALESCE(p_input.country, '')), ''), 'PE');

        -- 9. Si is_primary=TRUE: desmarcar principal previa de la persona
        IF v_is_primary = TRUE THEN
UPDATE hr.person_address
SET is_primary = FALSE,
    updated_at = NOW()
WHERE person_id  = p_input.person_id
  AND is_primary = TRUE;

GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
v_previous_primary_unset := (v_rows_affected > 0);
END IF;

        -- 10. INSERT
INSERT INTO hr.person_address (
    person_id,
    address_type,
    address_line1,
    address_line2,
    district,
    city,
    state,
    postal_code,
    country,
    latitude,
    longitude,
    is_primary,
    is_active
)
VALUES (
           p_input.person_id,
           p_input.address_type,
           TRIM(p_input.address_line1),
           p_input.address_line2,
           p_input.district,
           p_input.city,
           p_input.state,
           p_input.postal_code,
           v_country,
           p_input.latitude,
           p_input.longitude,
           v_is_primary,
           TRUE
       )
    RETURNING address_id INTO p_input.address_id;

v_result.address_status := 'INSERTED';
        v_result.person_id      := p_input.person_id;

END IF;

    -- ── Poblar resultado desde BD ─────────────────────────────────────────
SELECT
    a.address_id,
    a.person_id,
    a.address_type,
    a.address_line1,
    a.address_line2,
    a.district,
    a.city,
    a.state,
    a.postal_code,
    a.country,
    a.latitude,
    a.longitude,
    a.is_primary,
    a.is_active,
    a.created_at,
    a.updated_at
INTO
    v_result.address_id,
    v_result.person_id,
    v_result.address_type,
    v_result.address_line1,
    v_result.address_line2,
    v_result.district,
    v_result.city,
    v_result.state,
    v_result.postal_code,
    v_result.country,
    v_result.latitude,
    v_result.longitude,
    v_result.is_primary,
    v_result.is_active,
    v_result.created_at,
    v_result.updated_at
FROM hr.person_address a
WHERE a.address_id = p_input.address_id;

v_result.success                := TRUE;
    v_result.previous_primary_unset := v_previous_primary_unset;

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'PRIMARY_ADDRESS_CONFLICT';
        v_result.error_message := 'Conflicto de concurrencia al establecer dirección principal. '
                                  || 'Intente nuevamente';
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_person_document(api.upsert_person_document_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_person_document(p_input api.upsert_person_document_input) RETURNS api.upsert_person_document_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.upsert_person_document_result;
    v_doc_type          shared.document_type%ROWTYPE;
    v_doc_id            BIGINT;
    v_operation         VARCHAR(10);
    v_status            VARCHAR(20);
    v_verified_at       TIMESTAMPTZ;
    v_days_until_expiry INT;
    v_expiring_soon     BOOLEAN := FALSE;
BEGIN

    -- ── Validación 1: persona existe ──────────────────────────────────────
    IF NOT EXISTS (
        SELECT 1 FROM hr.person WHERE person_id = p_input.person_id
    ) THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'PERSON_NOT_FOUND';
        v_result.error_message := 'La persona person_id=' || p_input.person_id || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 2: tipo de documento existe y está activo ──────────────
SELECT * INTO v_doc_type
FROM shared.document_type
WHERE document_type_id = p_input.document_type_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DOCUMENT_TYPE_NOT_FOUND';
        v_result.error_message := 'El document_type_id=' || p_input.document_type_id
                                  || ' no existe';
RETURN v_result;
END IF;

    IF v_doc_type.is_active = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DOCUMENT_TYPE_NOT_FOUND';
        v_result.error_message := 'El tipo de documento "' || v_doc_type.code
                                  || '" está inactivo y no puede usarse';
RETURN v_result;
END IF;

    -- ── Validación 3: expiry_date obligatoria si requires_expiry = true ───
    IF v_doc_type.requires_expiry = TRUE AND p_input.expiry_date IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'EXPIRY_DATE_REQUIRED';
        v_result.error_message := 'El tipo de documento "' || v_doc_type.name
                                  || '" requiere fecha de vencimiento (requires_expiry=true)';
RETURN v_result;
END IF;

    -- ── Validación 4: rango de fechas coherente ───────────────────────────
    IF p_input.issue_date IS NOT NULL
       AND p_input.expiry_date IS NOT NULL
       AND p_input.expiry_date <= p_input.issue_date THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DATE_RANGE';
        v_result.error_message := 'expiry_date (' || p_input.expiry_date::TEXT
                                  || ') debe ser posterior a issue_date ('
                                  || p_input.issue_date::TEXT || ')';
RETURN v_result;
END IF;

    -- ── Validación 5: status dentro del dominio ───────────────────────────
    v_status := COALESCE(p_input.status, 'VALID');

    IF v_status NOT IN ('VALID', 'EXPIRED', 'PENDING', 'REJECTED') THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DOCUMENT_STATUS';
        v_result.error_message := 'status inválido: "' || v_status
                                  || '". Válidos: VALID, EXPIRED, PENDING, REJECTED';
RETURN v_result;
END IF;

    -- ── Validación 6: verificador existe si se proporcionó ─────────────────
    IF p_input.verified_by IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM identity.user
            WHERE user_id = p_input.verified_by
              AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'VERIFIER_NOT_FOUND';
            v_result.error_message := 'El verificador user_id=' || p_input.verified_by
                                      || ' no existe o está inactivo';
RETURN v_result;
END IF;

        v_verified_at := NOW();
END IF;

    -- ── Calcular días hasta vencimiento y flag expiring_soon ──────────────
    IF p_input.expiry_date IS NOT NULL THEN

        v_days_until_expiry := (p_input.expiry_date - CURRENT_DATE);

        IF v_doc_type.alert_days_before IS NOT NULL
           AND v_days_until_expiry <= v_doc_type.alert_days_before
           AND v_days_until_expiry >= 0 THEN
            v_expiring_soon := TRUE;
END IF;

        -- Auto-detectar EXPIRED si la fecha ya pasó y el status enviado era VALID
        IF p_input.expiry_date < CURRENT_DATE AND v_status = 'VALID' THEN
            v_status := 'EXPIRED';
END IF;

END IF;

    -- ── UPSERT: INSERT o UPDATE según si ya existe el tipo para esa persona
INSERT INTO hr.person_document (
    person_id,
    document_type_id,
    document_number,
    issuing_entity,
    issue_date,
    expiry_date,
    file_id,
    status,
    verified_by,
    verified_at,
    notes
)
VALUES (
           p_input.person_id,
           p_input.document_type_id,
           p_input.document_number,
           p_input.issuing_entity,
           p_input.issue_date,
           p_input.expiry_date,
           p_input.file_id,
           v_status,
           p_input.verified_by,
           v_verified_at,
           p_input.notes
       )
    ON CONFLICT (person_id, document_type_id)
    DO UPDATE SET
    document_number = EXCLUDED.document_number,
               issuing_entity  = EXCLUDED.issuing_entity,
               issue_date      = EXCLUDED.issue_date,
               expiry_date     = EXCLUDED.expiry_date,
               file_id         = COALESCE(EXCLUDED.file_id, hr.person_document.file_id),
               status          = EXCLUDED.status,
               verified_by     = EXCLUDED.verified_by,
               verified_at     = CASE
               WHEN EXCLUDED.verified_by IS NOT NULL THEN NOW()
               ELSE hr.person_document.verified_at
END,
        notes           = COALESCE(EXCLUDED.notes, hr.person_document.notes),
        updated_at      = NOW()
    RETURNING
        person_document_id,
        CASE
            WHEN xmax = 0 THEN 'INSERTED'   -- xmax=0 significa que fue un INSERT puro
            ELSE 'UPDATED'
END
INTO v_doc_id, v_operation;

    -- ── Poblar resultado campo a campo ────────────────────────────────────
SELECT
    pd.person_document_id,
    pd.person_id,
    pd.document_type_id,
    pd.document_number,
    pd.issue_date,
    pd.expiry_date,
    pd.status,
    pd.verified_by,
    pd.verified_at,
    pd.created_at,
    pd.updated_at
INTO
    v_result.person_document_id,
    v_result.person_id,
    v_result.document_type_id,
    v_result.document_number,
    v_result.issue_date,
    v_result.expiry_date,
    v_result.status,
    v_result.verified_by,
    v_result.verified_at,
    v_result.created_at,
    v_result.updated_at
FROM hr.person_document pd
WHERE pd.person_document_id = v_doc_id;

v_result.success           := TRUE;
    v_result.operation         := v_operation;
    v_result.document_type_code := v_doc_type.code;
    v_result.document_type_name := v_doc_type.name;
    v_result.restriction_type  := v_doc_type.restriction_type;
    v_result.alert_days_before := v_doc_type.alert_days_before;
    v_result.expiring_soon     := v_expiring_soon;
    v_result.days_until_expiry := v_days_until_expiry;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_personnel(api.upsert_personnel_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_personnel(p_input api.upsert_personnel_input) RETURNS api.upsert_personnel_result
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result                api.upsert_personnel_result;
    v_existing              hr.personnel%ROWTYPE;
    v_personnel_id          INT;
    v_employee_code         VARCHAR(20);
    v_code_was_generated    BOOLEAN := FALSE;
    v_employment_status     VARCHAR(20);
    v_has_changes           BOOLEAN;
    v_max_future_days       INT;
    v_cfg_value             TEXT;
    v_job_title_valid       BOOLEAN;

    v_valid_job_titles      TEXT[] := ARRAY[
        'DISPATCHER', 'CASHIER', 'MECHANIC', 'ADMIN_ASSISTANT',
        'MANAGER', 'ACCOUNTANT', 'HR_STAFF', 'ADMIN', 'SUPERVISOR',
        'INSPECTOR', 'COORDINATOR', 'ANALYST'
        ];
BEGIN

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: personnel_id NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.personnel_id IS NOT NULL THEN

        -- 1. Registro existe
        SELECT * INTO v_existing
        FROM hr.personnel
        WHERE personnel_id = p_input.personnel_id;

        IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'PERSONNEL_NOT_FOUND';
            v_result.error_message := 'personnel_id=' || p_input.personnel_id || ' no existe';
            RETURN v_result;
        END IF;

        -- 2. job_title si cambia
        IF p_input.job_title IS NOT NULL THEN
            IF TRIM(p_input.job_title) = '' THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_JOB_TITLE';
                v_result.error_message := 'job_title no puede ser una cadena vacía';
                RETURN v_result;
            END IF;

            v_job_title_valid := (
                UPPER(TRIM(p_input.job_title)) = ANY(v_valid_job_titles)
                    OR EXISTS (
                    SELECT 1 FROM shared.catalog
                    WHERE category  = 'job_title'
                      AND code      = UPPER(TRIM(p_input.job_title))
                      AND is_active = TRUE
                )
                );

            IF NOT v_job_title_valid THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_JOB_TITLE';
                v_result.error_message := 'job_title inválido: "' || p_input.job_title
                                              || '". Valores base: '
                    || ARRAY_TO_STRING(v_valid_job_titles, ', ');
                RETURN v_result;
            END IF;
        END IF;

        -- 3. employment_type si viene
        IF p_input.employment_type IS NOT NULL
            AND TRIM(p_input.employment_type) <> ''
            AND p_input.employment_type NOT IN ('FULL_TIME', 'PART_TIME', 'CONTRACT')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_TYPE';
            v_result.error_message := 'employment_type inválido: "' || p_input.employment_type
                || '". Válidos: FULL_TIME, PART_TIME, CONTRACT';
            RETURN v_result;
        END IF;

        -- 4. employment_status si viene
        IF p_input.employment_status IS NOT NULL
            AND p_input.employment_status NOT IN ('ACTIVE', 'SUSPENDED', 'TERMINATED')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_STATUS';
            v_result.error_message := 'employment_status inválido: "' || p_input.employment_status
                || '". Válidos: ACTIVE, SUSPENDED, TERMINATED';
            RETURN v_result;
        END IF;

        -- 5. hire_date si viene
        IF p_input.hire_date IS NOT NULL THEN
            SELECT value INTO v_cfg_value
            FROM shared.configuration WHERE key = 'hr.max_future_hire_days';
            BEGIN
                v_max_future_days := COALESCE(NULLIF(TRIM(v_cfg_value), ''), '30')::INT;
            EXCEPTION WHEN OTHERS THEN
                v_max_future_days := 30;
            END;

            IF p_input.hire_date > CURRENT_DATE + (v_max_future_days || ' days')::INTERVAL THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'HIRE_DATE_TOO_FAR_FUTURE';
                v_result.error_message := 'hire_date (' || p_input.hire_date::TEXT
                                              || ') supera el máximo de '
                                              || v_max_future_days || ' días en el futuro';
                RETURN v_result;
            END IF;
        END IF;

        -- 6. user_id si cambia
        IF p_input.user_id IS NOT NULL
            AND p_input.user_id IS DISTINCT FROM v_existing.user_id
        THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id  = p_input.user_id
                  AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_NOT_FOUND';
                v_result.error_message := 'user_id=' || p_input.user_id
                    || ' no existe o está inactivo';
                RETURN v_result;
            END IF;

            IF EXISTS (
                SELECT 1 FROM hr.personnel
                WHERE user_id      = p_input.user_id
                  AND personnel_id <> p_input.personnel_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_ALREADY_LINKED';
                v_result.error_message := 'user_id=' || p_input.user_id
                    || ' ya está vinculado a otro registro de personal';
                RETURN v_result;
            END IF;
        END IF;

        -- 7. employee_code si cambia
        IF p_input.employee_code IS NOT NULL
            AND TRIM(p_input.employee_code) <> ''
            AND TRIM(p_input.employee_code) <> v_existing.employee_code
        THEN
            IF EXISTS (
                SELECT 1 FROM hr.personnel
                WHERE employee_code = TRIM(p_input.employee_code)
                  AND personnel_id  <> p_input.personnel_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_EMPLOYEE_CODE';
                v_result.error_message := 'employee_code "' || TRIM(p_input.employee_code)
                    || '" ya está en uso por otro registro';
                RETURN v_result;
            END IF;
        END IF;

        -- 8. Detectar cambios reales
        v_has_changes :=
                (p_input.job_title          IS NOT NULL AND UPPER(TRIM(p_input.job_title)) IS DISTINCT FROM v_existing.job_title)          OR
                (p_input.department         IS NOT NULL AND p_input.department              IS DISTINCT FROM v_existing.department)         OR
                (p_input.hire_date          IS NOT NULL AND p_input.hire_date               IS DISTINCT FROM v_existing.hire_date)          OR
                (p_input.termination_date   IS NOT NULL AND p_input.termination_date        IS DISTINCT FROM v_existing.termination_date)   OR
                (p_input.employment_type    IS NOT NULL AND p_input.employment_type         IS DISTINCT FROM v_existing.employment_type)    OR
                (p_input.employment_status  IS NOT NULL AND p_input.employment_status       IS DISTINCT FROM v_existing.employment_status)  OR
                (p_input.base_salary        IS NOT NULL AND p_input.base_salary             IS DISTINCT FROM v_existing.base_salary)        OR
                (p_input.work_schedule      IS NOT NULL AND p_input.work_schedule           IS DISTINCT FROM v_existing.work_schedule)      OR
                (p_input.notes              IS NOT NULL AND p_input.notes                   IS DISTINCT FROM v_existing.notes)              OR
                (p_input.user_id            IS NOT NULL AND p_input.user_id                 IS DISTINCT FROM v_existing.user_id)            OR
                (p_input.employee_code      IS NOT NULL AND TRIM(p_input.employee_code)     IS DISTINCT FROM v_existing.employee_code);

        IF v_has_changes THEN
            UPDATE hr.personnel
            SET job_title         = COALESCE(NULLIF(UPPER(TRIM(p_input.job_title)), ''),  job_title),
                department        = COALESCE(p_input.department,                           department),
                hire_date         = COALESCE(p_input.hire_date,                            hire_date),
                termination_date  = COALESCE(p_input.termination_date,                     termination_date),
                employment_type   = COALESCE(p_input.employment_type,                      employment_type),
                employment_status = COALESCE(p_input.employment_status,                    employment_status),
                base_salary       = COALESCE(p_input.base_salary,                          base_salary),
                work_schedule     = COALESCE(p_input.work_schedule,                        work_schedule),
                notes             = COALESCE(p_input.notes,                                notes),
                user_id           = COALESCE(p_input.user_id,                              user_id),
                employee_code     = COALESCE(NULLIF(TRIM(p_input.employee_code), ''),      employee_code),
                updated_at        = NOW()
            WHERE personnel_id = p_input.personnel_id;

            v_result.personnel_status := 'UPDATED';
        ELSE
            v_result.personnel_status := 'SKIPPED';
        END IF;

        v_personnel_id       := p_input.personnel_id;
        v_code_was_generated := FALSE;


        -- ══════════════════════════════════════════════════════════════════════
        -- RAMA INSERT: personnel_id es NULL
        -- ══════════════════════════════════════════════════════════════════════
    ELSE

        -- 1. person_id obligatorio
        IF p_input.person_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_PERSON_ID';
            v_result.error_message := 'person_id es obligatorio al registrar personal';
            RETURN v_result;
        END IF;

        -- 2. person existe
        IF NOT EXISTS (
            SELECT 1 FROM hr.person WHERE person_id = p_input.person_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'PERSON_NOT_FOUND';
            v_result.error_message := 'person_id=' || p_input.person_id || ' no existe';
            RETURN v_result;
        END IF;

        -- 3. person no tiene ya un registro de personal
        IF EXISTS (
            SELECT 1 FROM hr.personnel WHERE person_id = p_input.person_id
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'PERSONNEL_ALREADY_EXISTS';
            v_result.error_message := 'La persona person_id=' || p_input.person_id
                || ' ya tiene un registro en hr.personnel';
            RETURN v_result;
        END IF;

        -- 4. company_id obligatorio y activa
        IF p_input.company_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_COMPANY_ID';
            v_result.error_message := 'company_id es obligatorio al registrar personal';
            RETURN v_result;
        END IF;

        IF NOT EXISTS (
            SELECT 1 FROM shared.company
            WHERE company_id = p_input.company_id AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COMPANY_NOT_FOUND';
            v_result.error_message := 'company_id=' || p_input.company_id
                || ' no existe o está inactiva';
            RETURN v_result;
        END IF;

        -- 5. hire_date obligatorio
        IF p_input.hire_date IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'HIRE_DATE_REQUIRED';
            v_result.error_message := 'hire_date es obligatorio al registrar personal';
            RETURN v_result;
        END IF;

        SELECT value INTO v_cfg_value
        FROM shared.configuration WHERE key = 'hr.max_future_hire_days';
        BEGIN
            v_max_future_days := COALESCE(NULLIF(TRIM(v_cfg_value), ''), '30')::INT;
        EXCEPTION WHEN OTHERS THEN
            v_max_future_days := 30;
        END;

        IF p_input.hire_date > CURRENT_DATE + (v_max_future_days || ' days')::INTERVAL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'HIRE_DATE_TOO_FAR_FUTURE';
            v_result.error_message := 'hire_date (' || p_input.hire_date::TEXT
                                          || ') supera el máximo de ' || v_max_future_days
                || ' días en el futuro';
            RETURN v_result;
        END IF;

        -- 6. job_title obligatorio y válido
        IF p_input.job_title IS NULL OR TRIM(p_input.job_title) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_JOB_TITLE';
            v_result.error_message := 'job_title es obligatorio al registrar personal';
            RETURN v_result;
        END IF;

        v_job_title_valid := (
            UPPER(TRIM(p_input.job_title)) = ANY(v_valid_job_titles)
                OR EXISTS (
                SELECT 1 FROM shared.catalog
                WHERE category  = 'job_title'
                  AND code      = UPPER(TRIM(p_input.job_title))
                  AND is_active = TRUE
            )
            );

        IF NOT v_job_title_valid THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_JOB_TITLE';
            v_result.error_message := 'job_title inválido: "' || p_input.job_title
                                          || '". Valores base: '
                || ARRAY_TO_STRING(v_valid_job_titles, ', ');
            RETURN v_result;
        END IF;

        -- 7. employment_type si viene
        IF p_input.employment_type IS NOT NULL
            AND TRIM(p_input.employment_type) <> ''
            AND p_input.employment_type NOT IN ('FULL_TIME', 'PART_TIME', 'CONTRACT')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_TYPE';
            v_result.error_message := 'employment_type inválido: "' || p_input.employment_type
                || '". Válidos: FULL_TIME, PART_TIME, CONTRACT';
            RETURN v_result;
        END IF;

        -- 8. employment_status (default ACTIVE)
        v_employment_status := COALESCE(
                NULLIF(TRIM(COALESCE(p_input.employment_status, '')), ''),
                'ACTIVE'
                               );

        IF v_employment_status NOT IN ('ACTIVE', 'SUSPENDED', 'TERMINATED') THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_EMPLOYMENT_STATUS';
            v_result.error_message := 'employment_status inválido: "' || v_employment_status
                || '". Válidos: ACTIVE, SUSPENDED, TERMINATED';
            RETURN v_result;
        END IF;

        -- 9. user_id si viene
        IF p_input.user_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id  = p_input.user_id
                  AND is_active = TRUE
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_NOT_FOUND';
                v_result.error_message := 'user_id=' || p_input.user_id
                    || ' no existe o está inactivo';
                RETURN v_result;
            END IF;

            IF EXISTS (
                SELECT 1 FROM hr.personnel WHERE user_id = p_input.user_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'USER_ALREADY_LINKED';
                v_result.error_message := 'user_id=' || p_input.user_id
                    || ' ya está vinculado a otro registro de personal';
                RETURN v_result;
            END IF;
        END IF;

        -- 10. employee_code: manual o autogenerado
        IF p_input.employee_code IS NOT NULL AND TRIM(p_input.employee_code) <> '' THEN
            IF EXISTS (
                SELECT 1 FROM hr.personnel
                WHERE employee_code = TRIM(p_input.employee_code)
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_EMPLOYEE_CODE';
                v_result.error_message := 'employee_code "' || TRIM(p_input.employee_code)
                    || '" ya está en uso';
                RETURN v_result;
            END IF;
            v_employee_code      := TRIM(p_input.employee_code);
            v_code_was_generated := FALSE;
        ELSE
            v_employee_code      := api._generate_employee_code();
            v_code_was_generated := TRUE;
        END IF;

        -- 11. INSERT
        INSERT INTO hr.personnel (
            person_id, company_id, user_id, employee_code,
            job_title, department, hire_date,
            employment_type, employment_status,
            base_salary, work_schedule, notes
        )
        VALUES (
                   p_input.person_id,
                   p_input.company_id,
                   p_input.user_id,
                   v_employee_code,
                   UPPER(TRIM(p_input.job_title)),
                   p_input.department,
                   p_input.hire_date,
                   p_input.employment_type,
                   v_employment_status,
                   p_input.base_salary,
                   p_input.work_schedule,
                   p_input.notes
               )
        RETURNING personnel_id INTO v_personnel_id;

        v_result.personnel_status := 'INSERTED';

    END IF;

    -- ── Poblar resultado desde BD ─────────────────────────────────────────
    SELECT
        pe.personnel_id, pe.person_id, pe.company_id, pe.user_id,
        pe.employee_code, pe.job_title, pe.department,
        pe.employment_type, pe.employment_status,
        pe.hire_date, pe.termination_date,
        pe.base_salary, pe.work_schedule,
        pe.created_at, pe.updated_at,
        p.full_name, p.tax_id
    INTO
        v_result.personnel_id, v_result.person_id, v_result.company_id, v_result.user_id,
        v_result.employee_code, v_result.job_title, v_result.department,
        v_result.employment_type, v_result.employment_status,
        v_result.hire_date, v_result.termination_date,
        v_result.base_salary, v_result.work_schedule,
        v_result.created_at, v_result.updated_at,
        v_result.full_name, v_result.tax_id
    FROM hr.personnel pe
             JOIN hr.person p ON p.person_id = pe.person_id
    WHERE pe.personnel_id = v_personnel_id;

    v_result.success                     := TRUE;
    v_result.employee_code_was_generated := v_code_was_generated;

    RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_EMPLOYEE_CODE';
        v_result.error_message := 'Conflicto de unicidad por concurrencia: ' || SQLERRM;
        RETURN v_result;
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        RETURN v_result;
END;
$$;


--
-- Name: upsert_role(api.upsert_role_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_role(p_input api.upsert_role_input) RETURNS api.upsert_role_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.upsert_role_result;
    v_existing              identity.role%ROWTYPE;
    v_template_name         VARCHAR(100);
    v_template_active       BOOLEAN;
    v_permissions_cloned    INT := 0;
    v_has_changes           BOOLEAN;
BEGIN

    -- ══════════════════════════════════════════════════════════
    -- RAMA INSERT: role_id es NULL
    -- ══════════════════════════════════════════════════════════
    IF p_input.role_id IS NULL THEN

        -- 1. tenant_id obligatorio
        IF p_input.tenant_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_TENANT_ID';
            v_result.error_message := 'tenant_id es obligatorio al crear un rol';
RETURN v_result;
END IF;

        -- 2. Tenant existe y está activo
        IF NOT EXISTS (
            SELECT 1 FROM identity.tenant
            WHERE tenant_id = p_input.tenant_id
              AND is_active  = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'TENANT_NOT_FOUND';
            v_result.error_message := 'tenant_id=' || p_input.tenant_id
                                      || ' no existe o está inactivo';
RETURN v_result;
END IF;

        -- 3. name obligatorio
        IF p_input.name IS NULL OR TRIM(p_input.name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_ROLE_NAME';
            v_result.error_message := 'name es obligatorio al crear un rol';
RETURN v_result;
END IF;

        -- 4. Nombre único dentro del tenant
        IF EXISTS (
            SELECT 1 FROM identity.role
            WHERE tenant_id = p_input.tenant_id
              AND name      = TRIM(p_input.name)
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DUPLICATE_ROLE_NAME';
            v_result.error_message := 'Ya existe un rol con el nombre "'
                                      || TRIM(p_input.name)
                                      || '" en tenant_id=' || p_input.tenant_id;
RETURN v_result;
END IF;

        -- 5. created_by existe si se proveyó
        IF p_input.created_by IS NOT NULL
           AND NOT EXISTS (
               SELECT 1 FROM identity."user"
               WHERE user_id = p_input.created_by
           )
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'CREATOR_NOT_FOUND';
            v_result.error_message := 'El user_id=' || p_input.created_by
                                      || ' indicado en created_by no existe';
RETURN v_result;
END IF;

        -- 6. Validar template si se pidió clonar
        IF p_input.clone_template_id IS NOT NULL THEN
SELECT name, is_active
INTO v_template_name, v_template_active
FROM identity.permission_template
WHERE template_id = p_input.clone_template_id;

IF NOT FOUND THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'TEMPLATE_NOT_FOUND';
                v_result.error_message := 'El permission_template id='
                                          || p_input.clone_template_id || ' no existe';
RETURN v_result;
END IF;

            IF v_template_active = FALSE THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'TEMPLATE_INACTIVE';
                v_result.error_message := 'El template "' || v_template_name
                                          || '" está inactivo y no puede usarse para clonar';
RETURN v_result;
END IF;
END IF;

        -- ── INSERT rol ────────────────────────────────────────────────────
INSERT INTO identity.role (
    tenant_id,
    name,
    description,
    is_active,
    created_by
)
VALUES (
           p_input.tenant_id,
           TRIM(p_input.name),
           p_input.description,
           COALESCE(p_input.is_active, TRUE),
           p_input.created_by
       )
    RETURNING role_id, tenant_id, name, description,
                  is_active, created_at, updated_at
INTO v_result.role_id, v_result.tenant_id, v_result.name,
    v_result.description, v_result.is_active,
    v_result.created_at, v_result.updated_at;

-- ── Clonar permisos del template si se indicó ─────────────────────
IF p_input.clone_template_id IS NOT NULL THEN
            INSERT INTO identity.role_permission (role_id, permission_id, is_active)
SELECT
    v_result.role_id,
    ptd.permission_id,
    TRUE
FROM identity.permission_template_detail ptd
         JOIN identity.permission p
              ON p.permission_id = ptd.permission_id
                  AND p.is_active     = TRUE
WHERE ptd.template_id = p_input.clone_template_id
    ON CONFLICT (role_id, permission_id) DO NOTHING;

GET DIAGNOSTICS v_permissions_cloned = ROW_COUNT;
END IF;

        v_result.role_status             := 'INSERTED';
        v_result.cloned_from_template_id := p_input.clone_template_id;
        v_result.cloned_from_template    := v_template_name;
        v_result.permissions_cloned      := v_permissions_cloned;
        v_result.warning                 := NULL;

    -- ══════════════════════════════════════════════════════════
    -- RAMA UPDATE: role_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════
ELSE

        -- 1. El rol existe
SELECT * INTO v_existing
FROM identity.role
WHERE role_id = p_input.role_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ROLE_NOT_FOUND';
            v_result.error_message := 'role_id=' || p_input.role_id || ' no existe';
RETURN v_result;
END IF;

        -- 2. name no vacío si viene
        IF p_input.name IS NOT NULL AND TRIM(p_input.name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_ROLE_NAME';
            v_result.error_message := 'name no puede ser una cadena vacía';
RETURN v_result;
END IF;

        -- 3. Nombre no duplicado en el tenant si cambia
        IF p_input.name IS NOT NULL
           AND TRIM(p_input.name) <> v_existing.name
        THEN
            IF EXISTS (
                SELECT 1 FROM identity.role
                WHERE tenant_id = v_existing.tenant_id
                  AND name      = TRIM(p_input.name)
                  AND role_id  <> p_input.role_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_ROLE_NAME';
                v_result.error_message := 'Ya existe otro rol con el nombre "'
                                          || TRIM(p_input.name)
                                          || '" en el mismo tenant';
RETURN v_result;
END IF;
END IF;

        -- 4. Detectar cambios reales (PATCH semántico)
        v_has_changes :=
            (p_input.name        IS NOT NULL AND TRIM(p_input.name) IS DISTINCT FROM v_existing.name)        OR
            (p_input.description IS NOT NULL AND p_input.description IS DISTINCT FROM v_existing.description) OR
            (p_input.is_active   IS NOT NULL AND p_input.is_active   IS DISTINCT FROM v_existing.is_active);

        IF v_has_changes THEN
UPDATE identity.role
SET name        = COALESCE(NULLIF(TRIM(p_input.name), ''), name),
    description = COALESCE(p_input.description,            description),
    is_active   = COALESCE(p_input.is_active,              is_active),
    updated_at  = NOW()
WHERE role_id = p_input.role_id
    RETURNING role_id, tenant_id, name, description,
                      is_active, created_at, updated_at
INTO v_result.role_id, v_result.tenant_id, v_result.name,
    v_result.description, v_result.is_active,
    v_result.created_at, v_result.updated_at;

v_result.role_status := 'UPDATED';
ELSE
            v_result.role_id     := v_existing.role_id;
            v_result.tenant_id   := v_existing.tenant_id;
            v_result.name        := v_existing.name;
            v_result.description := v_existing.description;
            v_result.is_active   := v_existing.is_active;
            v_result.created_at  := v_existing.created_at;
            v_result.updated_at  := v_existing.updated_at;
            v_result.role_status := 'SKIPPED';
END IF;

        -- 5. clone_template_id en UPDATE se ignora — advertir al caller
        v_result.cloned_from_template_id := NULL;
        v_result.cloned_from_template    := NULL;
        v_result.permissions_cloned      := 0;
        v_result.warning := CASE
            WHEN p_input.clone_template_id IS NOT NULL
            THEN 'clone_template_id=' || p_input.clone_template_id
                 || ' fue ignorado: el clonado de templates solo aplica en INSERT. '
                 || 'Para gestionar permisos de un rol existente use api.sync_role_permissions()'
            ELSE NULL
END;

END IF;

    v_result.success := TRUE;
RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_ROLE_NAME';
        v_result.error_message := 'Conflicto de unicidad concurrente: el nombre "'
                                  || TRIM(p_input.name)
                                  || '" fue tomado al mismo tiempo en este tenant';
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_route(api.upsert_route_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_route(p_input api.upsert_route_input) RETURNS api.upsert_route_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.upsert_route_result;
    v_existing          core_operations.route%ROWTYPE;
    v_has_changes       BOOLEAN;
    v_missing_fields    TEXT[] := ARRAY[]::TEXT[];
    v_company_id        INT;
    v_final_status      VARCHAR(10);
BEGIN

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: route_id NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.route_id IS NOT NULL THEN

        -- 1. La ruta existe
SELECT * INTO v_existing
FROM core_operations.route
WHERE route_id = p_input.route_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'ROUTE_NOT_FOUND';
            v_result.error_message := 'route_id=' || p_input.route_id || ' no existe';
RETURN v_result;
END IF;

        v_company_id := v_existing.company_id;  -- inmutable

        -- 2. code: si viene, no puede ser vacío y debe ser único en la empresa
        IF p_input.code IS NOT NULL THEN
            IF TRIM(p_input.code) = '' THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'MISSING_ROUTE_CODE';
                v_result.error_message := 'code no puede ser una cadena vacía';
RETURN v_result;
END IF;

            IF UPPER(TRIM(p_input.code)) <> v_existing.code THEN
                IF EXISTS (
                    SELECT 1 FROM core_operations.route
                    WHERE company_id = v_company_id
                      AND code       = UPPER(TRIM(p_input.code))
                      AND route_id  <> p_input.route_id
                ) THEN
                    v_result.success       := FALSE;
                    v_result.error_code    := 'DUPLICATE_ROUTE_CODE';
                    v_result.error_message := 'Ya existe otra ruta con código "'
                                                  || UPPER(TRIM(p_input.code))
                        || '" para esta empresa';
RETURN v_result;
END IF;
END IF;
END IF;

        -- 3. name: si viene, no puede ser vacío
        IF p_input.name IS NOT NULL AND TRIM(p_input.name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_ROUTE_NAME';
            v_result.error_message := 'name no puede ser una cadena vacía';
RETURN v_result;
END IF;

        -- 4. route_type: si viene, debe ser válido
        IF p_input.route_type IS NOT NULL
            AND TRIM(p_input.route_type) <> ''
            AND p_input.route_type NOT IN ('LINEAR', 'CIRCULAR')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_ROUTE_TYPE';
            v_result.error_message := 'route_type inválido: "' || p_input.route_type
                || '". Válidos: LINEAR, CIRCULAR';
RETURN v_result;
END IF;

        -- 5. total_distance_km > 0 si viene
        IF p_input.total_distance_km IS NOT NULL
            AND p_input.total_distance_km <= 0
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DISTANCE';
            v_result.error_message := 'total_distance_km debe ser mayor a 0. '
                                          || 'Recibido: ' || p_input.total_distance_km::TEXT;
RETURN v_result;
END IF;

        -- 6. estimated_duration_minutes > 0 si viene
        IF p_input.estimated_duration_minutes IS NOT NULL
            AND p_input.estimated_duration_minutes <= 0
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DURATION';
            v_result.error_message := 'estimated_duration_minutes debe ser mayor a 0. '
                                          || 'Recibido: ' || p_input.estimated_duration_minutes::TEXT;
RETURN v_result;
END IF;

        -- 7. Detectar cambios reales (semántica PATCH)
        v_has_changes :=
                (p_input.code IS NOT NULL
                    AND UPPER(TRIM(p_input.code)) IS DISTINCT FROM v_existing.code)
                    OR
                (p_input.name IS NOT NULL
                    AND TRIM(p_input.name) IS DISTINCT FROM v_existing.name)
                    OR
                (p_input.route_type IS NOT NULL
                    AND p_input.route_type IS DISTINCT FROM v_existing.route_type)
                    OR
                (p_input.total_distance_km IS NOT NULL
                    AND p_input.total_distance_km IS DISTINCT FROM v_existing.total_distance_km)
                    OR
                (p_input.estimated_duration_minutes IS NOT NULL
                    AND p_input.estimated_duration_minutes IS DISTINCT FROM v_existing.estimated_duration_minutes)
                    OR
                (p_input.is_active IS NOT NULL
                    AND p_input.is_active IS DISTINCT FROM v_existing.is_active);

        IF v_has_changes THEN
UPDATE core_operations.route
SET code                       = COALESCE(NULLIF(UPPER(TRIM(p_input.code)), ''),     code),
    name                       = COALESCE(NULLIF(TRIM(p_input.name), ''),            name),
    route_type                 = COALESCE(p_input.route_type,                        route_type),
    total_distance_km          = COALESCE(p_input.total_distance_km,                 total_distance_km),
    estimated_duration_minutes = COALESCE(p_input.estimated_duration_minutes,        estimated_duration_minutes),
    is_active                  = COALESCE(p_input.is_active,                         is_active),
    updated_at                 = NOW()
WHERE route_id = p_input.route_id;

v_final_status := 'UPDATED';
ELSE
            v_final_status := 'SKIPPED';
END IF;


        -- ══════════════════════════════════════════════════════════════════════
        -- RAMA INSERT: route_id es NULL
        -- ══════════════════════════════════════════════════════════════════════
ELSE

        -- 1. company_id obligatorio
        IF p_input.company_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_COMPANY_ID';
            v_result.error_message := 'company_id es obligatorio al crear una ruta';
RETURN v_result;
END IF;

        -- 2. Empresa existe y está activa
        IF NOT EXISTS (
            SELECT 1 FROM shared.company
            WHERE company_id = p_input.company_id
              AND is_active   = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COMPANY_NOT_FOUND';
            v_result.error_message := 'company_id=' || p_input.company_id
                || ' no existe o está inactiva';
RETURN v_result;
END IF;

        v_company_id := p_input.company_id;

        -- 3. code obligatorio y único
        IF p_input.code IS NULL OR TRIM(p_input.code) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_ROUTE_CODE';
            v_result.error_message := 'code es obligatorio al crear una ruta';
RETURN v_result;
END IF;

        IF EXISTS (
            SELECT 1 FROM core_operations.route
            WHERE company_id = p_input.company_id
              AND code       = UPPER(TRIM(p_input.code))
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DUPLICATE_ROUTE_CODE';
            v_result.error_message := 'Ya existe una ruta con código "'
                                          || UPPER(TRIM(p_input.code))
                || '" para esta empresa';
RETURN v_result;
END IF;

        -- 4. name obligatorio
        IF p_input.name IS NULL OR TRIM(p_input.name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_ROUTE_NAME';
            v_result.error_message := 'name es obligatorio al crear una ruta';
RETURN v_result;
END IF;

        -- 5. route_type válido si se proveyó
        IF p_input.route_type IS NOT NULL
            AND TRIM(p_input.route_type) <> ''
            AND p_input.route_type NOT IN ('LINEAR', 'CIRCULAR')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_ROUTE_TYPE';
            v_result.error_message := 'route_type inválido: "' || p_input.route_type
                || '". Válidos: LINEAR, CIRCULAR';
RETURN v_result;
END IF;

        -- 6. total_distance_km > 0 si se proveyó
        IF p_input.total_distance_km IS NOT NULL
            AND p_input.total_distance_km <= 0
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DISTANCE';
            v_result.error_message := 'total_distance_km debe ser mayor a 0. '
                                          || 'Recibido: ' || p_input.total_distance_km::TEXT;
RETURN v_result;
END IF;

        -- 7. estimated_duration_minutes > 0 si se proveyó
        IF p_input.estimated_duration_minutes IS NOT NULL
            AND p_input.estimated_duration_minutes <= 0
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_DURATION';
            v_result.error_message := 'estimated_duration_minutes debe ser mayor a 0. '
                                          || 'Recibido: ' || p_input.estimated_duration_minutes::TEXT;
RETURN v_result;
END IF;

        -- 8. INSERT
INSERT INTO core_operations.route (
    company_id,
    code,
    name,
    route_type,
    total_distance_km,
    estimated_duration_minutes,
    is_active
)
VALUES (
           p_input.company_id,
           UPPER(TRIM(p_input.code)),
           TRIM(p_input.name),
           p_input.route_type,
           p_input.total_distance_km,
           p_input.estimated_duration_minutes,
           TRUE
       )
    RETURNING route_id INTO p_input.route_id;

v_final_status := 'INSERTED';

END IF;

    -- ── Poblar resultado desde BD (estado final) ──────────────────────────
SELECT
    r.route_id,
    r.company_id,
    r.code,
    r.name,
    r.route_type,
    r.total_distance_km,
    r.estimated_duration_minutes,
    r.is_active,
    r.created_at,
    r.updated_at
INTO
    v_result.route_id,
    v_result.company_id,
    v_result.code,
    v_result.name,
    v_result.route_type,
    v_result.total_distance_km,
    v_result.estimated_duration_minutes,
    v_result.is_active,
    v_result.created_at,
    v_result.updated_at
FROM core_operations.route r
WHERE r.route_id = p_input.route_id;

-- ── incomplete_for_dispatch ───────────────────────────────────────────
--    Los terminales ya no se validan aquí; se infieren desde checkpoint.
--    Un route_id sin checkpoints tipo terminal con is_route_endpoint=true
--    se considera incompleto, pero esa verificación es responsabilidad
--    del endpoint de despacho, no de upsert_route.
--    Aquí solo validamos los metadatos propios de la ruta.
IF v_result.route_type IS NULL THEN
        v_missing_fields := v_missing_fields || ARRAY['route_type'];
END IF;
    IF v_result.total_distance_km IS NULL THEN
        v_missing_fields := v_missing_fields || ARRAY['total_distance_km'];
END IF;
    IF v_result.estimated_duration_minutes IS NULL THEN
        v_missing_fields := v_missing_fields || ARRAY['estimated_duration_minutes'];
END IF;

    -- Verificar que la ruta tenga endpoints definidos en checkpoint
    IF NOT EXISTS (
        SELECT 1 FROM core_operations.checkpoint
        WHERE route_id         = p_input.route_id
          AND checkpoint_type  = 'terminal'
          AND is_route_endpoint = TRUE
          AND is_active         = TRUE
    ) THEN
        v_missing_fields := v_missing_fields || ARRAY['checkpoints_endpoints'];
END IF;

    v_result.route_status            := v_final_status;
    v_result.incomplete_for_dispatch := array_length(v_missing_fields, 1) > 0;
    v_result.missing_fields          := v_missing_fields;
    v_result.success                 := TRUE;

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_ROUTE_CODE';
        v_result.error_message := 'Conflicto de unicidad por concurrencia: '
                                      || 'el código de ruta fue tomado simultáneamente. '
                                      || 'Detalle: ' || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_route_polyline(api.upsert_route_polyline_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_route_polyline(p_input api.upsert_route_polyline_input) RETURNS api.upsert_route_polyline_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result            api.upsert_route_polyline_result;
    v_route_code        VARCHAR(20);
    v_existing          core_operations.route_polyline%ROWTYPE;
    v_polyline_id       BIGINT;
    v_total_points      INT;
    v_point             JSONB;
    v_i                 INT;
    v_lon               NUMERIC;
    v_lat               NUMERIC;
    v_is_replace        BOOLEAN := FALSE;
BEGIN

    -- ── Validación 1: route_id obligatorio ────────────────────────────────
    IF p_input.route_id IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_ROUTE_ID';
        v_result.error_message := 'route_id es obligatorio';
RETURN v_result;
END IF;

    -- ── Validación 2: ruta existe y está activa ───────────────────────────
SELECT code INTO v_route_code
FROM core_operations.route
WHERE route_id = p_input.route_id
  AND is_active = TRUE;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'ROUTE_NOT_FOUND';
        v_result.error_message := 'La ruta route_id=' || p_input.route_id
                                  || ' no existe o está inactiva';
RETURN v_result;
END IF;

    -- ── Validación 3: direction dentro del dominio ────────────────────────
    IF p_input.direction IS NULL
       OR TRIM(p_input.direction) = ''
       OR p_input.direction NOT IN ('IDA', 'VUELTA')
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DIRECTION';
        v_result.error_message := 'direction inválida: "'
                                  || COALESCE(p_input.direction, 'NULL')
                                  || '". Válidas: IDA, VUELTA';
RETURN v_result;
END IF;

    -- ── Validación 4: coordinates obligatorio ─────────────────────────────
    IF p_input.coordinates IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'MISSING_COORDINATES';
        v_result.error_message := 'coordinates es obligatorio. Debe ser un array GeoJSON '
                                  || 'de pares [longitude, latitude]';
RETURN v_result;
END IF;

    -- ── Validación 5: coordinates debe ser un array JSON ─────────────────
    IF jsonb_typeof(p_input.coordinates) <> 'array' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_COORDINATES_FORMAT';
        v_result.error_message := 'coordinates debe ser un array JSON. '
                                  || 'Tipo recibido: ' || jsonb_typeof(p_input.coordinates);
RETURN v_result;
END IF;

    -- ── Validación 6: al menos 2 puntos ──────────────────────────────────
    v_total_points := jsonb_array_length(p_input.coordinates);

    IF v_total_points < 2 THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INSUFFICIENT_POINTS';
        v_result.error_message := 'coordinates debe tener al menos 2 puntos para '
                                  || 'definir una polilínea. '
                                  || 'Recibido: ' || v_total_points::TEXT || ' punto(s)';
RETURN v_result;
END IF;

    -- ── Validación 7: cada punto es un par [lon, lat] con valores en rango ─
FOR v_i IN 0 .. v_total_points - 1
    LOOP
        v_point := p_input.coordinates -> v_i;

        -- Debe ser array de exactamente 2 elementos
        IF jsonb_typeof(v_point) <> 'array' OR jsonb_array_length(v_point) <> 2 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_COORDINATE_PAIR';
            v_result.error_message := 'Cada punto debe ser un array [longitude, latitude]. '
                                      || 'Error en el punto índice ' || v_i::TEXT
                                      || ': ' || v_point::TEXT;
RETURN v_result;
END IF;

        -- Ambos elementos deben ser numéricos
        IF jsonb_typeof(v_point -> 0) <> 'number'
           OR jsonb_typeof(v_point -> 1) <> 'number'
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_COORDINATE_PAIR';
            v_result.error_message := 'Longitud y latitud deben ser valores numéricos. '
                                      || 'Error en el punto índice ' || v_i::TEXT
                                      || ': ' || v_point::TEXT;
RETURN v_result;
END IF;

        v_lon := (v_point -> 0)::NUMERIC;
        v_lat := (v_point -> 1)::NUMERIC;

        -- Rango de longitud [-180, 180]
        IF v_lon < -180 OR v_lon > 180 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COORDINATE_OUT_OF_RANGE';
            v_result.error_message := 'Longitud fuera de rango [-180, 180] '
                                      || 'en el punto índice ' || v_i::TEXT
                                      || ': ' || v_lon::TEXT;
RETURN v_result;
END IF;

        -- Rango de latitud [-90, 90]
        IF v_lat < -90 OR v_lat > 90 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COORDINATE_OUT_OF_RANGE';
            v_result.error_message := 'Latitud fuera de rango [-90, 90] '
                                      || 'en el punto índice ' || v_i::TEXT
                                      || ': ' || v_lat::TEXT;
RETURN v_result;
END IF;

END LOOP;

    -- ── ¿Ya existe una polilínea para (route_id, direction)? ─────────────
SELECT * INTO v_existing
FROM core_operations.route_polyline
WHERE route_id  = p_input.route_id
  AND direction = p_input.direction;

IF FOUND THEN
        -- ── REPLACE: comparar si hay cambio real ──────────────────────────
        --    Comparamos coordinates y encoded_polyline; total_points se deriva
        IF p_input.coordinates      IS DISTINCT FROM v_existing.coordinates
           OR p_input.encoded_polyline IS DISTINCT FROM v_existing.encoded_polyline
        THEN
UPDATE core_operations.route_polyline
SET coordinates      = p_input.coordinates,
    encoded_polyline = p_input.encoded_polyline,
    total_points     = v_total_points,
    updated_at       = NOW()
WHERE polyline_id = v_existing.polyline_id;

v_polyline_id   := v_existing.polyline_id;
            v_is_replace    := TRUE;
            v_result.polyline_status := 'REPLACED';
ELSE
            -- Sin cambios
            v_polyline_id            := v_existing.polyline_id;
            v_result.polyline_status := 'SKIPPED';
END IF;

ELSE
        -- ── INSERT: primera polilínea para esta dirección ─────────────────
        INSERT INTO core_operations.route_polyline (
            route_id,
            direction,
            coordinates,
            encoded_polyline,
            total_points
        )
        VALUES (
            p_input.route_id,
            p_input.direction,
            p_input.coordinates,
            p_input.encoded_polyline,
            v_total_points
        )
        RETURNING polyline_id INTO v_polyline_id;

        v_result.polyline_status := 'INSERTED';
END IF;

    -- ── Poblar resultado desde BD ─────────────────────────────────────────
SELECT
    pl.polyline_id,
    pl.route_id,
    pl.direction,
    pl.total_points,
    pl.encoded_polyline,
    pl.created_at,
    pl.updated_at
INTO
    v_result.polyline_id,
    v_result.route_id,
    v_result.direction,
    v_result.total_points,
    v_result.encoded_polyline,
    v_result.created_at,
    v_result.updated_at
FROM core_operations.route_polyline pl
WHERE pl.polyline_id = v_polyline_id;

v_result.success    := TRUE;
    v_result.route_code := v_route_code;

RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        -- Race condition concurrente en INSERT (otro proceso insertó primero)
        v_result.success       := FALSE;
        v_result.error_code    := 'CONCURRENT_CONFLICT';
        v_result.error_message := 'Conflicto de concurrencia al insertar la polilínea. '
                                  || 'Intente nuevamente';
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_tenant(api.upsert_tenant_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_tenant(p_input api.upsert_tenant_input) RETURNS api.upsert_tenant_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.upsert_tenant_result;
    v_existing_tenant       identity.tenant%ROWTYPE;
    v_company               shared.company%ROWTYPE;
    v_link_result           api.tenant_company_item_result;
    v_link_results          api.tenant_company_item_result[]
                                  := ARRAY[]::api.tenant_company_item_result[];
    -- Contadores
    v_total_linked          INT := 0;
    v_total_already_linked  INT := 0;
    v_total_unlinked        INT := 0;
    v_total_link_errors     INT := 0;
    -- Trabajo
    v_tenant_id             BIGINT;
    v_has_tenant_changes    BOOLEAN;
    v_submitted_company_ids INT[] := ARRAY[]::INT[];
    -- Para el sync de desvinculación
    v_unlinked_company_id   INT;
    v_unlinked_tax_id       VARCHAR(20);
    v_unlinked_legal_name   VARCHAR(255);
    -- Para detección de duplicados en el array de input
    v_processed_company_ids INT[] := ARRAY[]::INT[];
    v_company_id            INT;
BEGIN

    -- ── Validación global: name obligatorio en INSERT ─────────────────────
    IF p_input.tenant_id IS NULL THEN
        IF p_input.name IS NULL OR TRIM(p_input.name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_TENANT_NAME';
            v_result.error_message := 'name es obligatorio al crear un tenant';
RETURN v_result;
END IF;
END IF;

    -- ── RAMA UPDATE: tenant_id viene NOT NULL ─────────────────────────────
    IF p_input.tenant_id IS NOT NULL THEN

SELECT * INTO v_existing_tenant
FROM identity.tenant
WHERE tenant_id = p_input.tenant_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'TENANT_NOT_FOUND';
            v_result.error_message := 'tenant_id=' || p_input.tenant_id || ' no existe';
RETURN v_result;
END IF;

        -- Validar name no vacío si viene
        IF p_input.name IS NOT NULL AND TRIM(p_input.name) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_TENANT_NAME';
            v_result.error_message := 'name no puede ser una cadena vacía';
RETURN v_result;
END IF;

        -- Detectar cambios reales en el tenant
        v_has_tenant_changes :=
                (p_input.name      IS NOT NULL AND TRIM(p_input.name) IS DISTINCT FROM v_existing_tenant.name) OR
                (p_input.is_active IS NOT NULL AND p_input.is_active  IS DISTINCT FROM v_existing_tenant.is_active);

        IF v_has_tenant_changes THEN
UPDATE identity.tenant
SET name       = COALESCE(NULLIF(TRIM(p_input.name), ''), name),
    is_active  = COALESCE(p_input.is_active, is_active),
    updated_at = NOW()
WHERE tenant_id = p_input.tenant_id;

v_result.tenant_status := 'UPDATED';
ELSE
            v_result.tenant_status := 'SKIPPED';
END IF;

        v_tenant_id             := p_input.tenant_id;
        v_result.tenant_name    := COALESCE(NULLIF(TRIM(p_input.name), ''), v_existing_tenant.name);

        -- ── RAMA INSERT: tenant_id es NULL ────────────────────────────────────
ELSE

        INSERT INTO identity.tenant (name, is_active, created_at, updated_at)
        VALUES (
                   TRIM(p_input.name),
                   COALESCE(p_input.is_active, TRUE),
                   NOW(),
                   NOW()
               )
        RETURNING tenant_id INTO v_tenant_id;

        v_result.tenant_status := 'INSERTED';
        v_result.tenant_name   := TRIM(p_input.name);

END IF;

    v_result.tenant_id := v_tenant_id;

    -- ── SYNC DE VINCULACIONES ─────────────────────────────────────────────
    --    Si company_ids es NULL: no tocar vínculos (skip esta fase completa)
    --    Si company_ids es [] vacío: desvincular todas
    --    Si company_ids tiene IDs: ese es el estado final deseado

    IF p_input.company_ids IS NULL THEN
        -- No gestionar vínculos; dejar los existentes intactos
        v_result.success              := TRUE;
        v_result.total_linked         := 0;
        v_result.total_already_linked := 0;
        v_result.total_unlinked       := 0;
        v_result.total_link_errors    := 0;
        v_result.companies_detail     := v_link_results;
RETURN v_result;
END IF;

    -- ── FASE 1: Validar y vincular cada company del array enviado ─────────
    IF array_length(p_input.company_ids, 1) IS NOT NULL THEN

        FOREACH v_company_id IN ARRAY p_input.company_ids
            LOOP
                v_link_result.company_id    := v_company_id;
                v_link_result.tax_id        := NULL;
                v_link_result.legal_name    := NULL;
                v_link_result.status        := NULL;
                v_link_result.error_code    := NULL;
                v_link_result.error_message := NULL;

                -- Val: company_id no duplicado en el mismo array
                IF v_company_id = ANY(v_processed_company_ids) THEN
                    v_link_result.status        := 'ERROR';
                    v_link_result.error_code    := 'DUPLICATE_COMPANY_ID_IN_BATCH';
                    v_link_result.error_message := 'company_id=' || v_company_id
                        || ' aparece más de una vez en el array';
                    v_link_results      := v_link_results || v_link_result;
                    v_total_link_errors := v_total_link_errors + 1;
CONTINUE;
END IF;

                -- Val: la company existe
SELECT * INTO v_company
FROM shared.company
WHERE company_id = v_company_id;

IF NOT FOUND THEN
                    v_link_result.status        := 'ERROR';
                    v_link_result.error_code    := 'COMPANY_NOT_FOUND';
                    v_link_result.error_message := 'company_id=' || v_company_id || ' no existe';
                    v_link_results      := v_link_results || v_link_result;
                    v_total_link_errors := v_total_link_errors + 1;
CONTINUE;
END IF;

                v_link_result.tax_id     := v_company.tax_id;
                v_link_result.legal_name := v_company.legal_name;

                -- ¿Ya está vinculada?
                IF EXISTS (
                    SELECT 1 FROM identity.tenant_company
                    WHERE tenant_id  = v_tenant_id
                      AND company_id = v_company_id
                ) THEN
                    v_link_result.status    := 'ALREADY_LINKED';
                    v_total_already_linked  := v_total_already_linked + 1;
ELSE
                    -- Insertar nuevo vínculo
                    INSERT INTO identity.tenant_company (tenant_id, company_id, is_active, created_at)
                    VALUES (v_tenant_id, v_company_id, TRUE, NOW());

                    v_link_result.status := 'LINKED';
                    v_total_linked       := v_total_linked + 1;
END IF;

                v_link_results          := v_link_results || v_link_result;
                v_submitted_company_ids := v_submitted_company_ids || v_company_id;
                v_processed_company_ids := v_processed_company_ids || v_company_id;

END LOOP;

END IF; -- fin FASE 1

    -- ── FASE 2: Desvincular companies que ya no están en el payload ────────
    --    Solo se eliminan las que pasaron validación (v_submitted_company_ids).
    --    Las que tuvieron ERROR en validación se preservan en BD.
FOR v_unlinked_company_id, v_unlinked_tax_id, v_unlinked_legal_name IN
SELECT tc.company_id, c.tax_id, c.legal_name
FROM identity.tenant_company tc
         JOIN shared.company          c  ON c.company_id = tc.company_id
WHERE tc.tenant_id  = v_tenant_id
  AND tc.company_id <> ALL(v_submitted_company_ids)
ORDER BY tc.company_id
    LOOP
DELETE FROM identity.tenant_company
WHERE tenant_id  = v_tenant_id
  AND company_id = v_unlinked_company_id;

v_link_result.company_id    := v_unlinked_company_id;
            v_link_result.tax_id        := v_unlinked_tax_id;
            v_link_result.legal_name    := v_unlinked_legal_name;
            v_link_result.status        := 'UNLINKED';
            v_link_result.error_code    := NULL;
            v_link_result.error_message := NULL;
            v_link_results  := v_link_results || v_link_result;
            v_total_unlinked := v_total_unlinked + 1;

END LOOP;

    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success              := TRUE;
    v_result.total_linked         := v_total_linked;
    v_result.total_already_linked := v_total_already_linked;
    v_result.total_unlinked       := v_total_unlinked;
    v_result.total_link_errors    := v_total_link_errors;
    v_result.companies_detail     := v_link_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.companies_detail := v_link_results;
RETURN v_result;
END;
$$;


--
-- Name: upsert_users(api.upsert_users_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_users(p_input api.upsert_users_input) RETURNS api.upsert_users_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                    api.upsert_users_result;
    v_user                      api.user_item;
    v_item_result               api.user_item_result;
    v_item_results              api.user_item_result[]
                                    := ARRAY[]::api.user_item_result[];
    -- Contadores usuarios
    v_total_inserted            INT := 0;
    v_total_updated             INT := 0;
    v_total_skipped             INT := 0;
    v_total_errors              INT := 0;
    -- Contadores tenant_access
    v_total_ta_inserted         INT := 0;
    v_total_ta_updated          INT := 0;
    v_total_ta_skipped          INT := 0;
    -- Trabajo usuario
    v_existing                  identity."user"%ROWTYPE;
    v_has_changes               BOOLEAN;
    v_conflict_id               BIGINT;
    v_user_id                   BIGINT;
    -- Trabajo tenant_access
    v_existing_ta               identity.user_tenant_access%ROWTYPE;
    v_ta_id                     BIGINT;
    v_ta_status                 VARCHAR(10);
    -- Detección de duplicados en batch
    v_processed_ext_ids         VARCHAR(255)[] := ARRAY[]::VARCHAR[];
    v_processed_usernames       VARCHAR(100)[] := ARRAY[]::VARCHAR[];
    v_processed_emails          VARCHAR(255)[] := ARRAY[]::VARCHAR[];
BEGIN

    -- ── Validación global ─────────────────────────────────────────────────
    IF p_input.users IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NULL_USERS_ARRAY';
        v_result.error_message := 'El array de usuarios es NULL. Provea al menos un usuario';
RETURN v_result;
END IF;

    IF array_length(p_input.users, 1) IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'NO_USERS_PROVIDED';
        v_result.error_message := 'El array de usuarios está vacío. Provea al menos un usuario';
RETURN v_result;
END IF;

    -- ── Loop principal ────────────────────────────────────────────────────
    FOREACH v_user IN ARRAY p_input.users
    LOOP
        v_item_result.external_id           := v_user.external_id;
        v_item_result.username              := v_user.username;
        v_item_result.email                 := v_user.email;
        v_item_result.user_id               := NULL;
        v_item_result.status                := NULL;
        v_item_result.tenant_access_status  := NULL;
        v_item_result.user_tenant_access_id := NULL;
        v_item_result.error_code            := NULL;
        v_item_result.error_message         := NULL;
        v_item_result.created_at            := NULL;
        v_item_result.updated_at            := NULL;

        -- ── Val: external_id obligatorio ──────────────────────────────────
        IF v_user.external_id IS NULL OR TRIM(v_user.external_id) = '' THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'MISSING_EXTERNAL_ID';
            v_item_result.error_message := 'external_id es obligatorio y no puede estar vacío';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: tenant_id obligatorio ────────────────────────────────────
        IF v_user.tenant_id IS NULL THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'MISSING_TENANT_ID';
            v_item_result.error_message := 'tenant_id es obligatorio '
                                           || '(external_id="' || v_user.external_id || '")';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: tenant existe y está activo ──────────────────────────────
        IF NOT EXISTS (
            SELECT 1 FROM identity.tenant
            WHERE tenant_id = v_user.tenant_id
              AND is_active  = TRUE
        ) THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'TENANT_NOT_FOUND';
            v_item_result.error_message := 'tenant_id=' || v_user.tenant_id
                                           || ' no existe o está inactivo '
                                           || '(external_id="' || v_user.external_id || '")';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Val: granted_by existe si se proveyó ──────────────────────────
        IF v_user.granted_by IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM identity."user"
                WHERE user_id  = v_user.granted_by
                  AND is_active = TRUE
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'GRANTED_BY_NOT_FOUND';
                v_item_result.error_message := 'granted_by=' || v_user.granted_by
                                               || ' no existe o está inactivo '
                                               || '(external_id="' || v_user.external_id || '")';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

        -- ── Val: external_id no duplicado en batch ────────────────────────
        IF v_user.external_id = ANY(v_processed_ext_ids) THEN
            v_item_result.status        := 'ERROR';
            v_item_result.error_code    := 'DUPLICATE_EXTERNAL_ID_IN_BATCH';
            v_item_result.error_message := 'external_id "' || v_user.external_id
                                           || '" aparece más de una vez en el mismo lote';
            v_item_results := v_item_results || v_item_result;
            v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

        -- ── Buscar usuario por external_id ────────────────────────────────
SELECT * INTO v_existing
FROM identity."user"
WHERE external_id = v_user.external_id;

-- ════════════════════════════════════════════════════════
-- RAMA UPDATE
-- ════════════════════════════════════════════════════════
IF FOUND THEN

            -- username no tomado por otro en BD
            IF v_user.username IS NOT NULL
               AND v_user.username <> v_existing.username
            THEN
SELECT user_id INTO v_conflict_id
FROM identity."user"
WHERE username = v_user.username
  AND user_id <> v_existing.user_id;

IF FOUND THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_USERNAME';
                    v_item_result.error_message := 'El username "' || v_user.username
                                                   || '" ya está asignado a otro usuario en BD';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF v_user.username = ANY(v_processed_usernames) THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_USERNAME_IN_BATCH';
                    v_item_result.error_message := 'El username "' || v_user.username
                                                   || '" ya fue asignado en este lote';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

            -- email no tomado por otro en BD
            IF v_user.email IS NOT NULL
               AND v_user.email <> v_existing.email
            THEN
SELECT user_id INTO v_conflict_id
FROM identity."user"
WHERE email   = v_user.email
  AND user_id <> v_existing.user_id;

IF FOUND THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_EMAIL';
                    v_item_result.error_message := 'El email "' || v_user.email
                                                   || '" ya está registrado para otro usuario en BD';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

                IF v_user.email = ANY(v_processed_emails) THEN
                    v_item_result.status        := 'ERROR';
                    v_item_result.error_code    := 'DUPLICATE_EMAIL_IN_BATCH';
                    v_item_result.error_message := 'El email "' || v_user.email
                                                   || '" ya fue asignado en este lote';
                    v_item_results := v_item_results || v_item_result;
                    v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;
END IF;

            IF v_user.username IS NOT NULL AND TRIM(v_user.username) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_USERNAME';
                v_item_result.error_message := 'username no puede ser una cadena vacía';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            IF v_user.email IS NOT NULL AND TRIM(v_user.email) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_EMAIL';
                v_item_result.error_message := 'email no puede ser una cadena vacía';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            v_has_changes :=
                (v_user.username  IS NOT NULL AND v_user.username  IS DISTINCT FROM v_existing.username)  OR
                (v_user.email     IS NOT NULL AND v_user.email     IS DISTINCT FROM v_existing.email)     OR
                (v_user.full_name IS NOT NULL AND v_user.full_name IS DISTINCT FROM v_existing.full_name) OR
                (v_user.is_active IS NOT NULL AND v_user.is_active IS DISTINCT FROM v_existing.is_active);

            IF v_has_changes THEN
UPDATE identity."user"
SET username   = COALESCE(NULLIF(TRIM(v_user.username), ''), username),
    email      = COALESCE(NULLIF(TRIM(v_user.email), ''),    email),
    full_name  = COALESCE(v_user.full_name,                  full_name),
    is_active  = COALESCE(v_user.is_active,                  is_active),
    updated_at = NOW()
WHERE user_id = v_existing.user_id
    RETURNING user_id, created_at, updated_at
INTO v_user_id,
    v_item_result.created_at,
    v_item_result.updated_at;

v_item_result.username := COALESCE(v_user.username, v_existing.username);
                v_item_result.email    := COALESCE(v_user.email,    v_existing.email);
                v_item_result.status   := 'UPDATED';
                v_total_updated        := v_total_updated + 1;
ELSE
                v_user_id                := v_existing.user_id;
                v_item_result.username   := v_existing.username;
                v_item_result.email      := v_existing.email;
                v_item_result.created_at := v_existing.created_at;
                v_item_result.updated_at := v_existing.updated_at;
                v_item_result.status     := 'SKIPPED';
                v_total_skipped          := v_total_skipped + 1;
END IF;

            v_processed_usernames := v_processed_usernames
                || COALESCE(v_user.username, v_existing.username);
            v_processed_emails    := v_processed_emails
                || COALESCE(v_user.email, v_existing.email);

        -- ════════════════════════════════════════════════════════
        -- RAMA INSERT
        -- ════════════════════════════════════════════════════════
ELSE

            IF v_user.username IS NULL OR TRIM(v_user.username) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_USERNAME';
                v_item_result.error_message := 'username es obligatorio al crear un usuario '
                                               || '(external_id="' || v_user.external_id || '")';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            IF v_user.email IS NULL OR TRIM(v_user.email) = '' THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'MISSING_EMAIL';
                v_item_result.error_message := 'email es obligatorio al crear un usuario '
                                               || '(external_id="' || v_user.external_id || '")';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            IF v_user.username = ANY(v_processed_usernames) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_USERNAME_IN_BATCH';
                v_item_result.error_message := 'El username "' || v_user.username
                                               || '" ya fue asignado en este lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            IF v_user.email = ANY(v_processed_emails) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_EMAIL_IN_BATCH';
                v_item_result.error_message := 'El email "' || v_user.email
                                               || '" ya fue asignado en este lote';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            IF EXISTS (
                SELECT 1 FROM identity."user" WHERE username = v_user.username
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_USERNAME';
                v_item_result.error_message := 'El username "' || v_user.username
                                               || '" ya está en uso por otro usuario';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

            IF EXISTS (
                SELECT 1 FROM identity."user" WHERE email = v_user.email
            ) THEN
                v_item_result.status        := 'ERROR';
                v_item_result.error_code    := 'DUPLICATE_EMAIL';
                v_item_result.error_message := 'El email "' || v_user.email
                                               || '" ya está registrado para otro usuario';
                v_item_results := v_item_results || v_item_result;
                v_total_errors := v_total_errors + 1;
CONTINUE;
END IF;

INSERT INTO identity."user" (
    external_id, username, email, full_name, is_active
)
VALUES (
           TRIM(v_user.external_id),
           TRIM(v_user.username),
           TRIM(v_user.email),
           v_user.full_name,
           COALESCE(v_user.is_active, TRUE)
       )
    RETURNING user_id, created_at, updated_at
INTO v_user_id,
    v_item_result.created_at,
    v_item_result.updated_at;

v_item_result.status  := 'INSERTED';
            v_total_inserted      := v_total_inserted + 1;

            v_processed_usernames := v_processed_usernames || TRIM(v_user.username);
            v_processed_emails    := v_processed_emails    || TRIM(v_user.email);

END IF;

        -- ════════════════════════════════════════════════════════
        -- UPSERT user_tenant_access
        -- Se ejecuta para todo usuario que pasó validaciones
        -- (INSERT, UPDATE o SKIPPED). Un error aquí no revierte
        -- la operación del usuario — se registra en tenant_access_status.
        -- ════════════════════════════════════════════════════════
BEGIN
SELECT * INTO v_existing_ta
FROM identity.user_tenant_access
WHERE user_id  = v_user_id
  AND tenant_id = v_user.tenant_id;

IF FOUND THEN
                -- Ya existe: actualizar is_active y granted_by si cambian
                IF v_existing_ta.is_active IS DISTINCT FROM COALESCE(v_user.is_active, TRUE)
                   OR (v_user.granted_by IS NOT NULL
                       AND v_user.granted_by IS DISTINCT FROM v_existing_ta.granted_by)
                THEN
UPDATE identity.user_tenant_access
SET is_active  = COALESCE(v_user.is_active, v_existing_ta.is_active),
    granted_by = COALESCE(v_user.granted_by, v_existing_ta.granted_by),
    granted_at = NOW()
WHERE user_tenant_access_id = v_existing_ta.user_tenant_access_id
    RETURNING user_tenant_access_id INTO v_ta_id;

v_ta_status      := 'UPDATED';
                    v_total_ta_updated := v_total_ta_updated + 1;
ELSE
                    v_ta_id          := v_existing_ta.user_tenant_access_id;
                    v_ta_status      := 'SKIPPED';
                    v_total_ta_skipped := v_total_ta_skipped + 1;
END IF;
ELSE
                INSERT INTO identity.user_tenant_access (
                    user_id, tenant_id, is_active, granted_by, granted_at
                )
                VALUES (
                    v_user_id,
                    v_user.tenant_id,
                    COALESCE(v_user.is_active, TRUE),
                    v_user.granted_by,
                    NOW()
                )
                RETURNING user_tenant_access_id INTO v_ta_id;

                v_ta_status        := 'INSERTED';
                v_total_ta_inserted := v_total_ta_inserted + 1;
END IF;

            v_item_result.user_tenant_access_id := v_ta_id;
            v_item_result.tenant_access_status  := v_ta_status;

EXCEPTION
            WHEN OTHERS THEN
                -- Fallo en tenant_access no revierte el usuario
                v_item_result.tenant_access_status  := 'ERROR';
                v_item_result.user_tenant_access_id := NULL;
END;

        v_item_result.user_id   := v_user_id;
        v_item_results          := v_item_results || v_item_result;
        v_processed_ext_ids     := v_processed_ext_ids || v_user.external_id;

END LOOP;

    -- ── Resultado global ──────────────────────────────────────────────────
    v_result.success                      := TRUE;
    v_result.total_submitted              := array_length(p_input.users, 1);
    v_result.total_inserted               := v_total_inserted;
    v_result.total_updated                := v_total_updated;
    v_result.total_skipped                := v_total_skipped;
    v_result.total_errors                 := v_total_errors;
    v_result.total_tenant_access_inserted := v_total_ta_inserted;
    v_result.total_tenant_access_updated  := v_total_ta_updated;
    v_result.total_tenant_access_skipped  := v_total_ta_skipped;
    v_result.detail                       := v_item_results;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        v_result.detail        := v_item_results;
RETURN v_result;
END;
$$;


--
-- Name: upsert_vehicle(api.upsert_vehicle_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_vehicle(p_input api.upsert_vehicle_input) RETURNS api.upsert_vehicle_result
    LANGUAGE plpgsql
    AS $_$
DECLARE
v_result                    api.upsert_vehicle_result;
    v_existing                  fleet.vehicle%ROWTYPE;
    v_internal_code             VARCHAR(20);
    v_plate             VARCHAR(20);
    v_code_was_generated        BOOLEAN := FALSE;
    v_status                    VARCHAR(20);
    v_has_changes               BOOLEAN;
BEGIN

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: vehicle_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.vehicle_id IS NOT NULL THEN

        -- 1. El vehículo existe
SELECT * INTO v_existing
FROM fleet.vehicle
WHERE vehicle_id = p_input.vehicle_id;

IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'VEHICLE_NOT_FOUND';
            v_result.error_message := 'vehicle_id=' || p_input.vehicle_id || ' no existe';
RETURN v_result;
END IF;

        -- 2. Validar plate_number si cambia (formato + unicidad)
        IF p_input.plate_number IS NOT NULL
            AND UPPER(TRIM(p_input.plate_number)) <> v_existing.plate_number
        THEN
            IF TRIM(p_input.plate_number) = '' THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_PLATE_FORMAT';
                v_result.error_message := 'plate_number no puede ser una cadena vacía';
RETURN v_result;
END IF;
            v_plate := UPPER(REPLACE(TRIM(p_input.plate_number), ' ', ''));

            IF v_plate !~ '^[A-Z0-9]{2,4}-[A-Z0-9]{2,4}$' THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_PLATE_FORMAT';
                v_result.error_message := 'Formato de placa inválido: "' || p_input.plate_number
                    || '". Formato: AAA-000 o AAA-0000';
RETURN v_result;
END IF;

            IF EXISTS (
                SELECT 1 FROM fleet.vehicle
                WHERE plate_number = UPPER(TRIM(p_input.plate_number))
                  AND vehicle_id  <> p_input.vehicle_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_PLATE_NUMBER';
                v_result.error_message := 'La placa "' || UPPER(TRIM(p_input.plate_number))
                    || '" ya está registrada en otro vehículo';
RETURN v_result;
END IF;
END IF;

        -- 3. Validar chassis_number si cambia (unicidad)
        IF p_input.chassis_number IS NOT NULL
            AND NULLIF(TRIM(p_input.chassis_number), '') IS NOT NULL
            AND NULLIF(TRIM(p_input.chassis_number), '') IS DISTINCT FROM v_existing.chassis_number
        THEN
            IF EXISTS (
                SELECT 1 FROM fleet.vehicle
                WHERE chassis_number = TRIM(p_input.chassis_number)
                  AND vehicle_id     <> p_input.vehicle_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_CHASSIS_NUMBER';
                v_result.error_message := 'El número de chasis "' || TRIM(p_input.chassis_number)
                    || '" ya está registrado en otro vehículo';
RETURN v_result;
END IF;
END IF;

        -- 4. Validar internal_code si cambia (unicidad)
        IF p_input.internal_code IS NOT NULL
            AND TRIM(p_input.internal_code) <> ''
            AND TRIM(p_input.internal_code) <> v_existing.internal_code
        THEN
            IF EXISTS (
                SELECT 1 FROM fleet.vehicle
                WHERE internal_code = TRIM(p_input.internal_code)
                  AND vehicle_id    <> p_input.vehicle_id
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_INTERNAL_CODE';
                v_result.error_message := 'El código interno "' || TRIM(p_input.internal_code)
                    || '" ya está en uso por otro vehículo';
RETURN v_result;
END IF;
END IF;

        -- 5. Validar fuel_type si viene
        IF p_input.fuel_type IS NOT NULL
            AND TRIM(p_input.fuel_type) <> ''
            AND p_input.fuel_type NOT IN ('DIESEL', 'GNV', 'HYBRID', 'ELECTRIC', 'GASOLINE')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_FUEL_TYPE';
            v_result.error_message := 'fuel_type inválido: "' || p_input.fuel_type
                || '". Válidos: DIESEL, GNV, HYBRID, ELECTRIC, GASOLINE';
RETURN v_result;
END IF;

        -- 6. Validar status si viene
        IF p_input.status IS NOT NULL
            AND p_input.status NOT IN ('ACTIVE', 'INACTIVE', 'MAINTENANCE', 'RETIRED')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_VEHICLE_STATUS';
            v_result.error_message := 'status inválido: "' || p_input.status
                || '". Válidos: ACTIVE, INACTIVE, MAINTENANCE, RETIRED';
RETURN v_result;
END IF;

        -- 7. Validar año si viene
        IF p_input.year IS NOT NULL THEN
            IF p_input.year < 1980
                OR p_input.year > EXTRACT(YEAR FROM CURRENT_DATE)::INT + 1
            THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_YEAR';
                v_result.error_message := 'Año inválido: ' || p_input.year::TEXT
                                              || '. Debe estar entre 1980 y '
                    || (EXTRACT(YEAR FROM CURRENT_DATE)::INT + 1)::TEXT;
RETURN v_result;
END IF;
END IF;

        -- 8. Validar capacidades si vienen
        IF p_input.seating_capacity IS NOT NULL AND p_input.seating_capacity <= 0 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_CAPACITY';
            v_result.error_message := 'seating_capacity debe ser mayor a 0. '
                                          || 'Recibido: ' || p_input.seating_capacity::TEXT;
RETURN v_result;
END IF;

        IF p_input.standing_capacity IS NOT NULL AND p_input.standing_capacity < 0 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_CAPACITY';
            v_result.error_message := 'standing_capacity no puede ser negativo. '
                                          || 'Recibido: ' || p_input.standing_capacity::TEXT;
RETURN v_result;
END IF;

        -- 9. Detectar cambios reales (PATCH semántico)
        v_has_changes :=
                (p_input.plate_number     IS NOT NULL AND UPPER(TRIM(p_input.plate_number))    IS DISTINCT FROM v_existing.plate_number)     OR
                (p_input.internal_code    IS NOT NULL AND TRIM(p_input.internal_code)           IS DISTINCT FROM v_existing.internal_code)    OR
                (p_input.brand            IS NOT NULL AND p_input.brand                         IS DISTINCT FROM v_existing.brand)            OR
                (p_input.model            IS NOT NULL AND p_input.model                         IS DISTINCT FROM v_existing.model)            OR
                (p_input.year             IS NOT NULL AND p_input.year                          IS DISTINCT FROM v_existing.year)             OR
                (p_input.chassis_number   IS NOT NULL AND NULLIF(TRIM(p_input.chassis_number), '') IS DISTINCT FROM v_existing.chassis_number) OR
                (p_input.engine_number    IS NOT NULL AND NULLIF(TRIM(p_input.engine_number), '')  IS DISTINCT FROM v_existing.engine_number)  OR
                (p_input.fuel_type        IS NOT NULL AND p_input.fuel_type                     IS DISTINCT FROM v_existing.fuel_type)        OR
                (p_input.seating_capacity IS NOT NULL AND p_input.seating_capacity              IS DISTINCT FROM v_existing.seating_capacity) OR
                (p_input.standing_capacity IS NOT NULL AND p_input.standing_capacity            IS DISTINCT FROM v_existing.standing_capacity) OR
                (p_input.color            IS NOT NULL AND p_input.color                         IS DISTINCT FROM v_existing.color)            OR
                (p_input.status           IS NOT NULL AND p_input.status                        IS DISTINCT FROM v_existing.status)           OR
                (p_input.acquisition_date IS NOT NULL AND p_input.acquisition_date              IS DISTINCT FROM v_existing.acquisition_date) OR
                (p_input.is_operational   IS NOT NULL AND p_input.is_operational                IS DISTINCT FROM v_existing.is_operational);

        IF v_has_changes THEN
UPDATE fleet.vehicle
SET plate_number      = COALESCE(NULLIF(UPPER(TRIM(p_input.plate_number)), ''),    plate_number),
    internal_code     = COALESCE(NULLIF(TRIM(p_input.internal_code), ''),          internal_code),
    brand             = COALESCE(p_input.brand,                                    brand),
    model             = COALESCE(p_input.model,                                    model),
    year              = COALESCE(p_input.year,                                     year),
    chassis_number    = COALESCE(NULLIF(TRIM(COALESCE(p_input.chassis_number,'')),  ''), chassis_number),
    engine_number     = COALESCE(NULLIF(TRIM(COALESCE(p_input.engine_number, '')),  ''), engine_number),
    fuel_type         = COALESCE(p_input.fuel_type,                                fuel_type),
    seating_capacity  = COALESCE(p_input.seating_capacity,                         seating_capacity),
    standing_capacity = COALESCE(p_input.standing_capacity,                        standing_capacity),
    color             = COALESCE(p_input.color,                                    color),
    status            = COALESCE(p_input.status,                                   status),
    acquisition_date  = COALESCE(p_input.acquisition_date,                         acquisition_date),
    is_operational    = COALESCE(p_input.is_operational,                           is_operational),
    updated_at        = NOW()
WHERE vehicle_id = p_input.vehicle_id;

v_result.vehicle_status := 'UPDATED';
ELSE
            v_result.vehicle_status := 'SKIPPED';
END IF;

        v_result.internal_code_was_generated := FALSE;

        -- ══════════════════════════════════════════════════════════════════════
        -- RAMA INSERT: vehicle_id es NULL
        -- ══════════════════════════════════════════════════════════════════════
ELSE

        -- 1. company_id obligatorio
        IF p_input.company_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_COMPANY_ID';
            v_result.error_message := 'company_id es obligatorio al registrar un vehículo';
RETURN v_result;
END IF;

        -- 2. Empresa existe y está activa
        IF NOT EXISTS (
            SELECT 1 FROM shared.company
            WHERE company_id = p_input.company_id AND is_active = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'COMPANY_NOT_FOUND';
            v_result.error_message := 'company_id=' || p_input.company_id
                || ' no existe o está inactiva';
RETURN v_result;
END IF;

        -- 3. plate_number obligatorio y con formato válido
        IF p_input.plate_number IS NULL OR TRIM(p_input.plate_number) = '' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_PLATE_FORMAT';
            v_result.error_message := 'plate_number es obligatorio';
RETURN v_result;
END IF;

        v_plate := UPPER(REPLACE(TRIM(p_input.plate_number), ' ', ''));

        IF v_plate !~ '^[A-Z0-9]{2,4}-[A-Z0-9]{2,4}$' THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_PLATE_FORMAT';
            v_result.error_message := 'Formato de placa inválido: "' || p_input.plate_number
                                          || '". Formato requerido: AAA-000 o AAA-0000 '
                || '(3 letras mayúsculas, guion, 3 o 4 dígitos)';
RETURN v_result;
END IF;

        -- 4. Placa no duplicada
        IF EXISTS (
            SELECT 1 FROM fleet.vehicle
            WHERE plate_number = UPPER(TRIM(p_input.plate_number))
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'DUPLICATE_PLATE_NUMBER';
            v_result.error_message := 'La placa "' || UPPER(TRIM(p_input.plate_number))
                || '" ya está registrada en el sistema';
RETURN v_result;
END IF;

        -- 5. chassis_number no duplicado si se proveyó
        IF p_input.chassis_number IS NOT NULL
            AND TRIM(p_input.chassis_number) <> ''
        THEN
            IF EXISTS (
                SELECT 1 FROM fleet.vehicle
                WHERE chassis_number = TRIM(p_input.chassis_number)
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_CHASSIS_NUMBER';
                v_result.error_message := 'El número de chasis "' || p_input.chassis_number
                    || '" ya está registrado para otro vehículo';
RETURN v_result;
END IF;
END IF;

        -- 6. fuel_type válido si se proveyó
        IF p_input.fuel_type IS NOT NULL
            AND TRIM(p_input.fuel_type) <> ''
            AND p_input.fuel_type NOT IN ('DIESEL', 'GNV', 'HYBRID', 'ELECTRIC', 'GASOLINE')
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_FUEL_TYPE';
            v_result.error_message := 'fuel_type inválido: "' || p_input.fuel_type
                || '". Válidos: DIESEL, GNV, HYBRID, ELECTRIC, GASOLINE';
RETURN v_result;
END IF;

        -- 7. status dentro del dominio
        v_status := COALESCE(NULLIF(TRIM(COALESCE(p_input.status, '')), ''), 'ACTIVE');

        IF v_status NOT IN ('ACTIVE', 'INACTIVE', 'MAINTENANCE', 'RETIRED') THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_VEHICLE_STATUS';
            v_result.error_message := 'status inválido: "' || v_status
                || '". Válidos: ACTIVE, INACTIVE, MAINTENANCE, RETIRED';
RETURN v_result;
END IF;

        -- 8. Año en rango
        IF p_input.year IS NOT NULL THEN
            IF p_input.year < 1980
                OR p_input.year > EXTRACT(YEAR FROM CURRENT_DATE)::INT + 1
            THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'INVALID_YEAR';
                v_result.error_message := 'Año inválido: ' || p_input.year::TEXT
                                              || '. Debe estar entre 1980 y '
                    || (EXTRACT(YEAR FROM CURRENT_DATE)::INT + 1)::TEXT;
RETURN v_result;
END IF;
END IF;

        -- 9. Capacidades coherentes
        IF p_input.seating_capacity IS NOT NULL AND p_input.seating_capacity <= 0 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_CAPACITY';
            v_result.error_message := 'seating_capacity debe ser mayor a 0. '
                                          || 'Recibido: ' || p_input.seating_capacity::TEXT;
RETURN v_result;
END IF;

        IF p_input.standing_capacity IS NOT NULL AND p_input.standing_capacity < 0 THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_CAPACITY';
            v_result.error_message := 'standing_capacity no puede ser negativo. '
                                          || 'Recibido: ' || p_input.standing_capacity::TEXT;
RETURN v_result;
END IF;

        -- 10. Resolver internal_code
        IF p_input.internal_code IS NOT NULL AND TRIM(p_input.internal_code) <> '' THEN
            IF EXISTS (
                SELECT 1 FROM fleet.vehicle
                WHERE internal_code = TRIM(p_input.internal_code)
            ) THEN
                v_result.success       := FALSE;
                v_result.error_code    := 'DUPLICATE_INTERNAL_CODE';
                v_result.error_message := 'El código interno "' || p_input.internal_code
                    || '" ya está en uso';
RETURN v_result;
END IF;
            v_internal_code      := TRIM(p_input.internal_code);
            v_code_was_generated := FALSE;
ELSE
            v_internal_code      := api._generate_vehicle_code();
            v_code_was_generated := TRUE;
END IF;

        -- 11. INSERT
INSERT INTO fleet.vehicle (
    company_id,
    plate_number,
    internal_code,
    brand,
    model,
    year,
    chassis_number,
    engine_number,
    fuel_type,
    seating_capacity,
    standing_capacity,
    color,
    status,
    acquisition_date,
    is_operational
)
VALUES (
           p_input.company_id,
           UPPER(TRIM(p_input.plate_number)),
           v_internal_code,
           p_input.brand,
           p_input.model,
           p_input.year,
           NULLIF(TRIM(COALESCE(p_input.chassis_number, '')), ''),
           NULLIF(TRIM(COALESCE(p_input.engine_number,  '')), ''),
           p_input.fuel_type,
           p_input.seating_capacity,
           p_input.standing_capacity,
           p_input.color,
           v_status,
           p_input.acquisition_date,
           TRUE
       )
    RETURNING vehicle_id INTO p_input.vehicle_id;

v_result.vehicle_status              := 'INSERTED';
        v_result.internal_code_was_generated := v_code_was_generated;

END IF;

    -- ── Poblar resultado desde BD ─────────────────────────────────────────
SELECT
    v.vehicle_id,
    v.company_id,
    v.plate_number,
    v.internal_code,
    v.brand,
    v.model,
    v.year,
    v.chassis_number,
    v.engine_number,
    v.fuel_type,
    v.seating_capacity,
    v.standing_capacity,
    v.color,
    v.status,
    v.acquisition_date,
    v.is_operational,
    v.created_at,
    v.updated_at
INTO
    v_result.vehicle_id,
    v_result.company_id,
    v_result.plate_number,
    v_result.internal_code,
    v_result.brand,
    v_result.model,
    v_result.year,
    v_result.chassis_number,
    v_result.engine_number,
    v_result.fuel_type,
    v_result.seating_capacity,
    v_result.standing_capacity,
    v_result.color,
    v_result.status,
    v_result.acquisition_date,
    v_result.is_operational,
    v_result.created_at,
    v_result.updated_at
FROM fleet.vehicle v
WHERE v.vehicle_id = p_input.vehicle_id;

v_result.success := TRUE;
RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DUPLICATE_PLATE_NUMBER';
        v_result.error_message := 'Conflicto de unicidad por concurrencia '
                                      || '(placa, chasis o código interno duplicado). '
                                      || 'Detalle: ' || SQLERRM;
RETURN v_result;
WHEN check_violation THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'CONSTRAINT_VIOLATION';
        v_result.error_message := 'Violación de constraint en fleet.vehicle: ' || SQLERRM;
RETURN v_result;
WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$_$;


--
-- Name: upsert_vehicle_document(api.upsert_vehicle_document_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_vehicle_document(p_input api.upsert_vehicle_document_input) RETURNS api.upsert_vehicle_document_result
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result                api.upsert_vehicle_document_result;
    v_doc_type              shared.document_type%ROWTYPE;
    v_doc_id                BIGINT;
    v_operation             VARCHAR(10);
    v_status                VARCHAR(20);
    v_verified_at           TIMESTAMPTZ;
    v_days_until_expiry     INT;
    v_expiring_soon         BOOLEAN := FALSE;
    v_vehicle_blocked       BOOLEAN := FALSE;
    v_was_operational       BOOLEAN;
BEGIN

    -- ── Validación 1: vehículo existe ─────────────────────────────────────
SELECT is_operational INTO v_was_operational
FROM fleet.vehicle
WHERE vehicle_id = p_input.vehicle_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'VEHICLE_NOT_FOUND';
        v_result.error_message := 'El vehículo vehicle_id=' || p_input.vehicle_id
                                  || ' no existe';
RETURN v_result;
END IF;

    -- ── Validación 2: tipo de documento existe ────────────────────────────
SELECT * INTO v_doc_type
FROM shared.document_type
WHERE document_type_id = p_input.document_type_id;

IF NOT FOUND THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DOCUMENT_TYPE_NOT_FOUND';
        v_result.error_message := 'El document_type_id=' || p_input.document_type_id
                                  || ' no existe';
RETURN v_result;
END IF;

    IF v_doc_type.is_active = FALSE THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'DOCUMENT_TYPE_INACTIVE';
        v_result.error_message := 'El tipo de documento "' || v_doc_type.code
                                  || '" está inactivo y no puede usarse';
RETURN v_result;
END IF;

    -- ── Validación 3: expiry_date obligatoria si requires_expiry = true ───
    IF v_doc_type.requires_expiry = TRUE AND p_input.expiry_date IS NULL THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'EXPIRY_DATE_REQUIRED';
        v_result.error_message := 'El tipo de documento "' || v_doc_type.name
                                  || '" requiere fecha de vencimiento (requires_expiry=true)';
RETURN v_result;
END IF;

    -- ── Validación 4: rango de fechas coherente ───────────────────────────
    IF p_input.issue_date IS NOT NULL
       AND p_input.expiry_date IS NOT NULL
       AND p_input.expiry_date <= p_input.issue_date
    THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DATE_RANGE';
        v_result.error_message := 'expiry_date (' || p_input.expiry_date::TEXT
                                  || ') debe ser posterior a issue_date ('
                                  || p_input.issue_date::TEXT || ')';
RETURN v_result;
END IF;

    -- ── Validación 5: status dentro del dominio ───────────────────────────
    v_status := COALESCE(NULLIF(TRIM(COALESCE(p_input.status, '')), ''), 'VALID');

    IF v_status NOT IN ('VALID', 'EXPIRED', 'PENDING', 'REJECTED') THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_DOCUMENT_STATUS';
        v_result.error_message := 'status inválido: "' || v_status
                                  || '". Válidos: VALID, EXPIRED, PENDING, REJECTED';
RETURN v_result;
END IF;

    -- ── Validación 6: verificador existe y está activo ────────────────────
    IF p_input.verified_by IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM identity.user
            WHERE user_id   = p_input.verified_by
              AND is_active  = TRUE
        ) THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'VERIFIER_NOT_FOUND';
            v_result.error_message := 'El verificador user_id=' || p_input.verified_by
                                      || ' no existe o está inactivo';
RETURN v_result;
END IF;
        v_verified_at := NOW();
END IF;

    -- ── Auto-detección de EXPIRED si la fecha ya pasó ─────────────────────
    IF p_input.expiry_date IS NOT NULL
       AND p_input.expiry_date < CURRENT_DATE
       AND v_status = 'VALID'
    THEN
        v_status := 'EXPIRED';
END IF;

    -- ── Calcular días hasta vencimiento y flag expiring_soon ──────────────
    IF p_input.expiry_date IS NOT NULL THEN
        v_days_until_expiry := (p_input.expiry_date - CURRENT_DATE);

        IF v_doc_type.alert_days_before IS NOT NULL
           AND v_days_until_expiry <= v_doc_type.alert_days_before
           AND v_days_until_expiry >= 0
        THEN
            v_expiring_soon := TRUE;
END IF;
END IF;

    -- ── UPSERT principal ──────────────────────────────────────────────────
INSERT INTO fleet.vehicle_document (
    vehicle_id,
    document_type_id,
    document_number,
    issuing_entity,
    issue_date,
    expiry_date,
    file_id,
    status,
    verified_by,
    verified_at,
    notes
)
VALUES (
           p_input.vehicle_id,
           p_input.document_type_id,
           p_input.document_number,
           p_input.issuing_entity,
           p_input.issue_date,
           p_input.expiry_date,
           p_input.file_id,
           v_status,
           p_input.verified_by,
           v_verified_at,
           p_input.notes
       )
    ON CONFLICT (vehicle_id, document_type_id)
    DO UPDATE SET
    document_number = EXCLUDED.document_number,
               issuing_entity  = EXCLUDED.issuing_entity,
               issue_date      = EXCLUDED.issue_date,
               expiry_date     = EXCLUDED.expiry_date,
               file_id         = COALESCE(EXCLUDED.file_id,      fleet.vehicle_document.file_id),
               status          = EXCLUDED.status,
               verified_by     = EXCLUDED.verified_by,
               verified_at     = CASE
               WHEN EXCLUDED.verified_by IS NOT NULL THEN NOW()
               ELSE fleet.vehicle_document.verified_at
END,
        notes           = COALESCE(EXCLUDED.notes, fleet.vehicle_document.notes),
        updated_at      = NOW()
    RETURNING
        vehicle_document_id,
        CASE WHEN xmax = 0 THEN 'INSERTED' ELSE 'UPDATED' END
    INTO v_doc_id, v_operation;

    -- ── Bloqueo automático del vehículo si doc CRITICAL vence ─────────────
    -- Condición: tipo CRITICAL + status resultante = EXPIRED
    IF v_doc_type.restriction_type = 'CRITICAL'
       AND v_status = 'EXPIRED'
       AND v_was_operational = TRUE   -- solo actuar si estaba operacional
    THEN
UPDATE fleet.vehicle
SET
    is_operational  = FALSE,
    updated_at      = NOW()
WHERE vehicle_id = p_input.vehicle_id;

v_vehicle_blocked := TRUE;
END IF;

    -- ── Poblar resultado campo a campo ────────────────────────────────────
SELECT
    vd.vehicle_document_id,
    vd.vehicle_id,
    vd.document_type_id,
    vd.document_number,
    vd.issue_date,
    vd.expiry_date,
    vd.status,
    vd.verified_by,
    vd.verified_at,
    vd.created_at,
    vd.updated_at
INTO
    v_result.vehicle_document_id,
    v_result.vehicle_id,
    v_result.document_type_id,
    v_result.document_number,
    v_result.issue_date,
    v_result.expiry_date,
    v_result.status,
    v_result.verified_by,
    v_result.verified_at,
    v_result.created_at,
    v_result.updated_at
FROM fleet.vehicle_document vd
WHERE vd.vehicle_document_id = v_doc_id;

v_result.success            := TRUE;
    v_result.operation          := v_operation;
    v_result.document_type_code := v_doc_type.code;
    v_result.document_type_name := v_doc_type.name;
    v_result.restriction_type   := v_doc_type.restriction_type;
    v_result.alert_days_before  := v_doc_type.alert_days_before;
    v_result.expiring_soon      := v_expiring_soon;
    v_result.days_until_expiry  := v_days_until_expiry;
    v_result.vehicle_blocked    := v_vehicle_blocked;

RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
RETURN v_result;
END;
$$;


--
-- Name: upsert_vehicle_owner(api.upsert_vehicle_owner_input); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.upsert_vehicle_owner(p_input api.upsert_vehicle_owner_input) RETURNS api.upsert_vehicle_owner_result
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result            api.upsert_vehicle_owner_result;
    v_existing          fleet.vehicle_owner%ROWTYPE;
    v_person_exists     BOOLEAN;
    v_has_changes       BOOLEAN;
    v_owner_id          INT;
    v_person_record     hr.person%ROWTYPE;
BEGIN

    -- ── Validación de bank_account (aplica a INSERT y UPDATE) ─────────────
    IF p_input.bank_account IS NOT NULL AND TRIM(p_input.bank_account) <> '' THEN
        IF LENGTH(TRIM(p_input.bank_account)) < 8
            OR LENGTH(TRIM(p_input.bank_account)) > 50
        THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'INVALID_BANK_ACCOUNT';
            v_result.error_message := 'bank_account debe tener entre 8 y 50 caracteres. '
                                          || 'Recibido: "' || p_input.bank_account || '" ('
                                          || LENGTH(TRIM(p_input.bank_account))::TEXT || ' chars)';
            RETURN v_result;
        END IF;
    ELSIF p_input.bank_account IS NOT NULL AND TRIM(p_input.bank_account) = '' THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INVALID_BANK_ACCOUNT';
        v_result.error_message := 'bank_account no puede ser una cadena vacía. '
            || 'Omita el campo si no tiene cuenta bancaria';
        RETURN v_result;
    END IF;

    -- ══════════════════════════════════════════════════════════════════════
    -- RAMA UPDATE: vehicle_owner_id viene NOT NULL
    -- ══════════════════════════════════════════════════════════════════════
    IF p_input.vehicle_owner_id IS NOT NULL THEN

        -- 1. El propietario existe
        SELECT * INTO v_existing
        FROM fleet.vehicle_owner
        WHERE vehicle_owner_id = p_input.vehicle_owner_id;

        IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'OWNER_NOT_FOUND';
            v_result.error_message := 'vehicle_owner_id=' || p_input.vehicle_owner_id
                || ' no existe';
            RETURN v_result;
        END IF;

        -- 2. Detectar cambios reales (PATCH semántico — solo campos propios del rol)
        v_has_changes :=
                (p_input.bank_account IS NOT NULL AND
                 NULLIF(TRIM(COALESCE(p_input.bank_account,'')), '') IS DISTINCT FROM v_existing.bank_account) OR
                (p_input.is_active    IS NOT NULL AND p_input.is_active IS DISTINCT FROM v_existing.is_active);

        IF v_has_changes THEN
            UPDATE fleet.vehicle_owner
            SET bank_account = COALESCE(NULLIF(TRIM(COALESCE(p_input.bank_account,'')), ''), bank_account),
                is_active    = COALESCE(p_input.is_active,                                  is_active),
                updated_at   = NOW()
            WHERE vehicle_owner_id = p_input.vehicle_owner_id;

            v_result.owner_status := 'UPDATED';
        ELSE
            v_result.owner_status := 'SKIPPED';
        END IF;

        v_result.already_existed := TRUE;
        v_owner_id                := p_input.vehicle_owner_id;

        -- ══════════════════════════════════════════════════════════════════════
        -- RAMA INSERT: vehicle_owner_id es NULL
        -- ══════════════════════════════════════════════════════════════════════
    ELSE

        -- 1. person_id obligatorio
        IF p_input.person_id IS NULL THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'MISSING_PERSON_ID';
            v_result.error_message := 'person_id es obligatorio al registrar un propietario';
            RETURN v_result;
        END IF;

        -- 2. Persona existe en hr.person y obtener sus datos
        SELECT * INTO v_person_record
        FROM hr.person
        WHERE person_id = p_input.person_id;

        IF NOT FOUND THEN
            v_result.success       := FALSE;
            v_result.error_code    := 'PERSON_NOT_FOUND';
            v_result.error_message := 'person_id=' || p_input.person_id
                                          || ' no existe en hr.person. '
                || 'Use api.upsert_person primero';
            RETURN v_result;
        END IF;

        -- 3. Idempotencia: persona ya es propietaria → retornar existente con flag
        SELECT * INTO v_existing
        FROM fleet.vehicle_owner
        WHERE person_id = p_input.person_id;

        IF FOUND THEN
            v_result.success          := TRUE;
            v_result.owner_status     := 'INSERTED';    -- semánticamente "ya creado"
            v_result.already_existed  := TRUE;
            v_owner_id                 := v_existing.vehicle_owner_id;
        ELSE
            -- 4. INSERT - SOLO columnas que existen en vehicle_owner
            INSERT INTO fleet.vehicle_owner (
                person_id,
                bank_account,
                is_active,
                full_name,
                tax_id
            )
            VALUES (
                       p_input.person_id,
                       NULLIF(TRIM(COALESCE(p_input.bank_account, '')), ''),
                       TRUE,
                       v_person_record.full_name,
                       v_person_record.tax_id
                   )
            RETURNING vehicle_owner_id INTO v_owner_id;

            v_result.owner_status    := 'INSERTED';
            v_result.already_existed := FALSE;
        END IF;

    END IF;

    -- ── Poblar resultado desde BD (JOIN a hr.person para identidad/contacto) ─
    SELECT
        vo.vehicle_owner_id,
        vo.person_id,
        vo.bank_account,
        vo.is_active,
        vo.created_at,
        vo.updated_at,
        p.full_name,
        p.tax_id,
        p.email,
        p.phone_mobile
    INTO
        v_result.vehicle_owner_id,
        v_result.person_id,
        v_result.bank_account,
        v_result.is_active,
        v_result.created_at,
        v_result.updated_at,
        v_result.full_name,
        v_result.tax_id,
        v_result.email,
        v_result.phone_mobile
    FROM fleet.vehicle_owner vo
             JOIN hr.person p ON p.person_id = vo.person_id
    WHERE vo.vehicle_owner_id = v_owner_id;

    v_result.success := TRUE;
    RETURN v_result;

EXCEPTION
    WHEN unique_violation THEN
        -- Race condition en INSERT: person_id insertado concurrentemente
        SELECT * INTO v_existing
        FROM fleet.vehicle_owner WHERE person_id = p_input.person_id;

        SELECT
            v_existing.vehicle_owner_id,
            v_existing.person_id,
            v_existing.bank_account,
            v_existing.is_active,
            v_existing.created_at,
            v_existing.updated_at,
            p.full_name,
            p.tax_id,
            p.email,
            p.phone_mobile
        INTO
            v_result.vehicle_owner_id,
            v_result.person_id,
            v_result.bank_account,
            v_result.is_active,
            v_result.created_at,
            v_result.updated_at,
            v_result.full_name,
            v_result.tax_id,
            v_result.email,
            v_result.phone_mobile
        FROM hr.person p
        WHERE p.person_id = v_existing.person_id;

        v_result.success          := TRUE;
        v_result.owner_status     := 'INSERTED';
        v_result.already_existed  := TRUE;
        RETURN v_result;

    WHEN OTHERS THEN
        v_result.success       := FALSE;
        v_result.error_code    := 'INTERNAL_ERROR';
        v_result.error_message := SQLERRM;
        RETURN v_result;
END;
$$;


--
-- Name: notify_permission_change(); Type: FUNCTION; Schema: listener; Owner: -
--

CREATE FUNCTION listener.notify_permission_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify(
        'permissions_changed',
        json_build_object(
            'table', TG_TABLE_NAME,
            'operation', TG_OP,
            'timestamp', extract(epoch from now())
        )::text
    );

RETURN NULL;
END;
$$;


--
-- Name: audit_type(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.audit_type(p_type_name text) RETURNS TABLE(section text, detail text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Estructura del tipo
    RETURN QUERY
    SELECT
        'STRUCTURE'::TEXT,
        a.attname || ' ' || pg_catalog.format_type(a.atttypid, a.atttypmod)
    FROM pg_attribute a
    JOIN pg_type t ON a.attrelid = t.typrelid
    WHERE t.typname = p_type_name
    AND a.attnum > 0
    AND NOT a.attisdropped
    ORDER BY a.attnum;

    -- Funciones que lo usan
    RETURN QUERY
    SELECT
        'USED_IN'::TEXT,
        n.nspname || '.' || p.proname || '()'
    FROM pg_type t
    JOIN pg_depend d ON d.refobjid = t.oid
    JOIN pg_proc p ON p.oid = d.objid
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE t.typname = p_type_name;
END;
$$;


--
-- Name: create_gps_partition(timestamp with time zone); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.create_gps_partition(p_timestamp timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
v_start DATE;
    v_end DATE;
    v_table TEXT;
BEGIN
    -- Inicio del mes
    v_start := date_trunc('month', p_timestamp)::date;

    -- Inicio del siguiente mes
    v_end := (v_start + INTERVAL '1 month')::date;

    -- Nombre de la partición
    v_table := format('gps_raw_event_%s', to_char(v_start, 'YYYY_MM'));

    -- Verificar si existe
    IF NOT EXISTS (
        SELECT 1
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relname = v_table
        AND n.nspname = 'fleet'
    ) THEN
        -- 🏗️ Crear partición
        EXECUTE format(
            'CREATE TABLE fleet.%I PARTITION OF fleet.gps_raw_event
             FOR VALUES FROM (%L) TO (%L)',
            v_table, v_start, v_end
        );
END IF;
END;
$$;


--
-- Name: describe_type(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.describe_type(p_type_name text) RETURNS TABLE(column_name text, data_type text, position_at integer, is_array boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        a.attname::TEXT,
        pg_catalog.format_type(a.atttypid, a.atttypmod)::TEXT,
        a.attnum::INT,
        (pg_catalog.format_type(a.atttypid, a.atttypmod) LIKE '%[]')::BOOLEAN
    FROM pg_attribute a
    JOIN pg_type t ON a.attrelid = t.typrelid
    WHERE t.typname = p_type_name
    AND a.attnum > 0
    AND NOT a.attisdropped
    ORDER BY a.attnum;
END;
$$;


--
-- Name: find_active_sessions(); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_active_sessions() RETURNS TABLE(pid integer, usename text, application_name text, state text, wait_event_type text, wait_event text, time_in_state interval, query text)
    LANGUAGE sql
    AS $$
SELECT
    pid,
    usename,
    application_name,
    state,
    wait_event_type,
    wait_event,
    now() - state_change AS time_in_state,
    query
FROM pg_stat_activity
WHERE backend_type = 'client backend'
  AND pid <> pg_backend_pid();
$$;


--
-- Name: find_composite_types(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_composite_types(p_schema text DEFAULT NULL::text) RETURNS TABLE(schema_name text, type_name text, description text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        n.nspname::TEXT,
        t.typname::TEXT,
        obj_description(t.oid, 'pg_type')::TEXT
    FROM pg_type t
    JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE t.typtype = 'c'
    AND n.nspname NOT IN ('pg_catalog', 'information_schema')
    AND (p_schema IS NULL OR n.nspname = p_schema)
    ORDER BY n.nspname, t.typname;
END;
$$;


--
-- Name: find_current_pid(); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_current_pid() RETURNS integer
    LANGUAGE sql
    AS $$
SELECT pg_backend_pid();
$$;


--
-- Name: find_function_details(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_function_details(p_search text) RETURNS TABLE(schema_name text, function_name text, arguments text, return_type text, returns_table boolean, definition text)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
SELECT
    n.nspname::TEXT,
        p.proname::TEXT,

        -- argumentos de entrada
        pg_catalog.pg_get_function_arguments(p.oid)::TEXT,

        -- tipo de retorno (bonito)
        pg_catalog.pg_get_function_result(p.oid)::TEXT,

        -- si retorna TABLE
        (p.proretset AND p.prokind = 'f') AS returns_table,

    -- definición completa
    pg_catalog.pg_get_functiondef(p.oid)::TEXT

FROM pg_proc p
         JOIN pg_namespace n ON n.oid = p.pronamespace
WHERE n.nspname NOT IN ('pg_catalog', 'information_schema')
  AND p.proname ILIKE '%' || p_search || '%'
ORDER BY n.nspname, p.proname;
END;
$$;


--
-- Name: find_functions_by_schema(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_functions_by_schema(p_schema text) RETURNS TABLE(schema_name text, function_name text, return_type text, parameters text)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
SELECT
    n.nspname::TEXT AS schema_name,
        p.proname::TEXT AS function_name,
        pg_get_function_result(p.oid)::TEXT AS return_type,
        pg_get_function_arguments(p.oid)::TEXT AS parameters
FROM pg_proc p
         JOIN pg_namespace n
              ON n.oid = p.pronamespace
-- WHERE n.nspname = p_schema
WHERE n.nspname ILIKE '%' || p_schema || '%'
ORDER BY function_name;
END;
$$;


--
-- Name: find_functions_returning_type(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_functions_returning_type(p_type_name text) RETURNS TABLE(schema_name text, function_name text, return_type text, parameters text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        n.nspname::TEXT,
        p.proname::TEXT,
        pg_get_function_result(p.oid)::TEXT,
        pg_get_function_arguments(p.oid)::TEXT
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE pg_get_function_result(p.oid) ILIKE '%' || p_type_name || '%'
    ORDER BY n.nspname, p.proname;
END;
$$;


--
-- Name: find_functions_using_type(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_functions_using_type(p_type_name text) RETURNS TABLE(usage_type text, schema_name text, function_name text, return_type text, parameters text)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY

SELECT DISTINCT
    'DEPENDENCY'::TEXT AS usage_type,
        n.nspname::TEXT AS schema_name,
        p.proname::TEXT AS function_name,
        pg_get_function_result(p.oid)::TEXT AS return_type,
        pg_get_function_arguments(p.oid)::TEXT AS parameters
FROM pg_type t
         JOIN pg_depend d
              ON d.refobjid = t.oid
         JOIN pg_proc p
              ON p.oid = d.objid
         JOIN pg_namespace n
              ON n.oid = p.pronamespace
WHERE t.typtype = 'c'
  AND t.typname ILIKE '%' || p_type_name || '%'

ORDER BY usage_type, schema_name, function_name;

END;
$$;


--
-- Name: find_functions_with_type_parameter(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_functions_with_type_parameter(p_type_name text) RETURNS TABLE(schema_name text, function_name text, parameters text, return_type text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        n.nspname::TEXT,
        p.proname::TEXT,
        pg_get_function_arguments(p.oid)::TEXT,
        pg_get_function_result(p.oid)::TEXT
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE pg_get_function_arguments(p.oid) ILIKE '%' || p_type_name || '%'
    ORDER BY n.nspname, p.proname;
END;
$$;


--
-- Name: find_idle_in_transaction(integer); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_idle_in_transaction(p_minutes integer DEFAULT 5) RETURNS TABLE(pid integer, usename text, application_name text, state text, state_change timestamp with time zone, idle_duration interval)
    LANGUAGE sql
    AS $$
SELECT
    pid,
    usename,
    application_name,
    state,
    state_change,
    now() - state_change as idle_duration
FROM pg_stat_activity
WHERE state = 'idle in transaction'
  AND now() - state_change > (p_minutes || ' minutes')::interval
ORDER BY state_change;
$$;


--
-- Name: find_idle_listeners(); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_idle_listeners() RETURNS TABLE(pid integer, usename text, application_name text, state text, query text, idle_time interval)
    LANGUAGE sql
    AS $$
SELECT
    pid,
    usename,
    application_name,
    state,
    query,
    now() - state_change as idle_time
FROM pg_stat_activity
WHERE query LIKE 'LISTEN%'
  AND state = 'idle';
$$;


--
-- Name: find_listen_process(); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_listen_process() RETURNS TABLE(pid integer, usename text, application_name text, state text, query text)
    LANGUAGE sql
    AS $$
SELECT pid, usename, application_name, state, query
FROM pg_stat_activity
WHERE query LIKE 'LISTEN%';
$$;


--
-- Name: find_notification_queue_status(); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_notification_queue_status() RETURNS TABLE(usage numeric, status text)
    LANGUAGE sql
    AS $$
SELECT
    pg_notification_queue_usage() as usage,
        CASE
            WHEN pg_notification_queue_usage() > 0.5
                THEN 'CRITICAL: Queue >50%'
            WHEN pg_notification_queue_usage() > 0.1
                THEN 'WARNING: Queue >10%'
            ELSE 'OK'
END as status;
$$;


--
-- Name: find_queue_usage(); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_queue_usage() RETURNS numeric
    LANGUAGE sql
    AS $$
SELECT pg_notification_queue_usage();
$$;


--
-- Name: find_terminate_backend(integer); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_terminate_backend(p_pid integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_pid = pg_backend_pid() THEN
        RAISE EXCEPTION 'No puedes terminar tu propia conexión';
END IF;

RETURN pg_terminate_backend(p_pid);
END;
$$;


--
-- Name: find_types_by_name(text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.find_types_by_name(p_schema text DEFAULT ''::text) RETURNS TABLE(schema_name text, type_name text, description text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        n.nspname::TEXT,
        t.typname::TEXT,
        obj_description(t.oid, 'pg_type')::TEXT
    FROM pg_type t
    JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE t.typtype = 'c'
    AND n.nspname NOT IN ('pg_catalog', 'information_schema')
    AND (p_search = '' OR t.typname ILIKE '%' || p_schema || '%')
    ORDER BY t.typname;
END;
$$;


--
-- Name: get_user_permission(integer, text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.get_user_permission(p_user_id integer, p_code text) RETURNS TABLE(code character varying, company_id integer, scope_id integer, rol character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
RETURN QUERY
SELECT
    p.code,
    rps.company_id::INT,
    rps.scope_id::INT,
    r.name AS rol
FROM identity.user_role ur
         JOIN identity.role_permission rp ON ur.role_id = rp.role_id
         JOIN identity.permission p ON rp.permission_id = p.permission_id
         JOIN identity.role r ON ur.role_id = r.role_id
         LEFT JOIN identity.role_permission_scope rps
                   ON rp.role_permission_id = rps.role_permission_id
WHERE ur.user_id = p_user_id
  AND p.code = p_code;
END;
$$;


--
-- Name: kill_session(integer); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.kill_session(p_pid integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
v_result BOOLEAN;
BEGIN
SELECT pg_terminate_backend(p_pid) INTO v_result;
RETURN v_result;
END;
$$;


--
-- Name: reset_sequence(text, text); Type: FUNCTION; Schema: utilities; Owner: -
--

CREATE FUNCTION utilities.reset_sequence(p_table text, p_column text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
v_seq TEXT;
BEGIN
    -- Obtener nombre de la secuencia
SELECT pg_get_serial_sequence(p_table, p_column)
INTO v_seq;

-- Reiniciar secuencia correctamente
EXECUTE format(
        'SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM %s), 1), true)',
        v_seq, p_column, p_table
        );
END;
$$;


