--

CREATE TABLE core_operations.alert (
    alert_id bigint NOT NULL,
    alert_type_id integer NOT NULL,
    entity_type character varying(20) NOT NULL,
    entity_id bigint NOT NULL,
    trip_id bigint,
    vehicle_id integer,
    driver_id integer,
    severity character varying(20) NOT NULL,
    alert_timestamp timestamp with time zone NOT NULL,
    latitude numeric(10,8),
    longitude numeric(11,8),
    description text,
    metadata jsonb,
    acknowledged_by bigint,
    acknowledged_at timestamp with time zone,
    resolved_at timestamp with time zone,
    auto_closed_at timestamp with time zone,
    status character varying(20) DEFAULT 'ACTIVE'::character varying,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_alert_entity CHECK (((entity_type)::text = ANY ((ARRAY['VEHICLE'::character varying, 'DRIVER'::character varying, 'TRIP'::character varying, 'ROUTE'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT chk_alert_severity CHECK (((severity)::text = ANY ((ARRAY['CRITICAL'::character varying, 'HIGH'::character varying, 'MEDIUM'::character varying, 'LOW'::character varying, 'INFO'::character varying])::text[]))),
    CONSTRAINT chk_alert_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'ACKNOWLEDGED'::character varying, 'RESOLVED'::character varying, 'AUTO_CLOSED'::character varying])::text[])))
)
PARTITION BY RANGE (alert_timestamp);


