    CONSTRAINT chk_checkpoint_geofence CHECK ((geofence_radius_meters > 0)),
    CONSTRAINT chk_checkpoint_latitude CHECK (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric))),
    CONSTRAINT chk_checkpoint_longitude CHECK (((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))),
    CONSTRAINT chk_endpoint_only_terminal CHECK (((is_route_endpoint = false) OR (checkpoint_type = 'terminal'::core_operations.checkpoint_type_enum))),
    CONSTRAINT chk_geofence_required_for_control CHECK (((checkpoint_type = 'bus_stop'::core_operations.checkpoint_type_enum) OR (geofence_radius_meters IS NOT NULL)))
);


--
-- Name: TABLE checkpoint; Type: COMMENT; Schema: core_operations; Owner: -
--

COMMENT ON TABLE core_operations.checkpoint IS 'Unifica paraderos (bus_stop), controles (checkpoint) y terminales (terminal) como puntos georreferenciados de una ruta';


--
-- Name: COLUMN checkpoint.checkpoint_type; Type: COMMENT; Schema: core_operations; Owner: -
--

COMMENT ON COLUMN core_operations.checkpoint.checkpoint_type IS 'bus_stop = paradero, checkpoint = punto de control, terminal = inicio/fin de ruta';


--
-- Name: COLUMN checkpoint.is_route_endpoint; Type: COMMENT; Schema: core_operations; Owner: -
--

COMMENT ON COLUMN core_operations.checkpoint.is_route_endpoint IS 'Solo válido cuando checkpoint_type = terminal. Marca el inicio o fin físico de la ruta.';


--
-- Name: COLUMN checkpoint.geofence_radius_meters; Type: COMMENT; Schema: core_operations; Owner: -
--

COMMENT ON COLUMN core_operations.checkpoint.geofence_radius_meters IS 'Radio de geocerca en metros. Obligatorio para checkpoint y terminal.';


