CREATE TABLE fleet.gps_raw_event (
    raw_event_id bigint NOT NULL,
    gps_device_id integer NOT NULL,
    vehicle_id integer,
    beacon_mac_address character varying(17),
    latitude numeric(10,8) NOT NULL,
    longitude numeric(11,8) NOT NULL,
    altitude numeric(8,2),
    speed_kmh numeric(5,2),
    heading numeric(5,2),
    accuracy_meters numeric(6,2),
    satellites integer,
    gps_timestamp timestamp with time zone NOT NULL,
    server_timestamp timestamp with time zone DEFAULT now(),
    battery_level integer,
    raw_data character varying,
    created_at timestamp with time zone DEFAULT now(),
    track_id bigint,
    CONSTRAINT chk_gps_raw_accuracy CHECK (((accuracy_meters IS NULL) OR (accuracy_meters > (0)::numeric))),
    CONSTRAINT chk_gps_raw_battery CHECK (((battery_level IS NULL) OR ((battery_level >= 0) AND (battery_level <= 100)))),
    CONSTRAINT chk_gps_raw_heading CHECK (((heading IS NULL) OR ((heading >= (0)::numeric) AND (heading <= (360)::numeric)))),
    CONSTRAINT chk_gps_raw_latitude CHECK (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric))),
    CONSTRAINT chk_gps_raw_longitude CHECK (((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))),
    CONSTRAINT chk_gps_raw_satellites CHECK (((satellites IS NULL) OR (satellites >= 0))),
    CONSTRAINT chk_gps_raw_speed CHECK (((speed_kmh IS NULL) OR ((speed_kmh >= (0)::numeric) AND (speed_kmh <= (250)::numeric))))
)
PARTITION BY RANGE (gps_timestamp);


