-- Name: vehicle; Type: TABLE; Schema: fleet; Owner: -
--

CREATE TABLE fleet.vehicle (
    vehicle_id integer NOT NULL,
    plate_number character varying(10) NOT NULL,
    internal_code character varying(20) NOT NULL,
    company_id integer NOT NULL,
    brand character varying(100),
    model character varying(100),
    year integer,
    chassis_number character varying(50),
    engine_number character varying(50),
    fuel_type character varying(20),
    seating_capacity integer,
    standing_capacity integer,
    color character varying(50),
    status character varying(20) DEFAULT 'ACTIVE'::character varying,
    acquisition_date date,
    is_operational boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_vehicle_capacity CHECK ((((seating_capacity IS NULL) OR (seating_capacity > 0)) AND ((standing_capacity IS NULL) OR (standing_capacity >= 0)))),
    CONSTRAINT chk_vehicle_fuel_type CHECK (((fuel_type IS NULL) OR ((fuel_type)::text = ANY ((ARRAY['DIESEL'::character varying, 'GNV'::character varying, 'HYBRID'::character varying, 'ELECTRIC'::character varying, 'GASOLINE'::character varying])::text[])))),
    CONSTRAINT chk_vehicle_plate_format CHECK (((plate_number)::text ~ '^[A-Z0-9]{2,4}-[A-Z0-9]{2,4}$'::text)),
    CONSTRAINT chk_vehicle_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'MAINTENANCE'::character varying, 'RETIRED'::character varying])::text[]))),
    CONSTRAINT chk_vehicle_year CHECK (((year IS NULL) OR ((year >= 1980) AND ((year)::numeric <= (EXTRACT(year FROM CURRENT_DATE) + (1)::numeric)))))
);


